fn try_zeroed_transfer_buffer(len: usize) -> Result<alloc::vec::Vec<u8>, u32> {
    let mut bytes = alloc::vec::Vec::new();
    bytes
        .try_reserve_exact(len)
        .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
    bytes.resize(len, 0);
    Ok(bytes)
}

fn io_control_access_granted(granted: u32, control_code: u32) -> bool {
    const FILE_READ_DATA: u32 = 0x0000_0001;
    const FILE_WRITE_DATA: u32 = 0x0000_0002;
    const FILE_APPEND_DATA: u32 = 0x0000_0004;
    const GENERIC_READ: u32 = 0x8000_0000;
    const GENERIC_WRITE: u32 = 0x4000_0000;
    const GENERIC_ALL: u32 = 0x1000_0000;

    let required = nt_io_abi::ioctl::access(control_code);
    (required & nt_io_abi::ioctl::FILE_READ_ACCESS == 0
        || granted & (FILE_READ_DATA | GENERIC_READ | GENERIC_ALL) != 0)
        && (required & nt_io_abi::ioctl::FILE_WRITE_ACCESS == 0
            || granted & (FILE_WRITE_DATA | FILE_APPEND_DATA | GENERIC_WRITE | GENERIC_ALL) != 0)
}

fn file_io_mode_from_create(
    desired_access: u32,
    create_options: u32,
) -> Result<nt_io_completion::FileIoMode, u32> {
    const GENERIC_ACCESS: u32 = 0xF000_0000;
    const MAXIMUM_ALLOWED: u32 = 0x0200_0000;
    let alert = create_options & nt_fs::FILE_SYNCHRONOUS_IO_ALERT != 0;
    let nonalert = create_options & nt_fs::FILE_SYNCHRONOUS_IO_NONALERT != 0;
    nt_io_completion::FileIoMode::from_create_flags(
        alert,
        nonalert,
        desired_access & (nt_fs::SYNCHRONIZE | GENERIC_ACCESS | MAXIMUM_ALLOWED) != 0,
    )
}

unsafe fn reserve_synchronous_file_waiter() -> bool {
    let waiters = &mut *core::ptr::addr_of_mut!(SYNCHRONOUS_FILE_WAITERS);
    waiters.ensure_capacity()
}

unsafe fn reserve_file_irp_drain_waiter() -> Option<nt_io_manager::PendingFileIrpDrainReservation> {
    let waiters = &mut *core::ptr::addr_of_mut!(PENDING_FILE_IRP_DRAINS);
    waiters.reserve()
}

unsafe fn reserve_file_cleanup_waiter() -> Option<nt_io_manager::PendingFileCleanupWaitReservation>
{
    let waiters = &mut *core::ptr::addr_of_mut!(PENDING_FILE_CLEANUP_WAITS);
    waiters.reserve()
}

