type ExecServiceHandler = unsafe extern "C" fn(*mut ExecNtHandler, *const u64, usize) -> u32;

fn trace_setup_provision_phase(phase: &[u8], detail: u64) {
    const TRACE_LIMIT: u64 = 96;
    let trace = SETUP_PROVISION_TRACE_N.fetch_add(1, Ordering::Relaxed);
    if trace >= TRACE_LIMIT {
        return;
    }
    bump_progress();
    print_str(b"[setup-provision] phase=");
    print_str(phase);
    print_str(b" detail=");
    print_u64(detail);
    print_str(b"\n");
}

fn reset_setup_provision_trace() {
    SETUP_PROVISION_TRACE_N.store(0, Ordering::Relaxed);
}

struct ExecJournalNonSystemSetupSeedTarget<'a> {
    handler: &'a mut ExecNtHandler,
    created_keys: u32,
    changed_values: u32,
    failed: bool,
    last_status: u32,
}

impl<'a> ExecJournalNonSystemSetupSeedTarget<'a> {
    fn new(handler: &'a mut ExecNtHandler) -> Self {
        Self {
            handler,
            created_keys: 0,
            changed_values: 0,
            failed: false,
            last_status: 0,
        }
    }

    fn changed(&self) -> bool {
        self.created_keys != 0 || self.changed_values != 0
    }

    fn note_failure(&mut self, status: u32) {
        self.failed = true;
        self.last_status = status;
    }

    fn owns_non_system_path(&self, path: &str) -> bool {
        self.handler
            .mutable_hives
            .resolve_path(path)
            .is_some_and(|(hive, _)| hive != HIVE_SEL_SYSTEM)
    }
}

impl nt_hive_core::ReactOsSetupSeedTarget for ExecJournalNonSystemSetupSeedTarget<'_> {
    fn create_key(&mut self, path: &str) -> bool {
        if !self.owns_non_system_path(path) {
            self.note_failure(STATUS_INVALID_HANDLE);
            return false;
        }
        let existed = self.handler.mutable_registry_key_by_path(path).is_some();
        match self
            .handler
            .ensure_mutable_registry_key_by_path_journaled(path)
        {
            Ok(_) => {
                if !existed {
                    self.created_keys = self.created_keys.saturating_add(1);
                }
                true
            }
            Err(status) => {
                self.note_failure(status);
                false
            }
        }
    }

    fn set_value(
        &mut self,
        path: &str,
        name: &str,
        value_type: nt_hive_core::RegistryValueType,
        data: alloc::vec::Vec<u8>,
    ) -> bool {
        if !self.owns_non_system_path(path) {
            self.note_failure(STATUS_INVALID_HANDLE);
            return false;
        }
        if self.value_matches(path, name, value_type, &data) {
            return false;
        }
        let key = match self
            .handler
            .ensure_mutable_registry_key_by_path_journaled(path)
        {
            Ok(key) => key,
            Err(status) => {
                self.note_failure(status);
                return false;
            }
        };
        match self
            .handler
            .journal_set_mutable_value(key, name, value_type, &data)
        {
            Ok(()) => {
                self.changed_values = self.changed_values.saturating_add(1);
                true
            }
            Err(status) => {
                self.note_failure(status);
                false
            }
        }
    }

    fn has_value(&self, path: &str, name: &str) -> bool {
        self.owns_non_system_path(path)
            && self
                .handler
                .mutable_registry_key_by_path(path)
                .and_then(|key| self.handler.mutable_hives.query_value(key, name))
                .is_some()
    }

    fn value_matches(
        &self,
        path: &str,
        name: &str,
        value_type: nt_hive_core::RegistryValueType,
        data: &[u8],
    ) -> bool {
        self.owns_non_system_path(path)
            && self
                .handler
                .mutable_registry_key_by_path(path)
                .and_then(|key| self.handler.mutable_hives.query_value(key, name))
                .is_some_and(|(ty, existing)| ty == value_type && existing == data)
    }

    fn query_value(
        &self,
        path: &str,
        name: &str,
    ) -> Option<(nt_hive_core::RegistryValueType, alloc::vec::Vec<u8>)> {
        if !self.owns_non_system_path(path) {
            return None;
        }
        self.handler
            .mutable_registry_key_by_path(path)
            .and_then(|key| self.handler.mutable_hives.query_value(key, name))
            .map(|(ty, data)| (ty, data.to_vec()))
    }
}

enum OwnedSystemHiveMutation {
    CreateKey {
        path: alloc::string::String,
    },
    SetValue {
        path: alloc::string::String,
        name: alloc::string::String,
        value_type: nt_hive_core::RegistryValueType,
        data: alloc::vec::Vec<u8>,
    },
    DeleteValue {
        path: alloc::string::String,
        name: alloc::string::String,
    },
    DeleteKey {
        path: alloc::string::String,
    },
    SetKeyClass {
        path: alloc::string::String,
        class_name: Option<alloc::string::String>,
    },
    SetKeySecurity {
        path: alloc::string::String,
        descriptor: alloc::vec::Vec<u8>,
    },
}

#[derive(Clone, Copy)]
enum SystemHiveMutationOrigin {
    Setup,
    Runtime,
}

impl OwnedSystemHiveMutation {
    fn as_client_mutation(&self) -> nt_config_client::SystemHiveMutation<'_> {
        match self {
            Self::CreateKey { path } => nt_config_client::SystemHiveMutation::CreateKey { path },
            Self::SetValue {
                path,
                name,
                value_type,
                data,
            } => nt_config_client::SystemHiveMutation::SetValue {
                path,
                name,
                value_type: *value_type as u32,
                data,
            },
            Self::DeleteValue { path, name } => {
                nt_config_client::SystemHiveMutation::DeleteValue { path, name }
            }
            Self::DeleteKey { path } => nt_config_client::SystemHiveMutation::DeleteKey { path },
            Self::SetKeyClass { path, class_name } => {
                nt_config_client::SystemHiveMutation::SetKeyClass {
                    path,
                    class_name: class_name.as_deref(),
                }
            }
            Self::SetKeySecurity { path, descriptor } => {
                nt_config_client::SystemHiveMutation::SetKeySecurity { path, descriptor }
            }
        }
    }
}

struct CollectSystemSetupSeedTarget<'a> {
    handler: &'a ExecNtHandler,
    mutations: alloc::vec::Vec<OwnedSystemHiveMutation>,
    failed: bool,
}

impl<'a> CollectSystemSetupSeedTarget<'a> {
    fn new(handler: &'a ExecNtHandler) -> Self {
        Self {
            handler,
            mutations: alloc::vec::Vec::new(),
            failed: false,
        }
    }

    fn owns_system_path(&self, path: &str) -> bool {
        self.handler
            .mutable_hives
            .resolve_path(path)
            .is_some_and(|(hive, _)| hive == HIVE_SEL_SYSTEM)
    }

    fn pending_value(
        &self,
        path: &str,
        name: &str,
    ) -> Option<(nt_hive_core::RegistryValueType, &[u8])> {
        self.mutations
            .iter()
            .rev()
            .find_map(|mutation| match mutation {
                OwnedSystemHiveMutation::SetValue {
                    path: pending_path,
                    name: pending_name,
                    value_type,
                    data,
                } if pending_path.eq_ignore_ascii_case(path)
                    && pending_name.eq_ignore_ascii_case(name) =>
                {
                    Some((*value_type, data.as_slice()))
                }
                _ => None,
            })
    }
}

impl nt_hive_core::ReactOsSetupSeedTarget for CollectSystemSetupSeedTarget<'_> {
    fn create_key(&mut self, path: &str) -> bool {
        if !self.owns_system_path(path) {
            self.failed = true;
            return false;
        }
        if self.handler.mutable_registry_key_by_path(path).is_none()
            && !self.mutations.iter().any(|mutation| {
                matches!(
                    mutation,
                    OwnedSystemHiveMutation::CreateKey { path: pending }
                        if pending.eq_ignore_ascii_case(path)
                )
            })
        {
            self.mutations
                .push(OwnedSystemHiveMutation::CreateKey { path: path.into() });
        }
        true
    }

    fn set_value(
        &mut self,
        path: &str,
        name: &str,
        value_type: nt_hive_core::RegistryValueType,
        data: alloc::vec::Vec<u8>,
    ) -> bool {
        if !self.owns_system_path(path) {
            self.failed = true;
            return false;
        }
        if self.value_matches(path, name, value_type, &data) {
            return false;
        }
        if self.handler.mutable_registry_key_by_path(path).is_none() && !self.create_key(path) {
            return false;
        }
        self.mutations.push(OwnedSystemHiveMutation::SetValue {
            path: path.into(),
            name: name.into(),
            value_type,
            data,
        });
        true
    }

    fn has_value(&self, path: &str, name: &str) -> bool {
        self.pending_value(path, name).is_some()
            || self
                .handler
                .mutable_registry_key_by_path(path)
                .and_then(|key| self.handler.mutable_hives.query_value(key, name))
                .is_some()
    }

    fn value_matches(
        &self,
        path: &str,
        name: &str,
        value_type: nt_hive_core::RegistryValueType,
        data: &[u8],
    ) -> bool {
        self.pending_value(path, name)
            .or_else(|| {
                self.handler
                    .mutable_registry_key_by_path(path)
                    .and_then(|key| self.handler.mutable_hives.query_value(key, name))
            })
            .is_some_and(|(ty, existing)| ty == value_type && existing == data)
    }

    fn query_value(
        &self,
        path: &str,
        name: &str,
    ) -> Option<(nt_hive_core::RegistryValueType, alloc::vec::Vec<u8>)> {
        self.pending_value(path, name)
            .map(|(ty, data)| (ty, data.to_vec()))
            .or_else(|| {
                self.handler
                    .mutable_registry_key_by_path(path)
                    .and_then(|key| self.handler.mutable_hives.query_value(key, name))
                    .map(|(ty, data)| (ty, data.to_vec()))
            })
    }
}

