fn print_sanitized_ascii(bytes: &[u8], limit: usize) {
    for &byte in bytes.iter().take(limit) {
        debug_put_char(if (0x20..0x7f).contains(&byte) {
            byte
        } else {
            b'.'
        });
    }
}

fn print_sanitized_utf16_ascii(units: &[u16], limit: usize) {
    for &unit in units.iter().take(limit) {
        debug_put_char(if (0x20..0x7f).contains(&unit) {
            unit as u8
        } else {
            b'.'
        });
    }
}

#[inline]
fn read_le_u32_at(bytes: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
}

#[inline]
fn read_le_u64_at(bytes: &[u8], offset: usize) -> u64 {
    u64::from_le_bytes(bytes[offset..offset + 8].try_into().unwrap())
}

#[inline]
fn write_le_u16_at(bytes: &mut [u8], offset: usize, value: u16) {
    bytes[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
}

#[inline]
fn write_le_u32_at(bytes: &mut [u8], offset: usize, value: u32) {
    bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

#[inline]
fn write_le_u64_at(bytes: &mut [u8], offset: usize, value: u64) {
    bytes[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
}

fn nt_boolean_arg(value: u64) -> bool {
    (value as u8) != 0
}

#[inline]
fn nt_ulong_arg(value: u64) -> u32 {
    value as u32
}

#[inline]
fn nt_long_arg(value: u64) -> i32 {
    nt_ulong_arg(value) as i32
}

fn debug_register_error_status(error: nt_thread_start::Amd64DebugRegisterError) -> u32 {
    match error {
        nt_thread_start::Amd64DebugRegisterError::UnsupportedControlBits
        | nt_thread_start::Amd64DebugRegisterError::UnsupportedIoBreakpoint => STATUS_NOT_SUPPORTED,
        nt_thread_start::Amd64DebugRegisterError::InvalidBreakpointType
        | nt_thread_start::Amd64DebugRegisterError::InvalidBreakpointAccess
        | nt_thread_start::Amd64DebugRegisterError::InvalidDataBreakpointSize
        | nt_thread_start::Amd64DebugRegisterError::UnalignedDataBreakpoint => {
            STATUS_INVALID_PARAMETER
        }
    }
}

unsafe fn read_amd64_debug_register_state(
    tcb: u64,
) -> Result<nt_thread_start::Amd64DebugRegisterState, u32> {
    let mut slots = [None; nt_thread_start::AMD64_HW_BREAKPOINT_SLOTS];
    for (index, slot) in slots.iter_mut().enumerate() {
        let Some(breakpoint) = crate::win32k_glue::tcb_get_breakpoint(tcb, index as u64) else {
            return Err(STATUS_UNSUCCESSFUL);
        };
        if breakpoint.enabled {
            *slot = Some(nt_thread_start::Amd64DebugBreakpoint {
                address: breakpoint.vaddr,
                breakpoint_type: breakpoint.breakpoint_type,
                size: breakpoint.size,
                access: breakpoint.access,
            });
        }
    }
    nt_thread_start::synthesize_amd64_debug_registers(&slots).map_err(|_| STATUS_UNSUCCESSFUL)
}

unsafe fn apply_amd64_debug_register_plan(
    tcb: u64,
    plan: &[Option<nt_thread_start::Amd64DebugBreakpoint>;
         nt_thread_start::AMD64_HW_BREAKPOINT_SLOTS],
) -> u32 {
    for (index, breakpoint) in plan.iter().copied().enumerate() {
        let status = if let Some(breakpoint) = breakpoint {
            crate::win32k_glue::tcb_set_breakpoint(
                tcb,
                index as u64,
                breakpoint.address,
                breakpoint.breakpoint_type,
                breakpoint.size,
                breakpoint.access,
            )
        } else {
            crate::win32k_glue::tcb_unset_breakpoint(tcb, index as u64)
        };
        if status != 0 {
            return STATUS_UNSUCCESSFUL;
        }
    }
    0
}

#[allow(clippy::too_many_arguments)]
fn trace_named_pipe_io(
    pi: usize,
    badge: u64,
    tid: u64,
    op: &[u8],
    handle: u64,
    fs_context: u64,
    len: usize,
    status: u32,
    info: u64,
    event: u64,
    apc_context: u64,
    sample: &[u8],
) {
    let name_hash = crate::pipe_fid_name_hash(fs_context);
    if fs_context == 0 || name_hash == 0 {
        return;
    }
    let n = NAMED_PIPE_IO_TRACE_N.fetch_add(1, Ordering::Relaxed);
    if n >= 256 {
        return;
    }
    print_str(b"[pipe-io] #");
    print_u64(n);
    print_str(b" pi=");
    print_u64(pi as u64);
    print_str(b" badge=");
    print_u64(badge);
    print_str(b" tid=");
    print_u64(tid);
    print_str(b" op=");
    print_str(op);
    print_str(b" handle=0x");
    print_hex(handle as u32);
    print_str(b" fid=0x");
    print_hex(fs_context as u32);
    print_str(b" name_hash=0x");
    print_hex_u64(name_hash);
    print_str(b" len=");
    print_u64(len as u64);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" info=");
    print_u64(info);
    print_str(b" event=0x");
    print_hex(event as u32);
    print_str(b" apc_ctx=0x");
    print_hex(apc_context as u32);
    print_str(b" sample=");
    for &byte in sample.iter().take(16) {
        print_hex(byte as u32);
        print_str(b" ");
    }
    print_str(b"\n");
}

fn scm_worker_slot_for(nt: &ExecNtHandler) -> Option<usize> {
    match nt.hosted_thread_role_for_badge(nt.current_badge) {
        Some(HostedThreadRole::ScmWorkerSlot { slot }) if slot < TP_WORKER_SLOT_COUNT => Some(slot),
        _ => None,
    }
}

fn trace_handle_object_for(nt: &ExecNtHandler, handle: u64) {
    print_str(b" handle=0x");
    print_hex(handle as u32);
    let Some(pid) = nt.pm_pid_for_pi(nt.pi) else {
        print_str(b" access=no-pid obj=no-pid");
        return;
    };
    if handle > u32::MAX as u64 {
        print_str(b" access=invalid obj=invalid-handle");
        return;
    }
    let process_handle = handle as nt_process::Handle;
    match nt.pm.handle_access(pid, process_handle) {
        Some(access) => {
            print_str(b" access=0x");
            print_hex(access);
        }
        None => print_str(b" access=missing"),
    }
    print_str(b" obj=");
    match nt.pm.lookup_handle(pid, process_handle) {
        Some(nt_process::HandleObject::RoutedFile { file_id, device_id }) => {
            print_str(b"routed-file fid=0x");
            print_hex(file_id as u32);
            print_str(b" dev=0x");
            print_hex(device_id as u32);
        }
        Some(nt_process::HandleObject::File(file_id)) => {
            print_str(b"file fid=0x");
            print_hex(file_id as u32);
        }
        Some(nt_process::HandleObject::OverlayFile(file_id)) => {
            print_str(b"overlay-file fid=0x");
            print_hex(file_id as u32);
        }
        Some(nt_process::HandleObject::Opaque(tag)) => {
            print_str(b"opaque tag=0x");
            print_hex_u64(tag);
        }
        Some(nt_process::HandleObject::DiskFile { .. }) => print_str(b"disk-file"),
        Some(nt_process::HandleObject::Directory { .. }) => print_str(b"directory"),
        Some(nt_process::HandleObject::IoCompletion(_)) => print_str(b"io-completion"),
        Some(nt_process::HandleObject::RegistryKey(_)) => print_str(b"registry-key"),
        Some(nt_process::HandleObject::Process(_)) => print_str(b"process"),
        Some(nt_process::HandleObject::Thread(_)) => print_str(b"thread"),
        Some(nt_process::HandleObject::Section(_)) => print_str(b"section"),
        Some(nt_process::HandleObject::Token(_)) => print_str(b"token"),
        Some(nt_process::HandleObject::TokenObject(_)) => print_str(b"token-object"),
        Some(nt_process::HandleObject::DebugObject(_)) => print_str(b"debug-object"),
        Some(nt_process::HandleObject::Job(_)) => print_str(b"job"),
        None => print_str(b"missing"),
    }
}

#[allow(clippy::too_many_arguments)]
fn trace_scm_worker_read_io(
    nt: &ExecNtHandler,
    slot: usize,
    seq: u64,
    handle: u64,
    event: u64,
    iosb: u64,
    iosb_ok: bool,
    buffer: u64,
    len: usize,
    byte_offset: u64,
    apc_routine: u64,
    apc_context: u64,
    completion_event: Result<Option<usize>, u32>,
    disk_file: Result<Option<(u32, u32, u32)>, u32>,
    overlay_file: Option<u64>,
    route_status: u32,
    route_fid: u64,
    routed: bool,
    pending_file_id: u64,
    status: u32,
    information: u64,
) {
    if seq >= 16 {
        return;
    }
    print_str(b"[scm-worker-read-io] slot=");
    print_u64(slot as u64);
    print_str(b" #");
    print_u64(seq);
    print_str(b" pi=");
    print_u64(nt.pi as u64);
    print_str(b" badge=");
    print_u64(nt.current_badge);
    print_str(b" tid=");
    print_u64(nt.current_tid);
    trace_handle_object_for(nt, handle);
    print_str(b" event=0x");
    print_hex(event as u32);
    print_str(b" iosb=0x");
    print_hex_u64(iosb);
    print_str(b" iosb_ok=");
    print_u64(iosb_ok as u64);
    print_str(b" buffer=0x");
    print_hex_u64(buffer);
    print_str(b" len=");
    print_u64(len as u64);
    print_str(b" byte_offset=0x");
    print_hex_u64(byte_offset);
    print_str(b" apc=0x");
    print_hex_u64(apc_routine);
    print_str(b" apc_ctx=0x");
    print_hex_u64(apc_context);
    print_str(b" event_status=0x");
    match completion_event {
        Ok(Some(index)) => {
            print_hex(0);
            print_str(b" event_idx=");
            print_u64(index as u64);
        }
        Ok(None) => {
            print_hex(0);
            print_str(b" event_idx=none");
        }
        Err(event_status) => {
            print_hex(event_status);
            print_str(b" event_idx=err");
        }
    }
    print_str(b" disk_status=0x");
    match disk_file {
        Ok(Some((_cluster, size, _object_id))) => {
            print_hex(0);
            print_str(b" disk_size=");
            print_u64(size as u64);
        }
        Ok(None) => {
            print_hex(0);
            print_str(b" disk_size=none");
        }
        Err(disk_status) => {
            print_hex(disk_status);
            print_str(b" disk_size=err");
        }
    }
    print_str(b" overlay=0x");
    print_hex(overlay_file.unwrap_or(0) as u32);
    print_str(b" route_status=0x");
    print_hex(route_status);
    print_str(b" route_fid=0x");
    print_hex(route_fid as u32);
    print_str(b" routed=");
    print_u64(routed as u64);
    print_str(b" pending_file=0x");
    print_hex(pending_file_id as u32);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" info=");
    print_u64(information);
    print_str(b"\n");
}

