fn trace_wait_object(
    handler: &ExecNtHandler,
    phase: &[u8],
    handle: u64,
    object: WaitObject,
    timeout_ptr: u64,
    status: u32,
) {
    let trace_winlogon = handler.pi == 2
        && handler.current_badge == 4
        && LSA_RPC_SERVER_ACTIVE_SIGNALLED.load(Ordering::Relaxed) != 0
        && WINLOGON_SAS_MILESTONE.load(Ordering::Relaxed) == 0;
    if handler.pi != 6 && !trace_winlogon {
        return;
    }
    let n = WAIT_OBJECT_TRACE_N.fetch_add(1, Ordering::Relaxed);
    if n >= 192 {
        return;
    }
    print_str(b"[wait-object] pi=");
    print_u64(handler.pi as u64);
    print_str(b" badge=");
    print_u64(handler.current_badge);
    print_str(b" ");
    print_str(phase);
    print_str(b" handle=0x");
    print_hex_u64(handle);
    print_str(b" object=");
    print_str(object.describe());
    print_str(b" id=");
    print_u64(object.id());
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" timeout_ptr=0x");
    print_hex_u64(timeout_ptr);
    print_str(b" ready=");
    print_u64(handler.wait_object_ready(object) as u64);
    if object.kind() == WaitObject::KIND_DISPATCHER {
        let index = object.id() as usize;
        if let Some(entry) = handler.obj_ns.get(index) {
            print_str(b" ns-kind=");
            print_u64(entry.kind as u64);
            print_str(b" name=\"");
            print_sanitized_ascii(entry.name(), 48);
            print_str(b"\"");
            let mut full = [0u8; 192];
            let full_len = handler.query_object_namespace_path(index, &mut full);
            print_str(b" path=\"");
            print_sanitized_ascii(&full[..full_len.min(full.len())], 192);
            print_str(b"\"");
        }
        if let Some((kind, signaled)) = handler.events.query_existing(index as u64) {
            print_str(b" event=");
            print_str(match kind {
                EventKind::Notification => b"notification",
                EventKind::Synchronization => b"synchronization",
            });
            print_str(b" signaled=");
            print_u64(signaled as u64);
        } else if let Some((current, maximum)) = handler.semaphores.query(index as u64) {
            print_str(b" semaphore current=");
            print_u64(current as u64);
            print_str(b" max=");
            print_u64(maximum as u64);
        } else if handler.mutants.contains(index as u64) {
            print_str(b" mutant=1");
        }
    }
    print_str(b"\n");
}

fn trace_tp_worker_event_transition(
    handler: &ExecNtHandler,
    op: &[u8],
    handle: u64,
    index: usize,
    previous: Option<bool>,
    status: u32,
    woken: u64,
) {
    let Some((tp_pi, tp_slot)) = tp_worker_identity_from_badge(handler.current_badge) else {
        return;
    };
    let Some(n) = bump_tp_worker_slot_event_trace(tp_pi, tp_slot) else {
        return;
    };
    if n >= 64 {
        return;
    }
    print_str(b"[tp-worker-event] pi=");
    print_u64(tp_pi as u64);
    print_str(b" slot=");
    print_u64(tp_slot as u64);
    print_str(b" #");
    print_u64(n);
    print_str(b" badge=");
    print_u64(handler.current_badge);
    print_str(b" ");
    print_str(op);
    print_str(b" handle=0x");
    print_hex_u64(handle);
    print_str(b" obj=");
    print_u64(index as u64);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" prev=");
    match previous {
        Some(value) => print_u64(value as u64),
        None => print_str(b"-"),
    }
    print_str(b" woken=");
    print_u64(woken);
    if let Some((kind, signaled)) = handler.events.query_existing(index as u64) {
        print_str(b" event=");
        print_str(match kind {
            EventKind::Notification => b"notification",
            EventKind::Synchronization => b"synchronization",
        });
        print_str(b" signaled=");
        print_u64(signaled as u64);
    }
    print_str(b"\n");
}

fn trace_named_event_object(
    handler: &ExecNtHandler,
    op: &[u8],
    root_idx: usize,
    requested_path: &[u8],
    object_index: Option<usize>,
    status: u32,
    handle: u64,
    existed: bool,
) {
    let n = NAMED_EVENT_TRACE_N.fetch_add(1, Ordering::Relaxed);
    if n >= 256 {
        return;
    }
    print_str(b"[named-event] #");
    print_u64(n);
    print_str(b" pi=");
    print_u64(handler.pi as u64);
    print_str(b" badge=");
    print_u64(handler.current_badge);
    print_str(b" tid=");
    print_u64(handler.current_tid);
    print_str(b" op=");
    print_str(op);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" handle=0x");
    print_hex_u64(handle);
    print_str(b" existed=");
    print_u64(existed as u64);
    print_str(b" root=");
    print_u64(root_idx as u64);
    let mut root_path = [0u8; 192];
    let root_len = handler.query_object_namespace_path(root_idx, &mut root_path);
    print_str(b" root_path=\"");
    print_sanitized_ascii(&root_path[..root_len.min(root_path.len())], 192);
    print_str(b"\" request=\"");
    print_sanitized_ascii(requested_path, 192);
    print_str(b"\"");
    if let Some(index) = object_index {
        let mut full = [0u8; 192];
        let full_len = handler.query_object_namespace_path(index, &mut full);
        print_str(b" object=");
        print_u64(index as u64);
        print_str(b" path=\"");
        print_sanitized_ascii(&full[..full_len.min(full.len())], 192);
        print_str(b"\"");
        if let Some((kind, signaled)) = handler.events.query_existing(index as u64) {
            print_str(b" kind=");
            print_str(match kind {
                EventKind::Notification => b"notification",
                EventKind::Synchronization => b"synchronization",
            });
            print_str(b" signaled=");
            print_u64(signaled as u64);
        }
    }
    print_str(b"\n");
}

fn trace_winlogon_post_lsa_registry(
    handler: &ExecNtHandler,
    op: &[u8],
    key_path: Option<&str>,
    name: &str,
    status: u32,
    ty: Option<u32>,
    data: Option<&[u8]>,
) {
    if handler.pi != 2
        || handler.current_badge != 4
        || LSA_RPC_SERVER_ACTIVE_SIGNALLED.load(Ordering::Relaxed) == 0
        || WINLOGON_SAS_MILESTONE.load(Ordering::Relaxed) != 0
    {
        return;
    }
    let n = WINLOGON_POST_LSA_REGISTRY_TRACE_N.fetch_add(1, Ordering::Relaxed);
    if n >= 128 {
        return;
    }
    print_str(b"[wl-reg] #");
    print_u64(n);
    print_str(b" ");
    print_str(op);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" key=\"");
    if let Some(path) = key_path {
        print_sanitized_ascii(path.as_bytes(), 120);
    }
    print_str(b"\" name=\"");
    print_sanitized_ascii(name.as_bytes(), 64);
    print_str(b"\"");
    if let Some(ty) = ty {
        print_str(b" type=");
        print_u64(ty as u64);
    }
    if let Some(data) = data {
        print_str(b" bytes=");
        print_u64(data.len() as u64);
        if matches!(ty, Some(1 | 2 | 7)) {
            print_str(b" utf16=\"");
            let mut units = 0usize;
            for pair in data.chunks_exact(2) {
                if units >= 96 {
                    break;
                }
                let unit = u16::from_le_bytes([pair[0], pair[1]]);
                if unit == 0 {
                    break;
                }
                debug_put_char(if (0x20..0x7f).contains(&unit) {
                    unit as u8
                } else {
                    b'.'
                });
                units += 1;
            }
            print_str(b"\"");
        }
    }
    print_str(b"\n");
}

#[derive(Clone, Copy, Default)]
struct RegistryKeyStats {
    subkeys: u32,
    max_subkey_name_bytes: u32,
    max_subkey_class_bytes: u32,
    values: u32,
    max_value_name_bytes: u32,
    max_value_data_bytes: u32,
}

unsafe fn registered_frame_basic_information(
    pi: usize,
    page: u64,
) -> Option<nt_address_space::VmBasicInformation> {
    if csrss_frame_get_exact(pi as u64, page).0 == 0 {
        return None;
    }
    let mut allocation_base = page;
    while allocation_base >= 0x1000 {
        let previous = allocation_base - 0x1000;
        if csrss_frame_get_exact(pi as u64, previous).0 == 0 {
            break;
        }
        allocation_base = previous;
    }
    let mut end = page + 0x1000;
    while end < USER_ADDRESS_LIMIT && csrss_frame_get_exact(pi as u64, end).0 != 0 {
        end += 0x1000;
    }
    Some(nt_address_space::VmBasicInformation {
        base_address: page,
        allocation_base,
        allocation_protect: nt_address_space::PAGE_READWRITE,
        region_size: end - page,
        state: nt_address_space::MEM_COMMIT,
        protect: nt_address_space::PAGE_READWRITE,
        type_: nt_address_space::MEM_PRIVATE,
    })
}

#[derive(Copy, Clone)]
struct FixedMappingOverlap {
    base: u64,
    end: u64,
}

fn choose_first_fixed_overlap(
    current: Option<FixedMappingOverlap>,
    candidate: FixedMappingOverlap,
) -> Option<FixedMappingOverlap> {
    match current {
        Some(existing) if existing.base <= candidate.base => Some(existing),
        _ => Some(candidate),
    }
}

unsafe fn registered_frame_first_overlap_unowned_private_vad(
    vm_map: &nt_address_space::VmRegionMap<VM_REGION_CAPACITY>,
    pi: usize,
    base: u64,
    size: u64,
) -> Option<FixedMappingOverlap> {
    let end = base.checked_add(size)?;
    if size == 0 || end <= base {
        return None;
    }
    let mut page = base & !0xfffu64;
    while page < end {
        if csrss_frame_get_exact(pi as u64, page).0 != 0 && vm_map.extent_at(page).is_none() {
            return Some(FixedMappingOverlap {
                base: page,
                end: page + 0x1000,
            });
        }
        page = page.checked_add(0x1000)?;
    }
    None
}

unsafe fn fixed_mapping_authority_first_overlap(
    vm_map: &nt_address_space::VmRegionMap<VM_REGION_CAPACITY>,
    pi: usize,
    base: u64,
    size: u64,
) -> Option<FixedMappingOverlap> {
    let end = base.checked_add(size)?;
    if size == 0 || end <= base {
        return None;
    }
    let mut first = None;
    if KUSER_VA < end && base < KUSER_VA + 0x1000 && kuser_page_alias_get(pi) != 0 {
        first = choose_first_fixed_overlap(
            first,
            FixedMappingOverlap {
                base: KUSER_VA,
                end: KUSER_VA + 0x1000,
            },
        );
    }
    if let Some(range) = process_committed_mapping_first_overlap(pi as u64, base, size) {
        first = choose_first_fixed_overlap(
            first,
            FixedMappingOverlap {
                base: range.base,
                end: range.end(),
            },
        );
    }
    if let Some(frame) = registered_frame_first_overlap_unowned_private_vad(vm_map, pi, base, size)
    {
        first = choose_first_fixed_overlap(first, frame);
    }
    first
}

unsafe fn fixed_mapping_authority_range_overlaps(
    vm_map: &nt_address_space::VmRegionMap<VM_REGION_CAPACITY>,
    pi: usize,
    base: u64,
    size: u64,
) -> bool {
    let Some(end) = base.checked_add(size) else {
        return true;
    };
    if size == 0 || end <= base {
        return true;
    }
    fixed_mapping_authority_first_overlap(vm_map, pi, base, size).is_some()
}

fn align_up_allocation_granularity(value: u64) -> Option<u64> {
    value
        .checked_add(nt_address_space::ALLOCATION_GRANULARITY - 1)
        .map(|value| value & !(nt_address_space::ALLOCATION_GRANULARITY - 1))
}

unsafe fn allocate_private_vad_avoiding_fixed_authorities(
    before: &nt_address_space::VmRegionMap<VM_REGION_CAPACITY>,
    after: &mut nt_address_space::VmRegionMap<VM_REGION_CAPACITY>,
    target_pi: usize,
    requested_base: Option<u64>,
    requested_size: u64,
    allocation_type: u32,
    protection: u32,
    placement_limit: u64,
) -> Result<nt_address_space::VmAllocatePlan, u32> {
    const FIXED_AUTHORITY_PLACEMENT_RETRY_LIMIT: usize =
        VM_REGION_CAPACITY + PROCESS_COMMITTED_MAPPING_CAPACITY + 64;

    let auto_placement = requested_base.is_none();
    if !auto_placement {
        *after = *before;
        let plan = after.allocate_below(
            requested_base,
            requested_size,
            allocation_type,
            protection,
            placement_limit,
        )?;
        if fixed_mapping_authority_range_overlaps(before, target_pi, plan.base, plan.size) {
            return Err(nt_address_space::STATUS_CONFLICTING_ADDRESSES);
        }
        return Ok(plan);
    }

    let top_down = allocation_type & nt_address_space::MEM_TOP_DOWN != 0;
    let mut lower_bound = 0;
    let mut upper_bound = placement_limit;
    for _ in 0..=FIXED_AUTHORITY_PLACEMENT_RETRY_LIMIT {
        *after = *before;
        let plan = after.allocate_between(
            None,
            requested_size,
            allocation_type,
            protection,
            lower_bound,
            upper_bound,
        )?;
        let Some(overlap) =
            fixed_mapping_authority_first_overlap(before, target_pi, plan.base, plan.size)
        else {
            return Ok(plan);
        };
        if top_down {
            if overlap.base <= lower_bound {
                return Err(nt_address_space::STATUS_NO_MEMORY);
            }
            upper_bound = upper_bound.min(overlap.base);
        } else {
            let next_lower = align_up_allocation_granularity(overlap.end)
                .ok_or(nt_address_space::STATUS_NO_MEMORY)?;
            if next_lower <= lower_bound {
                return Err(nt_address_space::STATUS_NO_MEMORY);
            }
            lower_bound = next_lower;
        }
        if lower_bound >= upper_bound {
            return Err(nt_address_space::STATUS_NO_MEMORY);
        }
    }
    Err(nt_address_space::STATUS_NO_MEMORY)
}

fn committed_mapping_effective_page_protection(info: nt_address_space::VmBasicInformation) -> u32 {
    if info.type_ == nt_address_space::MEM_MAPPED {
        nt_address_space::mapped_view_fault_plan(info.protect, false).map_protection
    } else if info.type_ == nt_address_space::MEM_IMAGE {
        nt_address_space::image_view_fault_plan(info.protect, false).map_protection
    } else {
        info.protect
    }
}

impl RegistryKeyStats {
    fn add_subkey(&mut self, name_bytes: usize, class_bytes: usize) {
        self.subkeys = self.subkeys.saturating_add(1);
        self.max_subkey_name_bytes = self
            .max_subkey_name_bytes
            .max(name_bytes.min(u32::MAX as usize) as u32);
        self.max_subkey_class_bytes = self
            .max_subkey_class_bytes
            .max(class_bytes.min(u32::MAX as usize) as u32);
    }

    fn add_value(&mut self, name_bytes: usize, data_bytes: usize) {
        self.values = self.values.saturating_add(1);
        self.max_value_name_bytes = self
            .max_value_name_bytes
            .max(name_bytes.min(u32::MAX as usize) as u32);
        self.max_value_data_bytes = self
            .max_value_data_bytes
            .max(data_bytes.min(u32::MAX as usize) as u32);
    }
}

fn utf16le_byte_len(s: &str) -> usize {
    s.encode_utf16().count().saturating_mul(2)
}

fn append_utf16le(out: &mut alloc::vec::Vec<u8>, s: &str) {
    for w in s.encode_utf16() {
        out.extend_from_slice(&w.to_le_bytes());
    }
}

#[derive(Clone, Copy)]
struct KeyValueInfoLayout {
    total_len: usize,
    minimum_len: usize,
    name_len: usize,
    data_offset: Option<usize>,
    data_len: usize,
}

fn key_value_info_layout(
    class: u64,
    name: &str,
    data_len: usize,
) -> Result<KeyValueInfoLayout, u32> {
    let name_len = utf16le_byte_len(name);
    match class {
        0 => Ok(KeyValueInfoLayout {
            total_len: 0x0cusize
                .checked_add(name_len)
                .ok_or(STATUS_INSUFFICIENT_RESOURCES)?,
            minimum_len: 0x0c,
            name_len,
            data_offset: None,
            data_len: 0,
        }),
        1 | 3 => {
            let name_end = 0x14usize
                .checked_add(name_len)
                .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
            let data_offset = if data_len == 0 {
                None
            } else {
                Some(
                    name_end
                        .checked_add(7)
                        .ok_or(STATUS_INSUFFICIENT_RESOURCES)?
                        & !7usize,
                )
            };
            let total_len = data_offset
                .unwrap_or(name_end)
                .checked_add(data_len)
                .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
            Ok(KeyValueInfoLayout {
                total_len,
                minimum_len: 0x14,
                name_len,
                data_offset,
                data_len,
            })
        }
        2 => Ok(KeyValueInfoLayout {
            total_len: 0x0cusize
                .checked_add(data_len)
                .ok_or(STATUS_INSUFFICIENT_RESOURCES)?,
            minimum_len: 0x0c,
            name_len: 0,
            data_offset: Some(0x0c),
            data_len,
        }),
        4 => Ok(KeyValueInfoLayout {
            total_len: 0x08usize
                .checked_add(data_len)
                .ok_or(STATUS_INSUFFICIENT_RESOURCES)?,
            minimum_len: 0x08,
            name_len: 0,
            data_offset: Some(0x08),
            data_len,
        }),
        _ => Err(STATUS_INVALID_PARAMETER),
    }
}

fn put_u32_le(out: &mut [u8], offset: usize, value: u32) {
    out[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

fn registry_query_leaf_name(path: &str) -> &str {
    path.rsplit('\\')
        .find(|component| !component.is_empty())
        .unwrap_or(path)
}

fn build_registry_key_query_info(
    info_class: u32,
    full_path: &str,
    stats: RegistryKeyStats,
    class_name: Option<&str>,
) -> Result<(alloc::vec::Vec<u8>, usize), u32> {
    const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
    let leaf = registry_query_leaf_name(full_path);
    let leaf_bytes = utf16le_byte_len(leaf);
    let class_bytes = class_name.map(utf16le_byte_len).unwrap_or(0);
    match info_class {
        0 => {
            // KEY_BASIC_INFORMATION
            let header = 0x10usize;
            let mut info = alloc::vec::Vec::with_capacity(header + leaf_bytes);
            info.resize(header, 0);
            info[0x0c..0x10].copy_from_slice(&(leaf_bytes as u32).to_le_bytes());
            append_utf16le(&mut info, leaf);
            Ok((info, header))
        }
        1 => {
            // KEY_NODE_INFORMATION
            let header = 0x18usize;
            let mut info = alloc::vec::Vec::with_capacity(header + leaf_bytes + class_bytes);
            info.resize(header, 0);
            let class_offset = if class_bytes == 0 {
                u32::MAX
            } else {
                (header + leaf_bytes) as u32
            };
            info[0x0c..0x10].copy_from_slice(&class_offset.to_le_bytes());
            info[0x10..0x14].copy_from_slice(&(class_bytes as u32).to_le_bytes());
            info[0x14..0x18].copy_from_slice(&(leaf_bytes as u32).to_le_bytes());
            append_utf16le(&mut info, leaf);
            if let Some(class_name) = class_name {
                append_utf16le(&mut info, class_name);
            }
            Ok((info, header))
        }
        2 => {
            // KEY_FULL_INFORMATION.
            let header = 0x2cusize;
            let mut info = alloc::vec::Vec::new();
            info.resize(header, 0);
            let class_offset = if class_bytes == 0 {
                u32::MAX
            } else {
                header as u32
            };
            info[0x0c..0x10].copy_from_slice(&class_offset.to_le_bytes());
            info[0x10..0x14].copy_from_slice(&(class_bytes as u32).to_le_bytes());
            info[0x14..0x18].copy_from_slice(&stats.subkeys.to_le_bytes());
            info[0x18..0x1c].copy_from_slice(&stats.max_subkey_name_bytes.to_le_bytes());
            info[0x1c..0x20].copy_from_slice(&stats.max_subkey_class_bytes.to_le_bytes());
            info[0x20..0x24].copy_from_slice(&stats.values.to_le_bytes());
            info[0x24..0x28].copy_from_slice(&stats.max_value_name_bytes.to_le_bytes());
            info[0x28..0x2c].copy_from_slice(&stats.max_value_data_bytes.to_le_bytes());
            if let Some(class_name) = class_name {
                append_utf16le(&mut info, class_name);
            }
            Ok((info, header))
        }
        3 => {
            // KEY_NAME_INFORMATION
            let header = 0x04usize;
            let path_bytes = utf16le_byte_len(full_path);
            let mut info = alloc::vec::Vec::with_capacity(header + path_bytes);
            info.resize(header, 0);
            info[0..4].copy_from_slice(&(path_bytes as u32).to_le_bytes());
            append_utf16le(&mut info, full_path);
            Ok((info, header))
        }
        4 => {
            // KEY_CACHED_INFORMATION. sizeof is 0x28 on the x64 NT ABI due tail padding.
            let header = 0x28usize;
            let mut info = alloc::vec::Vec::new();
            info.resize(header, 0);
            info[0x0c..0x10].copy_from_slice(&stats.subkeys.to_le_bytes());
            info[0x10..0x14].copy_from_slice(&stats.max_subkey_name_bytes.to_le_bytes());
            info[0x14..0x18].copy_from_slice(&stats.values.to_le_bytes());
            info[0x18..0x1c].copy_from_slice(&stats.max_value_name_bytes.to_le_bytes());
            info[0x1c..0x20].copy_from_slice(&stats.max_value_data_bytes.to_le_bytes());
            info[0x20..0x24].copy_from_slice(&(leaf_bytes as u32).to_le_bytes());
            Ok((info, header))
        }
        5 => {
            // KEY_USER_FLAGS_INFORMATION. No user flags are attached to our key bodies yet.
            let mut info = alloc::vec::Vec::new();
            info.resize(4, 0);
            Ok((info, 4))
        }
        6 => {
            // KEY_VIRTUALIZATION_INFORMATION. Registry virtualization is disabled in this kernel;
            // expose the real key and report every virtualization bit clear.
            let mut info = alloc::vec::Vec::new();
            info.resize(4, 0);
            Ok((info, 4))
        }
        7 => {
            // KEY_HANDLE_TAGS_INFORMATION. We do not attach per-handle CM tags, so the tag mask is 0.
            let mut info = alloc::vec::Vec::new();
            info.resize(4, 0);
            Ok((info, 4))
        }
        _ => Err(STATUS_INVALID_PARAMETER),
    }
}

#[unsafe(no_mangle)]
