    fn registry_target_path(&self, target: KeyRef) -> Option<alloc::string::String> {
        if target == MACHINE_ROOT_KEY {
            return Some(alloc::string::String::from(r"\registry\machine"));
        }
        if target == USER_ROOT_KEY {
            return Some(alloc::string::String::from(r"\registry\user"));
        }
        if let Some(key) = self.mutable_key_handle(target) {
            return self.mutable_key_path(key);
        }
        if let Some(index) = overlay_key_idx(target) {
            return self.overlay.path(index).map(alloc::string::String::from);
        }
        let (hive, cell) = self.base_hive(target)?;
        let relative = hive.key_path(cell)?;
        let mut full = self.hive_mount_path(hive_sel(target))?;
        if !relative.is_empty() {
            full.push('\\');
            full.push_str(&relative);
        }
        Some(self.overlay_canon(&full))
    }

    /// Resolve a full NT path inside the `\Registry\User` namespace against the mount table.
    /// `None` if no mount owns the path, or the mount owns it but has no such key.
    pub(crate) fn resolve_user_key(&self, full_path: &str) -> Option<KeyRef> {
        let canon = nt_hive_core::canon_path(full_path);
        for mount in &self.hive_mounts {
            let Some(hive) = mount.hive.as_ref() else {
                if canon == mount.canon
                    || canon
                        .strip_prefix(mount.canon.as_str())
                        .is_some_and(|rest| rest.starts_with('\\'))
                {
                    return None;
                }
                continue;
            };
            if canon == mount.canon {
                return Some(mount.sel | hive.root());
            }
            let Some(rest) = canon
                .strip_prefix(mount.canon.as_str())
                .and_then(|rest| rest.strip_prefix('\\'))
            else {
                continue;
            };
            // The mount OWNS this path: it resolves here or nowhere (never fall through to a
            // different mount, which would let `\Registry\User\<sid>\x` answer out of `.Default`).
            return hive.open_key(rest).map(|cell| mount.sel | cell);
        }
        None
    }

    /// The effective OBJECT_ATTRIBUTES name for a registry open: the mirror-read `path`, or — when
    /// that came back EMPTY because the name is an `RTL_CONSTANT_STRING` in a `.rdata` page the
    /// process never dereferenced — the PE-backed read. (`RegOpenKeyExW(HKEY_USERS, L".Default")`
    /// in `userenv!CreateUserHive` is exactly that case.)
    ///
    /// # Safety
    /// `oa` is a caller VA read through the cross-AS reader, which bounds-checks every access.
    unsafe fn effective_objattr_name(&self, path: &str, oa: u64) -> alloc::string::String {
        if !path.is_empty() {
            return alloc::string::String::from(path);
        }
        self.read_registry_objattr_name(oa)
    }

    /// Decode a registry UNICODE_STRING from the calling process. Prefer the ordinary live-memory
    /// mirror (stack/heap/resident image), then fall back to the PE-backed reader for untouched DLL
    /// `.rdata` literals. This is the CM equivalent of ProbeForRead: dynamic names created by
    /// userenv must not be lost just because other registry callers need static-literal recovery.
    unsafe fn read_registry_ustr_units(&self, ustr_va: u64) -> alloc::vec::Vec<u16> {
        if ustr_va == 0 {
            return alloc::vec::Vec::new();
        }
        let mut expected_units = None;
        let mut len = [0u8; 2];
        if self.xas_read(ustr_va, &mut len) {
            let byte_len = u16::from_le_bytes(len) as usize;
            if byte_len & 1 == 0 {
                expected_units = Some((byte_len / 2).min(1024));
            }
        }
        let live = smss_read_ustr(ustr_va);
        if expected_units.is_some_and(|n| live.len() >= n)
            || expected_units.is_none() && !live.is_empty()
        {
            return live;
        }
        let backed = self.read_ustr_pe(ustr_va);
        if backed.len() > live.len() {
            backed
        } else {
            live
        }
    }

    unsafe fn read_registry_ustr_name(&self, ustr_va: u64) -> alloc::string::String {
        utf16_units_to_string(&self.read_registry_ustr_units(ustr_va))
    }

    unsafe fn read_registry_objattr_name(&self, oa_va: u64) -> alloc::string::String {
        if oa_va == 0 {
            return alloc::string::String::new();
        }
        let mut p = [0u8; 8];
        if !self.xas_read(oa_va + 0x10, &mut p) {
            return alloc::string::String::new();
        }
        self.read_registry_ustr_name(u64::from_le_bytes(p))
    }

    /// Split an NT registry path into its non-empty components.
    fn key_components(path: &str) -> alloc::vec::Vec<&str> {
        path.split('\\').filter(|c| !c.is_empty()).collect()
    }

    fn virtual_registry_root_target_from_canon(canon: &str) -> Option<KeyRef> {
        match canon {
            r"\registry\machine" => Some(MACHINE_ROOT_KEY),
            r"\registry\user" => Some(USER_ROOT_KEY),
            _ => None,
        }
    }

    /// True if `comps` is exactly `Registry\Machine` (the predefined `HKEY_LOCAL_MACHINE` root).
    fn is_machine_root_comps(comps: &[&str]) -> bool {
        comps.len() == 2
            && comps[0].eq_ignore_ascii_case("Registry")
            && comps[1].eq_ignore_ascii_case("Machine")
    }

    fn is_machine_namespace_root_component(component: &str) -> bool {
        component.eq_ignore_ascii_case("System")
            || component.eq_ignore_ascii_case("Software")
            || component.eq_ignore_ascii_case("Security")
            || component.eq_ignore_ascii_case("Sam")
            || component.eq_ignore_ascii_case("Hardware")
            || component.eq_ignore_ascii_case("BCD00000000")
    }

    /// Resolve the FULL NT path of a `\Registry\Machine` open target. The name may be absolute
    /// (`\Registry\Machine\...`), relative to the machine root sentinel / an already-open HKLM key,
    /// or a machine-hive-root relative name such as `System\CurrentControlSet\...`.
    fn machine_namespace_target(
        &self,
        root_target: Option<KeyRef>,
        name: &str,
    ) -> Option<alloc::string::String> {
        let comps = Self::key_components(name);
        let base = match root_target {
            None => {
                if Self::is_machine_root_comps(&comps) {
                    return Some(alloc::string::String::from(name));
                }
                if comps.len() > 2
                    && comps[0].eq_ignore_ascii_case("Registry")
                    && comps[1].eq_ignore_ascii_case("Machine")
                {
                    return Some(alloc::string::String::from(name));
                }
                if comps
                    .first()
                    .is_some_and(|component| Self::is_machine_namespace_root_component(component))
                {
                    let mut full = alloc::string::String::from(r"\Registry\Machine");
                    if !name.is_empty() {
                        full.push('\\');
                        full.push_str(name);
                    }
                    return Some(full);
                }
                return None;
            }
            Some(MACHINE_ROOT_KEY) => alloc::string::String::from(r"\Registry\Machine"),
            Some(target) => {
                let path = self.registry_target_path(target)?;
                if path != r"\registry\machine" && !path.starts_with(r"\registry\machine\") {
                    return None;
                }
                path
            }
        };
        let mut full = base;
        if !name.is_empty() {
            full.push('\\');
            full.push_str(name);
        }
        Some(full)
    }

    /// True if `comps` is exactly `Registry\User` (the predefined `HKEY_USERS` root).
    fn is_user_root_comps(comps: &[&str]) -> bool {
        comps.len() == 2
            && comps[0].eq_ignore_ascii_case("Registry")
            && comps[1].eq_ignore_ascii_case("User")
    }

    /// Resolve the FULL NT path of a `\Registry\User` open/load/unload target: either absolute
    /// (`\Registry\User\…`) or relative to the `HKEY_USERS` root sentinel / a key already inside
    /// the namespace. `None` when the target is not in the user namespace at all.
    fn user_namespace_target(
        &self,
        root_target: Option<KeyRef>,
        name: &str,
    ) -> Option<alloc::string::String> {
        let base = match root_target {
            None => {
                let comps = Self::key_components(name);
                if comps.len() > 2
                    && comps[0].eq_ignore_ascii_case("Registry")
                    && comps[1].eq_ignore_ascii_case("User")
                {
                    return Some(alloc::string::String::from(name));
                }
                return None;
            }
            Some(USER_ROOT_KEY) => alloc::string::String::from(r"\Registry\User"),
            Some(target) => {
                let path = self.registry_target_path(target)?;
                if path != r"\registry\user" && !path.starts_with(r"\registry\user\") {
                    return None;
                }
                path
            }
        };
        let mut full = base;
        if !name.is_empty() {
            full.push('\\');
            full.push_str(name);
        }
        Some(full)
    }

    /// `NtOpenKey` for the `\Registry\User` (`HKEY_USERS`) namespace. `Some(status)` when this open
    /// belongs to the namespace (and is therefore fully answered here), `None` to let the caller's
    /// existing resolution run unchanged.
    ///
    /// # Safety
    /// Reads the caller's OBJECT_ATTRIBUTES through the bounds-checked cross-AS reader and mints a
    /// handle into the current process's own EPROCESS handle table.
    unsafe fn open_user_namespace_key(
        &mut self,
        root_target: Option<KeyRef>,
        path: &str,
        oa: u64,
        args: &[u64],
    ) -> Option<u32> {
        let desired_access = nt_ulong_arg(args[1]);
        // An EMPTY mirror-read name means the OA names an `RTL_CONSTANT_STRING` in a `.rdata` page
        // the process never dereferenced — `userenv!UpdateUsersShellFolderSettings` opens
        // `SOFTWARE\…\Shell Folders` relative to the user-hive handle exactly that way — so recover
        // it from the backing PE. Only reached for an empty name, and a name that turns out NOT to
        // be in this namespace falls through with the caller's original `path` untouched.
        let name = self.effective_objattr_name(path, oa);
        // (a) The predefined `HKEY_USERS` root itself (advapi32's `MapDefaultKey`).
        if root_target.is_none() && Self::is_user_root_comps(&Self::key_components(&name)) {
            USER_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            return Some(self.mint_registry_key(USER_ROOT_KEY, desired_access, args[0]));
        }
        let full = self.user_namespace_target(root_target, &name)?;
        // (b) Overlay/mutable/base resolution follows the same full-path authority as machine
        // hives. A miss inside the namespace is a real NOT_FOUND, never a fabricated key.
        if USER_NS_TRACED.fetch_add(1, Ordering::Relaxed) < 40 {
            print_str(b"[user-ns] pi=");
            print_u64(self.pi as u64);
            print_str(b" open ");
            print_ascii_str(&full);
            print_str(b" -> ");
            print_u64(self.resolve_user_key(&full).unwrap_or(0) as u64);
            print_str(b"\n");
        }
        if let Some(status) = self.open_registry_full_path(&full, desired_access, args[0]) {
            if status == 0xC000_0034
                && self.current_process_is_winlogon()
                && post_profile_phase()
                && POST_PROFILE_TRACED.fetch_add(1, Ordering::Relaxed) < 64
            {
                print_str(b"[post-profile] open MISS ");
                print_ascii_str(&full);
                print_str(b"\n");
            }
            return Some(status);
        }
        if self.current_process_is_winlogon()
            && post_profile_phase()
            && POST_PROFILE_TRACED.fetch_add(1, Ordering::Relaxed) < 64
        {
            print_str(b"[post-profile] open MISS ");
            print_ascii_str(&full);
            print_str(b"\n");
        }
        Some(0xC000_0034) // STATUS_OBJECT_NAME_NOT_FOUND
    }

    /// Explorer's COM activation path uses HKCR, which ReactOS maps to
    /// `\Registry\Machine\Software\Classes`. Resolve that subtree for pi 6 with PE-backed
    /// OBJECT_ATTRIBUTES reads so DLL `.rdata` literals work the same way as they do for services.
    ///
    /// # Safety
    /// Reads the caller's OBJECT_ATTRIBUTES through the bounds-checked cross-AS reader and mints a
    /// handle into the current process's own EPROCESS handle table.
    unsafe fn open_explorer_classes_key(
        &mut self,
        root_target: Option<KeyRef>,
        path: &str,
        oa: u64,
        args: &[u64],
    ) -> Option<u32> {
        if !self.current_process_is_interactive_shell() {
            return None;
        }
        let desired_access = nt_ulong_arg(args[1]);
        let name = self.effective_objattr_name(path, oa);
        if root_target.is_none() {
            let comps = Self::key_components(&name);
            if comps.len() == 2
                && comps[0].eq_ignore_ascii_case("Registry")
                && comps[1].eq_ignore_ascii_case("Machine")
            {
                return Some(self.mint_registry_key(MACHINE_ROOT_KEY, desired_access, args[0]));
            }
        }

        let full = if root_target == Some(MACHINE_ROOT_KEY) {
            let mut full = alloc::string::String::from(r"\Registry\Machine");
            if !name.is_empty() {
                full.push('\\');
                full.push_str(&name);
            }
            Some(full)
        } else if let Some(parent_path) =
            root_target.and_then(|target| self.registry_target_path(target))
        {
            if parent_path != r"\registry\machine"
                && !parent_path.starts_with(r"\registry\machine\")
            {
                return None;
            }
            let mut full = parent_path;
            if !name.is_empty() {
                full.push('\\');
                full.push_str(&name);
            }
            Some(full)
        } else if root_target.is_none() {
            Some(name)
        } else {
            None
        }?;

        let canon = self.overlay_canon(&full);
        if canon != r"\registry\machine\software\classes"
            && !canon.starts_with(r"\registry\machine\software\classes\")
        {
            return None;
        }

        let bit = explorer_shell_com_class_bit_for_path(&canon);
        if let Some(status) = self.open_registry_full_path(&full, desired_access, args[0]) {
            if status == 0 && bit != 0 {
                EXPLORER_SHELL_COM_CLASS_OPEN_MASK.fetch_or(bit, Ordering::Relaxed);
            }
            return Some(status);
        }

        Some(0xC000_0034)
    }

    /// `NtOpenKey` for the `\Registry\Machine` (`HKEY_LOCAL_MACHINE`) namespace. This is the same
    /// overlay/mutable/base authority used by value queries and relative child opens; a miss inside
    /// the namespace is a real registry miss, not a synthetic success.
    ///
    /// # Safety
    /// Reads the caller's OBJECT_ATTRIBUTES through the bounds-checked cross-AS reader and mints a
    /// handle into the current process's own EPROCESS handle table.
    unsafe fn open_hosted_machine_key(
        &mut self,
        root_target: Option<KeyRef>,
        path: &str,
        oa: u64,
        args: &[u64],
    ) -> Option<u32> {
        let desired_access = nt_ulong_arg(args[1]);
        let name = self.effective_objattr_name(path, oa);
        let full = self.machine_namespace_target(root_target, &name)?;
        let canon = self.overlay_canon(&full);
        if canon == r"\registry\machine" {
            return Some(self.mint_registry_key(MACHINE_ROOT_KEY, desired_access, args[0]));
        }

        let bit = explorer_shell_com_class_bit_for_path(&canon);
        if let Some(status) = self.open_registry_full_path(&full, desired_access, args[0]) {
            if status == 0 && bit != 0 {
                EXPLORER_SHELL_COM_CLASS_OPEN_MASK.fetch_or(bit, Ordering::Relaxed);
            }
            return Some(status);
        }

        Some(0xC000_0034)
    }

    /// Bounded trace of a registry MISS in winlogon's post-profile window: which key, which value.
    fn trace_post_profile_registry(&self, what: &[u8], key: KeyRef, name: &str) {
        if POST_PROFILE_TRACED.fetch_add(1, Ordering::Relaxed) >= 64 {
            return;
        }
        print_str(b"[post-profile] ");
        print_str(what);
        print_str(b" MISS key=");
        match self.registry_target_path(key) {
            Some(path) => print_ascii_str(&path),
            None => {
                print_str(b"<non-hive 0x");
                print_hex(key);
                print_str(b">");
            }
        }
        print_str(b" value=\"");
        print_ascii_str(name);
        print_str(b"\"\n");
    }

    /// Read a whole file named by an NT path into `dst`, returning its byte length. Serves
    /// `NtLoadKey`'s SourceFile: the writable volume first (where a copied profile's `ntuser.dat`
    /// lives), then the read-only `\reactos` FAT reader.
    ///
    /// # Safety
    /// Borrows the mounted writable volume for the duration of the copy; single-threaded executive.
    unsafe fn read_file_by_nt_path(name16: &[u16], dst: &mut [u8]) -> Option<usize> {
        let mut folded = [0u8; FILE_OBJECT_NAME_CAP];
        let mut relative = [0u8; FILE_VOLUME_RELATIVE_CAP];
        if let Some(relative_len) =
            crate::writable_fs::writable_path_into(name16, &mut folded, &mut relative)
        {
            let fs = crate::writable_fs::writable_fs()?;
            let bytes = fs.file_bytes_relative(&relative[..relative_len])?;
            if bytes.len() > dst.len() {
                return None;
            }
            dst[..bytes.len()].copy_from_slice(bytes);
            return Some(bytes.len());
        }
        None
    }

    unsafe fn nt_save_key(&mut self, key_handle: u64, file_handle: u64) -> u32 {
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        const STATUS_REGISTRY_CORRUPT: u32 = 0xC000_014C;
        const KEY_READ: u32 = 0x0002_0019;
        NT_SAVE_KEY_CALLS.fetch_add(1, Ordering::Relaxed);

        if !self.current_token_has_privilege(nt_security::SE_BACKUP) {
            NT_SAVE_KEY_NO_PRIVILEGE.fetch_add(1, Ordering::Relaxed);
            return STATUS_PRIVILEGE_NOT_HELD;
        }

        let file_id = match self.overlay_write_file_id_for(file_handle) {
            Ok(file_id) => file_id,
            Err(status) => {
                if status == nt_fs::STATUS_INVALID_DEVICE_REQUEST {
                    NT_SAVE_KEY_INVALID_TARGET.fetch_add(1, Ordering::Relaxed);
                }
                return status;
            }
        };
        let key = match self.resolve_registry_key(key_handle, KEY_READ) {
            Ok(key) => key,
            Err(status) => return status,
        };
        if is_virtual_registry_key(key)
            || overlay_key_idx(key).is_some()
            || key == MACHINE_ROOT_KEY
            || key == USER_ROOT_KEY
        {
            return STATUS_ACCESS_DENIED;
        }
        let owned_image;
        let image = if let Some(mutable_key) = self.mutable_registry_key(key) {
            let Some(hive) = self.mutable_hives.hive(mutable_key.hive) else {
                return STATUS_INVALID_HANDLE;
            };
            owned_image = {
                let _alloc_ctx =
                    crate::allocator::enter_context(crate::allocator::ALLOC_CTX_HIVE_ENCODE);
                let encoded = if mutable_key.key == hive.root() {
                    nt_hive_core::try_encode_image(hive)
                        .map_err(nt_hive_core::HiveSubtreeEncodeError::Encode)
                } else {
                    nt_hive_core::try_encode_subtree_image(hive, mutable_key.key)
                };
                match encoded {
                    Ok(image) => image,
                    Err(nt_hive_core::HiveSubtreeEncodeError::InvalidRoot) => {
                        return STATUS_INVALID_HANDLE;
                    }
                    Err(nt_hive_core::HiveSubtreeEncodeError::Encode(err)) => {
                        print_str(b"[cm-save] mutable hive image encode failed err=");
                        print_str(match err {
                            nt_hive_core::HiveEncodeError::OutOfMemory => b"out-of-memory",
                            nt_hive_core::HiveEncodeError::SizeOverflow => b"size-overflow",
                        });
                        print_str(b"\n");
                        return STATUS_INSUFFICIENT_RESOURCES;
                    }
                }
            };
            owned_image.as_slice()
        } else {
            let (hive, cell) = match self.base_hive(key) {
                Some(hive) => hive,
                None => return STATUS_INVALID_HANDLE,
            };
            if cell != hive.root() {
                let _alloc_ctx =
                    crate::allocator::enter_context(crate::allocator::ALLOC_CTX_REGF_IMPORT);
                let imported = match nt_hive_regf::try_import_regf_subtree_into_hive(
                    hive,
                    cell,
                    hive_kind_for_selector(hive_sel(key)),
                ) {
                    Ok((hive, _stats)) => hive,
                    Err(nt_hive_regf::RegfHiveImportError::InvalidSourceKey) => {
                        return STATUS_INVALID_HANDLE;
                    }
                    Err(
                        nt_hive_regf::RegfHiveImportError::InvalidKey
                        | nt_hive_regf::RegfHiveImportError::InvalidSubkeyList
                        | nt_hive_regf::RegfHiveImportError::InvalidValue
                        | nt_hive_regf::RegfHiveImportError::InvalidClass
                        | nt_hive_regf::RegfHiveImportError::InvalidSecurityDescriptor
                        | nt_hive_regf::RegfHiveImportError::UnsupportedValueType(_)
                        | nt_hive_regf::RegfHiveImportError::DepthLimitOrCycle,
                    ) => {
                        return STATUS_REGISTRY_CORRUPT;
                    }
                    Err(nt_hive_regf::RegfHiveImportError::OutOfMemory) => {
                        return STATUS_INSUFFICIENT_RESOURCES;
                    }
                };
                owned_image = match nt_hive_core::try_encode_image(&imported) {
                    Ok(image) => image,
                    Err(nt_hive_core::HiveEncodeError::OutOfMemory)
                    | Err(nt_hive_core::HiveEncodeError::SizeOverflow) => {
                        return STATUS_INSUFFICIENT_RESOURCES;
                    }
                };
                owned_image.as_slice()
            } else {
                hive.bytes()
            }
        };
        let image_len = image.len();

        let zero = 0u64.to_le_bytes();
        let mut status = unsafe {
            crate::writable_fs::set_information(file_id, nt_fs::FILE_END_OF_FILE_INFORMATION, &zero)
        };
        if status != nt_fs::STATUS_SUCCESS {
            return status;
        }
        let (write_status, written) = unsafe { crate::writable_fs::write(file_id, Some(0), image) };
        if write_status != nt_fs::STATUS_SUCCESS {
            return write_status;
        }
        if written != image_len {
            return nt_fs::STATUS_INSUFFICIENT_RESOURCES;
        }
        let eof = (image_len as u64).to_le_bytes();
        status = unsafe {
            crate::writable_fs::set_information(file_id, nt_fs::FILE_END_OF_FILE_INFORMATION, &eof)
        };
        if status != nt_fs::STATUS_SUCCESS {
            return status;
        }
        status = unsafe { crate::writable_fs::flush(file_id) };
        if status == nt_fs::STATUS_SUCCESS {
            self.writable_fs_dirty = true;
            self.writable_fs_commit_required = true;
            NT_SAVE_KEY_ROOT_SAVED.fetch_add(1, Ordering::Relaxed);
            NT_SAVE_KEY_BYTES.store(image_len as u64, Ordering::Relaxed);
        }
        status
    }

    fn boot_mutable_hive_checkpoint_path(hive_sel: u32) -> Option<&'static str> {
        match hive_sel {
            HIVE_SEL_SYSTEM => Some(crate::writable_fs::CONFIG_SYSTEM_HIVE_PATH),
            HIVE_SEL_SOFTWARE => Some(crate::writable_fs::CONFIG_SOFTWARE_HIVE_PATH),
            HIVE_SEL_SECURITY => Some(crate::writable_fs::CONFIG_SECURITY_HIVE_PATH),
            HIVE_SEL_SAM => Some(crate::writable_fs::CONFIG_SAM_HIVE_PATH),
            HIVE_SEL_USER_DEFAULT => Some(crate::writable_fs::CONFIG_DEFAULT_HIVE_PATH),
            _ => None,
        }
    }

    fn mutable_hive_flush_failure_status(err: nt_hive_core::HiveFlushError) -> u32 {
        match err {
            nt_hive_core::HiveFlushError::Encode(_) => nt_fs::STATUS_INSUFFICIENT_RESOURCES,
            nt_hive_core::HiveFlushError::Io(_) => STATUS_UNSUCCESSFUL,
        }
    }

    fn print_mutable_hive_flush_failure(err: nt_hive_core::HiveFlushError) {
        match err {
            nt_hive_core::HiveFlushError::Encode(nt_hive_core::HiveEncodeError::OutOfMemory) => {
                print_str(b"encode-out-of-memory")
            }
            nt_hive_core::HiveFlushError::Encode(nt_hive_core::HiveEncodeError::SizeOverflow) => {
                print_str(b"encode-size-overflow")
            }
            nt_hive_core::HiveFlushError::Io(nt_hive_core::HiveIoError::Io) => print_str(b"io"),
            nt_hive_core::HiveFlushError::Io(nt_hive_core::HiveIoError::NotSupported) => {
                print_str(b"not-supported")
            }
        }
    }

    fn ensure_user_default_mutable_mount_only(&mut self) {
        if let Some(mount) = self
            .hive_mounts
            .iter_mut()
            .find(|mount| mount.sel == HIVE_SEL_USER_DEFAULT)
        {
            mount.hive = None;
            return;
        }
        let mount = hive_mount(HIVE_SEL_USER_DEFAULT);
        self.hive_mounts.push(HiveMount {
            sel: HIVE_SEL_USER_DEFAULT,
            canon: nt_hive_core::canon_path(mount),
            mount: alloc::string::String::from(mount),
            file: alloc::string::String::from(crate::writable_fs::CONFIG_DEFAULT_HIVE_PATH),
            hive: None,
            slot: None,
            dynamic: false,
        });
    }

    fn refresh_boot_hive_checkpoint_from_path(&mut self, hive_sel: u32, file_path: &str) -> bool {
        let mount_path = hive_mount(hive_sel);
        let log_bytes = unsafe { crate::writable_fs::hive_log_bytes_owned_if_mounted(file_path) }
            .unwrap_or_default();
        let Some(bytes) = (unsafe { crate::writable_fs::file_bytes_if_mounted(file_path) }) else {
            if log_bytes.is_empty() {
                return false;
            }
            let Some(hive) = self.mutable_hives.hive_mut(hive_sel) else {
                return false;
            };
            let base_sequence = hive.sequence;
            let last_sequence = nt_hive_core::replay_log(hive, &log_bytes, base_sequence);
            self.mutable_hives.clear_hive_dirty(hive_sel);
            let root_subkeys = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.subkey_count(hive.root()) as u64);
            print_str(b"[cm-restore] boot hive journal replayed ");
            print_ascii_str(mount_path);
            print_str(b" <- ");
            print_ascii_str(file_path);
            print_str(b" primary=installed-source root-subkeys=");
            print_u64(root_subkeys);
            print_str(b" log-bytes=");
            print_u64(log_bytes.len() as u64);
            print_str(b" sequence=");
            print_u64(base_sequence);
            print_str(b"..");
            print_u64(last_sequence);
            print_str(b"\n");
            return last_sequence > base_sequence;
        };
        if let Ok(mut hive) = nt_hive_core::decode_image(bytes) {
            let base_sequence = hive.sequence;
            let last_sequence = nt_hive_core::replay_log(&mut hive, &log_bytes, base_sequence);
            let root_subkeys = hive.subkey_count(hive.root()) as u64;
            if self
                .mutable_hives
                .mount(mount_path, hive_sel, hive)
                .is_err()
            {
                print_str(b"[cm-restore] boot hive checkpoint rejected invalid SYSTEM selection ");
                print_ascii_str(file_path);
                print_str(b"\n");
                return false;
            }
            self.mutable_hives.clear_hive_dirty(hive_sel);
            if hive_sel == HIVE_SEL_USER_DEFAULT {
                self.ensure_user_default_mutable_mount_only();
            }
            print_str(b"[cm-restore] boot hive checkpoint mounted ");
            print_ascii_str(mount_path);
            print_str(b" <- ");
            print_ascii_str(file_path);
            print_str(b" bytes=");
            print_u64(bytes.len() as u64);
            print_str(b" root-subkeys=");
            print_u64(root_subkeys);
            print_str(b" log-bytes=");
            print_u64(log_bytes.len() as u64);
            print_str(b" sequence=");
            print_u64(base_sequence);
            print_str(b"..");
            print_u64(last_sequence);
            print_str(b" format=core\n");
            return true;
        }
        if let Some(regf) = RegfHive::new(bytes) {
            let root_subkeys = regf.subkeys(regf.root()).len() as u64;
            if mount_mutable_regf_hive(&mut self.mutable_hives, hive_sel, mount_path, &regf)
                .is_err()
            {
                print_str(b"[cm-restore] boot regf checkpoint rejected ");
                print_ascii_str(file_path);
                print_str(b"\n");
                return false;
            }
            let base_sequence = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.sequence);
            let last_sequence = if let Some(hive) = self.mutable_hives.hive_mut(hive_sel) {
                nt_hive_core::replay_log(hive, &log_bytes, base_sequence)
            } else {
                base_sequence
            };
            self.mutable_hives.clear_hive_dirty(hive_sel);
            if hive_sel == HIVE_SEL_USER_DEFAULT {
                self.ensure_user_default_mutable_mount_only();
            }
            print_str(b"[cm-restore] boot hive checkpoint mounted ");
            print_ascii_str(mount_path);
            print_str(b" <- ");
            print_ascii_str(file_path);
            print_str(b" bytes=");
            print_u64(bytes.len() as u64);
            print_str(b" root-subkeys=");
            print_u64(root_subkeys);
            print_str(b" log-bytes=");
            print_u64(log_bytes.len() as u64);
            print_str(b" sequence=");
            print_u64(base_sequence);
            print_str(b"..");
            print_u64(last_sequence);
            print_str(b" format=regf\n");
            return true;
        }
        print_str(b"[cm-restore] boot hive checkpoint rejected ");
        print_ascii_str(file_path);
        print_str(b" bytes=");
        print_u64(bytes.len() as u64);
        print_str(b"\n");
        false
    }

    pub(crate) fn refresh_boot_hive_checkpoints_from_writable_config(&mut self) -> bool {
        if self.boot_hive_checkpoints_refreshed {
            return false;
        }
        self.boot_hive_checkpoints_refreshed = true;
        let mut mounted = false;
        for (hive_sel, file_path) in [
            (
                HIVE_SEL_SOFTWARE,
                crate::writable_fs::CONFIG_SOFTWARE_HIVE_PATH,
            ),
            (
                HIVE_SEL_SECURITY,
                crate::writable_fs::CONFIG_SECURITY_HIVE_PATH,
            ),
            (HIVE_SEL_SAM, crate::writable_fs::CONFIG_SAM_HIVE_PATH),
            (
                HIVE_SEL_USER_DEFAULT,
                crate::writable_fs::CONFIG_DEFAULT_HIVE_PATH,
            ),
        ] {
            mounted |= self.refresh_boot_hive_checkpoint_from_path(hive_sel, file_path);
        }
        if mounted {
            self.registry_services_order_cache_valid = false;
            print_str(b"[cm-restore] boot hive checkpoints refreshed from writable config\n");
        }
        mounted
    }

    fn checkpoint_boot_mutable_hive(&mut self, hive_sel: u32, dirty_cells: usize) -> u32 {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        if dirty_cells == 0 {
            return nt_fs::STATUS_SUCCESS;
        }
        let Some(file_path) = Self::boot_mutable_hive_checkpoint_path(hive_sel) else {
            return STATUS_INVALID_HANDLE;
        };
        print_str(b"[cm-flush] boot hive checkpoint begin dirty-cells=");
        print_u64(dirty_cells as u64);
        print_str(b" heap-headroom=");
        print_u64(crate::allocator::remaining() as u64);
        print_str(b" path=");
        print_ascii_str(file_path);
        print_str(b"\n");
        let image_len = {
            let Some(hive) = self.mutable_hives.hive(hive_sel) else {
                return STATUS_INVALID_HANDLE;
            };
            match nt_hive_core::encoded_image_len(hive) {
                Ok(len) => len,
                Err(err) => {
                    REG_FLUSH_KEY_BOOT_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
                    print_str(b"[cm-flush] boot hive checkpoint measure failed err=");
                    print_str(match err {
                        nt_hive_core::HiveEncodeError::OutOfMemory => b"out-of-memory",
                        nt_hive_core::HiveEncodeError::SizeOverflow => b"size-overflow",
                    });
                    print_str(b" path=");
                    print_ascii_str(file_path);
                    print_str(b"\n");
                    return nt_fs::STATUS_INSUFFICIENT_RESOURCES;
                }
            }
        };
        let flush_result = {
            let _alloc_ctx =
                crate::allocator::enter_context(crate::allocator::ALLOC_CTX_WRITABLE_ATOMIC_WRITE);
            let Some(hive) = self.mutable_hives.hive_mut(hive_sel) else {
                return STATUS_INVALID_HANDLE;
            };
            let provider = crate::writable_fs::WritableHiveIoProvider::new(file_path);
            let mut manager = nt_hive_core::HiveManager::new(provider);
            manager.try_flush(hive)
        };
        if let Err(err) = flush_result {
            REG_FLUSH_KEY_BOOT_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
            print_str(b"[cm-flush] boot hive checkpoint failed err=");
            Self::print_mutable_hive_flush_failure(err);
            print_str(b" path=");
            print_ascii_str(file_path);
            print_str(b"\n");
            return Self::mutable_hive_flush_failure_status(err);
        }
        let compacted = {
            let Some(hive) = self.mutable_hives.hive_mut(hive_sel) else {
                return STATUS_INVALID_HANDLE;
            };
            hive.compact_value_blobs()
        };
        match compacted {
            Ok(compaction) if compaction.reclaimed_blobs() != 0 => {
                print_str(b"[cm-flush] compacted hive value blobs=");
                print_u64(compaction.blobs_before as u64);
                print_str(b"->");
                print_u64(compaction.blobs_after as u64);
                print_str(b" bytes=");
                print_u64(compaction.bytes_before as u64);
                print_str(b"->");
                print_u64(compaction.bytes_after as u64);
                print_str(b" path=");
                print_ascii_str(file_path);
                print_str(b"\n");
            }
            Ok(_) => {}
            Err(err) => {
                print_str(b"[cm-flush] hive value compaction deferred err=");
                print_str(match err {
                    nt_hive_core::HiveValueBlobCompactError::MissingBlob => b"missing-blob",
                    nt_hive_core::HiveValueBlobCompactError::OutOfMemory => b"out-of-memory",
                });
                print_str(b" path=");
                print_ascii_str(file_path);
                print_str(b"\n");
            }
        }
        {
            self.writable_fs_dirty = true;
            self.writable_fs_commit_required = true;
            REG_FLUSH_KEY_BOOT_HIVE_CHECKPOINTS.fetch_add(1, Ordering::Relaxed);
            REG_FLUSH_KEY_BOOT_HIVE_BYTES.store(image_len as u64, Ordering::Relaxed);
            if let Some(bit) = Self::boot_mutable_hive_pending_bit(hive_sel) {
                self.mutable_hive_journal_pending_boot_mask &= !bit;
                self.mutable_hive_journal_dirty_boot_mask &= !bit;
            }
            print_str(b"[cm-flush] boot hive checkpoint ");
            print_u64(image_len as u64);
            print_str(b"B dirty-cells=");
            print_u64(dirty_cells as u64);
            print_str(b" path=");
            print_ascii_str(file_path);
            print_str(b"\n");
        }
        nt_fs::STATUS_SUCCESS
    }

    pub(crate) fn complete_committed_mutable_hive_journal_snapshot(&mut self, reason: &[u8]) {
        let pending_records = self.mutable_hive_journal_pending_records;
        let pending_boot_mask = self.mutable_hive_journal_pending_boot_mask;
        let dirty_boot_mask = self.mutable_hive_journal_dirty_boot_mask;
        if pending_records == 0 && dirty_boot_mask == 0 {
            return;
        }

        let mut boot_hives = 0usize;
        let mut dirty_cells = 0usize;
        let mut durable_bytes = 0usize;
        let mut counted_mask = 0u8;
        for hive_sel in [
            HIVE_SEL_SYSTEM,
            HIVE_SEL_SOFTWARE,
            HIVE_SEL_SECURITY,
            HIVE_SEL_SAM,
            HIVE_SEL_USER_DEFAULT,
        ] {
            let Some(bit) = Self::boot_mutable_hive_pending_bit(hive_sel) else {
                continue;
            };
            if dirty_boot_mask & bit == 0 {
                continue;
            }
            let Some(file_path) = Self::boot_mutable_hive_checkpoint_path(hive_sel) else {
                continue;
            };
            let dirty = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.dirty_count());
            if dirty == 0 {
                continue;
            }
            let image_len = unsafe { crate::writable_fs::hive_image_len_at(file_path) };
            let log_len = unsafe { crate::writable_fs::hive_log_len_if_mounted(file_path) };
            if log_len == 0 {
                continue;
            }
            let hive_bytes = image_len.saturating_add(log_len);
            if hive_bytes == 0 {
                continue;
            }
            boot_hives = boot_hives.saturating_add(1);
            dirty_cells = dirty_cells.saturating_add(dirty);
            durable_bytes = durable_bytes.saturating_add(hive_bytes);
            counted_mask |= bit;
        }

        if boot_hives != 0 {
            REG_FLUSH_KEY_BOOT_HIVE_CHECKPOINTS.fetch_add(1, Ordering::Relaxed);
            REG_FLUSH_KEY_BOOT_HIVE_BYTES.store(durable_bytes as u64, Ordering::Relaxed);
            print_str(b"[cm-flush] boot hive journal snapshot committed reason=");
            print_str(reason);
            print_str(b" pending-records=");
            print_u64(pending_records as u64);
            print_str(b" pending-mask=");
            print_u64(pending_boot_mask as u64);
            print_str(b" hives=");
            print_u64(boot_hives as u64);
            print_str(b" dirty-cells=");
            print_u64(dirty_cells as u64);
            print_str(b" bytes=");
            print_u64(durable_bytes as u64);
            print_str(b"\n");
            self.mutable_hive_journal_dirty_boot_mask &= !counted_mask;
        }
        self.mutable_hive_journal_pending_records = 0;
        self.mutable_hive_journal_pending_boot_mask = 0;
    }

    fn checkpoint_boot_mutable_hive_preserving_headroom(
        &mut self,
        hive_sel: u32,
        dirty_cells: usize,
        min_post_checkpoint_headroom: usize,
    ) -> u32 {
        const MIN_IMAGE_HINT: usize = 0x1_0000;
        if dirty_cells == 0 {
            return nt_fs::STATUS_SUCCESS;
        }
        let Some(file_path) = Self::boot_mutable_hive_checkpoint_path(hive_sel) else {
            return 0xC000_0008;
        };
        let Some(hive) = self.mutable_hives.hive(hive_sel) else {
            return 0xC000_0008;
        };
        let image_len_hint = match nt_hive_core::encoded_image_len(hive) {
            Ok(len) => len,
            Err(_) => usize::MAX,
        };
        let required_headroom = image_len_hint
            .max(MIN_IMAGE_HINT)
            .saturating_add(min_post_checkpoint_headroom);
        let headroom = crate::allocator::remaining();
        if headroom < required_headroom {
            REG_FLUSH_KEY_BOOT_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
            print_str(b"[cm-flush] boot hive checkpoint insufficient-headroom dirty-cells=");
            print_u64(dirty_cells as u64);
            print_str(b" heap-headroom=");
            print_u64(headroom as u64);
            print_str(b" required=");
            print_u64(required_headroom as u64);
            print_str(b" preserve=");
            print_u64(min_post_checkpoint_headroom as u64);
            print_str(b" path=");
            print_ascii_str(file_path);
            print_str(b"\n");
            return nt_fs::STATUS_INSUFFICIENT_RESOURCES;
        }
        self.checkpoint_boot_mutable_hive(hive_sel, dirty_cells)
    }

    fn flush_all_mutable_hives_preserving_headroom(
        &mut self,
        min_post_checkpoint_headroom: usize,
    ) -> u32 {
        let mut total_dirty = 0usize;
        for hive_sel in [
            HIVE_SEL_SYSTEM,
            HIVE_SEL_SOFTWARE,
            HIVE_SEL_SECURITY,
            HIVE_SEL_SAM,
            HIVE_SEL_USER_DEFAULT,
        ] {
            let dirty = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.dirty_count());
            total_dirty = total_dirty.saturating_add(dirty);
            let status = self.checkpoint_boot_mutable_hive_preserving_headroom(
                hive_sel,
                dirty,
                min_post_checkpoint_headroom,
            );
            if status != nt_fs::STATUS_SUCCESS {
                return status;
            }
        }

        for hive_sel in HIVE_SEL_DYNAMIC {
            let dirty = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.dirty_count());
            total_dirty = total_dirty.saturating_add(dirty);
            let status = self.checkpoint_dynamic_mutable_hive(hive_sel, dirty);
            if status != nt_fs::STATUS_SUCCESS {
                return status;
            }
        }

        REG_FLUSH_KEY_MUTABLE_DIRTY_CELLS.store(total_dirty as u64, Ordering::Relaxed);
        nt_fs::STATUS_SUCCESS
    }

    pub(crate) fn checkpoint_dirty_boot_mutable_hives_preserving_headroom(&mut self) -> u32 {
        #[derive(Copy, Clone)]
        struct Candidate {
            hive_sel: u32,
            dirty: usize,
            image_len: usize,
        }

        const MIN_POST_BOOT_HIVE_PRIMARY_SEED_HEADROOM: usize = 0x18_0000;
        const HIVE_SELS: [u32; 5] = [
            HIVE_SEL_SYSTEM,
            HIVE_SEL_SOFTWARE,
            HIVE_SEL_SECURITY,
            HIVE_SEL_SAM,
            HIVE_SEL_USER_DEFAULT,
        ];

        let mut total_dirty = 0usize;
        let mut candidates = [None; 5];
        let mut candidate_len = 0usize;
        for hive_sel in HIVE_SELS {
            let dirty = self
                .mutable_hives
                .hive(hive_sel)
                .map_or(0, |hive| hive.dirty_count());
            total_dirty = total_dirty.saturating_add(dirty);
            if dirty == 0 {
                continue;
            }
            if Self::boot_mutable_hive_checkpoint_path(hive_sel).is_none() {
                continue;
            }
            let Some(hive) = self.mutable_hives.hive(hive_sel) else {
                continue;
            };
            let image_len = match nt_hive_core::encoded_image_len(hive) {
                Ok(len) => len,
                Err(_) => usize::MAX,
            };
            candidates[candidate_len] = Some(Candidate {
                hive_sel,
                dirty,
                image_len,
            });
            candidate_len += 1;
        }
        REG_FLUSH_KEY_MUTABLE_DIRTY_CELLS.store(total_dirty as u64, Ordering::Relaxed);

        loop {
            let headroom = crate::allocator::remaining();
            let mut selected: Option<(usize, Candidate)> = None;
            for (index, candidate) in candidates[..candidate_len].iter().enumerate() {
                let Some(candidate) = candidate else {
                    continue;
                };
                let required_headroom = candidate
                    .image_len
                    .saturating_add(MIN_POST_BOOT_HIVE_PRIMARY_SEED_HEADROOM);
                if headroom < required_headroom {
                    continue;
                }
                let replace = selected
                    .map(|(_, best)| candidate.image_len > best.image_len)
                    .unwrap_or(true);
                if replace {
                    selected = Some((index, *candidate));
                }
            }

            let Some((index, candidate)) = selected else {
                break;
            };
            let status = self.checkpoint_boot_mutable_hive(candidate.hive_sel, candidate.dirty);
            if status != nt_fs::STATUS_SUCCESS {
                return status;
            }
            candidates[index] = None;
        }

        let remaining_dirty = self.boot_mutable_hive_dirty_cells();
        REG_FLUSH_KEY_MUTABLE_DIRTY_CELLS.store(remaining_dirty as u64, Ordering::Relaxed);
        if remaining_dirty != 0 {
            print_str(b"[cm-flush] quiesce boot hive checkpoint deferred dirty-cells=");
            print_u64(remaining_dirty as u64);
            print_str(b" heap-headroom=");
            print_u64(crate::allocator::remaining() as u64);
            print_str(b"\n");
        }
        nt_fs::STATUS_SUCCESS
    }

    pub(crate) fn boot_mutable_hive_dirty_cells(&self) -> usize {
        let mut total_dirty = 0usize;
        for hive_sel in [
            HIVE_SEL_SYSTEM,
            HIVE_SEL_SOFTWARE,
            HIVE_SEL_SECURITY,
            HIVE_SEL_SAM,
            HIVE_SEL_USER_DEFAULT,
        ] {
            total_dirty = total_dirty.saturating_add(
                self.mutable_hives
                    .hive(hive_sel)
                    .map_or(0, |hive| hive.dirty_count()),
            );
        }
        total_dirty
    }

    fn checkpoint_dynamic_mutable_hive(&mut self, hive_sel: u32, dirty_cells: usize) -> u32 {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        if dirty_cells == 0 {
            return nt_fs::STATUS_SUCCESS;
        }
        let Some(file_path) = self
            .hive_mounts
            .iter()
            .find(|mount| mount.dynamic && mount.sel == hive_sel)
            .map(|mount| mount.file.clone())
        else {
            return STATUS_INVALID_HANDLE;
        };
        let image_len = {
            let Some(hive) = self.mutable_hives.hive(hive_sel) else {
                return STATUS_INVALID_HANDLE;
            };
            match nt_hive_core::encoded_image_len(hive) {
                Ok(len) => len,
                Err(err) => {
                    REG_FLUSH_KEY_DYNAMIC_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
                    print_str(b"[cm-flush] dynamic hive checkpoint measure failed err=");
                    print_str(match err {
                        nt_hive_core::HiveEncodeError::OutOfMemory => b"out-of-memory",
                        nt_hive_core::HiveEncodeError::SizeOverflow => b"size-overflow",
                    });
                    print_str(b" path=");
                    print_ascii_str(&file_path);
                    print_str(b"\n");
                    return nt_fs::STATUS_INSUFFICIENT_RESOURCES;
                }
            }
        };
        if image_len > USER_HIVE_SLOT_BYTES {
            REG_FLUSH_KEY_DYNAMIC_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
            print_str(b"[cm-flush] dynamic hive checkpoint too large bytes=");
            print_u64(image_len as u64);
            print_str(b" path=");
            print_ascii_str(&file_path);
            print_str(b"\n");
            return nt_fs::STATUS_INSUFFICIENT_RESOURCES;
        }
        let flush_result = {
            let _alloc_ctx =
                crate::allocator::enter_context(crate::allocator::ALLOC_CTX_WRITABLE_ATOMIC_WRITE);
            let Some(hive) = self.mutable_hives.hive_mut(hive_sel) else {
                return STATUS_INVALID_HANDLE;
            };
            let provider = crate::writable_fs::WritableHiveIoProvider::new(&file_path);
            let mut manager = nt_hive_core::HiveManager::new(provider);
            manager.try_flush(hive)
        };
        if let Err(err) = flush_result {
            REG_FLUSH_KEY_DYNAMIC_HIVE_FAILURES.fetch_add(1, Ordering::Relaxed);
            print_str(b"[cm-flush] dynamic hive checkpoint failed err=");
            Self::print_mutable_hive_flush_failure(err);
            print_str(b" path=");
            print_ascii_str(&file_path);
            print_str(b"\n");
            return Self::mutable_hive_flush_failure_status(err);
        }
        {
            self.writable_fs_dirty = true;
            self.writable_fs_commit_required = true;
            REG_FLUSH_KEY_DYNAMIC_HIVE_CHECKPOINTS.fetch_add(1, Ordering::Relaxed);
            REG_FLUSH_KEY_DYNAMIC_HIVE_BYTES.store(image_len as u64, Ordering::Relaxed);
            print_str(b"[cm-flush] dynamic hive checkpoint ");
            print_u64(image_len as u64);
            print_str(b"B dirty-cells=");
            print_u64(dirty_cells as u64);
            print_str(b" path=");
            print_ascii_str(&file_path);
            print_str(b"\n");
        }
        nt_fs::STATUS_SUCCESS
    }

    /// `NtLoadKey*` — ReactOS `ntoskrnl/config/ntapi.c:1148` (`NtLoadKeyEx`). Mount a hive file at
    /// a key in the registry namespace. Ordinary ReactOS/Windows `regf` images are imported into
    /// the mutable hive authority; D3 dynamic checkpoints saved by this kernel are accepted as
    /// mutable-only `nt-hive-core` images. Base `NtLoadKey` passes `flags = 0` and a null trust-class
    /// key; `NtLoadKey2` / `NtLoadKeyEx` feed their additional arguments here.
    ///
    /// # Safety
    /// Reads two caller OBJECT_ATTRIBUTES through the bounds-checked cross-AS reader.
    unsafe fn nt_load_key_ex(
        &mut self,
        target_oa: u64,
        source_oa: u64,
        flags: u32,
        trust_class_key: u64,
    ) -> u32 {
        let _load_alloc_ctx =
            crate::allocator::enter_context(crate::allocator::ALLOC_CTX_NT_LOAD_KEY);
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        const STATUS_SHARING_VIOLATION: u32 = 0xC000_0043;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        const STATUS_REGISTRY_CORRUPT: u32 = 0xC000_014C;
        const REG_NO_LAZY_FLUSH: u32 = 0x0000_0004;
        NT_LOAD_KEY_CALLS.fetch_add(1, Ordering::Relaxed);

        if flags & !REG_NO_LAZY_FLUSH != 0 {
            return STATUS_INVALID_PARAMETER;
        }

        // `SeSinglePrivilegeCheck(SeRestorePrivilege, PreviousMode)` (ntapi.c:1168). Enforced, not
        // assumed: `userenv!AcquireRemoveRestorePrivilege(TRUE)` must really have ENABLED it on the
        // caller's token through `NtAdjustPrivilegesToken` (the LocalSystem token carries
        // SeRestorePrivilege present-but-DISABLED, exactly as ReactOS's does).
        let held = self.current_token_has_privilege(nt_security::SE_RESTORE);
        NT_LOAD_KEY_PRIVILEGE_HELD.store(held as u64, Ordering::Relaxed);
        if !held {
            NT_LOAD_KEY_NO_PRIVILEGE.fetch_add(1, Ordering::Relaxed);
            print_str(b"[cm-load] NtLoadKey REFUSED: SeRestorePrivilege not held (pi=");
            print_u64(self.pi as u64);
            print_str(b")\n");
            return STATUS_PRIVILEGE_NOT_HELD;
        }

        if trust_class_key != 0 {
            match self.resolve_registry_key(trust_class_key, 0) {
                Ok(_) => {}
                Err(status) => return status,
            }
        }

        // The TARGET key: RootDirectory (usually the HKEY_USERS handle) + the leaf name (the SID).
        let mut rd = [0u8; 8];
        if target_oa == 0 || !self.xas_read(target_oa + 8, &mut rd) {
            return 0xC000_0005; // STATUS_ACCESS_VIOLATION
        }
        let root_dir = u64::from_le_bytes(rd);
        let root_target = if root_dir == 0 {
            None
        } else {
            match self.resolve_registry_key(root_dir, 0) {
                Ok(target) => Some(target),
                Err(status) => return status,
            }
        };
        let target_name = self.effective_objattr_name("", target_oa);
        let Some(full) = self.user_namespace_target(root_target, &target_name) else {
            // Only the `\Registry\User` namespace has hive mounts in this executive; a load
            // anywhere else is refused rather than faked.
            print_str(b"[cm-load] NtLoadKey target is not under \\Registry\\User\n");
            return STATUS_INVALID_PARAMETER;
        };
        let canon = nt_hive_core::canon_path(&full);
        if canon == r"\registry\user" {
            return STATUS_INVALID_PARAMETER;
        }
        if self.hive_mounts.iter().any(|m| m.canon == canon) {
            // The hive is already mounted here — `userenv!LoadUserProfileW` explicitly tolerates
            // ERROR_SHARING_VIOLATION as "the profile is already loaded" (profile.c:2136).
            return STATUS_SHARING_VIOLATION;
        }

        // The SOURCE file: read the whole regf out of the filesystem into a durable static slot.
        let file16 = self.read_objattr_name_pe(source_oa);
        let mut file_name = alloc::string::String::new();
        for &unit in &file16 {
            if let Some(c) = char::from_u32(unit as u32) {
                file_name.push(c);
            }
        }
        let Some(slot) = (0..USER_HIVE_SLOTS)
            .find(|s| USER_HIVE_SLOT_USED.load(Ordering::Relaxed) & (1 << s) == 0)
        else {
            print_str(b"[cm-load] NtLoadKey REFUSED: all hive slots in use\n");
            return STATUS_INSUFFICIENT_RESOURCES;
        };
        // SAFETY: single-threaded executive; the slot is claimed below and only released by
        // `NtUnloadKey`, which drops the borrowing mount first.
        let buffer = &mut (*core::ptr::addr_of_mut!(USER_HIVE_BUF))[slot];
        let Some(len) = Self::read_file_by_nt_path(&file16, buffer) else {
            print_str(b"[cm-load] NtLoadKey: source file unreadable: ");
            print_ascii_str(&file_name);
            print_str(b"\n");
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        // SAFETY: the slot is a `'static` array; the borrow lives exactly as long as the mount.
        let bytes: &'static [u8] =
            core::slice::from_raw_parts((*core::ptr::addr_of!(USER_HIVE_BUF))[slot].as_ptr(), len);
        let regf_hive = RegfHive::new(bytes);
        let mut core_hive = None;
        let hive_sel = HIVE_SEL_DYNAMIC[slot];
        let mut root_subkeys = if let Some(ref hive) = regf_hive {
            hive.subkeys(hive.root()).len() as u64
        } else {
            let provider_core_hive =
                if unsafe { crate::writable_fs::file_bytes_if_mounted(&file_name).is_some() } {
                    let mut manager = nt_hive_core::HiveManager::new(
                        crate::writable_fs::WritableHiveIoProvider::new(&file_name),
                    );
                    match manager.boot(hive_kind_for_selector(hive_sel)) {
                        Ok(hive) => Some(hive),
                        Err(nt_hive_core::HiveBootError::Io(_)) => {
                            print_str(b"[cm-load] NtLoadKey: core hive provider I/O failed for ");
                            print_ascii_str(&file_name);
                            print_str(b"\n");
                            return STATUS_UNSUCCESSFUL;
                        }
                        Err(nt_hive_core::HiveBootError::Decode(_)) => None,
                    }
                } else {
                    None
                };
            match provider_core_hive.or_else(|| nt_hive_core::decode_image(bytes).ok()) {
                Some(hive) => {
                    let root_subkeys = hive.subkey_count(hive.root()) as u64;
                    core_hive = Some(hive);
                    root_subkeys
                }
                None => {
                    print_str(b"[cm-load] NtLoadKey: not a regf/core hive (");
                    print_u64(len as u64);
                    print_str(b" bytes)\n");
                    return STATUS_REGISTRY_CORRUPT;
                }
            }
        };
        USER_HIVE_SLOT_USED.fetch_or(1 << slot, Ordering::Relaxed);
        if let Some(ref hive) = regf_hive {
            let imported = {
                let _import_alloc_ctx =
                    crate::allocator::enter_context(crate::allocator::ALLOC_CTX_REGF_IMPORT);
                nt_hive_regf::try_import_regf_into_hive(hive, hive_kind_for_selector(hive_sel))
            };
            let (mut hive, _stats) = match imported {
                Ok(imported) => imported,
                Err(
                    nt_hive_regf::RegfHiveImportError::InvalidSourceKey
                    | nt_hive_regf::RegfHiveImportError::InvalidKey
                    | nt_hive_regf::RegfHiveImportError::InvalidSubkeyList
                    | nt_hive_regf::RegfHiveImportError::InvalidValue,
                ) => {
                    USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
                    print_str(b"[cm-load] NtLoadKey: mutable import invalid root key bytes=");
                    print_u64(len as u64);
                    print_str(b" target=");
                    print_ascii_str(&full);
                    print_str(b"\n");
                    return STATUS_REGISTRY_CORRUPT;
                }
                Err(
                    nt_hive_regf::RegfHiveImportError::InvalidClass
                    | nt_hive_regf::RegfHiveImportError::InvalidSecurityDescriptor
                    | nt_hive_regf::RegfHiveImportError::UnsupportedValueType(_)
                    | nt_hive_regf::RegfHiveImportError::DepthLimitOrCycle,
                ) => {
                    USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
                    print_str(b"[cm-load] NtLoadKey: mutable import metadata corrupt bytes=");
                    print_u64(len as u64);
                    print_str(b" target=");
                    print_ascii_str(&full);
                    print_str(b"\n");
                    return STATUS_REGISTRY_CORRUPT;
                }
                Err(nt_hive_regf::RegfHiveImportError::OutOfMemory) => {
                    USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
                    print_str(b"[cm-load] NtLoadKey: mutable import out of memory bytes=");
                    print_u64(len as u64);
                    print_str(b" target=");
                    print_ascii_str(&full);
                    print_str(b"\n");
                    return STATUS_INSUFFICIENT_RESOURCES;
                }
            };
            let log_bytes =
                unsafe { crate::writable_fs::hive_log_bytes_owned_if_mounted(&file_name) }
                    .unwrap_or_default();
            if !log_bytes.is_empty() {
                let base_sequence = hive.sequence;
                let last_sequence = nt_hive_core::replay_log(&mut hive, &log_bytes, base_sequence);
                print_str(b"[cm-load] NtLoadKey replayed source hive journal bytes=");
                print_u64(log_bytes.len() as u64);
                print_str(b" sequence=");
                print_u64(base_sequence);
                print_str(b"..");
                print_u64(last_sequence);
                print_str(b" source=");
                print_ascii_str(&file_name);
                print_str(b"\n");
            }
            drop(log_bytes);
            root_subkeys = hive.subkey_count(hive.root()) as u64;
            if self.mutable_hives.mount(&full, hive_sel, hive).is_err() {
                USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
                return STATUS_REGISTRY_CORRUPT;
            }
            self.mutable_hives.clear_hive_dirty(hive_sel);
        } else if let Some(hive) = core_hive {
            if self.mutable_hives.mount(&full, hive_sel, hive).is_err() {
                USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
                return STATUS_REGISTRY_CORRUPT;
            }
            NT_LOAD_KEY_CORE_HIVE_MOUNTED.fetch_add(1, Ordering::Relaxed);
        }
        self.note_mutable_hives_changed_preserving_services_order();
        self.hive_mounts.push(HiveMount {
            sel: hive_sel,
            canon,
            mount: full,
            file: file_name,
            hive: regf_hive,
            slot: Some(slot),
            dynamic: true,
        });
        NT_LOAD_KEY_MOUNTED.fetch_add(1, Ordering::Relaxed);
        NT_LOAD_KEY_HIVE_BYTES.store(len as u64, Ordering::Relaxed);
        NT_LOAD_KEY_ROOT_SUBKEYS.store(root_subkeys, Ordering::Relaxed);
        print_str(b"[cm-load] NtLoadKey MOUNTED ");
        print_ascii_str(&self.hive_mounts[self.hive_mounts.len() - 1].mount);
        print_str(b" <- ");
        print_ascii_str(&self.hive_mounts[self.hive_mounts.len() - 1].file);
        print_str(b" bytes=");
        print_u64(len as u64);
        print_str(b" root-subkeys=");
        print_u64(root_subkeys);
        print_str(b" slot=");
        print_u64(slot as u64);
        print_str(b"\n");
        // CONTENT read-back through the namespace, not through the mount object: resolve
        // `<mount>\Environment` the way a hosted process' `NtOpenKey` would and compare its `TEMP`
        // value with the SAME value in the `.Default` prototype the profile hive was copied from.
        // Byte-for-byte equality of a non-empty value is what makes "a REAL hive is mounted here"
        // a measurement instead of a claim.
        let mut env_path = self.hive_mounts[self.hive_mounts.len() - 1].mount.clone();
        env_path.push_str("\\Environment");
        let mounted_temp = self
            .mutable_registry_value_by_path(&env_path, "TEMP")
            .or_else(|| {
                self.resolve_key(&env_path)
                    .and_then(|key| self.registry_value(key, "TEMP"))
            });
        let default_temp = self
            .mutable_registry_value_by_path(r"\Registry\User\.Default\Environment", "TEMP")
            .or_else(|| {
                self.resolve_key(r"\Registry\User\.Default\Environment")
                    .and_then(|key| self.registry_value(key, "TEMP"))
            });
        match (&mounted_temp, &default_temp) {
            (Some((ty, data)), Some((dty, ddata)))
                if !data.is_empty() && ty == dty && data == ddata =>
            {
                NT_LOAD_KEY_VALUE_READBACK.store(1, Ordering::Relaxed);
                print_str(b"[cm-load] read-back \\Environment\\TEMP through the mount: ");
                print_u64(data.len() as u64);
                print_str(b" bytes, type ");
                print_u64(*ty as u64);
                print_str(b", identical to \\Registry\\User\\.Default's\n");
            }
            _ => {
                print_str(b"[cm-load] read-back MISMATCH mounted=");
                print_u64(mounted_temp.map_or(0, |(_, d)| d.len() as u64));
                print_str(b" default=");
                print_u64(default_temp.map_or(0, |(_, d)| d.len() as u64));
                print_str(b"\n");
            }
        }
        0
    }

    unsafe fn capture_driver_service_registry_path(
        &self,
        ustr_va: u64,
    ) -> Result<alloc::string::String, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_OBJECT_NAME_INVALID: u32 = 0xC000_0033;
        const STATUS_OBJECT_PATH_SYNTAX_BAD: u32 = 0xC000_003B;
        const MAX_DRIVER_SERVICE_PATH_BYTES: usize = 1024;

        if ustr_va == 0 {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut header = [0u8; 16];
        if !self.xas_read(ustr_va, &mut header) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let byte_len = u16::from_le_bytes([header[0], header[1]]) as usize;
        let maximum_len = u16::from_le_bytes([header[2], header[3]]) as usize;
        let buffer = u64::from_le_bytes(header[8..16].try_into().unwrap());
        if byte_len == 0 || buffer == 0 {
            return Err(STATUS_INVALID_PARAMETER);
        }
        if (byte_len & 1) != 0 || byte_len > maximum_len || byte_len > 0xFFFC {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        if byte_len > MAX_DRIVER_SERVICE_PATH_BYTES {
            return Err(STATUS_OBJECT_PATH_SYNTAX_BAD);
        }
        let mut bytes = [0u8; MAX_DRIVER_SERVICE_PATH_BYTES];
        if !self.xas_read(buffer, &mut bytes[..byte_len]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut path = alloc::string::String::new();
        for index in 0..byte_len / 2 {
            let unit = u16::from_le_bytes([bytes[index * 2], bytes[index * 2 + 1]]);
            if !(0x20..=0x7e).contains(&unit) {
                return Err(STATUS_OBJECT_NAME_INVALID);
            }
            path.push(char::from_u32(unit as u32).ok_or(STATUS_OBJECT_NAME_INVALID)?);
        }
        Ok(path)
    }

    fn driver_service_name_from_registry_path(
        &self,
        path: &str,
    ) -> Result<alloc::string::String, u32> {
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_OBJECT_NAME_INVALID: u32 = 0xC000_0033;
        const STATUS_OBJECT_PATH_SYNTAX_BAD: u32 = 0xC000_003B;

        let (hive_id, relative_path) = self
            .mutable_hives
            .resolve_path(path)
            .ok_or(STATUS_OBJECT_PATH_SYNTAX_BAD)?;
        if hive_id != HIVE_SEL_SYSTEM {
            return Err(STATUS_OBJECT_PATH_SYNTAX_BAD);
        }
        let selected = self
            .mutable_hives
            .hive(HIVE_SEL_SYSTEM)
            .and_then(|hive| hive.current_control_set().ok())
            .ok_or(STATUS_OBJECT_PATH_SYNTAX_BAD)?;
        let comps: alloc::vec::Vec<&str> = relative_path
            .split('\\')
            .filter(|component| !component.is_empty())
            .collect();
        if comps.len() != 3
            || !comps[0].eq_ignore_ascii_case(selected.as_str())
            || !comps[1].eq_ignore_ascii_case("Services")
        {
            return Err(STATUS_OBJECT_PATH_SYNTAX_BAD);
        }
        let service = comps[2];
        if service.is_empty() {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let bytes = service.as_bytes();
        if !bytes
            .iter()
            .copied()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-' || b == b'.')
            || bytes.windows(2).any(|w| w == b"..")
        {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        Ok(alloc::string::String::from(service))
    }

    unsafe fn nt_load_driver(&mut self, service_name_ustr: u64) -> u32 {
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        const STATUS_IMAGE_ALREADY_LOADED: u32 = 0xC000_010E;
        const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;

        if !self.current_token_has_privilege(nt_security::SE_LOAD_DRIVER) {
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        let service_path = match self.capture_driver_service_registry_path(service_name_ustr) {
            Ok(path) => path,
            Err(status) => return status,
        };
        let service = match self.driver_service_name_from_registry_path(&service_path) {
            Ok(service) => service,
            Err(status) => return status,
        };
        let spec = match live_config_driver_service_launch_spec(
            &service,
            nt_config_manager::SERVICE_DEMAND_START,
        ) {
            Ok(spec) => spec,
            Err(status) => return status as u32,
        };
        if driver_launch::driver_id_by_name(&spec.driver_object_path).is_some() {
            return STATUS_IMAGE_ALREADY_LOADED;
        }

        let start_reservation =
            if spec.class == driver_launch::DriverClass::Device && !spec.devnodes.is_empty() {
                if REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 || !wait_reply_pool_has_free() {
                    return STATUS_INSUFFICIENT_RESOURCES;
                }
                match self.pending_driver_loads.reserve() {
                    Ok(reservation) => Some(reservation),
                    Err(_) => return STATUS_INSUFFICIENT_RESOURCES,
                }
            } else {
                None
            };

        let Some(fs) = exec_fs() else {
            if let Some(reservation) = start_reservation {
                self.pending_driver_loads
                    .cancel(reservation)
                    .expect("unused driver-load reservation became stale");
            }
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        let Some(dc) =
            driver_launch::load_driver(&fs, &spec.image_path, spec.class, &spec.driver_object_path)
        else {
            if let Some(reservation) = start_reservation {
                self.pending_driver_loads
                    .cancel(reservation)
                    .expect("failed driver load lost its continuation reservation");
            }
            return STATUS_UNSUCCESSFUL;
        };
        if let Some(reservation) = start_reservation {
            let mut batch =
                OwnedHostedPnpStartBatch::new(&dc, spec, HostedPnpStartOptions::demand_start());
            match batch.drive() {
                OwnedHostedPnpStartProgress::AwaitingCompletion => {
                    self.pending_driver_load_transfer = Some((batch, reservation));
                    return nt_status::NtStatus::PENDING.raw() as u32;
                }
                OwnedHostedPnpStartProgress::Complete(result) => {
                    self.pending_driver_loads
                        .cancel(reservation)
                        .expect("synchronous driver START lost its continuation reservation");
                    if let Err(failure) = result {
                        if !failure.teardown_blocked {
                            let _ =
                                driver_launch::unload_driver_by_name(batch.driver_object_path());
                        }
                        return failure.status.raw() as u32;
                    }
                }
                OwnedHostedPnpStartProgress::OwnershipLost(failure) => {
                    self.pending_driver_loads
                        .publish(
                            reservation,
                            PendingDriverStart {
                                batch,
                                owner: PendingDriverStartOwner::Detached,
                            },
                        )
                        .expect("lost driver START ownership could not publish its barrier");
                    return failure.status.raw() as u32;
                }
            }
        }
        0
    }

    unsafe fn nt_unload_driver(&mut self, service_name_ustr: u64) -> u32 {
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;

        if !self.current_token_has_privilege(nt_security::SE_LOAD_DRIVER) {
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        let service_path = match self.capture_driver_service_registry_path(service_name_ustr) {
            Ok(path) => path,
            Err(status) => return status,
        };
        let service = match self.driver_service_name_from_registry_path(&service_path) {
            Ok(service) => service,
            Err(status) => return status,
        };
        let driver_object_path = match live_config_driver_service_launch_spec(
            &service,
            nt_config_manager::SERVICE_DEMAND_START,
        ) {
            Ok(spec) => spec.driver_object_path,
            Err(status) => return status as u32,
        };
        for slot in 0..self.pending_driver_loads.slot_count() {
            if self.pending_driver_loads.get(slot).is_some_and(|pending| {
                pending
                    .batch
                    .driver_object_path()
                    .eq_ignore_ascii_case(&driver_object_path)
            }) {
                return nt_status::NtStatus::DEVICE_BUSY.raw() as u32;
            }
        }
        match driver_launch::unload_driver_by_name(&driver_object_path) {
            Ok(()) => 0,
            Err(status) => status.raw() as u32,
        }
    }

    /// `NtUnloadKey*` — ReactOS `ntoskrnl/config/ntapi.c:1796` (`NtUnloadKey2`) plus the event
    /// form. Detach a hive `NtLoadKey*` mounted: the mount goes, its backing slot is released, and
    /// the write overlay's keys under that path are detached too — otherwise the writes made
    /// through the mount would keep answering at the same path and the "unload" would be cosmetic.
    ///
    /// # Safety
    /// Reads the caller's OBJECT_ATTRIBUTES through the bounds-checked cross-AS reader.
    unsafe fn nt_unload_key_ex(&mut self, target_oa: u64, flags: u32, event: u64) -> u32 {
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        const REG_FORCE_UNLOAD: u32 = 0x0000_0001;
        NT_UNLOAD_KEY_CALLS.fetch_add(1, Ordering::Relaxed);
        if flags != 0 && flags != REG_FORCE_UNLOAD {
            NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
            return STATUS_INVALID_PARAMETER;
        }
        if !self.current_token_has_privilege(nt_security::SE_RESTORE) {
            NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        let event_index = if event != 0 {
            match self.event_index_for_handle(event, EVENT_MODIFY_STATE) {
                Ok(index) => Some(index),
                Err(status) => {
                    NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
                    return status;
                }
            }
        } else {
            None
        };
        let oa = target_oa;
        let mut rd = [0u8; 8];
        if oa == 0 || !self.xas_read(oa + 8, &mut rd) {
            return 0xC000_0005; // STATUS_ACCESS_VIOLATION
        }
        let root_dir = u64::from_le_bytes(rd);
        let root_target = if root_dir == 0 {
            None
        } else {
            match self.resolve_registry_key(root_dir, 0) {
                Ok(target) => Some(target),
                Err(status) => return status,
            }
        };
        let name = self.effective_objattr_name("", oa);
        let Some(full) = self.user_namespace_target(root_target, &name) else {
            NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
            return STATUS_INVALID_PARAMETER;
        };
        let canon = nt_hive_core::canon_path(&full);
        let Some(index) = self.hive_mounts.iter().position(|m| m.canon == canon) else {
            NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        if !self.hive_mounts[index].dynamic {
            // `.Default` is mounted by the boot, not by a caller: refusing to unload it is the
            // same refusal NT makes for a hive it did not load on request.
            NT_UNLOAD_KEY_REFUSED.fetch_add(1, Ordering::Relaxed);
            return STATUS_INVALID_PARAMETER;
        }
        let mount = self.hive_mounts.remove(index);
        if let Some(slot) = mount.slot {
            USER_HIVE_SLOT_USED.fetch_and(!(1u64 << slot), Ordering::Relaxed);
        }
        if self.mutable_hives.unmount(&mount.mount).is_some() {
            self.note_mutable_hives_changed_preserving_services_order();
        }
        let mut mutable_handles_invalidated = 0usize;
        for entry in self.mutable_key_handles.iter_mut() {
            if entry.as_ref().is_some_and(|key| key.hive == mount.sel) {
                *entry = None;
                mutable_handles_invalidated += 1;
            }
        }
        let overlay_detached = self.overlay.detach_subtree(&canon);
        NT_UNLOAD_KEY_DETACHED.fetch_add(1, Ordering::Relaxed);
        if let Some(index) = event_index {
            let status = self.signal_event_index(index);
            if status != 0 {
                return status;
            }
        }
        print_str(b"[cm-load] NtUnloadKey DETACHED ");
        print_ascii_str(&mount.mount);
        print_str(b" overlay-keys=");
        print_u64(overlay_detached as u64);
        print_str(b" mutable-handles=");
        print_u64(mutable_handles_invalidated as u64);
        print_str(b" mounts-left=");
        print_u64(self.hive_mounts.len() as u64);
        print_str(b"\n");
        0
    }

    fn registry_overlay_index(&self, target: KeyRef) -> Option<usize> {
        if let Some(index) = overlay_key_idx(target) {
            return Some(index);
        }
        if target == MACHINE_ROOT_KEY || target == USER_ROOT_KEY {
            return None;
        }
        let path = self.registry_target_path(target)?;
        self.registry_overlay_index_for_path(&path)
    }

    fn registry_overlay_index_for_path(&self, full_path: &str) -> Option<usize> {
        let canon = self.overlay_canon(full_path);
        self.registry_overlay_index_for_canon_path(&canon)
    }

    fn registry_overlay_index_for_canon_path(&self, canon: &str) -> Option<usize> {
        self.overlay
            .find_for_path_authority(canon, self.mutable_hive_owns_path(canon))
    }

    fn mutable_registry_key_by_path(
        &self,
        full_path: &str,
    ) -> Option<nt_hive_core::ResolvedHiveKey> {
        self.mutable_hives.resolve_key(full_path)
    }

    fn ensure_mutable_registry_key_by_path_journaled(
        &mut self,
        full_path: &str,
    ) -> Result<nt_hive_core::ResolvedHiveKey, u32> {
        let canon = self.overlay_canon(full_path);
        if let Some(key) = self.mutable_registry_key_by_path(&canon) {
            return Ok(key);
        }
        if !self.mutable_hive_owns_path(&canon) {
            return Err(STATUS_INVALID_HANDLE);
        }
        let Some((parent_path, leaf)) = canon.rsplit_once('\\') else {
            return Err(STATUS_OBJECT_PATH_SYNTAX_BAD);
        };
        if parent_path.is_empty() || leaf.is_empty() {
            return Err(STATUS_OBJECT_PATH_SYNTAX_BAD);
        }
        let parent = self.ensure_mutable_registry_key_by_path_journaled(parent_path)?;
        if let Some(key) = self.mutable_registry_key_by_path(&canon) {
            return Ok(key);
        }
        self.journal_create_mutable_subkey(parent, leaf)
    }

    fn mutable_registry_key(&self, target: KeyRef) -> Option<nt_hive_core::ResolvedHiveKey> {
        if let Some(key) = self.mutable_key_handle(target) {
            return Some(key);
        }
        let full_path = self.registry_target_path(target)?;
        self.mutable_registry_key_by_path(&full_path)
    }

    fn registry_key_class_by_path(&self, full_path: &str) -> Option<alloc::string::String> {
        let key = self.mutable_registry_key_by_path(full_path)?;
        self.mutable_hives
            .key_class(key)
            .map(alloc::string::String::from)
    }

    fn registry_key_class(&self, target: KeyRef) -> Option<alloc::string::String> {
        let key = self.mutable_registry_key(target)?;
        self.mutable_hives
            .key_class(key)
            .map(alloc::string::String::from)
    }

    fn registry_key_security_descriptor(&self, target: KeyRef) -> Option<&[u8]> {
        if target == MACHINE_ROOT_KEY {
            return self.registry_machine_root_security_descriptor.as_deref();
        }
        if target == USER_ROOT_KEY {
            return self.registry_user_root_security_descriptor.as_deref();
        }
        if let Some(index) = self.registry_overlay_index(target) {
            if let Some(descriptor) = self.overlay.key_security_descriptor(index) {
                return Some(descriptor);
            }
        }
        let key = self.mutable_registry_key(target)?;
        self.mutable_hives.key_security_descriptor(key)
    }

    fn set_registry_key_security_descriptor(
        &mut self,
        target: KeyRef,
        descriptor: &[u8],
    ) -> Result<(), u32> {
        if target == MACHINE_ROOT_KEY {
            self.registry_machine_root_security_descriptor = Some(descriptor.to_vec());
            return Ok(());
        }
        if target == USER_ROOT_KEY {
            self.registry_user_root_security_descriptor = Some(descriptor.to_vec());
            return Ok(());
        }
        if let Some(index) = self.registry_overlay_index(target) {
            if self.overlay.set_key_security_descriptor(index, descriptor) {
                return Ok(());
            }
            return Err(0xC000_0008);
        }
        if let Some(key) = self.mutable_registry_key(target) {
            if key.hive == HIVE_SEL_SYSTEM {
                let path = self.mutable_key_path(key).ok_or(STATUS_INVALID_HANDLE)?;
                self.commit_and_project_system_mutations(
                    &[OwnedSystemHiveMutation::SetKeySecurity {
                        path,
                        descriptor: descriptor.to_vec(),
                    }],
                    SystemHiveMutationOrigin::Runtime,
                )?;
            } else {
                self.journal_set_mutable_key_security_descriptor(key, descriptor)?;
            }
            self.note_mutable_hives_changed_preserving_services_order();
            return Ok(());
        }
        if self.base_hive(target).is_some() {
            return Err(0xC000_0022);
        }
        let Some(path) = self.registry_target_path(target) else {
            return Err(0xC000_0008);
        };
        if self.overlay.len() >= OVERLAY_KEY_MAX as usize {
            return Err(0xC000_009A);
        }
        let canon = self.overlay_canon(&path);
        let (index, _) = self.overlay.create_owned_with_volatility(canon, false);
        if !self.overlay.set_key_security_descriptor(index, descriptor) {
            return Err(0xC000_0008);
        }
        Ok(())
    }

    fn registry_subkey_class(&self, target: KeyRef, name: &str) -> Option<alloc::string::String> {
        let mut full_path = self.registry_target_path(target)?;
        if !full_path.is_empty() && !full_path.ends_with('\\') {
            full_path.push('\\');
        }
        full_path.push_str(name);
        self.registry_key_class_by_path(&full_path)
    }

    fn note_mutable_registry_key_open(&self, key: ResolvedHiveKey, full_path: &str) {
        let canon = self.overlay_canon(full_path);
        if Self::is_dynamic_user_volatile_env_canon(&canon) {
            USER_VOLATILE_ENV_OPENED.fetch_add(1, Ordering::Relaxed);
        }
        if key.hive == HIVE_SEL_SYSTEM && is_keyboard_layout_key(&canon) {
            KBD_LAYOUT_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        }
        if key.hive == HIVE_SEL_SOFTWARE {
            SOFTWARE_HIVE_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
            if self.current_process_is_winlogon() && is_winlogon_key(&canon) {
                WINLOGON_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
            }
            if self.current_process_is_winlogon() && is_profile_list_key(&canon) {
                WINLOGON_PROFILE_LIST_OPENS.fetch_add(1, Ordering::Relaxed);
                WINLOGON_PROFILE_LIST_HITS.fetch_add(1, Ordering::Relaxed);
            }
        } else if key.hive == HIVE_SEL_SECURITY || key.hive == HIVE_SEL_SAM {
            LSA_HIVE_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            if key.hive == HIVE_SEL_SAM {
                SAM_HIVE_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            }
        } else if key.hive == HIVE_SEL_USER_DEFAULT {
            USER_DEFAULT_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        } else if is_dynamic_hive_selector(key.hive) {
            USER_HIVE_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        }
    }

    fn note_base_registry_key_open(&self, key: KeyRef, full_path: &str) {
        let canon = self.overlay_canon(full_path);
        if Self::is_dynamic_user_volatile_env_canon(&canon) {
            USER_VOLATILE_ENV_OPENED.fetch_add(1, Ordering::Relaxed);
        }
        let sel = hive_sel(key);
        if sel == HIVE_SEL_SYSTEM && is_keyboard_layout_key(&canon) {
            KBD_LAYOUT_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        }
        if sel == HIVE_SEL_SOFTWARE {
            SOFTWARE_HIVE_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
            if self.current_process_is_winlogon() && is_winlogon_key(&canon) {
                WINLOGON_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
            }
            if self.current_process_is_winlogon() && is_profile_list_key(&canon) {
                WINLOGON_PROFILE_LIST_OPENS.fetch_add(1, Ordering::Relaxed);
                WINLOGON_PROFILE_LIST_HITS.fetch_add(1, Ordering::Relaxed);
            }
        } else if sel == HIVE_SEL_SECURITY || sel == HIVE_SEL_SAM {
            LSA_HIVE_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            if sel == HIVE_SEL_SAM {
                SAM_HIVE_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            }
        } else if sel == HIVE_SEL_USER_DEFAULT {
            USER_DEFAULT_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        } else if is_dynamic_hive_selector(sel) {
            USER_HIVE_KEY_OPENED.fetch_add(1, Ordering::Relaxed);
        }
    }

    fn note_registry_open_miss(&self, full_path: &str) {
        if self.current_process_is_winlogon() && is_profile_list_key(full_path) {
            WINLOGON_PROFILE_LIST_OPENS.fetch_add(1, Ordering::Relaxed);
        }
        if is_lsa_hive_path(full_path) {
            LSA_HIVE_OPEN_MISS.fetch_add(1, Ordering::Relaxed);
        }
    }

    unsafe fn open_registry_full_path(
        &mut self,
        full_path: &str,
        desired: u32,
        out: u64,
    ) -> Option<u32> {
        let canon = self.overlay_canon(full_path);
        if let Some(target) = Self::virtual_registry_root_target_from_canon(&canon) {
            if target == USER_ROOT_KEY {
                USER_ROOT_OPENED.fetch_add(1, Ordering::Relaxed);
            }
            return Some(self.mint_registry_key(target, desired, out));
        }
        if let Some(index) = self.registry_overlay_index_for_canon_path(&canon) {
            if Self::is_dynamic_user_volatile_env_canon(&canon) {
                USER_VOLATILE_ENV_OPENED.fetch_add(1, Ordering::Relaxed);
            }
            return Some(self.mint_registry_key(OVERLAY_KEY_TAG | index as u32, desired, out));
        }
        if let Some(mutable_key) = self.mutable_registry_key_by_path(full_path) {
            self.note_mutable_registry_key_open(mutable_key, full_path);
            return Some(self.mint_mutable_registry_key(mutable_key, desired, out));
        }
        if self.mutable_hive_owns_path(full_path) {
            self.note_registry_open_miss(full_path);
            return Some(0xC000_0034);
        }
        let base_key = self.resolve_key(full_path)?;
        self.note_base_registry_key_open(base_key, full_path);
        Some(self.mint_registry_key(base_key, desired, out))
    }

    fn mutable_registry_value_by_path(
        &self,
        full_path: &str,
        name: &str,
    ) -> Option<(u32, alloc::vec::Vec<u8>)> {
        let key = self.mutable_registry_key_by_path(full_path)?;
        let (ty, data) = self.mutable_hives.query_value(key, name)?;
        Some((ty as u32, data.to_vec()))
    }

    fn set_mutable_registry_value_by_path(
        &mut self,
        full_path: &str,
        name: &str,
        ty: u32,
        data: &[u8],
    ) -> bool {
        let Some(key) = self.mutable_registry_key_by_path(full_path) else {
            return false;
        };
        if key.hive == HIVE_SEL_SYSTEM {
            return false;
        }
        let Some(value_type) = nt_hive_core::RegistryValueType::from_u32(ty) else {
            return false;
        };
        if self
            .journal_set_mutable_value(key, name, value_type, data)
            .is_err()
        {
            return false;
        }
        self.note_mutable_hives_changed_for_services_order_change(
            self.registry_services_order_value_write_may_reorder(full_path),
        );
        true
    }

    fn ensure_mutable_registry_value_by_path(
        &mut self,
        full_path: &str,
        name: &str,
        ty: u32,
        data: &[u8],
    ) -> Option<bool> {
        let key = self.mutable_registry_key_by_path(full_path)?;
        let value_type = nt_hive_core::RegistryValueType::from_u32(ty)?;
        if self
            .mutable_hives
            .query_value(key, name)
            .is_some_and(|(existing_type, existing)| {
                existing_type == value_type && existing == data
            })
        {
            return Some(false);
        }
        self.set_mutable_registry_value_by_path(full_path, name, ty, data)
            .then_some(true)
    }

    fn nt_initialize_registry(&self, flag: u32) -> u32 {
        if flag > CM_BOOT_FLAG_MAX {
            return STATUS_INVALID_PARAMETER;
        }
        if (CM_BOOT_FLAG_ACCEPTED..=CM_BOOT_FLAG_MAX).contains(&flag) {
            if flag == CM_BOOT_FLAG_ACCEPTED {
                return STATUS_INVALID_PARAMETER;
            }
            if CM_REGISTRY_BOOT_ACCEPTED
                .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                return STATUS_ACCESS_DENIED;
            }
            CM_REGISTRY_LAZY_FLUSH_ENABLED.store(true, Ordering::Release);
            return 0;
        }
        if flag != CM_BOOT_FLAG_SMSS && flag != CM_BOOT_FLAG_SETUP {
            return STATUS_INVALID_PARAMETER;
        }
        if CM_REGISTRY_BOOT_FLAG
            .compare_exchange(u32::MAX, flag, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return STATUS_ACCESS_DENIED;
        }
        CM_REGISTRY_BOOT_SETUP.store(flag == CM_BOOT_FLAG_SETUP, Ordering::Release);
        0
    }

    fn current_user_locale_registry_path(&self) -> alloc::string::String {
        let candidate = self
            .pm
            .effective_token(self.current_tid as nt_process::ThreadId)
            .and_then(|token| self.token_store.get(token))
            .map(|token| {
                let mut path = alloc::string::String::from(r"\Registry\User\");
                path.push_str(&token.user.to_sddl());
                path.push_str(r"\Control Panel\International");
                path
            });
        if let Some(path) = candidate {
            let canon = self.overlay_canon(&path);
            if self.registry_path_exists(&canon) {
                return path;
            }
        }
        alloc::string::String::from(r"\Registry\User\.Default\Control Panel\International")
    }

    fn locale_registry_path_and_value(
        &self,
        user_profile: bool,
    ) -> (alloc::string::String, &'static str) {
        if user_profile {
            (self.current_user_locale_registry_path(), "Locale")
        } else {
            (
                alloc::string::String::from(
                    r"\Registry\Machine\System\CurrentControlSet\Control\Nls\Language",
                ),
                "Default",
            )
        }
    }

    fn locale_id_from_registry_value(&self, user_profile: bool) -> Result<u32, u32> {
        const REG_DWORD: u32 = 4;
        const REG_SZ: u32 = 1;
        let (path, value_name) = self.locale_registry_path_and_value(user_profile);
        let (ty, data) = self
            .mutable_registry_value_by_path(&path, value_name)
            .or_else(|| {
                let key = self.resolve_key(&path)?;
                self.registry_value(key, value_name)
            })
            .ok_or(STATUS_OBJECT_NAME_NOT_FOUND)?;
        if ty == REG_DWORD && data.len() == core::mem::size_of::<u32>() {
            Ok(u32::from_le_bytes(data[..4].try_into().unwrap()))
        } else if ty == REG_SZ {
            parse_utf16le_ascii_hex_u32(&data).ok_or(STATUS_UNSUCCESSFUL)
        } else {
            Err(STATUS_UNSUCCESSFUL)
        }
    }

    fn persist_default_locale(&mut self, user_profile: bool, locale_id: u32) -> Result<(), u32> {
        const REG_SZ: u32 = 1;
        let (path, value_name) = self.locale_registry_path_and_value(user_profile);
        let mut ascii8 = [0u8; 8];
        let mut ascii4 = [0u8; 4];
        let ascii: &[u8] = if user_profile {
            locale_id_ascii8(locale_id, &mut ascii8);
            &ascii8
        } else {
            locale_id_ascii4(locale_id, &mut ascii4);
            &ascii4
        };
        let mut data = [0u8; 18];
        let len = utf16le_ascii_z(ascii, &mut data).ok_or(STATUS_INVALID_PARAMETER)?;
        if self.mutable_registry_key_by_path(&path).is_none() {
            return Err(STATUS_OBJECT_NAME_NOT_FOUND);
        }
        if !user_profile {
            let value_type = nt_hive_core::RegistryValueType::Sz;
            if self
                .mutable_registry_key_by_path(&path)
                .and_then(|key| self.mutable_hives.query_value(key, value_name))
                .is_some_and(|(existing_type, existing)| {
                    existing_type == value_type && existing == &data[..len]
                })
            {
                return Ok(());
            }
            self.commit_and_project_system_mutations(
                &[OwnedSystemHiveMutation::SetValue {
                    path,
                    name: value_name.into(),
                    value_type,
                    data: data[..len].to_vec(),
                }],
                SystemHiveMutationOrigin::Runtime,
            )?;
            self.note_mutable_hives_changed_preserving_services_order();
            return Ok(());
        }
        self.ensure_mutable_registry_value_by_path(&path, value_name, REG_SZ, &data[..len])
            .map(|_| ())
            .ok_or(STATUS_UNSUCCESSFUL)
    }

    fn nt_set_default_locale(&mut self, user_profile: bool, mut locale_id: u32) -> u32 {
        if locale_id & NT_BOGUS_LOCALE_ID != 0 {
            return STATUS_INVALID_PARAMETER;
        }
        if locale_id == 0 {
            match self.locale_id_from_registry_value(user_profile) {
                Ok(found) => locale_id = found,
                Err(status) => return status,
            }
        } else if let Err(status) = self.persist_default_locale(user_profile, locale_id) {
            return status;
        }
        if user_profile {
            NT_SESSION_DEFAULT_LOCALE.store(locale_id, Ordering::Relaxed);
        } else {
            NT_SYSTEM_DEFAULT_LOCALE.store(locale_id, Ordering::Relaxed);
            NT_DEFAULT_UI_LANGUAGE.store(locale_id & 0xffff, Ordering::Relaxed);
        }
        0
    }

    fn registry_value_with<R>(
        &self,
        target: KeyRef,
        name: &str,
        mut visit: impl FnMut(u32, &[u8]) -> R,
    ) -> Option<R> {
        if let Some(index) = self.registry_overlay_index(target) {
            if self.overlay.value_is_deleted(index, name) {
                return None;
            }
            if let Some((ty, data)) = self.overlay.value(index, name) {
                return Some(visit(ty, data));
            }
            let path = self.overlay.path(index)?;
            if let Some(key) = self.mutable_registry_key_by_path(path) {
                let (ty, data) = self.mutable_hives.query_value(key, name)?;
                return Some(visit(ty as u32, data));
            }
            if self.mutable_hive_owns_path(path) {
                return None;
            }
            let key = self.resolve_key(path)?;
            let (hive, cell) = self.base_hive(key)?;
            return hive.value_with(cell, name, visit);
        }
        if let Some(key) = self.mutable_registry_key(target) {
            let (ty, data) = self.mutable_hives.query_value(key, name)?;
            return Some(visit(ty as u32, data));
        }
        if let Some(path) = self.registry_target_path(target) {
            if self.mutable_hive_owns_path(&path) {
                return None;
            }
        }
        let (hive, cell) = self.base_hive(target)?;
        hive.value_with(cell, name, visit)
    }

    fn mutable_hive_owns_path(&self, path: &str) -> bool {
        self.mutable_hives.owns_path(path)
    }

    fn registry_value_matches(
        &self,
        target: KeyRef,
        name: &str,
        value_type: u32,
        data: &[u8],
    ) -> Option<bool> {
        if let Some(index) = self.registry_overlay_index(target) {
            if self.overlay.value_is_deleted(index, name) {
                return None;
            }
            if let Some((ty, existing)) = self.overlay.value(index, name) {
                return Some(ty == value_type && existing == data);
            }
            let path = self.overlay.path(index)?;
            if let Some(key) = self.mutable_registry_key_by_path(path) {
                let (ty, existing) = self.mutable_hives.query_value(key, name)?;
                return Some(ty as u32 == value_type && existing == data);
            }
            if self.mutable_hive_owns_path(path) {
                return None;
            }
            let key = self.resolve_key(path)?;
            let (hive, cell) = self.base_hive(key)?;
            return hive.value_matches(cell, name, value_type, data);
        }
        if let Some(key) = self.mutable_registry_key(target) {
            let (ty, existing) = self.mutable_hives.query_value(key, name)?;
            return Some(ty as u32 == value_type && existing == data);
        }
        if let Some(path) = self.registry_target_path(target) {
            if self.mutable_hive_owns_path(&path) {
                return None;
            }
        }
        let (hive, cell) = self.base_hive(target)?;
        hive.value_matches(cell, name, value_type, data)
    }

    unsafe fn read_user_data_vec(
        &self,
        data_ptr: u64,
        data_size: usize,
        scratch_cap: usize,
    ) -> Result<alloc::vec::Vec<u8>, u32> {
        if data_size == 0 {
            return Ok(alloc::vec::Vec::new());
        }
        if data_ptr == 0 {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut data = alloc::vec::Vec::new();
        if data.try_reserve_exact(data_size).is_err() {
            return Err(0xC000_009A);
        }
        let scratch = core::slice::from_raw_parts_mut(
            core::ptr::addr_of_mut!(OVERLAY_WRITE_SCRATCH) as *mut u8,
            scratch_cap,
        );
        let mut offset = 0usize;
        while offset < data_size {
            let chunk = (data_size - offset).min(scratch_cap);
            if !self.xas_read(data_ptr + offset as u64, &mut scratch[..chunk]) {
                return Err(STATUS_ACCESS_VIOLATION);
            }
            data.extend_from_slice(&scratch[..chunk]);
            offset += chunk;
        }
        Ok(data)
    }

    unsafe fn user_data_equals(&self, data_ptr: u64, expected: &[u8], scratch_cap: usize) -> bool {
        if expected.is_empty() {
            return true;
        }
        if data_ptr == 0 {
            return false;
        }
        let scratch = core::slice::from_raw_parts_mut(
            core::ptr::addr_of_mut!(OVERLAY_WRITE_SCRATCH) as *mut u8,
            scratch_cap,
        );
        let mut offset = 0usize;
        while offset < expected.len() {
            let chunk = (expected.len() - offset).min(scratch_cap);
            if !self.xas_read(data_ptr + offset as u64, &mut scratch[..chunk]) {
                return false;
            }
            if scratch[..chunk] != expected[offset..offset + chunk] {
                return false;
            }
            offset += chunk;
        }
        true
    }

    fn registry_path_exists(&self, canon: &str) -> bool {
        matches!(
            canon,
            r"\" | r"\registry" | r"\registry\machine" | r"\registry\user"
        ) || self.registry_overlay_index_for_canon_path(canon).is_some()
            || if self.mutable_hive_owns_path(canon) {
                self.mutable_hives.resolve_key(canon).is_some()
            } else {
                self.resolve_key(canon).is_some()
            }
    }

    fn registry_value(&self, target: KeyRef, name: &str) -> Option<(u32, alloc::vec::Vec<u8>)> {
        self.registry_value_with(target, name, |ty, data| (ty, data.to_vec()))
    }

    fn registry_immediate_child_name<'a>(full_path: &'a str, parent_path: &str) -> Option<&'a str> {
        let mut full = full_path.split('\\').filter(|part| !part.is_empty());
        for parent in parent_path.split('\\').filter(|part| !part.is_empty()) {
            let current = full.next()?;
            if !current.eq_ignore_ascii_case(parent) {
                return None;
            }
        }
        let child = full.next()?;
        if full.next().is_some() {
            return None;
        }
        Some(child)
    }

    fn push_registry_mount_child(
        out: &mut alloc::vec::Vec<alloc::string::String>,
        parent_path: &str,
        mount_path: &str,
    ) {
        let Some(child) = Self::registry_immediate_child_name(mount_path, parent_path) else {
            return;
        };
        if out.iter().any(|seen| seen.eq_ignore_ascii_case(child)) {
            return;
        }
        out.push(alloc::string::String::from(child));
    }

    fn registry_mounted_hive_subkeys(
        &self,
        parent_path: &str,
    ) -> alloc::vec::Vec<alloc::string::String> {
        let mut subkeys = alloc::vec::Vec::new();
        for sel in [
            HIVE_SEL_SYSTEM,
            HIVE_SEL_SOFTWARE,
            HIVE_SEL_SECURITY,
            HIVE_SEL_SAM,
        ] {
            let mount_path = hive_mount(sel);
            if self.mutable_hives.owns_path(mount_path) {
                Self::push_registry_mount_child(&mut subkeys, parent_path, mount_path);
            }
        }
        for mount in &self.hive_mounts {
            if self.mutable_hives.owns_path(&mount.mount) {
                Self::push_registry_mount_child(&mut subkeys, parent_path, &mount.mount);
            }
        }
        subkeys
    }

    fn registry_subkey_exists_in_materialized_authority(
        &self,
        mutable_base: Option<ResolvedHiveKey>,
        base_key: Option<KeyRef>,
        name: &str,
    ) -> bool {
        mutable_base
            .and_then(|key| {
                self.mutable_hives
                    .hive(key.hive)?
                    .open_subkey(key.key, name)
                    .map(|_| ())
            })
            .or_else(|| {
                base_key.and_then(|key| {
                    let (hive, base) = self.base_hive(key)?;
                    hive.open_subkey(base, name).map(|_| ())
                })
            })
            .is_some()
    }

    fn registry_child_path(parent_path: &str, child_name: &str) -> alloc::string::String {
        let mut path = alloc::string::String::from(parent_path);
        if !path.ends_with('\\') {
            path.push('\\');
        }
        path.push_str(child_name);
        path
    }

    fn registry_overlay_subkey_is_authoritative(
        &self,
        parent_path: &str,
        child_name: &str,
    ) -> bool {
        let child_path = Self::registry_child_path(parent_path, child_name);
        let canon = self.overlay_canon(&child_path);
        self.registry_overlay_index_for_canon_path(&canon).is_some()
            || !self.mutable_hive_owns_path(&canon)
    }

    fn registry_value_by_index_with<R>(
        &self,
        target: KeyRef,
        requested_index: usize,
        mut visit: impl FnMut(&str, u32, &[u8], Option<ResolvedHiveValue>) -> R,
    ) -> Option<R> {
        let overlay_index = self.registry_overlay_index(target);
        let base_path = if let Some(index) = overlay_index {
            self.overlay.path(index).map(alloc::string::String::from)
        } else {
            self.registry_target_path(target)
        };
        let mutable_base = base_path
            .as_deref()
            .and_then(|path| self.mutable_registry_key_by_path(path));
        let mutable_owned = base_path
            .as_deref()
            .is_some_and(|path| self.mutable_hive_owns_path(path));
        let base_key = if let Some(index) = overlay_index {
            if mutable_owned {
                None
            } else {
                self.overlay
                    .path(index)
                    .and_then(|path| self.resolve_key(path))
            }
        } else if mutable_owned {
            None
        } else if !is_virtual_registry_key(target) {
            Some(target)
        } else {
            None
        };
        let mut visible_index = 0usize;
        if let Some(key) = mutable_base {
            if let Some(hive) = self.mutable_hives.hive(key.hive) {
                let value_count = hive.value_count(key.key);
                for index in 0..value_count {
                    let Some((source, name, ty, data)) =
                        self.mutable_hives.value_ref_by_index(key, index)
                    else {
                        continue;
                    };
                    if let Some(overlay) = overlay_index {
                        if self.overlay.value_is_deleted(overlay, name) {
                            continue;
                        }
                        if visible_index == requested_index {
                            if let Some((overlay_ty, overlay_data)) =
                                self.overlay.value(overlay, name)
                            {
                                return Some(visit(name, overlay_ty, overlay_data, None));
                            }
                            return Some(visit(name, ty as u32, data, Some(source)));
                        }
                        visible_index += 1;
                        continue;
                    }
                    if visible_index == requested_index {
                        return Some(visit(name, ty as u32, data, Some(source)));
                    }
                    visible_index += 1;
                }
            }
        } else if let Some((hive, base)) = base_key.and_then(|key| self.base_hive(key)) {
            for index in 0..hive.value_count(base) {
                let Some(hit) = hive.value_by_index_with(base, index, |name, ty, data| {
                    if let Some(overlay) = overlay_index {
                        if self.overlay.value_is_deleted(overlay, name) {
                            return None;
                        }
                        if visible_index == requested_index {
                            if let Some((overlay_ty, overlay_data)) =
                                self.overlay.value(overlay, name)
                            {
                                return Some(visit(name, overlay_ty, overlay_data, None));
                            }
                            return Some(visit(name, ty, data, None));
                        }
                        visible_index += 1;
                        return None;
                    }
                    if visible_index == requested_index {
                        return Some(visit(name, ty, data, None));
                    }
                    visible_index += 1;
                    None
                }) else {
                    continue;
                };
                if let Some(result) = hit {
                    return Some(result);
                }
            }
        }
        if let Some(overlay) = overlay_index {
            for index in 0..self.overlay.values_len(overlay) {
                let Some((name, ty, data)) = self.overlay.value_by_index(overlay, index) else {
                    continue;
                };
                let exists_in_base = mutable_base
                    .and_then(|key| self.mutable_hives.query_value(key, name).map(|_| ()))
                    .or_else(|| {
                        base_key.and_then(|key| {
                            let (hive, base) = self.base_hive(key)?;
                            hive.value_exists(base, name).then_some(())
                        })
                    })
                    .is_some();
                if exists_in_base {
                    continue;
                }
                if visible_index == requested_index {
                    return Some(visit(name, ty, data, None));
                }
                visible_index += 1;
            }
        }
        None
    }

    fn registry_key_stats(&self, target: KeyRef) -> RegistryKeyStats {
        let mut stats = RegistryKeyStats::default();
        let path = self.registry_target_path(target);
        let overlay_index = self.registry_overlay_index(target);
        let mutable_base = path
            .as_deref()
            .and_then(|path| self.mutable_registry_key_by_path(path));
        let mutable_owned = path
            .as_deref()
            .is_some_and(|path| self.mutable_hive_owns_path(path));
        let base_key = if let Some(index) = overlay_key_idx(target) {
            if mutable_owned {
                None
            } else {
                self.overlay
                    .path(index)
                    .and_then(|overlay_path| self.resolve_key(overlay_path))
            }
        } else if mutable_owned {
            None
        } else if !is_virtual_registry_key(target) {
            Some(target)
        } else {
            None
        };
        if let Some(key) = mutable_base {
            if let Some(hive) = self.mutable_hives.hive(key.hive) {
                for index in 0..hive.subkey_count(key.key) {
                    let Some(name) = hive.subkey_name_by_index(key.key, index) else {
                        continue;
                    };
                    let class_bytes = hive
                        .subkey_class_by_index(key.key, index)
                        .map(utf16le_byte_len)
                        .unwrap_or(0);
                    stats.add_subkey(name.encode_utf16().count().saturating_mul(2), class_bytes);
                }
                for index in 0..hive.value_count(key.key) {
                    let Some((name, _, data)) = hive.value_by_index(key.key, index) else {
                        continue;
                    };
                    if let Some(overlay) = overlay_index {
                        if self.overlay.value_is_deleted(overlay, name) {
                            continue;
                        }
                        if let Some((_, overlay_data)) = self.overlay.value(overlay, name) {
                            stats.add_value(
                                name.encode_utf16().count().saturating_mul(2),
                                overlay_data.len(),
                            );
                            continue;
                        }
                    }
                    stats.add_value(name.encode_utf16().count().saturating_mul(2), data.len());
                }
            }
        } else if let Some((hive, base)) = base_key.and_then(|key| self.base_hive(key)) {
            for index in 0.. {
                let Some(name_len) = hive.subkey_name_utf16_len_by_index(base, index) else {
                    break;
                };
                stats.add_subkey(name_len.saturating_mul(2), 0);
            }
            for index in 0..hive.value_count(base) {
                let Some(name) = hive.value_name_by_index(base, index) else {
                    continue;
                };
                if let Some(overlay) = overlay_index {
                    if self.overlay.value_is_deleted(overlay, &name) {
                        continue;
                    }
                    if let Some((_, overlay_data)) = self.overlay.value(overlay, &name) {
                        stats.add_value(
                            name.encode_utf16().count().saturating_mul(2),
                            overlay_data.len(),
                        );
                        continue;
                    }
                }
                if let Some((name_bytes, data_bytes)) = hive.value_lengths_by_index(base, index) {
                    stats.add_value(name_bytes, data_bytes);
                }
            }
        }
        let mount_subkeys = path
            .as_deref()
            .map(|path| self.registry_mounted_hive_subkeys(path))
            .unwrap_or_default();
        for name in &mount_subkeys {
            if !self.registry_subkey_exists_in_materialized_authority(mutable_base, base_key, name)
            {
                stats.add_subkey(name.encode_utf16().count().saturating_mul(2), 0);
            }
        }
        if let Some(path) = path.as_deref() {
            for index in 0..self.overlay.subkeys_len(path) {
                let Some(name) = self.overlay.subkey_by_index(path, index) else {
                    continue;
                };
                let exists_in_base = self.registry_subkey_exists_in_materialized_authority(
                    mutable_base,
                    base_key,
                    name,
                );
                let exists_as_mount = mount_subkeys
                    .iter()
                    .any(|mounted| mounted.eq_ignore_ascii_case(name));
                if !exists_in_base
                    && !exists_as_mount
                    && self.registry_overlay_subkey_is_authoritative(path, name)
                {
                    stats.add_subkey(name.encode_utf16().count().saturating_mul(2), 0);
                }
            }
        }
        if let Some(overlay) = overlay_index {
            for index in 0..self.overlay.values_len(overlay) {
                let Some((name, _, data)) = self.overlay.value_by_index(overlay, index) else {
                    continue;
                };
                let exists_in_base = mutable_base
                    .and_then(|key| self.mutable_hives.query_value(key, name).map(|_| ()))
                    .or_else(|| {
                        base_key.and_then(|key| {
                            let (hive, base) = self.base_hive(key)?;
                            hive.value_exists(base, name).then_some(())
                        })
                    })
                    .is_some();
                if !exists_in_base {
                    stats.add_value(name.encode_utf16().count().saturating_mul(2), data.len());
                }
            }
        }
        stats
    }

    fn note_mutable_hives_changed(&mut self) {
        self.invalidate_registry_services_order_cache();
        bump_progress();
    }

    fn note_mutable_hives_changed_preserving_services_order(&mut self) {
        bump_progress();
    }

    fn note_mutable_hives_changed_for_services_order_change(
        &mut self,
        services_order_may_change: bool,
    ) {
        if services_order_may_change {
            self.invalidate_registry_services_order_cache();
        }
        bump_progress();
    }

    fn invalidate_registry_services_order_cache(&mut self) {
        self.registry_services_order_cache_valid = false;
        self.registry_services_order_cache.clear();
    }

    fn registry_subkey_by_index(
        &mut self,
        target: KeyRef,
        requested_index: usize,
    ) -> Option<alloc::string::String> {
        let path = self.registry_target_path(target);
        if path
            .as_deref()
            .is_some_and(|path| self.is_system_services_registry_path(path))
        {
            return self.registry_ordered_service_subkey_by_index(requested_index);
        }
        let mutable_base = path
            .as_deref()
            .and_then(|path| self.mutable_registry_key_by_path(path));
        let mutable_owned = path
            .as_deref()
            .is_some_and(|path| self.mutable_hive_owns_path(path));
        let base_key = if let Some(index) = overlay_key_idx(target) {
            if mutable_owned {
                None
            } else {
                self.overlay
                    .path(index)
                    .and_then(|overlay_path| self.resolve_key(overlay_path))
            }
        } else if mutable_owned {
            None
        } else if !is_virtual_registry_key(target) {
            Some(target)
        } else {
            None
        };
        let mut visible_index = 0usize;
        if let Some(key) = mutable_base {
            if let Some(hive) = self.mutable_hives.hive(key.hive) {
                for index in 0..hive.subkey_count(key.key) {
                    let Some(name) = hive.subkey_name_by_index(key.key, index) else {
                        continue;
                    };
                    if visible_index == requested_index {
                        return Some(alloc::string::String::from(name));
                    }
                    visible_index += 1;
                }
            }
        } else if let Some((hive, base)) = base_key.and_then(|key| self.base_hive(key)) {
            for index in 0.. {
                let Some((name, _)) = hive.subkey_by_index(base, index) else {
                    break;
                };
                if visible_index == requested_index {
                    return Some(name);
                }
                visible_index += 1;
            }
        }
        let mount_subkeys = path
            .as_deref()
            .map(|path| self.registry_mounted_hive_subkeys(path))
            .unwrap_or_default();
        for name in &mount_subkeys {
            if self.registry_subkey_exists_in_materialized_authority(mutable_base, base_key, name) {
                continue;
            }
            if visible_index == requested_index {
                return Some(name.clone());
            }
            visible_index += 1;
        }
        if let Some(path) = path.as_deref() {
            for index in 0..self.overlay.subkeys_len(path) {
                let Some(name) = self.overlay.subkey_by_index(path, index) else {
                    continue;
                };
                if self.registry_subkey_exists_in_materialized_authority(
                    mutable_base,
                    base_key,
                    name,
                ) {
                    continue;
                }
                if mount_subkeys
                    .iter()
                    .any(|mounted| mounted.eq_ignore_ascii_case(name))
                {
                    continue;
                }
                if !self.registry_overlay_subkey_is_authoritative(path, name) {
                    continue;
                }
                if visible_index == requested_index {
                    return Some(alloc::string::String::from(name));
                }
                visible_index += 1;
            }
        }
        None
    }

    fn system_services_registry_canon(&self) -> alloc::string::String {
        self.overlay_canon(nt_config_manager::SERVICES_PATH)
    }

    fn is_system_services_registry_path(&self, path: &str) -> bool {
        nt_hive_core::canon_path(path) == self.system_services_registry_canon()
    }

    fn registry_services_descendant_depth_from_canon(&self, canon: &str) -> Option<usize> {
        let services = self.system_services_registry_canon();
        if canon == services {
            return Some(0);
        }
        let rest = canon.strip_prefix(&services)?;
        let rest = rest.strip_prefix('\\')?;
        if rest.is_empty() {
            return None;
        }
        Some(rest.split('\\').filter(|part| !part.is_empty()).count())
    }

    fn registry_services_order_key_membership_may_change(&self, path: &str) -> bool {
        let canon = nt_hive_core::canon_path(path);
        matches!(
            self.registry_services_descendant_depth_from_canon(&canon),
            Some(1)
        )
    }

    fn registry_services_order_value_write_may_reorder(&self, path: &str) -> bool {
        let canon = nt_hive_core::canon_path(path);
        canon == self.overlay_canon(nt_config_manager::SERVICE_GROUP_ORDER_PATH)
            || matches!(
                self.registry_services_descendant_depth_from_canon(&canon),
                Some(1)
            )
    }

    fn registry_ordered_service_subkey_by_index(
        &mut self,
        requested_index: usize,
    ) -> Option<alloc::string::String> {
        if !self.registry_services_order_cache_valid
            && !self.rebuild_registry_services_order_cache()
        {
            return None;
        }
        self.registry_services_order_cache
            .get(requested_index)
            .cloned()
    }

    fn rebuild_registry_services_order_cache(&mut self) -> bool {
        crate::SERVICES_ORDER_REBUILDS.fetch_add(1, Ordering::Relaxed);
        let Some(services_key) =
            self.mutable_registry_key_by_path(nt_config_manager::SERVICES_PATH)
        else {
            self.registry_services_order_cache.clear();
            self.registry_services_order_cache_valid = true;
            return true;
        };
        let Some(hive) = self.mutable_hives.hive(services_key.hive) else {
            self.registry_services_order_cache.clear();
            self.registry_services_order_cache_valid = true;
            return true;
        };
        let mut entries = alloc::vec::Vec::with_capacity(hive.subkey_count(services_key.key));
        for index in 0..hive.subkey_count(services_key.key) {
            let Some(name) = hive.subkey_name_by_index(services_key.key, index) else {
                continue;
            };
            let Some(service_key) = hive.open_subkey(services_key.key, name) else {
                continue;
            };
            entries.push(nt_config_manager::ServiceDatabaseOrderEntry {
                name: alloc::string::String::from(name),
                service_type: hive.query_dword(service_key, "Type"),
                start_type: hive.query_dword(service_key, "Start"),
                load_order_group: Self::hive_query_registry_string(hive, service_key, "Group"),
                tag: hive.query_dword(service_key, "Tag"),
            });
        }
        let group_order = Self::hive_service_group_order(hive);
        nt_config_manager::sort_service_database_order_entries(&mut entries, &group_order);
        self.registry_services_order_cache.clear();
        for entry in entries {
            self.registry_services_order_cache.push(entry.name);
        }
        self.registry_services_order_cache_valid = true;
        true
    }

    fn hive_service_group_order(
        hive: &nt_hive_core::Hive,
    ) -> alloc::vec::Vec<alloc::string::String> {
        let selected = hive
            .current_control_set()
            .expect("mounted SYSTEM hive has a validated selected control set");
        let mut path = alloc::string::String::from(selected.as_str());
        path.push_str("\\Control\\ServiceGroupOrder");
        let Some(key) = hive.open_key(&path) else {
            return alloc::vec::Vec::new();
        };
        Self::hive_query_registry_multi_string(hive, key, "List").unwrap_or_default()
    }

    fn hive_query_registry_string(
        hive: &nt_hive_core::Hive,
        key: nt_hive_core::CellId,
        name: &str,
    ) -> Option<alloc::string::String> {
        let (value_type, data) = hive.query_value(key, name)?;
        nt_config_manager::RegistryValue {
            name: alloc::string::String::new(),
            value_type,
            data: alloc::vec::Vec::from(data),
        }
        .as_string()
    }

    fn hive_query_registry_multi_string(
        hive: &nt_hive_core::Hive,
        key: nt_hive_core::CellId,
        name: &str,
    ) -> Option<alloc::vec::Vec<alloc::string::String>> {
        let (value_type, data) = hive.query_value(key, name)?;
        nt_config_manager::RegistryValue {
            name: alloc::string::String::new(),
            value_type,
            data: alloc::vec::Vec::from(data),
        }
        .as_multi_string()
    }

    /// Resolve a fault BADGE's process index (pi) to its EPROCESS pid (the badge↔pid convergence
    /// link). Returns `None` before the ProcessManager has created that hosted process.
    pub(crate) fn pm_pid_for_pi(&self, pi: usize) -> Option<nt_process::ProcessId> {
        self.process_mechanisms
            .pid_for_pi(pi)
            .or_else(|| self.temporary_pid_for_pi(pi))
    }

