    pub(crate) fn hosted_tp_worker_tcb(&self, pi: usize, slot: usize) -> Option<u64> {
        self.hosted_thread_tcb_for_badge(tp_worker_badge(pi, slot))
    }

    pub(crate) fn first_free_hosted_tp_worker_slot(&self, pi: usize) -> Option<usize> {
        let used = *self.tp_worker_window_used.get(pi)?;
        (0..TP_WORKER_SLOT_COUNT)
            .find(|&slot| Self::tp_worker_slot_bit(slot).is_some_and(|bit| used & bit == 0))
    }

    pub(crate) fn reserve_hosted_tp_worker_slot(
        &mut self,
        pi: usize,
        slot: usize,
        tid: u64,
    ) -> bool {
        self.reserve_hosted_worker_window_slot(pi, slot, tid, HostedThreadRole::TpWorker { slot })
    }

    pub(crate) fn reserve_hosted_worker_window_slot(
        &mut self,
        pi: usize,
        slot: usize,
        tid: u64,
        role: HostedThreadRole,
    ) -> bool {
        if pi >= MAX_PI || slot >= TP_WORKER_SLOT_COUNT {
            return false;
        }
        if role
            .worker_window_slot()
            .is_none_or(|role_slot| role_slot != slot)
        {
            return false;
        }
        let Some(bit) = Self::tp_worker_slot_bit(slot) else {
            return false;
        };
        if self.tp_worker_window_used[pi] & bit != 0 {
            return false;
        }
        let badge = tp_worker_badge(pi, slot);
        if !self.reserve_hosted_thread_runtime(pi, tid, badge, role) {
            return false;
        }
        self.tp_worker_window_used[pi] |= bit;
        true
    }

    pub(crate) fn release_unmapped_hosted_tp_worker_slot(
        &mut self,
        pi: usize,
        slot: usize,
        tid: u64,
    ) {
        let _ = self.release_hosted_thread_runtime(tid);
        unsafe { release_hosted_tp_worker_window_resources(pi, slot) };
        self.clear_hosted_tp_worker_window_slot(pi, slot);
    }

    pub(crate) fn clear_hosted_tp_worker_window_slot(&mut self, pi: usize, slot: usize) {
        if pi < MAX_PI {
            if let Some(bit) = Self::tp_worker_slot_bit(slot) {
                self.tp_worker_window_used[pi] &= !bit;
            }
        }
    }

    pub(crate) fn clear_hosted_tp_worker_windows(&mut self, pi: usize) {
        if pi < MAX_PI {
            for slot in 0..TP_WORKER_SLOT_COUNT {
                unsafe { release_hosted_tp_worker_window_resources(pi, slot) };
            }
            self.tp_worker_window_used[pi] = 0;
        }
    }

    pub(crate) fn hosted_tp_worker_window_mask(&self, pi: usize) -> u64 {
        self.tp_worker_window_used.get(pi).copied().unwrap_or(0)
    }

    fn abandon_created_hosted_thread(&mut self, pool_slot: usize, tid: u64, handle: u64) {
        let _ = self.release_hosted_thread_runtime(tid);
        if let Some(pid) = self.pm_pid_for_pi(self.pi) {
            let _ = self.close_process_handle(pid, handle);
        }
        let thread = tid as nt_process::ThreadId;
        let _ = self
            .pm
            .set_thread_state(thread, nt_process::ThreadState::Initialized);
        self.release_pool_usage_slot(self.pi, pool_slot);
    }

    fn abandon_created_hosted_thread_for(
        &mut self,
        owner_pi: usize,
        pool_slot: usize,
        tid: u64,
        caller_pid: nt_process::ProcessId,
        handle: u64,
    ) {
        let _ = self.release_hosted_thread_runtime(tid);
        let _ = self.close_process_handle(caller_pid, handle);
        let thread = tid as nt_process::ThreadId;
        let _ = self
            .pm
            .set_thread_state(thread, nt_process::ThreadState::Initialized);
        self.release_pool_usage_slot(owner_pi, pool_slot);
    }

    fn reserve_created_hosted_thread_role(
        &mut self,
        pool_slot: usize,
        tid: u64,
        handle: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> bool {
        if self.hosted_thread_tid_for_role(self.pi, role).is_some()
            || !self.reserve_hosted_thread_runtime(self.pi, tid, badge, role)
        {
            self.abandon_created_hosted_thread(pool_slot, tid, handle);
            return false;
        }
        true
    }

    pub(crate) fn release_hosted_thread_runtime(
        &mut self,
        tid: u64,
    ) -> Option<HostedThreadRuntime> {
        self.thread_runtime.release_tid(tid)
    }

    fn hosted_thread_mechanism_for_tid(&self, tid: u64) -> Option<nt_user_host::ThreadMechanism> {
        if tid == 0 || tid > u32::MAX as u64 {
            return None;
        }
        let tid32 = tid as nt_process::ThreadId;
        self.thread_mechanisms.get_by_tid(tid32).or_else(|| {
            for pi in 0..MAX_PI {
                if self.pm_main_tid_for_pi(pi) == Some(tid32) {
                    return Some(nt_user_host::ThreadMechanism {
                        pi,
                        tid: tid32,
                        kind: nt_user_host::ThreadMechanismKind::Main,
                    });
                }
                for slot in 0..PM_RUNTIME_THREAD_SLOTS {
                    if self.pm_pool_tid_for_slot(pi, slot) == Some(tid32) {
                        return Some(nt_user_host::ThreadMechanism {
                            pi,
                            tid: tid32,
                            kind: nt_user_host::ThreadMechanismKind::Pool { slot },
                        });
                    }
                }
            }
            None
        })
    }

    pub(crate) fn hosted_process_image(
        &self,
        pi: usize,
    ) -> Option<nt_exe_image::HostedProcessImageRef<'_>> {
        // SAFETY: `service_sec_image` constructs the handler after the loop-owned catalog and drops
        // it before the catalog. Catalog mutations occur inside the same serialized service loop:
        // bootstrap seeds the initial images, and NtOpenFile may admit later executable images before
        // their NtCreateSection/NtCreateProcess path consumes the metadata.
        unsafe { (&*self.hosted_images).get_by_pi(pi) }
    }

