    fn current_hosted_thread_role(&self) -> Option<HostedThreadRole> {
        self.hosted_thread_role_for_current_badge().or_else(|| {
            self.thread_runtime
                .get_by_tid(self.current_tid)
                .map(|runtime| runtime.role)
        })
    }

    fn current_thread_has_role(&self, role: HostedThreadRole) -> bool {
        self.current_hosted_thread_role() == Some(role)
    }

    pub(crate) fn refresh_process_manager_gates(&self) {
        let mut process_count = 0u64;
        let mut identity_ok = 0u64;
        let mut running_process_mask = 0u64;
        let mut main_threads_ok = 0u64;
        let mut min_handle_cap = usize::MAX;
        let mut max_handle_cap = 0usize;
        for pi in 0..MAX_PI {
            let Some(pid) = self.pm_pid_for_pi(pi) else {
                continue;
            };
            let bit = if pi < 64 { 1u64 << pi } else { 0 };
            process_count += 1;
            let handle_cap = self.pm.handle_capacity(pid);
            min_handle_cap = min_handle_cap.min(handle_cap);
            max_handle_cap = max_handle_cap.max(handle_cap);
            let distinct = (0..MAX_PI)
                .all(|other_pi| other_pi == pi || self.pm_pid_for_pi(other_pi) != Some(pid));
            let process_running = self
                .pm
                .process(pid)
                .is_some_and(|process| process.state == nt_process::ProcessState::Running);
            let mut image_identity_ok = false;
            if let Some(image) = self.hosted_process_image(pi) {
                if distinct
                    && self.pm.process(pid).is_some_and(|process| {
                        process
                            .image_file_name
                            .eq_ignore_ascii_case(image.process_name)
                    })
                {
                    image_identity_ok = true;
                    identity_ok |= bit;
                }
            }
            if image_identity_ok && process_running {
                running_process_mask |= bit;
            }
            let tid = self.pm_main_tid_for_pi(pi).unwrap_or(0);
            if tid != 0 {
                let cid_ok = self.pm.client_id(tid)
                    == Some(nt_process::ClientId {
                        unique_process: pid,
                        unique_thread: tid,
                    });
                if self.pm.main_thread(pid) == Some(tid) && process_running && cid_ok {
                    main_threads_ok |= bit;
                }
            }
        }
        PM_PROC_COUNT.store(process_count, Ordering::Relaxed);
        PM_OBJECT_COUNT.store(self.pm.process_count() as u64, Ordering::Relaxed);
        PM_IDENTITY_OK.store(identity_ok, Ordering::Relaxed);
        PM_RUNNING_PROCESS_MASK.store(running_process_mask, Ordering::Relaxed);
        PM_MAIN_THREADS_OK.store(main_threads_ok, Ordering::Relaxed);
        PM_HANDLE_CAP_BOOT.store(
            if process_count == 0 {
                0
            } else {
                min_handle_cap as u64
            },
            Ordering::Relaxed,
        );
        PM_HANDLE_CAP_MAX.store(max_handle_cap as u64, Ordering::Relaxed);
    }

    pub(crate) fn insert_process_handle(
        &mut self,
        pid: nt_process::ProcessId,
        object: nt_process::HandleObject,
        granted_access: u32,
    ) -> Result<nt_process::Handle, u32> {
        let cap_before = self.pm.handle_capacity(pid);
        let handle = self.pm.insert_handle(pid, object, granted_access)?;
        self.record_process_handle_insert(pid, cap_before);
        Ok(handle)
    }

    fn insert_inherited_process_handle(
        &mut self,
        pid: nt_process::ProcessId,
        inherited: nt_process::InheritedHandle,
    ) -> Result<nt_process::Handle, u32> {
        let cap_before = self.pm.handle_capacity(pid);
        let handle = self.pm.insert_inherited_handle(pid, inherited)?;
        self.record_process_handle_insert(pid, cap_before);
        Ok(handle)
    }

    fn record_process_handle_insert(&mut self, pid: nt_process::ProcessId, cap_before: usize) {
        let cap_after = self.pm.handle_capacity(pid);
        if cap_after > cap_before {
            PM_HANDLE_CAP_GROWTHS.fetch_add(1, Ordering::Relaxed);
        }
        if cap_after as u64 > PM_HANDLE_CAP_MAX.load(Ordering::Relaxed) {
            PM_HANDLE_CAP_MAX.store(cap_after as u64, Ordering::Relaxed);
        }
        let count = self.pm.handle_count(pid) as u64;
        if count > PM_HANDLE_PEAK.load(Ordering::Relaxed) {
            PM_HANDLE_PEAK.store(count, Ordering::Relaxed);
        }
        PM_HANDLES_TRACKED.fetch_add(1, Ordering::Relaxed);
    }

    fn allocate_hosted_process_slot(
        &mut self,
        parent: nt_process::ProcessId,
        image: nt_exe_image::HostedProcessImageRef<'_>,
        flags: u32,
        job_member_level: u32,
    ) -> Result<usize, u32> {
        let child_pi = image.pi;
        let name = image.process_name;
        let selected_job = self
            .pm
            .select_child_job(Some(parent), flags, job_member_level)?;
        let inherited_handles = if flags & nt_process::PROCESS_CREATE_FLAGS_INHERIT_HANDLES != 0 {
            self.pm.inheritable_handles(parent)?
        } else {
            Vec::new()
        };
        if let Some(existing_pid) = self.pm_pid_for_pi(child_pi) {
            let matches_existing = self.pm.process(existing_pid).is_some_and(|process| {
                process.image_file_name.eq_ignore_ascii_case(name)
                    && process.parent == Some(parent)
                    && self.pm.process_job(existing_pid) == selected_job
            });
            if matches_existing {
                return Ok(child_pi);
            }
            return Err(nt_process::STATUS_INVALID_PARAMETER);
        }
        let token = self
            .pm
            .process_primary_token(parent)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        self.token_store
            .retain(token)
            .map_err(|_| nt_process::STATUS_INVALID_HANDLE)?;
        if let Err(status) = self.publish_registered_hosted_process_metadata(image) {
            let _ = self.token_store.release(token);
            return Err(status);
        }
        let pid = match self.pm.create_process_with_job_policy(
            name,
            Some(parent),
            None,
            flags,
            job_member_level,
        ) {
            Ok(pid) => pid,
            Err(status) => {
                let _ = self.token_store.release(token);
                self.drain_job_notifications();
                self.drain_job_destructions();
                return Err(status);
            }
        };
        self.drain_job_notifications();
        for inherited in inherited_handles {
            if let Err(status) = self.retain_external_handle_reference(inherited.object) {
                let _ = self.token_store.release(token);
                self.rollback_hosted_process_creation(child_pi, pid);
                return Err(status);
            }
            if let Err(status) = self.insert_inherited_process_handle(pid, inherited) {
                self.release_external_handle_reference(inherited.object);
                let _ = self.token_store.release(token);
                self.rollback_hosted_process_creation(child_pi, pid);
                return Err(status);
            }
        }
        if let Err(status) = self.pm.replace_process_primary_token(pid, Some(token)) {
            let _ = self.token_store.release(token);
            self.rollback_hosted_process_creation(child_pi, pid);
            return Err(status);
        }
        self.pm
            .reserve_process_threads(pid, 1 + PM_RUNTIME_THREAD_SLOTS);
        self.process_vspaces[child_pi] = 0;
        self.clear_hosted_tp_worker_windows(child_pi);
        let main_tid = match self.pm.create_thread(pid, 0, 0, false) {
            Ok(tid) => tid,
            Err(status) => {
                self.rollback_hosted_process_creation(child_pi, pid);
                return Err(status);
            }
        };
        if let Err(status) =
            self.register_hosted_process_identity(child_pi, pid, main_tid, image.top_badge)
        {
            self.rollback_hosted_process_creation(child_pi, pid);
            return Err(status);
        }
        for slot in 0..PM_RUNTIME_THREAD_SLOTS {
            let tid = match self.pm.create_thread(pid, 0, 0, false) {
                Ok(tid) => tid,
                Err(status) => {
                    self.rollback_hosted_process_creation(child_pi, pid);
                    return Err(status);
                }
            };
            if let Err(status) = self
                .pm
                .set_thread_state(tid, nt_process::ThreadState::Initialized)
            {
                self.rollback_hosted_process_creation(child_pi, pid);
                return Err(status);
            }
            if let Err(status) = self.register_hosted_pool_thread_identity(child_pi, slot, tid) {
                self.rollback_hosted_process_creation(child_pi, pid);
                return Err(status);
            }
        }
        self.pm.reserve_handles(pid, PM_HANDLE_RESERVE);
        PM_DYNAMIC_PROCESS_ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        self.refresh_process_manager_gates();
        unsafe {
            print_str(b"[pm-dynamic] allocated hosted process pi=");
            print_u64(child_pi as u64);
            print_str(b" pid=");
            print_u64(pid as u64);
            print_str(b" parent=");
            print_u64(parent as u64);
            print_str(b" image=");
            print_str(name.as_bytes());
            print_str(b" token=");
            print_u64(token.raw() as u64);
            print_str(b" inherited\n");
        }
        Ok(child_pi)
    }

    fn rollback_hosted_process_creation(&mut self, pi: usize, pid: nt_process::ProcessId) {
        while let Some(object) = self.pm.take_any_handle(pid) {
            self.release_handle_object(object);
        }
        let _ = self.thread_mechanisms.release_main(pi);
        for slot in 0..PM_RUNTIME_THREAD_SLOTS {
            let _ = self.thread_mechanisms.release_pool(pi, slot);
        }
        let _ = self.process_mechanisms.release_pi(pi);
        let deletion = self
            .pm
            .abort_process_creation(pid)
            .expect("unpublished process creation remains privately owned");
        if let Some(token) = deletion.primary_token {
            let _ = self.token_store.release(token);
        }
        debug_assert!(deletion.exception_port.is_none());
        self.process_vspaces[pi] = 0;
        self.pool_used[pi] = 0;
        self.clear_hosted_tp_worker_windows(pi);
        self.drain_job_notifications();
        self.drain_job_destructions();
        self.refresh_process_manager_gates();
    }
    /// Mint an executive handle for the CURRENT process (`self.pi`) and record it in that process's
    /// real EPROCESS handle table. The returned value is the process-local NT handle
    /// (`(slot + 1) * 4`); consumers that need side state must key it by process and clear it on the
    /// matching successful `NtClose`.
    pub(crate) fn mint_handle(&mut self) -> u64 {
        if let Some(pid) = self.pm_pid_for_pi(self.pi) {
            if let Ok(h) = self.insert_process_handle(pid, nt_process::HandleObject::Opaque(0), 0) {
                return h as u64;
            }
        }
        // Fallback (no EPROCESS for this pi yet): global monotonic value.
        let h = self.next_handle;
        self.next_handle += 1;
        h
    }

    fn map_directory_object_access(mut access: u32) -> u32 {
        const READ_CONTROL: u32 = 0x0002_0000;
        const DIRECTORY_ALL_ACCESS: u32 = 0x000F_0000 | 0x000F;
        if access & 0x8000_0000 != 0 {
            access |= READ_CONTROL | DIRECTORY_QUERY_ACCESS | DIRECTORY_TRAVERSE_ACCESS;
        }
        if access & 0x4000_0000 != 0 {
            access |= READ_CONTROL
                | DIRECTORY_CREATE_OBJECT_ACCESS
                | DIRECTORY_CREATE_SUBDIRECTORY_ACCESS;
        }
        if access & 0x2000_0000 != 0 {
            access |= READ_CONTROL | DIRECTORY_TRAVERSE_ACCESS;
        }
        if access & (0x1000_0000 | 0x0200_0000) != 0 {
            access |= DIRECTORY_ALL_ACCESS;
        }
        access & !(0xF000_0000 | 0x0200_0000)
    }

    fn map_symbolic_link_object_access(mut access: u32) -> u32 {
        const READ_CONTROL: u32 = 0x0002_0000;
        const SYMBOLIC_LINK_ALL_ACCESS: u32 = 0x000F_0000 | SYMBOLIC_LINK_QUERY_ACCESS;
        if access & 0x8000_0000 != 0 {
            access |= READ_CONTROL | SYMBOLIC_LINK_QUERY_ACCESS;
        }
        if access & 0x2000_0000 != 0 {
            access |= READ_CONTROL | SYMBOLIC_LINK_QUERY_ACCESS;
        }
        if access & (0x1000_0000 | 0x0200_0000) != 0 {
            access |= SYMBOLIC_LINK_ALL_ACCESS;
        }
        access & !(0xF000_0000 | 0x0200_0000)
    }

    fn object_namespace_handle_tag(kind: u8, index: usize) -> Option<u64> {
        let tag = match kind {
            OBJ_KIND_DIRECTORY => DIRECTORY_OBJECT_HANDLE_TAG,
            OBJ_KIND_SYMBOLIC_LINK => SYMBOLIC_LINK_HANDLE_TAG,
            OBJ_KIND_EVENT => EVENT_HANDLE_TAG,
            OBJ_KIND_SEMAPHORE => SEMAPHORE_HANDLE_TAG,
            OBJ_KIND_MUTANT => MUTANT_HANDLE_TAG,
            OBJ_KIND_TIMER => TIMER_HANDLE_TAG,
            _ => return None,
        };
        Some(tag | index as u64)
    }

    fn object_namespace_tag_kind(tag: u64) -> Option<u8> {
        match tag & OBJECT_NAMESPACE_HANDLE_TAG_MASK {
            DIRECTORY_OBJECT_HANDLE_TAG => Some(OBJ_KIND_DIRECTORY),
            SYMBOLIC_LINK_HANDLE_TAG => Some(OBJ_KIND_SYMBOLIC_LINK),
            _ => None,
        }
    }

    fn opaque_object_namespace_index(tag: u64) -> Option<(u8, usize)> {
        let tag_kind = if tag & EVENT_HANDLE_TAG_MASK == EVENT_HANDLE_TAG {
            Some(OBJ_KIND_EVENT)
        } else if tag & SEMAPHORE_HANDLE_TAG_MASK == SEMAPHORE_HANDLE_TAG {
            Some(OBJ_KIND_SEMAPHORE)
        } else if tag & MUTANT_HANDLE_TAG_MASK == MUTANT_HANDLE_TAG {
            Some(OBJ_KIND_MUTANT)
        } else if tag & TIMER_HANDLE_TAG_MASK == TIMER_HANDLE_TAG {
            Some(OBJ_KIND_TIMER)
        } else {
            Self::object_namespace_tag_kind(tag)
        }?;
        Some((tag_kind, (tag & 0xFFFF_FFFF) as usize))
    }

    fn object_namespace_mapped_access(kind: u8, desired_access: u32) -> Option<u32> {
        match kind {
            OBJ_KIND_DIRECTORY => Some(Self::map_directory_object_access(desired_access)),
            OBJ_KIND_SYMBOLIC_LINK => Some(Self::map_symbolic_link_object_access(desired_access)),
            _ => None,
        }
    }

    fn mint_object_namespace_handle(&mut self, index: usize, desired_access: u32) -> Option<u64> {
        let entry = self.obj_ns.get(index)?;
        if !entry.is_live() {
            return None;
        }
        let tag = Self::object_namespace_handle_tag(entry.kind, index)?;
        let access = Self::object_namespace_mapped_access(entry.kind, desired_access)?;
        let pid = self.pm_pid_for_pi(self.pi)?;
        self.insert_process_handle(pid, nt_process::HandleObject::Opaque(tag), access)
            .ok()
            .map(|handle| handle as u64)
    }

    fn object_namespace_index_for_handle(
        &self,
        handle: u64,
        required_kind: Option<u8>,
        required_access: u32,
    ) -> Result<usize, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if handle >= OBJ_HANDLE_BASE {
            let index = (handle - OBJ_HANDLE_BASE) as usize;
            let entry = self.obj_ns.get(index).ok_or(STATUS_INVALID_HANDLE)?;
            if !entry.is_live() {
                return Err(STATUS_INVALID_HANDLE);
            }
            if required_kind.is_some_and(|kind| entry.kind != kind) {
                return Err(STATUS_OBJECT_TYPE_MISMATCH);
            }
            return Ok(index);
        }
        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let handle = handle as nt_process::Handle;
        let tag = match self.pm.lookup_handle(pid, handle) {
            Some(nt_process::HandleObject::Opaque(tag)) => tag,
            Some(_) => return Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => return Err(STATUS_INVALID_HANDLE),
        };
        let tag_kind = Self::object_namespace_tag_kind(tag).ok_or(STATUS_OBJECT_TYPE_MISMATCH)?;
        if required_kind.is_some_and(|kind| tag_kind != kind) {
            return Err(STATUS_OBJECT_TYPE_MISMATCH);
        }
        let granted = self
            .pm
            .handle_access(pid, handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        let index = (tag & 0xFFFF_FFFF) as usize;
        let entry = self.obj_ns.get(index).ok_or(STATUS_INVALID_HANDLE)?;
        if !entry.is_live() || entry.kind != tag_kind {
            return Err(STATUS_INVALID_HANDLE);
        }
        Ok(index)
    }

    /// Mint a process-local handle for an anonymous keyed event. The wait/release rendezvous is
    /// currently keyed by the caller's raw `Key` value, so the object only needs durable handle-table
    /// ownership plus a non-NULL value for ReactOS' per-process RTL keyed-event global.
    pub(crate) fn mint_keyed_event_handle(&mut self, access: u32) -> u64 {
        if let Some(pid) = self.pm_pid_for_pi(self.pi) {
            if let Ok(h) = self.insert_process_handle(
                pid,
                nt_process::HandleObject::Opaque(KEYEDEVENT_HANDLE_TAG),
                access,
            ) {
                return h as u64;
            }
        }
        self.mint_handle()
    }

    fn reserve_current_process_handle_slot(
        &mut self,
    ) -> Result<nt_process::HandleReservation, u32> {
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let capacity = self.pm.handle_capacity(pid);
        let reservation = self.pm.try_reserve_handle_slot(pid)?;
        let reserved = self.pm.handle_capacity(pid);
        if reserved != capacity {
            PM_HANDLE_CAP_GROWTHS.fetch_add(1, Ordering::Relaxed);
            PM_HANDLE_CAP_MAX.fetch_max(reserved as u64, Ordering::Relaxed);
        }
        Ok(reservation)
    }

    fn bind_reserved_file_handle(
        &mut self,
        file_id: u64,
        reservation: nt_process::HandleReservation,
        access: u32,
    ) -> Result<u64, u32> {
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        if reservation.process_id != pid {
            return Err(STATUS_INVALID_HANDLE);
        }
        let (device_id, _) = driver_launch::hosted_file_route(file_id)
            .ok_or(nt_fs::STATUS_INVALID_DEVICE_REQUEST)?;
        if self.file_completion.device_id(file_id)? != device_id {
            return Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST);
        }
        self.pm.bind_reserved_handle(
            reservation,
            nt_process::HandleObject::RoutedFile { file_id, device_id },
            access,
        )?;
        if let Err(status) = self.file_completion.commit_reserved_file_handle(file_id) {
            let _ = self.pm.cancel_bound_handle(reservation);
            return Err(status);
        }
        Ok(reservation.handle as u64)
    }

    pub(crate) fn publish_bound_file_handle(
        &mut self,
        reservation: nt_process::HandleReservation,
    ) -> Result<u64, u32> {
        let handle = self.pm.publish_reserved_handle(reservation)?;
        let count = self.pm.handle_count(reservation.process_id) as u64;
        PM_HANDLE_PEAK.fetch_max(count, Ordering::Relaxed);
        PM_HANDLES_TRACKED.fetch_add(1, Ordering::Relaxed);
        Ok(handle as u64)
    }

    /// Mint a process-local handle for a read-only file on the mounted FAT volume.
    pub(crate) fn mint_disk_file_handle(
        &mut self,
        file: crate::fs_loader::FatOpenMetadata,
        volume_relative_path: &[u8],
        access: u32,
        share_access: u32,
        create_options: u32,
    ) -> Result<u64, u32> {
        let pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let first_cluster = file.first_cluster;
        let size =
            u32::try_from(file.metadata.end_of_file).map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
        let object_id = self.readonly_file_opens.create(
            first_cluster,
            size,
            volume_relative_path,
            access,
            share_access,
            create_options,
            file.metadata,
            file.alternate_name,
        )?;
        let handle = match self.insert_process_handle(
            pid,
            nt_process::HandleObject::DiskFile {
                first_cluster,
                size,
                object_id,
            },
            access,
        ) {
            Ok(handle) => handle,
            Err(status) => {
                let _ = self.readonly_file_opens.release(object_id);
                return Err(status);
            }
        };
        Ok(handle as u64)
    }

    fn readonly_disk_open_entry(
        name16: &[u16],
        desired_access: u32,
        open_options: u32,
    ) -> Option<crate::fs_loader::FatOpenMetadata> {
        if !Self::readonly_disk_open_allowed(desired_access, open_options) {
            return None;
        }
        Self::readonly_volume_metadata(name16).filter(|entry| !entry.metadata.is_directory)
    }

    fn readonly_disk_open_allowed(desired_access: u32, open_options: u32) -> bool {
        nt_fs::installed_file_open_action(desired_access, nt_fs::FILE_OPEN, open_options)
            == Ok(nt_fs::InstalledFileOpenAction::ReadOnly)
    }

    fn readonly_volume_metadata(name16: &[u16]) -> Option<crate::fs_loader::FatOpenMetadata> {
        nt_fs::nt_path_to_volume_relative(name16, b"reactos").and_then(|path| unsafe {
            exec_fs().and_then(|fs| crate::fs_loader::fat_open_path_metadata(&fs, &path))
        })
    }

    fn readonly_volume_entry(name16: &[u16]) -> Option<(u32, u32, u8)> {
        let path = nt_fs::nt_path_to_volume_relative(name16, b"reactos")?;
        unsafe {
            let fs = exec_fs()?;
            if path.is_empty() {
                Some((fs.root_cl, 0, 0x10))
            } else {
                fat_open_path_entry(&fs, &path)
            }
        }
    }

    fn readonly_volume_relative_is_dir(relative: &[u8]) -> bool {
        unsafe {
            let Some(fs) = exec_fs() else {
                return false;
            };
            if relative.is_empty() {
                return true;
            }
            fat_open_path_entry(&fs, relative)
                .is_some_and(|(_, _, attributes)| attributes & 0x10 != 0)
        }
    }

    fn overlay_open_missed(status: u32) -> bool {
        status == nt_fs::STATUS_OBJECT_NAME_NOT_FOUND
            || status == nt_fs::STATUS_OBJECT_PATH_NOT_FOUND
    }

    fn volume_relative_parent(relative: &[u8]) -> Option<&[u8]> {
        let trimmed = relative.strip_suffix(b"\\").unwrap_or(relative);
        if trimmed.is_empty() {
            return None;
        }
        Some(match trimmed.iter().rposition(|byte| *byte == b'\\') {
            Some(index) => &trimmed[..index],
            None => &[],
        })
    }

    fn readonly_disk_open_miss_status(name16: &[u16]) -> Option<u32> {
        let path = nt_fs::nt_path_to_volume_relative(name16, b"reactos")?;
        let fs = unsafe { exec_fs() }?;
        if path.is_empty() {
            return Some(nt_fs::STATUS_NOT_A_DIRECTORY);
        }
        Some(match unsafe { fat_open_path_entry(&fs, &path) } {
            Some((_, _, attributes)) if attributes & 0x10 != 0 => nt_fs::STATUS_NOT_A_DIRECTORY,
            Some(_) => nt_fs::STATUS_NOT_SUPPORTED,
            None => nt_fs::STATUS_OBJECT_NAME_NOT_FOUND,
        })
    }

    fn unserved_nt_create_file_namespace(&self, name16: &[u16]) -> u32 {
        // A file namespace this kernel has no mounted device or filesystem service for. Report a
        // real object namespace miss: no fabricated handle, and no implementation-stub status.
        if !NT_CREATE_FILE_UNSERVED_NAMESPACE_TRACED.swap(true, Ordering::Relaxed) {
            print_str(b"[nt-create-file] pi=");
            print_u64(self.pi as u64);
            print_str(b" unserved file namespace -> STATUS_OBJECT_PATH_NOT_FOUND name=\"");
            for &unit in name16.iter().take(96) {
                debug_put_char(if (0x20..0x7f).contains(&unit) {
                    unit as u8
                } else {
                    b'?'
                });
            }
            print_str(b"\"\n");
        }
        NT_CREATE_FILE_UNSERVED_NAMESPACE.fetch_add(1, Ordering::Relaxed);
        nt_fs::STATUS_OBJECT_PATH_NOT_FOUND
    }

    /// Mint a process-local handle for a directory on the mounted FAT volume.
    pub(crate) fn mint_directory_handle(
        &mut self,
        directory: crate::fs_loader::FatOpenMetadata,
        volume_relative_path: &[u8],
        access: u32,
        share_access: u32,
        create_options: u32,
    ) -> Result<u64, u32> {
        let pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let first_cluster = directory.first_cluster;
        if !directory.metadata.is_directory {
            return Err(nt_fs::STATUS_NOT_A_DIRECTORY);
        }
        let object_id = self.directory_opens.create(
            first_cluster,
            volume_relative_path,
            access,
            share_access,
            create_options,
            directory.metadata,
            directory.alternate_name,
        )?;
        let handle = match self.insert_process_handle(
            pid,
            nt_process::HandleObject::Directory {
                first_cluster,
                object_id,
            },
            access,
        ) {
            Ok(handle) => handle,
            Err(status) => {
                let _ = self.directory_opens.release(object_id);
                return Err(status);
            }
        };
        Ok(handle as u64)
    }

    unsafe fn create_overlay_file_relative(
        &mut self,
        relative: &[u8],
        desired_access: u32,
        file_attributes: u32,
        share_access: u32,
        disposition: u32,
        options: u32,
    ) -> (u32, u64, u64) {
        let (mut status, file_id, information) = crate::writable_fs::create(
            relative,
            desired_access,
            file_attributes,
            share_access,
            disposition,
            options,
        );
        let Some(file_id) = file_id else {
            return (status, 0, 0);
        };
        self.writable_fs_dirty = true;
        match self.mint_overlay_file_handle(file_id, desired_access) {
            Some(handle) => (status, information, handle),
            None => {
                status = STATUS_INSUFFICIENT_RESOURCES;
                (status, 0, 0)
            }
        }
    }

    unsafe fn open_installed_file(
        &mut self,
        source: crate::fs_loader::FatOpenMetadata,
        relative: &[u8],
        desired_access: u32,
        file_attributes: u32,
        share_access: u32,
        disposition: u32,
        options: u32,
    ) -> (u32, u64, u64) {
        if source.metadata.is_directory {
            return (nt_fs::STATUS_FILE_IS_A_DIRECTORY, 0, 0);
        }
        let action = match nt_fs::installed_file_open_action(desired_access, disposition, options) {
            Ok(action) => action,
            Err(status) => return (status, 0, 0),
        };
        let copy_mode = match action {
            nt_fs::InstalledFileOpenAction::ReadOnly => {
                return match self.mint_disk_file_handle(
                    source,
                    relative,
                    desired_access,
                    share_access,
                    options,
                ) {
                    Ok(handle) => (nt_fs::STATUS_SUCCESS, nt_fs::FILE_OPENED as u64, handle),
                    Err(status) => (status, 0, 0),
                };
            }
            nt_fs::InstalledFileOpenAction::CopyContents => {
                crate::writable_fs::InstalledFileCopyUp::PreserveContents
            }
            nt_fs::InstalledFileOpenAction::CopyMetadata => {
                crate::writable_fs::InstalledFileCopyUp::MetadataOnly
            }
            nt_fs::InstalledFileOpenAction::NameCollision => {
                return (nt_fs::STATUS_OBJECT_NAME_COLLISION, 0, 0);
            }
        };
        if let Err(status) = self.readonly_file_opens.check_share(
            relative,
            source.metadata,
            desired_access,
            share_access,
        ) {
            return (status, 0, 0);
        }
        if let Some(parent) = Self::volume_relative_parent(relative) {
            if !Self::readonly_volume_relative_is_dir(parent) {
                return (nt_fs::STATUS_OBJECT_PATH_NOT_FOUND, 0, 0);
            }
            match crate::writable_fs::ensure_installed_directory_relative(parent) {
                Ok(true) => self.writable_fs_dirty = true,
                Ok(false) => {}
                Err(status) => return (status, 0, 0),
            }
        }
        if let Err(status) = crate::writable_fs::copy_up_installed_file(relative, source, copy_mode)
        {
            return (status, 0, 0);
        }
        self.create_overlay_file_relative(
            relative,
            desired_access,
            file_attributes,
            share_access,
            disposition,
            options,
        )
    }

    unsafe fn create_local_file_relative(
        &mut self,
        root: FileParseRoot,
        name16: &[u16],
        desired_access: u32,
        file_attributes: u32,
        share_access: u32,
        disposition: u32,
        options: u32,
    ) -> (u32, u64, u64) {
        let mut folded = [0u8; FILE_OBJECT_NAME_CAP];
        let mut relative = [0u8; FILE_OBJECT_NAME_CAP];
        let relative_len =
            match Self::capture_relative_file_path(name16, &mut folded, &mut relative) {
                Ok(length) => length,
                Err(status) => return (status, 0, 0),
            };
        let relative = &relative[..relative_len];

        let publish_overlay = |this: &mut Self, result: (u32, Option<u64>, u64)| {
            let (mut status, file_id, information) = result;
            let mut handle = 0;
            if let Some(file_id) = file_id {
                this.writable_fs_dirty = true;
                match this.mint_overlay_file_handle(file_id, desired_access) {
                    Some(opened) => handle = opened,
                    None => status = STATUS_INSUFFICIENT_RESOURCES,
                }
            }
            (status, information, handle)
        };

        match root {
            FileParseRoot::OverlayFile(root_file_id) => publish_overlay(
                self,
                crate::writable_fs::create_relative_to_directory(
                    root_file_id,
                    relative,
                    desired_access,
                    file_attributes,
                    share_access,
                    disposition,
                    options,
                ),
            ),
            FileParseRoot::FatDirectory {
                first_cluster,
                object_id,
            } => {
                let mut parent_path = [0u8; nt_fs::DIRECTORY_OPEN_PATH_CAP];
                let parent_len = {
                    let Ok(open) = self.directory_opens.get(object_id) else {
                        return (STATUS_INVALID_HANDLE, 0, 0);
                    };
                    if open.first_cluster != first_cluster
                        || open.volume_relative_path().len() > parent_path.len()
                    {
                        return (STATUS_INVALID_HANDLE, 0, 0);
                    }
                    let length = open.volume_relative_path().len();
                    parent_path[..length].copy_from_slice(open.volume_relative_path());
                    length
                };
                let mut full_path = [0u8; nt_fs::DIRECTORY_OPEN_PATH_CAP];
                let full_len = match Self::join_volume_relative_path(
                    &parent_path[..parent_len],
                    relative,
                    &mut full_path,
                ) {
                    Ok(length) => length,
                    Err(status) => return (status, 0, 0),
                };
                let full_path = &full_path[..full_len];
                if crate::writable_fs::query_attributes_relative_if_mounted(full_path).is_some() {
                    return publish_overlay(
                        self,
                        crate::writable_fs::create(
                            full_path,
                            desired_access,
                            file_attributes,
                            share_access,
                            disposition,
                            options,
                        ),
                    );
                }
                let fat_entry = exec_fs().and_then(|fs| {
                    crate::fs_loader::fat_open_path_metadata_from(&fs, first_cluster, relative)
                });
                if let Some(source) = fat_entry.filter(|entry| !entry.metadata.is_directory) {
                    return self.open_installed_file(
                        source,
                        full_path,
                        desired_access,
                        file_attributes,
                        share_access,
                        disposition,
                        options,
                    );
                }
                if disposition == nt_fs::FILE_OPEN
                    || (disposition == nt_fs::FILE_OPEN_IF && fat_entry.is_some())
                {
                    let Some(entry) = fat_entry else {
                        return (nt_fs::STATUS_OBJECT_NAME_NOT_FOUND, 0, 0);
                    };
                    let is_directory = entry.metadata.is_directory;
                    if options & nt_fs::FILE_DIRECTORY_FILE != 0 && !is_directory {
                        return (nt_fs::STATUS_NOT_A_DIRECTORY, 0, 0);
                    }
                    if options & nt_fs::FILE_NON_DIRECTORY_FILE != 0 && is_directory {
                        return (nt_fs::STATUS_FILE_IS_A_DIRECTORY, 0, 0);
                    }
                    let handle = if is_directory {
                        self.mint_directory_handle(
                            entry,
                            full_path,
                            desired_access,
                            share_access,
                            options,
                        )
                    } else if Self::readonly_disk_open_allowed(desired_access, options) {
                        self.mint_disk_file_handle(
                            entry,
                            full_path,
                            desired_access,
                            share_access,
                            options,
                        )
                    } else {
                        return (nt_fs::STATUS_NOT_SUPPORTED, 0, 0);
                    };
                    return match handle {
                        Ok(handle) => (nt_fs::STATUS_SUCCESS, nt_fs::FILE_OPENED as u64, handle),
                        Err(status) => (status, 0, 0),
                    };
                }
                if disposition == nt_fs::FILE_CREATE && fat_entry.is_some() {
                    return (nt_fs::STATUS_OBJECT_NAME_COLLISION, 0, 0);
                }
                if let Some(parent) = Self::volume_relative_parent(full_path) {
                    if Self::readonly_volume_relative_is_dir(parent)
                        && crate::writable_fs::provision_directory_relative_change(parent)
                            == Some(true)
                    {
                        self.writable_fs_dirty = true;
                    }
                }
                publish_overlay(
                    self,
                    crate::writable_fs::create(
                        full_path,
                        desired_access,
                        file_attributes,
                        share_access,
                        disposition,
                        options,
                    ),
                )
            }
            FileParseRoot::NonDirectoryFile => (nt_fs::STATUS_NOT_A_DIRECTORY, 0, 0),
            FileParseRoot::Absolute
            | FileParseRoot::ObjectDirectory { .. }
            | FileParseRoot::HostedFile { .. } => (STATUS_INVALID_HANDLE, 0, 0),
        }
    }

    fn disk_file_for(&self, handle: u64) -> Result<Option<(u32, u32, u32)>, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const FILE_READ_DATA: u32 = 0x0000_0001;
        const GENERIC_READ: u32 = 0x8000_0000;
        const GENERIC_ALL: u32 = 0x1000_0000;
        let Some(pid) = self.pm_pid_for_pi(self.pi) else {
            return Ok(None);
        };
        let Some(object) = self.pm.lookup_handle(pid, handle as nt_process::Handle) else {
            return Ok(None);
        };
        match object {
            nt_process::HandleObject::DiskFile {
                first_cluster,
                size,
                object_id,
            } => {
                let access = self
                    .pm
                    .handle_access(pid, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if access & (FILE_READ_DATA | GENERIC_READ | GENERIC_ALL) == 0 {
                    return Err(STATUS_ACCESS_DENIED);
                }
                let open = self.readonly_file_opens.get(object_id)?;
                if open.first_cluster != first_cluster || open.size != size {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(Some((first_cluster, size, object_id)))
            }
            _ => Ok(None),
        }
    }

    unsafe fn readonly_disk_read_to_user(
        &self,
        first_cluster: u32,
        file_size: u32,
        offset: u32,
        buffer: u64,
        len: usize,
    ) -> Result<usize, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DEVICE_NOT_READY: u32 = 0xC000_00A3;
        const STATUS_IO_DEVICE_ERROR: u32 = 0xC000_0185;
        const READ_SCRATCH_CAP: usize = 64 * 1024;

        let Some(fs) = exec_fs() else {
            return Err(STATUS_DEVICE_NOT_READY);
        };
        let total = len.min(file_size.saturating_sub(offset) as usize);
        let scratch = core::slice::from_raw_parts_mut(
            core::ptr::addr_of_mut!(OVERLAY_WRITE_SCRATCH) as *mut u8,
            READ_SCRATCH_CAP,
        );
        let mut copied = 0usize;
        while copied < total {
            let chunk = (total - copied).min(scratch.len());
            let file_offset = offset + copied as u32;
            let read = fat_read_file_range(
                &fs,
                first_cluster,
                file_size,
                file_offset,
                &mut scratch[..chunk],
            );
            if read != chunk {
                return Err(STATUS_IO_DEVICE_ERROR);
            }
            let Some(dst) = buffer.checked_add(copied as u64) else {
                return Err(STATUS_ACCESS_VIOLATION);
            };
            if read != 0 && !self.xas_try_write_buf(dst, &scratch[..read]) {
                return Err(STATUS_ACCESS_VIOLATION);
            }
            copied += read;
        }
        Ok(copied)
    }

    /// Mint a process-local handle for a file or directory on the WRITABLE overlay volume.
    /// `file_id` is that volume's own file-object id (see `writable_fs`).
    pub(crate) fn mint_overlay_file_handle(&mut self, file_id: u64, access: u32) -> Option<u64> {
        let privileges = nt_fs::FileOpenPrivileges {
            manage_volume: self.current_token_has_privilege(nt_security::SE_MANAGE_VOLUME),
        };
        if unsafe { crate::writable_fs::capture_open_privileges(file_id, privileges) }
            != nt_fs::STATUS_SUCCESS
        {
            unsafe { crate::writable_fs::close(file_id) };
            return None;
        }
        let Some(pid) = self.pm_pid_for_pi(self.pi) else {
            unsafe { crate::writable_fs::close(file_id) };
            return None;
        };
        let handle = match self.insert_process_handle(
            pid,
            nt_process::HandleObject::OverlayFile(file_id),
            access,
        ) {
            Ok(handle) => handle,
            Err(_) => {
                // The volume owns the file object until a handle takes it; give it back.
                unsafe { crate::writable_fs::close(file_id) };
                return None;
            }
        };
        Some(handle as u64)
    }

    /// The writable-overlay file-object id behind `handle`, or `None` when the handle names some
    /// other kind of object (so the caller falls through to its existing routing).
    pub(crate) fn overlay_file_id_for(&self, handle: u64) -> Option<u64> {
        let pid = self.pm_pid_for_pi(self.pi)?;
        match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::OverlayFile(file_id)) => Some(file_id),
            _ => None,
        }
    }

    /// Resolve a writable-overlay FILE_OBJECT for services that must write kernel-owned bytes to a
    /// caller-opened file. Other file backends fail visibly until they expose the same write seam.
    pub(crate) fn overlay_write_file_id_for(&self, handle: u64) -> Result<u64, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        const FILE_WRITE_DATA: u32 = 0x0000_0002;
        const GENERIC_WRITE: u32 = 0x4000_0000;
        const GENERIC_ALL: u32 = 0x1000_0000;

        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let object = self
            .pm
            .lookup_handle(pid, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        let access = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if access & (FILE_WRITE_DATA | GENERIC_WRITE | GENERIC_ALL) == 0 {
            return Err(STATUS_ACCESS_DENIED);
        }
        match object {
            nt_process::HandleObject::OverlayFile(file_id) => Ok(file_id),
            nt_process::HandleObject::File(_)
            | nt_process::HandleObject::RoutedFile { .. }
            | nt_process::HandleObject::DiskFile { .. }
            | nt_process::HandleObject::Directory { .. } => {
                Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST)
            }
            _ => Err(STATUS_OBJECT_TYPE_MISMATCH),
        }
    }

    /// Mint a process-local event handle that references a shared executive event identity.
    pub(crate) fn mint_event_handle(&mut self, event_index: usize, access: u32) -> Option<u64> {
        let pid = self.pm_pid_for_pi(self.pi)?;
        let tag = EVENT_HANDLE_TAG | event_index as u64;
        let handle = self
            .insert_process_handle(
                pid,
                nt_process::HandleObject::Opaque(tag),
                nt_kernel_exec::map_event_access(access),
            )
            .ok()?;
        Some(handle as u64)
    }

    /// Resolve a typed process-local event handle and enforce the access requested by the operation.
    pub(crate) fn event_index_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<usize, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if handle >= OBJ_HANDLE_BASE {
            let index = (handle - OBJ_HANDLE_BASE) as usize;
            return match self.obj_ns.get(index) {
                Some(entry) if entry.kind != 2 => Err(STATUS_OBJECT_TYPE_MISMATCH),
                _ => Err(STATUS_INVALID_HANDLE),
            };
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let tag = match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::Opaque(tag))
                if tag & EVENT_HANDLE_TAG_MASK == EVENT_HANDLE_TAG =>
            {
                tag
            }
            Some(_) => return Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => return Err(STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        let index = (tag & 0xFFFF_FFFF) as usize;
        self.obj_ns
            .get(index)
            .filter(|entry| entry.kind == 2 && self.events.contains(index as u64))
            .map(|_| index)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    pub(crate) fn mint_timer_handle(&mut self, timer_index: usize, access: u32) -> Option<u64> {
        let pid = self.pm_pid_for_pi(self.pi)?;
        let tag = TIMER_HANDLE_TAG | timer_index as u64;
        let handle = self
            .insert_process_handle(
                pid,
                nt_process::HandleObject::Opaque(tag),
                nt_kernel_exec::map_timer_access(access),
            )
            .ok()?;
        Some(handle as u64)
    }

    pub(crate) fn timer_index_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<usize, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if handle >= OBJ_HANDLE_BASE {
            let index = (handle - OBJ_HANDLE_BASE) as usize;
            return match self.obj_ns.get(index) {
                Some(entry) if entry.kind != OBJ_KIND_TIMER => Err(STATUS_OBJECT_TYPE_MISMATCH),
                _ => Err(STATUS_INVALID_HANDLE),
            };
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let tag = match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::Opaque(tag))
                if tag & TIMER_HANDLE_TAG_MASK == TIMER_HANDLE_TAG =>
            {
                tag
            }
            Some(_) => return Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => return Err(STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        let index = (tag & 0xFFFF_FFFF) as usize;
        self.obj_ns
            .get(index)
            .filter(|entry| entry.kind == OBJ_KIND_TIMER && self.events.contains(index as u64))
            .map(|_| index)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    pub(crate) fn signal_event_index(&mut self, index: usize) -> u32 {
        let Some(previous) = self.events.set_existing(index as u64) else {
            return 0xC000_0008; // STATUS_INVALID_HANDLE
        };
        if !previous {
            // SAFETY: native dispatch is serialized; the signal and waiter selection are one
            // executive transition.
            unsafe { wait_wake_dispatcher_set(self) };
        }
        0
    }

