    pub(crate) fn mutant_index_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<usize, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if handle >= OBJ_HANDLE_BASE {
            let index = (handle - OBJ_HANDLE_BASE) as usize;
            return match self.obj_ns.get(index) {
                Some(entry) if entry.kind != 4 => Err(STATUS_OBJECT_TYPE_MISMATCH),
                _ => Err(STATUS_INVALID_HANDLE),
            };
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let tag = match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::Opaque(tag))
                if tag & MUTANT_HANDLE_TAG_MASK == MUTANT_HANDLE_TAG =>
            {
                tag
            }
            Some(_) => return Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => return Err(STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        let index = (tag & 0xFFFF_FFFF) as usize;
        self.obj_ns
            .get(index)
            .filter(|entry| entry.kind == 4 && self.mutants.contains(index as u64))
            .map(|_| index)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    /// Resolve a typed process-local `DEBUG_OBJECT` handle and enforce the access the operation
    /// requires (`DbgkDebugObjectMapping`-mapped at create time).
    pub(crate) fn debug_object_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<nt_process::dbgk::DebugObjectId, u32> {
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        let pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let object = match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::DebugObject(object)) => object,
            Some(_) => return Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => return Err(nt_process::STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        if self.pm.debug_object(object).is_none() {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        }
        Ok(object)
    }

    /// Mirror a debug object's modelled `EventsPresent` onto the dispatcher event backing it, so a
    /// parked `NtWaitForDebugEvent` waiter is woken (or re-blocked) by the ordinary wait machinery.
    pub(crate) fn sync_debug_object_signal(&mut self, object: nt_process::dbgk::DebugObjectId) {
        let Some((key, present)) = self
            .pm
            .debug_object(object)
            .map(|o| (o.host_event, o.events_present()))
        else {
            return;
        };
        if key == 0 {
            return;
        }
        let index = key - 1;
        if present {
            let _ = self.events.set_existing(index);
        } else {
            self.events.clear_existing(index);
        }
    }

    /// ★ POST-SIDE WAKE CORRECTNESS. Mirror **every** live debug object's modelled `EventsPresent`
    /// onto the dispatcher event backing it, and — when that newly signals one — run the ordinary
    /// dispatcher wake so a thread parked inside `NtWaitForDebugEvent` is resumed.
    ///
    /// Why blanket rather than per-object: debug events are posted from many places that are not
    /// the five dbgk syscall arms — the `nt-process` lifecycle (thread create / thread exit /
    /// process exit, reached through `NtCreateThread`/`NtTerminate*`) and now
    /// [`dbgk_forward_exception`](Self::dbgk_forward_exception) from the FAULT path. Before this,
    /// only the dbgk arms mirrored the signal, so an event queued by any other path marked the
    /// modelled `EventsPresent` but never set the dispatcher event and could not wake a parked
    /// debugger. This runs at the one chokepoint every syscall passes through
    /// (`NativeSyscallHandler::handle`) plus the fault-path forward, so posting is uniformly
    /// wake-correct wherever it happens.
    ///
    /// Costs nothing on a plain boot: with no debug object alive it returns on the first line, so
    /// the live syscall path is byte-identical.
    pub(crate) fn sync_debug_object_signals(&mut self) {
        if self.pm.debug_object_count() == 0 {
            return;
        }
        // Debug objects are per-debugger and few (one per `DbgUiConnectToDbg`); 8 covers every
        // realistic set, and a longer one simply keeps the objects the loop already mirrored.
        let mut ids = [0 as nt_process::dbgk::DebugObjectId; 8];
        let n = self.pm.debug_object_ids_into(&mut ids);
        let mut newly_signalled = false;
        for &object in &ids[..n] {
            let Some((key, present)) = self
                .pm
                .debug_object(object)
                .map(|o| (o.host_event, o.events_present()))
            else {
                continue;
            };
            if key == 0 {
                continue;
            }
            let index = key - 1;
            if present && !self.dispatcher_ready(index as usize) {
                newly_signalled = true;
            }
            self.sync_debug_object_signal(object);
        }
        if newly_signalled {
            unsafe { wait_wake_dispatcher_set(self) };
        }
    }

    /// `DbgkForwardException` — report a user-mode exception taken by hosted process index `pi` to
    /// that process's `EPROCESS.DebugPort`, and wake a debugger parked on it.
    ///
    /// ★ SAFETY PROPERTY: when the process is **not** being debugged this returns `false` having
    /// done nothing at all (two table lookups, no logging, no state change), so every caller's
    /// existing unrecoverable-fault handling runs byte-identically. On the current boot nothing
    /// attaches a debugger to a hosted process, so this always takes that early return.
    ///
    /// `tid_hint` is the reporting thread (0 ⇒ the process's main thread — the fault path's
    /// per-badge identity is not yet resolved where the classification happens). `first_chance` is
    /// `DbgkForwardException`'s `!SecondChance`.
    ///
    /// Returns `true` when the event was queued. The reporting thread is **not** blocked on the
    /// debugger's continue — see `ntdll_plan.md` §D for what that does and does not mean.
    pub(crate) fn dbgk_forward_exception(
        &mut self,
        pi: usize,
        tid_hint: u64,
        record: nt_process::dbgk::ExceptionRecord,
        first_chance: bool,
    ) -> bool {
        let Some(pid) = self.pm_pid_for_pi(pi) else {
            return false;
        };
        if !self.pm.is_process_being_debugged(pid) {
            return false;
        }
        let tid = match tid_hint {
            0 => self.pm.main_thread(pid).unwrap_or(0),
            hint => hint as nt_process::ThreadId,
        };
        if self
            .pm
            .report_exception(pid, tid, record, first_chance)
            .is_none()
        {
            return false;
        }
        DBGK_EXCEPTIONS_FORWARDED.fetch_add(1, Ordering::Relaxed);
        self.sync_debug_object_signals();
        true
    }

    /// ★ TARGET-SIDE BLOCKING — `DbgkpQueueMessage`'s wait on `DebugEvent->ContinueEvent`.
    ///
    /// Park the thread that just reported a debug event for hosted process `pi` on the event it
    /// queued, so it does **not** return from its fault/syscall until `NtDebugContinue` resolves it
    /// (`dbgk_wake_target`). The park itself is the ordinary reply-capability steal
    /// ([`dbgk_reporter_park`]); the stolen capability is recorded ON THE `DEBUG_EVENT`
    /// ([`nt_process::dbgk::ReporterBlock`]) — where NT keeps the waiting reporter.
    ///
    /// `kind` is the fault flavour that says which reply shape resumes it (`DBGK_BLOCK_*`);
    /// `resume_status` is what a SYSCALL-flavoured reporter returns when resumed.
    ///
    /// ★ SAFETY PROPERTY: returns `false` having done NOTHING when the process is not being
    /// debugged (the path every fault on the live boot takes), when no debug port resolves, when the
    /// reply pool is exhausted, or when the queued event could not take the block — so the caller
    /// falls back to its existing post-and-continue handling and the fault path is byte-identical.
    ///
    /// `reply_cap` names the Reply capability the reporter's blocked Call is bound to: pass **0**
    /// (every production call site) to steal the ACTIVE one out of `REPLY_MAIN_SLOT`, or an explicit
    /// capability when the caller already received the fault on a reply object of its own.
    #[allow(clippy::too_many_arguments)]
    pub(crate) unsafe fn dbgk_block_reporter(
        &mut self,
        pi: usize,
        tid_hint: u64,
        badge: u64,
        kind: u8,
        reply_cap: u64,
        syscall_reply: nt_syscall_abi::ParkedSyscallReply,
        resume_ip: u64,
        resume_sp: u64,
        resume_flags: u64,
        resume_status: u64,
    ) -> bool {
        let Some(pid) = self.pm_pid_for_pi(pi) else {
            return false;
        };
        let Some(object) = self.pm.process_debug_port(pid) else {
            return false;
        };
        let tid = match tid_hint {
            0 => self.pm.main_thread(pid).unwrap_or(0),
            hint => hint as nt_process::ThreadId,
        };
        let client_id = nt_process::ClientId {
            unique_process: pid,
            unique_thread: tid,
        };
        let parked = if reply_cap != 0 {
            let block = nt_process::dbgk::ReporterBlock {
                kind,
                reply_cap,
                pi: pi as u32,
                tid: tid as u64,
                badge,
                syscall_reply,
                resume_ip,
                resume_sp,
                resume_flags,
                resume_status,
            };
            DBGK_REPORTERS_BLOCKED.fetch_add(1, Ordering::Relaxed);
            block.is_blocked().then_some(block)
        } else {
            dbgk_reporter_park(
                kind,
                pi,
                tid as u64,
                badge,
                syscall_reply,
                resume_ip,
                resume_sp,
                resume_flags,
                resume_status,
            )
        };
        let Some(block) = parked else {
            return false;
        };
        if self.pm.block_reporter(object, client_id, block) {
            return true;
        }
        // Nothing eligible took the block (no non-NOWAIT event queued for this client). Recycle the
        // stolen Reply object and let the caller's own handling proceed — the reporter is left
        // blocked exactly as `park_and_log!`'s recv-without-reply would leave it.
        dbgk_reporter_abandon(&block);
        false
    }

    /// `DbgkpWakeTarget` — apply a continue status to the reporter blocked on a resolved event.
    ///
    /// | continue status | what happens to the reporting thread |
    /// |---|---|
    /// | `DBG_CONTINUE` / `DBG_EXCEPTION_HANDLED` | **RESUMED** with its fault-flavoured reply — the exception is dismissed and it CONTINUES EXECUTION (a `#PF` retries the faulting instruction, an int3 resumes past it, a syscall returns its status) |
    /// | `DBG_EXCEPTION_NOT_HANDLED` at a FAULT | left blocked: the fault site's own unrecoverable handling stands (today's outcome). Its win32k user-mode callbacks are unwound, exactly as `park_and_log!` does |
    /// | `DBG_EXCEPTION_NOT_HANDLED` from a SYSCALL | resumed (there is no exception to decline — the syscall simply completes) |
    /// | `DBG_TERMINATE_THREAD` | **ENFORCED**: the reporting thread is really terminated and never resumed |
    /// | `DBG_TERMINATE_PROCESS` | **ENFORCED**: its whole process is terminated (every thread), and never resumed |
    ///
    /// Returns the [`WakeAction`](nt_process::dbgk::WakeAction) taken.
    pub(crate) unsafe fn dbgk_wake_target(
        &mut self,
        client_id: nt_process::ClientId,
        block: Option<nt_process::dbgk::ReporterBlock>,
        continue_status: u32,
    ) -> nt_process::dbgk::WakeAction {
        use nt_process::dbgk::{wake_action, ReporterBlock, WakeAction};
        let block = block.unwrap_or(ReporterBlock::default());
        let action = wake_action(&block, continue_status);
        match action {
            WakeAction::None => {}
            WakeAction::Resume => {
                dbgk_reporter_resume(self, &block);
            }
            WakeAction::LeaveBlocked => {
                dbgk_reporter_abandon(&block);
                DBGK_REPORTERS_LEFT_BLOCKED.fetch_add(1, Ordering::Relaxed);
                // The reporter will never return, so any win32k user-mode callback it owns must be
                // unwound — the same dead-client discipline `park_and_log!` applies.
                crate::win32k_glue::unwind_dead_client_user_callbacks(block.pi);
            }
            WakeAction::TerminateThread => {
                dbgk_reporter_abandon(&block);
                let _ = self.pm.terminate_thread_at(
                    client_id.unique_thread,
                    nt_process::dbgk::DBG_TERMINATE_THREAD,
                    nt_system_time_100ns() as i64,
                );
                DBGK_TERMINATES_ENFORCED.fetch_add(1, Ordering::Relaxed);
            }
            WakeAction::TerminateProcess => {
                dbgk_reporter_abandon(&block);
                let _ = self.pm.terminate_process_at(
                    client_id.unique_process,
                    nt_process::dbgk::DBG_TERMINATE_PROCESS,
                    nt_system_time_100ns() as i64,
                );
                DBGK_TERMINATES_ENFORCED.fetch_add(1, Ordering::Relaxed);
                if block.is_blocked() {
                    crate::win32k_glue::unwind_dead_client_user_callbacks(block.pi);
                }
            }
        }
        action
    }

    /// ★ THE ESCAPE HATCH. Release every reporter blocked on `object` (optionally only `pid`'s), so
    /// a debugger that dies, closes its debug object, or simply never continues can NEVER leave a
    /// target parked forever — which would be a boot that fails to quiesce.
    ///
    /// Faithful to `DbgkClearProcessDebugObject`, which marks every flushed event
    /// `STATUS_DEBUGGER_INACTIVE` and wakes its target: a **syscall** reporter is genuinely resumed
    /// (its operation completes), while a **fault** reporter — whose fault was unrecoverable and
    /// whose site would have parked it anyway — is left blocked with its Reply object recycled.
    /// Returns how many reporters were released.
    pub(crate) unsafe fn dbgk_release_blocked_reporters(
        &mut self,
        object: nt_process::dbgk::DebugObjectId,
        pid: Option<nt_process::ProcessId>,
    ) -> usize {
        let empty = (
            nt_process::ClientId {
                unique_process: 0,
                unique_thread: 0,
            },
            nt_process::dbgk::ReporterBlock::default(),
        );
        let mut released = [empty; PM_DEBUG_EVENTS_PER_OBJECT];
        let mut total = 0usize;
        loop {
            let n = self
                .pm
                .drain_blocked_reporters_into(object, pid, &mut released);
            if n == 0 {
                break;
            }
            for (_client, block) in released[..n].iter().copied() {
                if block.is_fault() {
                    dbgk_reporter_abandon(&block);
                    crate::win32k_glue::unwind_dead_client_user_callbacks(block.pi);
                } else {
                    dbgk_reporter_resume(self, &block);
                }
                DBGK_REPORTERS_RELEASED.fetch_add(1, Ordering::Relaxed);
            }
            total += n;
            if n < released.len() {
                break;
            }
        }
        total
    }

    /// Release every blocked reporter on EVERY live debug object — the unconditional, bounded
    /// backstop the boot runs before the gate. With no debug object alive it returns on its first
    /// line, so a plain boot pays nothing.
    pub(crate) unsafe fn dbgk_release_all_blocked_reporters(&mut self) -> usize {
        if self.pm.debug_object_count() == 0 {
            return 0;
        }
        let mut ids = [0 as nt_process::dbgk::DebugObjectId; 8];
        let n = self.pm.debug_object_ids_into(&mut ids);
        let mut released = 0;
        for &object in &ids[..n] {
            released += self.dbgk_release_blocked_reporters(object, None);
        }
        released
    }

    /// `DbgkMapViewOfSection` — an **IMAGE** view at `base` became mapped in hosted process index
    /// `pi`. Records it in the process's modelled module list and posts `DbgKmLoadDllApi` to its
    /// `EPROCESS.DebugPort`, waking a debugger parked on it.
    ///
    /// ★ SAFETY PROPERTY: with **no** `DEBUG_OBJECT` alive anywhere — every boot today — this
    /// returns `false` on its first line, so the section-mapping path (every DLL load, every
    /// demand-map, win32k's client mappings) is byte-identical. `report_module_load` itself is gated
    /// the same way, so not even the module list is touched.
    ///
    /// `file_handle` is the MAPPING process's own handle to the image file; the wait duplicates it
    /// into the debugger's table (`DbgkpOpenHandles`) and leaves 0 if it cannot. `name_pointer` is a
    /// pointer in the debuggee to the module name — NT reports
    /// `&NtCurrentTeb()->NtTib.ArbitraryUserPointer`.
    pub(crate) fn dbgk_module_load(
        &mut self,
        pi: usize,
        base: u64,
        file_handle: u64,
        debug_info: (u32, u32),
        name_pointer: u64,
    ) -> bool {
        if self.pm.debug_object_count() == 0 {
            return false;
        }
        let Some(pid) = self.pm_pid_for_pi(pi) else {
            return false;
        };
        let tid = self.dbgk_reporting_tid(pid);
        let module = nt_process::ProcessModule {
            pid,
            base,
            file_handle,
            debug_info_file_offset: debug_info.0,
            debug_info_size: debug_info.1,
            name_pointer,
        };
        if self.pm.report_module_load(pid, tid, module).is_none() {
            return false;
        }
        DBGK_MODULE_LOADS.fetch_add(1, Ordering::Relaxed);
        // `DbgkMapViewOfSection` queues with flags 0 ⇒ the MAPPING THREAD BLOCKS on the continue.
        // The park needs this caller's resume context, so latch the request for the reply site.
        self.dbgk_block_request = true;
        self.sync_debug_object_signals();
        true
    }

    /// `DbgkUnMapViewOfSection` — the view at `base` was unmapped from hosted process index `pi`.
    /// Posts `DbgKmUnloadDllApi` **only when `base` names a tracked IMAGE view** (the modelled form
    /// of `MmUnmapViewOfSection`'s `if (DbgBase)` guard — a data / anonymous view was never
    /// recorded). Same first-line no-debug-object early return as [`dbgk_module_load`].
    pub(crate) fn dbgk_module_unload(&mut self, pi: usize, base: u64) -> bool {
        if self.pm.debug_object_count() == 0 || base == 0 {
            return false;
        }
        let Some(pid) = self.pm_pid_for_pi(pi) else {
            return false;
        };
        let tid = self.dbgk_reporting_tid(pid);
        if self.pm.report_module_unload(pid, tid, base).is_none() {
            return false;
        }
        DBGK_MODULE_UNLOADS.fetch_add(1, Ordering::Relaxed);
        self.sync_debug_object_signals();
        true
    }

    /// ★ `DbgkpMarkProcessPeb` — write `PEB->BeingDebugged` THROUGH into the target's LIVE PEB page.
    ///
    /// `ProcessManager` already models the flag (`EPROCESS.being_debugged`, set by
    /// `debug_active_process` and cleared by `remove_process_debug` / `destroy_debug_object`), but
    /// the byte a debuggee actually reads is `NtCurrentPeb()->BeingDebugged` — `PEB+2` in its own
    /// address space. Without this write-through the whole break-in is INERT: `DbgUiRemoteBreakin`
    /// reads a zero byte, skips `DbgBreakPoint` and exits silently.
    ///
    /// The write uses the SAME general cross-process client-memory path `NtWriteVirtualMemory` uses
    /// (`client_copyout_mapped` against the target's registered frames / demand-fill scratch); every
    /// hosted process's PEB frame is registered with a permanent executive alias at spawn
    /// (`csrss_frame_put_at(pi, SMSS_PEB_VA, peb, scr + 0x1000)`), so no new mechanism is invented
    /// and the write works with or without the loop context.
    ///
    /// ★ SAFETY: only ever reached from the five dbgk service arms, none of which runs on a boot
    /// with no debugger — so the live PEB is never touched.
    pub(crate) unsafe fn dbgk_mark_process_peb(&mut self, pi: usize, being_debugged: bool) -> bool {
        // `PEB.BeingDebugged` — the byte-exact PEB layout's own constant, shared with the ntdll
        // side that READS it (`nt_ntdll::dbg::remote_breakin_action`), so the two cannot drift.
        const PEB_BEING_DEBUGGED_OFFSET: u64 = nt_ntdll_layout::PEB_BEING_DEBUGGED_OFFSET as u64;
        if pi >= MAX_PI {
            return false;
        }
        let (filled, nfilled, scratch_base) = match self.loop_ctx {
            Some(ctx) => {
                let procs = unsafe { &*ctx.procs };
                let filled: &[u64] = if pi == self.pi {
                    let current = unsafe { &*ctx.filled_pages };
                    &current[..]
                } else {
                    let per_process = unsafe { &*ctx.pfilled };
                    &per_process[pi][..]
                };
                (filled, procs[pi].faults as usize, procs[pi].scratch_base)
            }
            // Post-loop (the self-tests) there is no loop context; the PEB page is reachable through
            // its registered permanent alias, which `client_copyout_mapped` consults first.
            None => (&[][..], 0usize, 0u64),
        };
        let written = unsafe {
            img_spawn::client_copyout_mapped(
                pi as u64,
                SMSS_PEB_VA + PEB_BEING_DEBUGGED_OFFSET,
                &[u8::from(being_debugged)],
                filled,
                nfilled,
                scratch_base,
            )
        };
        if written {
            DBGK_PEB_MARKS.fetch_add(1, Ordering::Relaxed);
        }
        written
    }

    /// Write `PEB->BeingDebugged` through for every process still attached to `object` — the
    /// detach-side half of [`Self::dbgk_mark_process_peb`], used by `NtRemoveProcessDebug`'s
    /// object-wide sibling `DbgkpCloseObject` (the debugger's last handle went away).
    pub(crate) unsafe fn dbgk_clear_peb_marks_for_object(
        &mut self,
        object: nt_process::dbgk::DebugObjectId,
    ) {
        for pi in 0..MAX_PI {
            let Some(pid) = self.pm_pid_for_pi(pi) else {
                continue;
            };
            if self.pm.process_debug_port(pid) == Some(object) {
                unsafe { self.dbgk_mark_process_peb(pi, false) };
            }
        }
    }

    /// The thread a dbgk message from the current syscall reports for: the live caller when the loop
    /// has resolved one, else the process's main thread (what `dbgk_forward_exception` falls back to).
    fn dbgk_reporting_tid(&self, pid: nt_process::ProcessId) -> nt_process::ThreadId {
        match self.current_tid {
            0 => self.pm.main_thread(pid).unwrap_or(0),
            tid => tid as nt_process::ThreadId,
        }
    }

    pub(crate) fn wait_object_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<WaitObject, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if let Some(object) = self.process_thread_or_file_wait_object(handle, required_access)? {
            return Ok(object);
        }
        let mut saw_invalid_handle = false;
        match self.event_index_for_handle(handle, required_access) {
            Ok(index) => return Ok(WaitObject::dispatcher(index)),
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        match self.timer_index_for_handle(handle, required_access) {
            Ok(index) => return Ok(WaitObject::dispatcher(index)),
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        match self.semaphore_index_for_handle(handle, required_access) {
            Ok(index) => return Ok(WaitObject::dispatcher(index)),
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        match self.mutant_index_for_handle(handle, required_access) {
            Ok(index) => return Ok(WaitObject::dispatcher(index)),
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        self.win32k_event_wait_object(handle).or_else(|_| {
            Err(if saw_invalid_handle {
                STATUS_INVALID_HANDLE
            } else {
                STATUS_OBJECT_TYPE_MISMATCH
            })
        })
    }

    fn signal_object_for_wait_handle(
        &self,
        handle: u64,
    ) -> Result<nt_kernel_exec::DispatcherSignalObject, u32> {
        let mut saw_invalid_handle = false;
        match self.event_index_for_handle(handle, EVENT_MODIFY_STATE) {
            Ok(index) => return Ok(nt_kernel_exec::DispatcherSignalObject::Event(index as u64)),
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        match self.semaphore_index_for_handle(handle, SEMAPHORE_MODIFY_STATE) {
            Ok(index) => {
                return Ok(nt_kernel_exec::DispatcherSignalObject::Semaphore(
                    index as u64,
                ));
            }
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        match self.mutant_index_for_handle(handle, 0) {
            Ok(index) => {
                return Ok(nt_kernel_exec::DispatcherSignalObject::Mutant {
                    identity: index as u64,
                    thread: self.current_tid,
                });
            }
            Err(STATUS_ACCESS_DENIED) => return Err(STATUS_ACCESS_DENIED),
            Err(STATUS_INVALID_HANDLE) => saw_invalid_handle = true,
            Err(STATUS_OBJECT_TYPE_MISMATCH) => {}
            Err(status) => return Err(status),
        }
        Err(if saw_invalid_handle {
            STATUS_INVALID_HANDLE
        } else {
            STATUS_OBJECT_TYPE_MISMATCH
        })
    }

    fn signal_dispatcher_for_wait(
        &mut self,
        object: nt_kernel_exec::DispatcherSignalObject,
    ) -> u32 {
        match nt_kernel_exec::signal_dispatcher_for_wait(
            &mut self.events,
            &mut self.semaphores,
            &mut self.mutants,
            object,
        ) {
            Ok(()) => {
                // Native dispatch is serialized. Waking existing waiters and publishing this
                // caller's wait below are one executive transition, so no signal-state mutation can
                // interleave between the two halves of NtSignalAndWaitForSingleObject.
                unsafe {
                    wait_wake_dispatcher_set(self);
                }
                0
            }
            Err(nt_kernel_exec::DispatcherSignalError::InvalidObject) => STATUS_INVALID_HANDLE,
            Err(nt_kernel_exec::DispatcherSignalError::SemaphoreLimitExceeded) => 0xC000_0047,
            Err(nt_kernel_exec::DispatcherSignalError::MutantNotOwned) => 0xC000_0046,
        }
    }

    fn begin_single_object_wait(
        &mut self,
        operation: &'static [u8],
        handle: u64,
        object: WaitObject,
        alertable: bool,
        timeout_ptr: u64,
        timeout_interval: Option<i64>,
    ) -> u32 {
        if alertable {
            match unsafe { self.try_deliver_current_user_apc() } {
                Ok(true) => return 0x0000_00C0,
                Ok(false) => {}
                Err(status) => return status,
            }
        }
        if self.wait_object_ready(object) {
            trace_wait_object(self, b"ready", handle, object, timeout_ptr, 0);
            print_str(b"[wait] pi=");
            print_u64(self.pi as u64);
            print_str(b" ");
            print_str(operation);
            print_str(b"(");
            print_str(object.describe());
            print_str(b" ");
            print_u64(object.id());
            print_str(b") already SIGNALLED -> immediate WAIT_0\n");
            self.wait_object_consume(object);
            return 0;
        }
        if let Some(timeout) = timeout_interval.map(PendingWaitTimeout::from_interval) {
            if timeout.is_due_now() == Some(true) {
                trace_wait_object(
                    self,
                    b"timeout-immediate",
                    handle,
                    object,
                    timeout_ptr,
                    0x102,
                );
                return 0x102;
            }
            self.wait_timeout = timeout;
        }
        self.wait_park_event = object.raw() as i64;
        self.wait_alertable = alertable;
        trace_wait_object(self, b"park", handle, object, timeout_ptr, 0x102);
        print_str(b"[wait] pi=");
        print_u64(self.pi as u64);
        print_str(b" ");
        print_str(operation);
        print_str(b"(");
        print_str(object.describe());
        print_str(b" ");
        print_u64(object.id());
        print_str(b") UNSIGNALLED -> PARK caller (reply-cap park)\n");
        0x102
    }

    fn begin_multiple_object_wait(
        &mut self,
        count: u32,
        handle_array: u64,
        wait_type: u32,
        alertable: bool,
        timeout_ptr: u64,
    ) -> u32 {
        if count == 0 || count as usize > WAITER_MAX_EVENTS {
            return STATUS_INVALID_PARAMETER_1;
        }
        if wait_type > 1 {
            return STATUS_INVALID_PARAMETER_3;
        }
        let timeout_interval = match self.wait_timeout_interval(timeout_ptr) {
            Ok(timeout) => timeout,
            Err(status) => return status,
        };
        if handle_array == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        if handle_array & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }

        // Capture the full user array before resolving any handle, matching Ob's rule that a caller
        // cannot retarget later entries while the kernel references the earlier ones.
        let count = count as usize;
        for index in 0..count {
            let Some(address) = handle_array.checked_add((index as u64) * 8) else {
                return STATUS_ACCESS_VIOLATION;
            };
            let mut bytes = [0u8; 8];
            if !unsafe { self.xas_read(address, &mut bytes) } {
                return STATUS_ACCESS_VIOLATION;
            }
            self.wait_capture_handles[index] = u64::from_le_bytes(bytes);
        }

        for index in 0..count {
            let handle = self.wait_capture_handles[index];
            self.wait_park_objects[index] =
                match self.wait_object_for_handle(handle, SYNCHRONIZE_ACCESS) {
                    Ok(object) => object,
                    Err(status) => return status,
                };
        }

        let wait_all = wait_type == 0;
        if wait_all {
            for left in 0..count {
                if self.wait_park_objects[left + 1..count].contains(&self.wait_park_objects[left]) {
                    return STATUS_INVALID_PARAMETER_MIX;
                }
            }
        }
        if alertable {
            match unsafe { self.try_deliver_current_user_apc() } {
                Ok(true) => return 0x0000_00C0,
                Ok(false) => {}
                Err(status) => return status,
            }
        }

        if wait_all {
            let mut all_ready = true;
            for index in 0..count {
                if !self.wait_object_ready(self.wait_park_objects[index]) {
                    all_ready = false;
                    break;
                }
            }
            if all_ready {
                for index in 0..count {
                    let object = self.wait_park_objects[index];
                    self.wait_object_consume(object);
                }
                return 0;
            }
        } else {
            for index in 0..count {
                let object = self.wait_park_objects[index];
                if self.wait_object_ready(object) {
                    self.wait_object_consume(object);
                    return index as u32;
                }
            }
        }

        if let Some(timeout) = timeout_interval.map(PendingWaitTimeout::from_interval) {
            if timeout.is_due_now() == Some(true) {
                return 0x102;
            }
            self.wait_timeout = timeout;
        }
        for (index, result_index) in self.wait_park_result_indices[..count]
            .iter_mut()
            .enumerate()
        {
            *result_index = index as u8;
        }
        self.wait_park_count = count;
        self.wait_park_all = wait_all;
        self.wait_alertable = alertable;
        0x102
    }

    fn process_thread_or_file_wait_object(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<Option<WaitObject>, u32> {
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;

        let caller = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;

        if handle == u64::MAX {
            return self
                .pm
                .resolve_process_handle(caller, handle, required_access)
                .map(WaitObject::process)
                .map(Some);
        }
        if handle == u64::MAX - 1 {
            return self
                .pm
                .resolve_thread_handle(
                    caller,
                    self.current_tid as nt_process::ThreadId,
                    handle,
                    required_access,
                )
                .map(WaitObject::thread)
                .map(Some);
        }
        if handle > u32::MAX as u64 {
            return Ok(None);
        }

        match self.pm.lookup_handle(caller, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::Process(pid)) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                if self.pm.process(pid).is_none() {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(Some(WaitObject::process(pid)))
            }
            Some(nt_process::HandleObject::Thread(tid)) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                if self.pm.thread(tid).is_none() {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(Some(WaitObject::thread(tid)))
            }
            Some(
                nt_process::HandleObject::File(file_id)
                | nt_process::HandleObject::RoutedFile { file_id, .. },
            ) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                if self.file_completion.is_signaled(file_id).is_err() {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(Some(WaitObject::file(file_id)))
            }
            Some(nt_process::HandleObject::DiskFile { object_id, .. }) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                self.readonly_file_opens.is_signaled(object_id)?;
                Ok(Some(WaitObject::fat_file(object_id)))
            }
            Some(nt_process::HandleObject::Directory { object_id, .. }) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                self.directory_opens.is_signaled(object_id)?;
                Ok(Some(WaitObject::fat_directory(object_id)))
            }
            Some(nt_process::HandleObject::OverlayFile(file_id)) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                unsafe { crate::writable_fs::is_file_signaled(file_id)? };
                Ok(Some(WaitObject::overlay_file(file_id)))
            }
            Some(nt_process::HandleObject::Job(id)) => {
                let granted = self
                    .pm
                    .handle_access(caller, handle as nt_process::Handle)
                    .ok_or(STATUS_INVALID_HANDLE)?;
                if required_access != 0 && granted & required_access != required_access {
                    return Err(STATUS_ACCESS_DENIED);
                }
                if !self.pm.job_exists(id) {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(Some(WaitObject::job(id)))
            }
            Some(_) | None => Ok(None),
        }
    }

    fn win32k_event_wait_object(&self, handle: u64) -> Result<WaitObject, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        crate::win32k_subsystem::event_body_for_client_handle(handle)
            .map(WaitObject::win32k_event_body)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    fn dispatcher_object_for_thread(
        &self,
        index: usize,
        thread: u64,
    ) -> Option<nt_kernel_exec::DispatcherObject> {
        match self.obj_ns.get(index).map(|entry| entry.kind) {
            Some(OBJ_KIND_EVENT) | Some(OBJ_KIND_TIMER) => {
                Some(nt_kernel_exec::DispatcherObject::Event(index as u64))
            }
            Some(OBJ_KIND_SEMAPHORE) => {
                Some(nt_kernel_exec::DispatcherObject::Semaphore(index as u64))
            }
            Some(OBJ_KIND_MUTANT) => Some(nt_kernel_exec::DispatcherObject::Mutant {
                identity: index as u64,
                thread,
            }),
            None if self.events.contains(index as u64) => {
                Some(nt_kernel_exec::DispatcherObject::Event(index as u64))
            }
            _ => None,
        }
    }

    pub(crate) fn dispatcher_ready(&self, index: usize) -> bool {
        self.dispatcher_ready_for(index, self.current_tid)
    }

    pub(crate) fn dispatcher_ready_for(&self, index: usize, thread: u64) -> bool {
        self.dispatcher_object_for_thread(index, thread)
            .is_some_and(|object| {
                nt_kernel_exec::dispatcher_ready(
                    &self.events,
                    &self.semaphores,
                    &self.mutants,
                    object,
                )
            })
    }

    pub(crate) fn dispatcher_consume(&mut self, index: usize) -> bool {
        self.dispatcher_consume_for(index, self.current_tid)
    }

    pub(crate) fn dispatcher_consume_for(&mut self, index: usize, thread: u64) -> bool {
        let Some(object) = self.dispatcher_object_for_thread(index, thread) else {
            return false;
        };
        nt_kernel_exec::consume_dispatcher(
            &mut self.events,
            &mut self.semaphores,
            &mut self.mutants,
            object,
        )
    }

    pub(crate) fn wait_object_ready(&self, object: WaitObject) -> bool {
        self.wait_object_ready_for(object, self.current_tid)
    }

    fn retain_dispatcher_wait_reference(&mut self, index: usize) -> Result<(), u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;

        let Some(entry) = self.obj_ns.get(index) else {
            // Internal dispatcher events (for example DEBUG_OBJECT.EventsPresent) are rooted by
            // their kernel owner for that owner's lifetime and are never namespace-slot aliases.
            return self
                .events
                .contains(index as u64)
                .then_some(())
                .ok_or(STATUS_INVALID_HANDLE);
        };
        let backing_exists = match entry.kind {
            OBJ_KIND_EVENT | OBJ_KIND_TIMER => self.events.contains(index as u64),
            OBJ_KIND_SEMAPHORE => self.semaphores.contains(index as u64),
            OBJ_KIND_MUTANT => self.mutants.contains(index as u64),
            _ => false,
        };
        if !entry.is_live() || !backing_exists {
            return Err(STATUS_INVALID_HANDLE);
        }
        self.obj_ns[index].wait_references = self.obj_ns[index]
            .wait_references
            .checked_add(1)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        Ok(())
    }

    fn release_dispatcher_wait_reference(&mut self, index: usize) -> Result<(), u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;

        let Some(entry) = self.obj_ns.get(index) else {
            return self
                .events
                .contains(index as u64)
                .then_some(())
                .ok_or(STATUS_INVALID_HANDLE);
        };
        if !entry.is_live() {
            return Err(STATUS_INVALID_HANDLE);
        }
        let references = entry
            .wait_references
            .checked_sub(1)
            .ok_or(STATUS_INVALID_PARAMETER)?;
        let kind = entry.kind;
        self.obj_ns[index].wait_references = references;
        let final_handleless_reference = references == 0
            && Self::object_namespace_handle_tag(kind, index).is_some_and(|tag| {
                self.pm
                    .handle_object_count(nt_process::HandleObject::Opaque(tag))
                    == 0
            });
        if final_handleless_reference {
            self.obj_delete_name_check(index);
        }
        Ok(())
    }

    /// Pin the exact object identity stored in a published wait record. Handle capture has already
    /// enforced access; these owner-specific references only prevent destruction or slot reuse.
    pub(crate) fn retain_wait_object_reference(&mut self, object: WaitObject) -> Result<(), u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        match object.kind() {
            WaitObject::KIND_DISPATCHER => {
                self.retain_dispatcher_wait_reference(object.id() as usize)
            }
            WaitObject::KIND_PROCESS => self
                .pm
                .retain_process_wait_reference(object.id() as nt_process::ProcessId),
            WaitObject::KIND_THREAD => self
                .pm
                .retain_thread_wait_reference(object.id() as nt_process::ThreadId),
            // win32k event bodies live in its non-reclaiming session pool. Resolution produced the
            // body immediately before this serialized park, so the pool allocation is the root.
            WaitObject::KIND_WIN32K_EVENT if object.id() != 0 => Ok(()),
            WaitObject::KIND_FILE => self.file_completion.retain_file(object.id()),
            WaitObject::KIND_FAT_FILE => self.readonly_file_opens.retain_io(object.id() as u32),
            WaitObject::KIND_FAT_DIRECTORY => self.directory_opens.retain_io(object.id() as u32),
            WaitObject::KIND_OVERLAY_FILE => unsafe {
                crate::writable_fs::retain_io_reference(object.id())
            },
            WaitObject::KIND_JOB => self
                .pm
                .retain_job_wait_reference(object.id() as nt_process::job::JobId),
            _ => Err(STATUS_INVALID_HANDLE),
        }
    }

    pub(crate) fn release_wait_object_reference(&mut self, object: WaitObject) -> Result<(), u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        match object.kind() {
            WaitObject::KIND_DISPATCHER => {
                self.release_dispatcher_wait_reference(object.id() as usize)
            }
            WaitObject::KIND_PROCESS => {
                let pid = object.id() as nt_process::ProcessId;
                self.pm.release_process_wait_reference(pid)?;
                let _ = self.try_delete_hosted_process_object(pid);
                Ok(())
            }
            WaitObject::KIND_THREAD => {
                let tid = object.id() as nt_process::ThreadId;
                let pid = self.pm.thread(tid).map(|thread| thread.process_id);
                self.pm.release_thread_wait_reference(tid)?;
                if let Some(pid) = pid {
                    let _ = self.try_delete_hosted_process_object(pid);
                }
                Ok(())
            }
            WaitObject::KIND_WIN32K_EVENT if object.id() != 0 => Ok(()),
            WaitObject::KIND_FILE => {
                let release = self.file_completion.release_file(object.id())?;
                self.complete_file_reference_release(object.id(), release);
                Ok(())
            }
            WaitObject::KIND_FAT_FILE => self.readonly_file_opens.release_io(object.id() as u32),
            WaitObject::KIND_FAT_DIRECTORY => self.directory_opens.release_io(object.id() as u32),
            WaitObject::KIND_OVERLAY_FILE => unsafe {
                crate::writable_fs::release_io_reference(object.id())
            },
            WaitObject::KIND_JOB => {
                let id = object.id() as nt_process::job::JobId;
                let _ = self.pm.release_job_wait_reference(id)?;
                self.drain_job_destructions();
                Ok(())
            }
            _ => Err(STATUS_INVALID_HANDLE),
        }
    }

    pub(crate) fn wait_object_ready_for(&self, object: WaitObject, thread: u64) -> bool {
        match object.kind() {
            WaitObject::KIND_DISPATCHER => self.dispatcher_ready_for(object.id() as usize, thread),
            WaitObject::KIND_PROCESS => self.pm.is_process_signaled(object.id() as u32),
            WaitObject::KIND_THREAD => self.pm.is_thread_signaled(object.id() as u32),
            WaitObject::KIND_WIN32K_EVENT => crate::win32k_subsystem::event_body_ready(object.id()),
            WaitObject::KIND_FILE => self
                .file_completion
                .is_signaled(object.id())
                .unwrap_or(false),
            WaitObject::KIND_FAT_FILE => self
                .readonly_file_opens
                .is_signaled(object.id() as u32)
                .unwrap_or(false),
            WaitObject::KIND_FAT_DIRECTORY => self
                .directory_opens
                .is_signaled(object.id() as u32)
                .unwrap_or(false),
            WaitObject::KIND_OVERLAY_FILE => unsafe {
                crate::writable_fs::is_file_signaled(object.id()).unwrap_or(false)
            },
            WaitObject::KIND_JOB => self
                .pm
                .is_job_signaled(object.id() as nt_process::job::JobId),
            _ => false,
        }
    }

    pub(crate) fn wait_object_consume(&mut self, object: WaitObject) -> bool {
        self.wait_object_consume_for(object, self.current_tid)
    }

    pub(crate) fn wait_object_consume_for(&mut self, object: WaitObject, thread: u64) -> bool {
        match object.kind() {
            WaitObject::KIND_DISPATCHER => {
                self.dispatcher_consume_for(object.id() as usize, thread)
            }
            WaitObject::KIND_PROCESS | WaitObject::KIND_THREAD => true,
            WaitObject::KIND_WIN32K_EVENT => {
                crate::win32k_subsystem::event_body_consume(object.id())
            }
            WaitObject::KIND_FILE
            | WaitObject::KIND_FAT_FILE
            | WaitObject::KIND_FAT_DIRECTORY
            | WaitObject::KIND_OVERLAY_FILE
            | WaitObject::KIND_JOB => true,
            _ => false,
        }
    }

    pub(crate) unsafe fn abandon_mutants_for_thread(&mut self, tid: u64) -> u64 {
        let abandoned = self.mutants.abandon_thread(tid) as u64;
        if abandoned != 0 {
            let _ = wait_wake_dispatcher_set(self);
        }
        abandoned
    }

    pub(crate) fn mint_io_completion_handle(&mut self, object_id: u32, access: u32) -> Option<u64> {
        let pid = self.pm_pid_for_pi(self.pi)?;
        let handle = self
            .insert_process_handle(
                pid,
                nt_process::HandleObject::IoCompletion(object_id),
                access,
            )
            .ok()?;
        Some(handle as u64)
    }
    fn io_completion_id_for(&self, handle: u64, required_access: u32) -> Result<u32, u32> {
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        let pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_io_completion::STATUS_INVALID_HANDLE)?;
        let object_id = match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::IoCompletion(object_id)) => object_id,
            _ => return Err(nt_io_completion::STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(pid, handle as nt_process::Handle)
            .ok_or(nt_io_completion::STATUS_INVALID_HANDLE)?;
        if granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        Ok(object_id)
    }

    pub(crate) fn post_io_completion_packet(
        &mut self,
        object_id: u32,
        packet: nt_io_completion::CompletionPacket,
    ) -> u32 {
        let trace_depth_before = self.io_completion_ports.depth(object_id).ok();
        if let Some(waiter) =
            unsafe { (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).pop_port(object_id) }
        {
            let wake_packet = match self
                .io_completion_ports
                .remove(object_id, nt_io_completion::RemoveMode::Poll)
            {
                Ok(nt_io_completion::RemoveResult::Packet(queued)) => {
                    trace_io_completion_packet(
                        self.pi,
                        b"wake-oldest-queued",
                        object_id,
                        trace_depth_before,
                        self.current_badge,
                        waiter.badge,
                        queued,
                    );
                    if let Err(status) = self.io_completion_ports.enqueue(object_id, packet) {
                        let _ = unsafe {
                            (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).insert(waiter)
                        };
                        return status;
                    }
                    queued
                }
                Ok(nt_io_completion::RemoveResult::Empty(_)) => {
                    trace_io_completion_packet(
                        self.pi,
                        b"wake-direct",
                        object_id,
                        trace_depth_before,
                        self.current_badge,
                        waiter.badge,
                        packet,
                    );
                    packet
                }
                Err(status) => {
                    let _ = unsafe {
                        (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).insert(waiter)
                    };
                    return status;
                }
            };
            if self.io_completion_wake.is_some() {
                trace_io_completion_packet(
                    self.pi,
                    b"wake-overwrite",
                    object_id,
                    self.io_completion_ports.depth(object_id).ok(),
                    self.current_badge,
                    waiter.badge,
                    wake_packet,
                );
            }
            self.io_completion_wake = Some((waiter, wake_packet));
            return nt_io_completion::STATUS_SUCCESS;
        }
        trace_io_completion_packet(
            self.pi,
            b"enqueue",
            object_id,
            trace_depth_before,
            self.current_badge,
            0,
            packet,
        );
        self.io_completion_ports
            .enqueue(object_id, packet)
            .map_or_else(|status| status, |_| nt_io_completion::STATUS_SUCCESS)
    }

    pub(crate) fn signal_file_completion(&mut self, file_id: u64, status: u32) -> u32 {
        let file_signaled = match self.file_completion.complete_file(file_id, status) {
            Ok(signaled) => signaled,
            Err(status) => return status,
        };
        if file_signaled {
            unsafe { wait_wake_dispatcher_set(self) };
        }
        nt_fs::STATUS_SUCCESS
    }

    pub(crate) fn post_file_completion_packet(
        &mut self,
        file_id: u64,
        apc_context: u64,
        status: u32,
        information: u64,
        completed_inline: bool,
        operation_suppressed: bool,
    ) -> u32 {
        let should_queue = match self.file_completion.should_queue_completion_packet(
            file_id,
            apc_context,
            status,
            completed_inline,
            operation_suppressed,
        ) {
            Ok(should_queue) => should_queue,
            Err(status) => return status,
        };
        if !should_queue {
            return nt_fs::STATUS_SUCCESS;
        }
        if let Some(binding) = self.file_completion.binding(file_id) {
            return self.post_io_completion_packet(
                binding.port_id,
                nt_io_completion::CompletionPacket {
                    key_context: binding.key_context,
                    apc_context,
                    status,
                    information,
                },
            );
        }
        nt_fs::STATUS_SUCCESS
    }

    pub(crate) fn queue_file_user_apc(
        &mut self,
        tid: u64,
        apc_routine: u64,
        apc_context: u64,
        iosb: u64,
    ) -> u32 {
        if apc_routine == 0 {
            return nt_fs::STATUS_SUCCESS;
        }
        let Ok(tid) = nt_process::ThreadId::try_from(tid) else {
            return STATUS_INVALID_HANDLE;
        };
        let apc = nt_process::UserApc {
            routine: apc_routine,
            normal_context: apc_context,
            system_argument1: iosb,
            system_argument2: 0,
        };
        match self.pm.queue_kernel_user_apc(tid, apc) {
            Ok(target_tid) => {
                let trace = FILE_USER_APC_TRACE_N.fetch_add(1, Ordering::Relaxed);
                if trace < 32 {
                    print_str(b"[file-apc] queued tid=");
                    print_u64(target_tid as u64);
                    print_str(b" routine=0x");
                    print_hex_u64(apc_routine);
                    print_str(b" context=0x");
                    print_hex_u64(apc_context);
                    print_str(b" iosb=0x");
                    print_hex_u64(iosb);
                    print_str(b"\n");
                }
                let _ = unsafe {
                    crate::service_sec_image::reconcile_user_apc_waits(self, target_tid as u64)
                };
                nt_fs::STATUS_SUCCESS
            }
            Err(status) => {
                let trace = FILE_USER_APC_TRACE_N.fetch_add(1, Ordering::Relaxed);
                if trace < 32 {
                    print_str(b"[file-apc] queue failed tid=");
                    print_u64(tid as u64);
                    print_str(b" routine=0x");
                    print_hex_u64(apc_routine);
                    print_str(b" status=0x");
                    print_hex(status);
                    print_str(b"\n");
                }
                status
            }
        }
    }

    pub(crate) fn file_apc_target_gone(&self, tid: u64) -> bool {
        let Ok(tid) = nt_process::ThreadId::try_from(tid) else {
            return true;
        };
        self.pm
            .thread(tid)
            .is_none_or(|thread| thread.state == nt_process::ThreadState::Terminated)
    }

    pub(crate) fn observe_completed_npfs_read(
        &self,
        file_id: u64,
        badge: u64,
        status: u32,
        information: u64,
        output: &[u8],
        first_chunk: bool,
    ) {
        let Some((device_id, fs_context)) = driver_launch::hosted_file_route(file_id) else {
            return;
        };
        if driver_launch::device_id_by_name("\\Device\\NamedPipe") != Some(device_id) {
            return;
        }
        unsafe {
            driver_launch::trace_dcerpc_read_reassembly_from_slice(
                fs_context,
                status,
                information,
                output,
            );
        }
        if !first_chunk
            || !self.current_process_is_lsass()
            || output.first() != Some(&5)
            || crate::pipe_fid_name_hash(fs_context) != lsarpc_pipe_name_hash()
        {
            return;
        }

        let pdu_type = output.get(2).copied().unwrap_or(0xFF) as u64;
        if self
            .hosted_thread_role_for_badge(badge)
            .is_some_and(|role| role.is_lsa_rpc_worker())
        {
            LSA_WORKER_PDU_READS.fetch_add(1, Ordering::Relaxed);
            let _ = LSA_WORKER_FIRST_PDU_TYPE.compare_exchange(
                0xFF,
                pdu_type,
                Ordering::Relaxed,
                Ordering::Relaxed,
            );
        } else {
            LSA_SELF_RPC_CLIENT_READS.fetch_add(1, Ordering::Relaxed);
        }
    }

    pub(crate) fn hosted_file_is_named_pipe(&self, file_id: u64) -> bool {
        driver_launch::hosted_file_route(file_id).is_some_and(|(device_id, _)| {
            driver_launch::device_id_by_name("\\Device\\NamedPipe") == Some(device_id)
        })
    }

    fn pending_pipe_listen_for_server(&self, server_context: u64) -> bool {
        server_context != 0
            && unsafe {
                (&*core::ptr::addr_of!(PENDING_FILE_IO))
                    .drain_all()
                    .any(|(_, pending)| {
                        pending.delivery_state == 0
                            && pending.major == major::IRP_MJ_FILE_SYSTEM_CONTROL
                            && pending.control_code == FSCTL_PIPE_LISTEN
                            && driver_launch::hosted_file_route(pending.file_id)
                                .is_some_and(|(_, context)| context == server_context)
                    })
            }
    }

    pub(crate) fn complete_terminal_file_io(
        &mut self,
        file_id: u64,
        event_obj_idx: u64,
        tid: u64,
        apc_routine: u64,
        apc_context: u64,
        iosb: u64,
        status: u32,
        information: u64,
        completed_inline: bool,
        completion_port_suppressed: bool,
    ) {
        if !nt_io_completion::file_io_status_publishes_completion(status, completed_inline) {
            return;
        }
        unsafe {
            let _ = self.write_current_iosb(iosb, status, information);
        }
        if event_obj_idx != u64::MAX {
            let _ = self.signal_event_index(event_obj_idx as usize);
            self.io_signal_event = event_obj_idx as i64;
        }
        let signal_file = file_id != 0
            && (event_obj_idx == u64::MAX
                || self
                    .file_completion
                    .is_synchronous(file_id)
                    .unwrap_or(false));
        if signal_file {
            let _ = self.signal_file_completion(file_id, status);
        }
        if apc_routine != 0 {
            let _ = self.queue_file_user_apc(tid, apc_routine, apc_context, iosb);
        } else if file_id != 0 {
            let _ = self.post_file_completion_packet(
                file_id,
                apc_context,
                status,
                information,
                completed_inline,
                completion_port_suppressed,
            );
        }
    }

    pub(crate) fn release_file_reference(&mut self, file_id: u64) {
        // A synchronous operation's reference protects the FILE_OBJECT while Busy is held. Inline
        // paths request their normal release here, but the service tail performs it after unlocking.
        if self.current_synchronous_file_lock == file_id {
            return;
        }
        if let Ok(release) = self.file_completion.release_file(file_id) {
            self.complete_file_reference_release(file_id, release);
        }
    }

    fn release_file_handle_reference(&mut self, file_id: u64) {
        if let Ok(release) = self.file_completion.release_handle(file_id) {
            self.complete_file_reference_release(file_id, release);
        }
    }

    fn complete_file_reference_release(
        &mut self,
        file_id: u64,
        release: nt_io_completion::FileReferenceRelease,
    ) {
        if release.cleanup_required {
            match self
                .file_completion
                .begin_cleanup(file_id)
                .expect("last File handle lost its cleanup policy owner")
            {
                nt_io_completion::FileIoAcquireResult::Bypassed
                | nt_io_completion::FileIoAcquireResult::Acquired => unsafe {
                    crate::service_sec_image::start_file_cleanup(self, file_id);
                },
                nt_io_completion::FileIoAcquireResult::Contended { .. } => {}
            }
        }
        if let Some(port_id) = release.port_id {
            self.release_io_completion_reference(port_id);
        }
    }

    fn io_completion_namespace_index(&self, id: u32) -> Option<usize> {
        self.obj_ns.iter().position(|entry| {
            entry.is_live() && entry.kind == OBJ_KIND_IO_COMPLETION && entry.payload == id as u64
        })
    }

    /// Drop one body reference and unlink a named completion port after its final reference goes.
    pub(crate) fn release_io_completion_reference(&mut self, id: u32) {
        if self.io_completion_ports.release(id).is_err()
            || self.io_completion_ports.depth(id).is_ok()
        {
            return;
        }
        for entry in self.obj_ns.iter_mut().filter(|entry| {
            entry.is_live() && entry.kind == OBJ_KIND_IO_COMPLETION && entry.payload == id as u64
        }) {
            entry.unlink();
        }
    }

    pub(crate) fn release_file_cleanup_reference(&mut self, file_id: u64) {
        let release = self
            .file_completion
            .release_cleanup_reference(file_id)
            .expect("completed File cleanup lost its transferred handle reference");
        self.complete_file_reference_release(file_id, release);
    }

    fn cancel_target_for_handle(&self, handle: u64) -> Result<Option<u64>, u32> {
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        match self.pm.lookup_handle(pid, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::File(file_id))
            | Some(nt_process::HandleObject::RoutedFile { file_id, .. }) => {
                if file_id == 0 || self.file_completion.is_signaled(file_id).is_err() {
                    Err(STATUS_INVALID_HANDLE)
                } else {
                    Ok(Some(file_id))
                }
            }
            Some(nt_process::HandleObject::DiskFile { .. })
            | Some(nt_process::HandleObject::Directory { .. })
            | Some(nt_process::HandleObject::OverlayFile(_)) => Ok(None),
            Some(_) => Err(STATUS_OBJECT_TYPE_MISMATCH),
            None => Err(STATUS_INVALID_HANDLE),
        }
    }

    pub(crate) unsafe fn write_current_iosb(
        &self,
        iosb: u64,
        status: u32,
        information: u64,
    ) -> bool {
        if iosb == 0 || !self.probe_user_output(iosb, 16) {
            return false;
        }
        self.xas_write_buf(iosb, &status.to_le_bytes());
        self.xas_write_buf(iosb + 8, &information.to_le_bytes());
        true
    }

    unsafe fn nt_device_io_control_file_service(&mut self, args: &[u64]) -> u32 {
        let iosb = args[4];
        if iosb == 0 || !self.probe_user_output(iosb, 16) {
            return STATUS_ACCESS_VIOLATION;
        }

        let ioctl = nt_ulong_arg(args[5]);
        let raw_input_len = nt_ulong_arg(args[7]) as usize;
        let raw_output_len = nt_ulong_arg(args[9]) as usize;
        if raw_input_len != 0 && args[6] == 0 {
            self.write_current_iosb(iosb, STATUS_ACCESS_VIOLATION, 0);
            return STATUS_ACCESS_VIOLATION;
        }
        if raw_output_len != 0 && args[8] == 0 {
            self.write_current_iosb(iosb, STATUS_ACCESS_VIOLATION, 0);
            return STATUS_ACCESS_VIOLATION;
        }

        if args[0] > u32::MAX as u64 {
            self.write_current_iosb(iosb, STATUS_INVALID_HANDLE, 0);
            return STATUS_INVALID_HANDLE;
        }
        let handle = args[0] as nt_process::Handle;
        let access = match self.hosted_file_access_for(args[0]) {
            Some(access) => access,
            None => {
                self.write_current_iosb(iosb, STATUS_INVALID_HANDLE, 0);
                return STATUS_INVALID_HANDLE;
            }
        };
        let route = match self.hosted_file_route_for(args[0]) {
            Some(route) => route,
            None => match self
                .pm_pid_for_pi(self.pi)
                .and_then(|pid| self.pm.lookup_handle(pid, handle))
            {
                Some(nt_process::HandleObject::DiskFile { .. })
                | Some(nt_process::HandleObject::Directory { .. })
                | Some(nt_process::HandleObject::OverlayFile(_)) => {
                    self.write_current_iosb(iosb, STATUS_INVALID_DEVICE_REQUEST, 0);
                    return STATUS_INVALID_DEVICE_REQUEST;
                }
                Some(_) => {
                    self.write_current_iosb(iosb, STATUS_OBJECT_TYPE_MISMATCH, 0);
                    return STATUS_OBJECT_TYPE_MISMATCH;
                }
                None => {
                    self.write_current_iosb(iosb, STATUS_INVALID_HANDLE, 0);
                    return STATUS_INVALID_HANDLE;
                }
            },
        };
        let synchronous_file = match self.file_completion.is_synchronous(route.file_id) {
            Ok(synchronous) => synchronous,
            Err(status) => {
                self.write_current_iosb(iosb, status, 0);
                return status;
            }
        };
        if args[2] != 0 && self.file_completion.binding(route.file_id).is_some() {
            self.write_current_iosb(iosb, STATUS_INVALID_PARAMETER, 0);
            return STATUS_INVALID_PARAMETER;
        }

        if !io_control_access_granted(access, ioctl) {
            self.write_current_iosb(iosb, STATUS_ACCESS_DENIED, 0);
            return STATUS_ACCESS_DENIED;
        }

        let mut input = match try_zeroed_transfer_buffer(raw_input_len) {
            Ok(input) => input,
            Err(status) => {
                self.write_current_iosb(iosb, status, 0);
                return status;
            }
        };
        if raw_input_len != 0 && !self.xas_read(args[6], &mut input) {
            self.write_current_iosb(iosb, STATUS_ACCESS_VIOLATION, 0);
            return STATUS_ACCESS_VIOLATION;
        }
        let mut output = match try_zeroed_transfer_buffer(raw_output_len) {
            Ok(output) => output,
            Err(status) => {
                self.write_current_iosb(iosb, status, 0);
                return status;
            }
        };
        let output_valid = raw_output_len == 0
            || if nt_io_abi::ioctl::method(ioctl) == nt_io_abi::ioctl::METHOD_IN_DIRECT {
                self.xas_read(args[8], &mut output)
            } else {
                self.probe_user_output(args[8], raw_output_len)
            };
        if !output_valid {
            self.write_current_iosb(iosb, STATUS_ACCESS_VIOLATION, 0);
            return STATUS_ACCESS_VIOLATION;
        }

        let completion_port_suppressed =
            nt_io_completion::io_event_suppresses_completion_port(args[1]);
        let event_obj_idx = match self.prepare_io_event_for_request(args[1]) {
            Ok(Some(index)) => index as u64,
            Ok(None) => u64::MAX,
            Err(event_status) => {
                self.write_current_iosb(iosb, event_status, 0);
                return event_status;
            }
        };
        if !self.reserve_pending_file_io_owner()
            || (synchronous_file
                && (REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 || !wait_reply_pool_has_free()))
        {
            self.write_current_iosb(iosb, STATUS_INSUFFICIENT_RESOURCES, 0);
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        match self.prepare_hosted_file_io(route, args[0], access) {
            Ok(true) => {}
            Ok(false) => return STATUS_PENDING,
            Err(status) => {
                if !self.user_apc_redirected {
                    self.write_current_iosb(iosb, status, 0);
                }
                return status;
            }
        }
        if let Err(status) = self.file_completion.set_signaled(route.file_id, false) {
            self.release_file_reference(route.file_id);
            self.write_current_iosb(iosb, status, 0);
            return status;
        }

        let mut information = 0u64;
        let mut pending_irp_id = 0u64;
        let mut status = match self.dispatch_hosted_file_irp_for(
            route,
            major::IRP_MJ_DEVICE_CONTROL as u64,
            ioctl as u64,
            &input,
            &mut output,
        ) {
            Ok((driver_status, completed, irp_id)) => {
                information = completed;
                pending_irp_id = irp_id;
                driver_status as u32
            }
            Err(route_status) => route_status,
        };
        if status == STATUS_PENDING {
            if pending_irp_id == 0 {
                status = STATUS_INSUFFICIENT_RESOURCES;
                information = 0;
                self.complete_terminal_file_io(
                    route.file_id,
                    event_obj_idx,
                    self.current_tid,
                    args[2],
                    args[3],
                    iosb,
                    status,
                    information,
                    false,
                    completion_port_suppressed,
                );
                self.release_file_reference(route.file_id);
            } else {
                self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                    file_id: route.file_id,
                    irp_id: pending_irp_id,
                    major: major::IRP_MJ_DEVICE_CONTROL,
                    control_code: ioctl,
                    operation: nt_io_manager::PendingFileIoOperation::Transfer,
                    delivery_state: 0,
                    pi: self.pi as u32,
                    tid: self.current_tid,
                    sync_lock_owner_tid: 0,
                    badge: self.current_badge,
                    consumer_abandoned: false,
                    user_apc_interrupt_requested: false,
                    output_va: args[8],
                    output_len: raw_output_len as u32,
                    output_offset: 0,
                    iosb_va: iosb,
                    apc_routine: args[2],
                    apc_context: args[3],
                    completion_port_suppressed,
                    signal_file: synchronous_file || event_obj_idx == u64::MAX,
                    publish_iocp: args[2] == 0,
                    event_obj_idx,
                    reply_cap: 0,
                    reply_required: false,
                    native_call_transport: false,
                    reply_mrs: [0; 18],
                    resume_ip: 0,
                    resume_sp: 0,
                    resume_flags: 0,
                });
                self.pending_file_io_wait = synchronous_file;
            }
        } else {
            if nt_io_completion::file_io_status_copies_output(status) {
                let copy_len = information as usize;
                if copy_len > output.len() {
                    status = STATUS_INVALID_BUFFER_SIZE;
                    information = 0;
                } else if copy_len != 0 && !self.xas_try_write_buf(args[8], &output[..copy_len]) {
                    status = STATUS_ACCESS_VIOLATION;
                    information = 0;
                }
            }
            self.complete_terminal_file_io(
                route.file_id,
                event_obj_idx,
                self.current_tid,
                args[2],
                args[3],
                iosb,
                status,
                information,
                true,
                completion_port_suppressed,
            );
            self.release_file_reference(route.file_id);
        }
        status
    }

    unsafe fn abandon_pending_file_io_for_thread(&mut self, tid: u64) -> usize {
        let mut transfers = Vec::new();
        (&mut *core::ptr::addr_of_mut!(PENDING_FILE_IO))
            .abandon_thread_transfers_with(tid, |pending| transfers.push(pending));
        for pending in transfers.iter().copied() {
            match pending.operation {
                nt_io_manager::PendingFileIoOperation::LocalByteLock(operation) => {
                    if let Some(wait_id) = nt_fs::ByteRangeWaitId::from_raw(operation.wait_id) {
                        let _ = self.byte_range_locks.cancel_wait(wait_id);
                    }
                }
                nt_io_manager::PendingFileIoOperation::LocalDirectoryNotify(operation) => {
                    let _ =
                        self.cancel_local_directory_notify(pending.file_id, operation.notify_id);
                }
                _ => {
                    let _ = driver_launch::cancel_irp_if_pending(pending.irp_id);
                }
            }
            if pending.reply_cap != 0 {
                release_reply_pool_cap(pending.reply_cap);
            }
            thread_wait_state_clear_badge_ready(self, pending.badge);
        }
        if !transfers.is_empty() {
            self.publish_local_byte_lock_completions();
            crate::service_sec_image::FILE_IO_DELIVERY_RETRY_PENDING.store(true, Ordering::Release);
        }

        let mut creates = Vec::new();
        (&mut *core::ptr::addr_of_mut!(PENDING_FILE_IO))
            .take_thread_creates_with(tid, |pending| creates.push(pending));
        for pending in creates.iter().copied() {
            let _ = driver_launch::abandon_pending_irp(pending.irp_id);
            if pending.reply_cap != 0 {
                release_reply_pool_cap(pending.reply_cap);
            }
            thread_wait_state_clear_badge_ready(self, pending.badge);
            self.release_unpublished_hosted_create(pending);
        }
        transfers.len() + creates.len()
    }

    unsafe fn abandon_synchronous_file_waiters_for_thread(&mut self, tid: u64) -> usize {
        let mut waiters = Vec::new();
        (&mut *core::ptr::addr_of_mut!(SYNCHRONOUS_FILE_WAITERS))
            .take_thread_with(tid, |waiter| waiters.push(waiter));
        for waiter in waiters.iter().copied() {
            if waiter.reply_cap != 0 {
                release_reply_pool_cap(waiter.reply_cap);
            }
            thread_wait_state_clear_badge_ready(self, waiter.badge);
            match waiter.state {
                nt_io_manager::SynchronousFileWaitState::Waiting => {
                    self.file_completion
                        .cancel_io_waiter(waiter.file_id)
                        .expect("teardown lost synchronous File waiter count");
                }
                nt_io_manager::SynchronousFileWaitState::Promoted => {
                    self.file_completion
                        .cancel_promoted_io(waiter.file_id, waiter.tid)
                        .expect("teardown lost promoted synchronous File owner");
                    let _ =
                        crate::service_sec_image::synchronous_file_wake_next(self, waiter.file_id);
                }
            }
            self.release_file_reference(waiter.file_id);
        }
        waiters.len()
    }

    unsafe fn abandon_file_irp_drain_waiters_for_thread(&mut self, tid: u64) -> usize {
        let mut waiters = Vec::new();
        (&mut *core::ptr::addr_of_mut!(PENDING_FILE_IRP_DRAINS))
            .take_thread_with(tid, |waiter| waiters.push(waiter));
        for waiter in waiters.iter().copied() {
            if waiter.reply_cap != 0 {
                release_reply_pool_cap(waiter.reply_cap);
            }
            thread_wait_state_clear_badge_ready(self, waiter.badge);
            self.release_file_reference(waiter.file_id);
        }
        waiters.len()
    }

    unsafe fn abandon_file_cleanup_waiters_for_thread(&mut self, tid: u64) -> usize {
        let mut waiters = Vec::new();
        (&mut *core::ptr::addr_of_mut!(PENDING_FILE_CLEANUP_WAITS))
            .take_thread_with(tid, |waiter| waiters.push(waiter));
        for waiter in waiters.iter().copied() {
            if waiter.reply_cap != 0 {
                release_reply_pool_cap(waiter.reply_cap);
            }
            thread_wait_state_clear_badge_ready(self, waiter.badge);
        }
        // The thread owns only its reply continuation. The final-handle reference and canonical
        // CLEANUP/CLOSE lifecycle survive caller teardown and continue to manager completion.
        waiters.len()
    }

    pub(crate) unsafe fn cancel_file_io_for_thread_teardown(&mut self, tid: u64) -> usize {
        self.abandon_pending_file_io_for_thread(tid)
            + self.abandon_synchronous_file_waiters_for_thread(tid)
            + self.abandon_file_irp_drain_waiters_for_thread(tid)
            + self.abandon_file_cleanup_waiters_for_thread(tid)
    }

    unsafe fn nt_cancel_io_file_service(&mut self, args: &[u64]) -> u32 {
        let file_handle = args[0];
        let iosb = args[1];
        if iosb == 0 || !self.probe_user_output(iosb, 16) {
            return STATUS_ACCESS_VIOLATION;
        }
        let file_id = match self.cancel_target_for_handle(file_handle) {
            Ok(target) => target,
            Err(status) => return status,
        };
        let mut matched = 0usize;
        let mut terminal = 0usize;
        let local_file_object = if file_id.is_none() {
            match self.local_file_object_for_handle(file_handle) {
                Ok(file_object) => file_object,
                Err(status) => return status,
            }
        } else {
            None
        };
        if let Some(file_object) = local_file_object {
            let requests: alloc::vec::Vec<_> = (&*core::ptr::addr_of!(PENDING_FILE_IO))
                .drain_all()
                .filter_map(|(_, pending)| {
                    if pending.file_id != file_object || pending.tid != self.current_tid {
                        return None;
                    }
                    match pending.operation {
                        nt_io_manager::PendingFileIoOperation::LocalByteLock(operation) => {
                            Some((false, operation.wait_id))
                        }
                        nt_io_manager::PendingFileIoOperation::LocalDirectoryNotify(operation) => {
                            Some((true, operation.notify_id))
                        }
                        _ => None,
                    }
                })
                .collect();
            matched = requests.len();
            for (directory_notify, request_id) in requests {
                terminal += if directory_notify {
                    self.cancel_local_directory_notify(file_object, request_id) as usize
                } else {
                    nt_fs::ByteRangeWaitId::from_raw(request_id)
                        .is_some_and(|wait_id| self.byte_range_locks.cancel_wait(wait_id))
                        as usize
                };
            }
            self.publish_local_byte_lock_completions();
        } else if let Some(file_id) = file_id {
            let initial = driver_launch::file_thread_io_drain_state(file_id, self.current_tid);
            matched = initial.total;
            terminal = initial.terminal_unacknowledged;
            // The common case requires no continuation resource and cannot fail due to reply-pool
            // pressure merely because no I/O exists to drain.
            if !initial.is_drained() {
                if REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 || !wait_reply_pool_has_free() {
                    return STATUS_INSUFFICIENT_RESOURCES;
                }
                let Some(reservation) = reserve_file_irp_drain_waiter() else {
                    return STATUS_INSUFFICIENT_RESOURCES;
                };
                if let Err(status) = self.file_completion.retain_file(file_id) {
                    assert!((&mut *core::ptr::addr_of_mut!(PENDING_FILE_IRP_DRAINS))
                        .cancel_reservation(reservation));
                    return status;
                }
                let state = match driver_launch::cancel_file_thread_io(file_id, self.current_tid) {
                    Ok(state) => state,
                    Err(status) => {
                        assert!((&mut *core::ptr::addr_of_mut!(PENDING_FILE_IRP_DRAINS))
                            .cancel_reservation(reservation));
                        self.release_file_reference(file_id);
                        return status;
                    }
                };
                matched = state.total;
                terminal = state.terminal_unacknowledged;
                if state.is_drained() {
                    assert!((&mut *core::ptr::addr_of_mut!(PENDING_FILE_IRP_DRAINS))
                        .cancel_reservation(reservation));
                    self.release_file_reference(file_id);
                } else {
                    // Cancellation may have completed inside the manager pump. Force both exact
                    // owners to publish and ACK before the drain continuation can wake.
                    crate::service_sec_image::FILE_IO_DELIVERY_RETRY_PENDING
                        .store(true, Ordering::Release);
                    self.pipe_endpoint_progress = true;
                    self.pending_file_irp_drain = Some((
                        nt_io_manager::PendingFileIrpDrain {
                            file_id,
                            pi: self.pi as u32,
                            tid: self.current_tid,
                            badge: self.current_badge,
                            iosb_va: iosb,
                            native_call_transport: self.current_native_call_transport,
                            resume_ip: self.current_resume_ip,
                            resume_sp: self.current_sp,
                            resume_flags: self.current_flags,
                            ..nt_io_manager::PendingFileIrpDrain::default()
                        },
                        reservation,
                    ));
                }
            }
        }
        let cancelled = matched;
        if self.pending_file_irp_drain.is_none() {
            // ReactOS treats this final write as best effort and still returns success if another
            // thread invalidated the probed IOSB while cancellation drained.
            let _ = self.xas_try_write_buf(iosb, &0u32.to_le_bytes());
            let _ = self.xas_try_write_buf(iosb + 8, &0u64.to_le_bytes());
        }
        let trace = NT_CANCEL_IO_FILE_TRACE_N.fetch_add(1, Ordering::Relaxed);
        if trace < 32 || cancelled != 0 {
            print_str(b"[nt-cancel-io-file] #");
            print_u64(trace);
            print_str(b" pi=");
            print_u64(self.pi as u64);
            print_str(b" badge=");
            print_u64(self.current_badge);
            print_str(b" tid=");
            print_u64(self.current_tid);
            print_str(b" handle=0x");
            print_hex(file_handle as u32);
            print_str(b" fid=0x");
            print_hex(file_id.or(local_file_object).unwrap_or(0) as u32);
            print_str(b" cancelled=");
            print_u64(cancelled as u64);
            print_str(b" terminal=");
            print_u64(terminal as u64);
            print_str(b" parked=");
            print_u64(self.pending_file_irp_drain.is_some() as u64);
            print_str(b"\n");
        }
        if self.pending_file_irp_drain.is_some() {
            STATUS_PENDING
        } else {
            0
        }
    }

    unsafe fn nt_notify_change_directory_file_service(&mut self, args: &[u64]) -> u32 {
        let handle = args[0];
        let event = args[1];
        let apc_routine = args[2];
        let apc_context = args[3];
        let iosb = args[4];
        let buffer = args[5];
        let buffer_length = nt_ulong_arg(args[6]);
        let completion_filter = nt_ulong_arg(args[7]);
        let watch_tree = nt_boolean_arg(args[8]);

        if iosb == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        if iosb & 7 != 0 || (buffer_length != 0 && buffer & 3 != 0) {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if !self.probe_user_output(iosb, 16)
            || (buffer_length != 0
                && (buffer == 0 || !self.probe_user_output(buffer, buffer_length as usize)))
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let parameters = nt_io_manager::DirectoryNotifyParameters {
            length: buffer_length,
            completion_filter,
        };
        if !nt_io_manager::valid_directory_notify_parameters(parameters) {
            return STATUS_INVALID_PARAMETER;
        }

        let local_route = match self.local_directory_notify_route_for(handle) {
            Ok(route) => route,
            Err(status) => return status,
        };
        let hosted_route = if local_route.is_none() {
            match self.hosted_file_route_for(handle) {
                Some(route) => Some(route),
                None => return STATUS_INVALID_HANDLE,
            }
        } else {
            None
        };
        let hosted_access = if let Some(route) = hosted_route {
            let Some(access) = self.hosted_file_access_for(handle) else {
                return STATUS_INVALID_HANDLE;
            };
            if !nt_io_manager::directory_notify_access_granted(
                nt_types::AccessMask::from_bits_retain(access),
            ) {
                return STATUS_ACCESS_DENIED;
            }
            if apc_routine != 0 && self.file_completion.binding(route.file_id).is_some() {
                return STATUS_INVALID_PARAMETER;
            }
            access
        } else {
            0
        };
        let event_obj_idx = match self.prepare_io_event_for_request(event) {
            Ok(index) => index.map_or(u64::MAX, |index| index as u64),
            Err(status) => return status,
        };
        let completion_port_suppressed =
            nt_io_completion::io_event_suppresses_completion_port(event);
        let synchronous = local_route
            .as_ref()
            .map(LocalDirectoryNotifyRoute::synchronous)
            .unwrap_or_else(|| {
                self.file_completion
                    .is_synchronous(hosted_route.unwrap().file_id)
                    .unwrap_or(true)
            });
        if !self.reserve_pending_file_io_owner()
            || (synchronous
                && (REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 || !wait_reply_pool_has_free()))
        {
            return STATUS_INSUFFICIENT_RESOURCES;
        }

        if let Some(route) = local_route {
            let request_id = self.allocate_local_directory_notify_irp_id();
            let file_object = route.file_object();
            if let Err(status) = self.begin_local_file_io(file_object) {
                return status;
            }
            let registration = match &route {
                LocalDirectoryNotifyRoute::Fat {
                    file_object,
                    directory,
                    ..
                } => self.readonly_directory_notifications.register(
                    *file_object,
                    directory,
                    completion_filter,
                    watch_tree,
                    buffer_length,
                    request_id,
                ),
                LocalDirectoryNotifyRoute::Overlay { file_id, .. } => {
                    crate::writable_fs::notify_change_directory(
                        *file_id,
                        completion_filter,
                        watch_tree,
                        buffer_length,
                        request_id,
                    )
                }
            };
            let notify_id = match registration {
                Ok(id) => id,
                Err(status) => {
                    self.complete_terminal_local_file_io(
                        file_object,
                        synchronous,
                        event_obj_idx,
                        self.current_tid,
                        apc_routine,
                        apc_context,
                        iosb,
                        status,
                        0,
                        true,
                        completion_port_suppressed,
                    );
                    return status;
                }
            };
            self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                file_id: file_object,
                irp_id: request_id,
                major: major::IRP_MJ_DIRECTORY_CONTROL,
                control_code: 0,
                operation: nt_io_manager::PendingFileIoOperation::LocalDirectoryNotify(
                    nt_io_manager::PendingLocalDirectoryNotify {
                        notify_id: notify_id.raw(),
                        status: STATUS_PENDING,
                        information: 0,
                        alertable: route.alertable(),
                    },
                ),
                delivery_state: 0,
                pi: self.pi as u32,
                tid: self.current_tid,
                sync_lock_owner_tid: 0,
                badge: self.current_badge,
                consumer_abandoned: false,
                user_apc_interrupt_requested: false,
                output_va: buffer,
                output_len: buffer_length,
                output_offset: 0,
                iosb_va: iosb,
                apc_routine,
                apc_context,
                completion_port_suppressed,
                signal_file: synchronous || event_obj_idx == u64::MAX,
                publish_iocp: false,
                event_obj_idx,
                reply_cap: 0,
                reply_required: false,
                native_call_transport: false,
                reply_mrs: [0; 18],
                resume_ip: 0,
                resume_sp: 0,
                resume_flags: 0,
            });
            self.pending_file_io_wait = synchronous;
            return STATUS_PENDING;
        }

        let route = hosted_route.unwrap();
        let mut output = match try_zeroed_transfer_buffer(buffer_length as usize) {
            Ok(output) => output,
            Err(status) => return status,
        };
        match self.prepare_hosted_file_io(route, handle, hosted_access) {
            Ok(true) => {}
            Ok(false) => return STATUS_PENDING,
            Err(status) => return status,
        }
        if let Err(status) = self.file_completion.set_signaled(route.file_id, false) {
            self.release_file_reference(route.file_id);
            return status;
        }
        let stack_flags = if watch_tree {
            nt_io_manager::StackFlags::WATCH_TREE
        } else {
            nt_io_manager::StackFlags::empty()
        };
        let (mut status, mut information, pending_irp_id) =
            match driver_launch::dispatch_hosted_file_notify_directory_irp_result_exact(
                route.file_id,
                self.current_tid,
                parameters,
                stack_flags,
                &mut output,
            ) {
                Ok((status, information, irp_id, _)) => (
                    status as u32,
                    information,
                    irp_id.map_or(0, nt_io_manager::IrpId::raw),
                ),
                Err(status) => (status, 0, 0),
            };
        if status == STATUS_PENDING && pending_irp_id == 0 {
            status = STATUS_INSUFFICIENT_RESOURCES;
        }
        if status == STATUS_PENDING {
            self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                file_id: route.file_id,
                irp_id: pending_irp_id,
                major: major::IRP_MJ_DIRECTORY_CONTROL,
                control_code: 0,
                operation: nt_io_manager::PendingFileIoOperation::Transfer,
                delivery_state: 0,
                pi: self.pi as u32,
                tid: self.current_tid,
                sync_lock_owner_tid: 0,
                badge: self.current_badge,
                consumer_abandoned: false,
                user_apc_interrupt_requested: false,
                output_va: buffer,
                output_len: buffer_length,
                output_offset: 0,
                iosb_va: iosb,
                apc_routine,
                apc_context,
                completion_port_suppressed,
                signal_file: synchronous || event_obj_idx == u64::MAX,
                publish_iocp: apc_routine == 0,
                event_obj_idx,
                reply_cap: 0,
                reply_required: false,
                native_call_transport: false,
                reply_mrs: [0; 18],
                resume_ip: 0,
                resume_sp: 0,
                resume_flags: 0,
            });
            self.pending_file_io_wait = synchronous;
        } else {
            if nt_io_completion::file_io_status_copies_output(status) {
                let copy_len = information as usize;
                if copy_len > output.len() {
                    status = STATUS_INVALID_BUFFER_SIZE;
                    information = 0;
                } else if copy_len != 0 && !self.xas_try_write_buf(buffer, &output[..copy_len]) {
                    status = STATUS_ACCESS_VIOLATION;
                    information = 0;
                }
            }
            self.complete_terminal_file_io(
                route.file_id,
                event_obj_idx,
                self.current_tid,
                apc_routine,
                apc_context,
                iosb,
                status,
                information,
                true,
                completion_port_suppressed,
            );
            self.release_file_reference(route.file_id);
        }
        status
    }

    unsafe fn nt_lock_file_service(&mut self, args: &[u64]) -> u32 {
        const STATUS_PENDING: u32 = 0x0000_0103;
        let handle = args[0];
        let event = args[1];
        let apc_routine = args[2];
        let apc_context = args[3];
        let iosb = args[4];
        let mut offset_bytes = [0u8; 8];
        let mut length_bytes = [0u8; 8];
        if iosb == 0
            || !self.probe_user_output(iosb, 16)
            || args[5] == 0
            || !self.xas_read(args[5], &mut offset_bytes)
            || args[6] == 0
            || !self.xas_read(args[6], &mut length_bytes)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let byte_offset = u64::from_le_bytes(offset_bytes);
        let length = u64::from_le_bytes(length_bytes);
        let key = nt_ulong_arg(args[7]);
        let fail_immediately = nt_boolean_arg(args[8]);
        let exclusive = nt_boolean_arg(args[9]);
        let pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_fs::STATUS_INVALID_HANDLE,
        };
        let local_route = match self.local_byte_lock_route_for(handle) {
            Ok(route) => route,
            Err(status) => return status,
        };
        let hosted_route = if local_route.is_none() {
            match self.hosted_file_route_for(handle) {
                Some(route) => Some(route),
                None => return nt_fs::STATUS_INVALID_HANDLE,
            }
        } else {
            None
        };
        if hosted_route.is_some_and(|route| {
            apc_routine != 0 && self.file_completion.binding(route.file_id).is_some()
        }) {
            return STATUS_INVALID_PARAMETER;
        }
        let hosted_access = if hosted_route.is_some() {
            match self.hosted_file_access_for(handle) {
                Some(access)
                    if access
                        & (0x0000_0001 | 0x0000_0002 | 0x8000_0000 | 0x4000_0000 | 0x1000_0000)
                        != 0 =>
                {
                    access
                }
                Some(_) => return STATUS_ACCESS_DENIED,
                None => return nt_fs::STATUS_INVALID_HANDLE,
            }
        } else {
            0
        };
        let event_obj_idx = match self.prepare_lock_event_for_request(event) {
            Ok(index) => index.map_or(u64::MAX, |index| index as u64),
            Err(status) => return status,
        };
        let completion_port_suppressed =
            nt_io_completion::io_event_suppresses_completion_port(event);
        let synchronous = local_route
            .map(|route| route.synchronous)
            .unwrap_or_else(|| {
                self.file_completion
                    .is_synchronous(hosted_route.unwrap().file_id)
                    .unwrap_or(true)
            });
        if !self.reserve_pending_file_io_owner()
            || (synchronous
                && (REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 || !wait_reply_pool_has_free()))
        {
            return STATUS_INSUFFICIENT_RESOURCES;
        }

        if let Some(route) = local_route {
            let request_id = self.allocate_local_byte_lock_irp_id();
            if let Err(status) = self.begin_local_file_io(route.file_object) {
                return status;
            }
            let request = nt_fs::ByteRangeLockRequest::new(
                route.file_id,
                nt_fs::ByteRangeLockOwner::new(route.file_object, pid as u64, key),
                byte_offset,
                length,
                exclusive,
            );
            match self
                .byte_range_locks
                .lock(request, fail_immediately, request_id)
            {
                nt_fs::ByteRangeLockResult::Granted => {
                    self.complete_terminal_local_file_io(
                        route.file_object,
                        synchronous,
                        event_obj_idx,
                        self.current_tid,
                        apc_routine,
                        apc_context,
                        iosb,
                        nt_fs::STATUS_SUCCESS,
                        0,
                        true,
                        completion_port_suppressed,
                    );
                    nt_fs::STATUS_SUCCESS
                }
                nt_fs::ByteRangeLockResult::Failed(status) => {
                    self.complete_terminal_local_file_io(
                        route.file_object,
                        synchronous,
                        event_obj_idx,
                        self.current_tid,
                        apc_routine,
                        apc_context,
                        iosb,
                        status,
                        0,
                        true,
                        completion_port_suppressed,
                    );
                    status
                }
                nt_fs::ByteRangeLockResult::Pending(wait_id) => {
                    self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                        file_id: route.file_object,
                        irp_id: request_id,
                        major: major::IRP_MJ_LOCK_CONTROL,
                        control_code: 0,
                        operation: nt_io_manager::PendingFileIoOperation::LocalByteLock(
                            nt_io_manager::PendingLocalByteLock {
                                wait_id: wait_id.raw(),
                                status: STATUS_PENDING,
                                alertable: route.alertable,
                            },
                        ),
                        delivery_state: 0,
                        pi: self.pi as u32,
                        tid: self.current_tid,
                        sync_lock_owner_tid: 0,
                        badge: self.current_badge,
                        consumer_abandoned: false,
                        user_apc_interrupt_requested: false,
                        output_va: 0,
                        output_len: 0,
                        output_offset: 0,
                        iosb_va: iosb,
                        apc_routine,
                        apc_context,
                        completion_port_suppressed,
                        signal_file: synchronous || event_obj_idx == u64::MAX,
                        publish_iocp: false,
                        event_obj_idx,
                        reply_cap: 0,
                        reply_required: false,
                        native_call_transport: false,
                        reply_mrs: [0; 18],
                        resume_ip: 0,
                        resume_sp: 0,
                        resume_flags: 0,
                    });
                    self.pending_file_io_wait = synchronous;
                    STATUS_PENDING
                }
            }
        } else {
            let route = hosted_route.unwrap();
            match self.prepare_hosted_file_io(route, handle, hosted_access) {
                Ok(true) => {}
                Ok(false) => return STATUS_PENDING,
                Err(status) => return status,
            }
            if let Err(status) = self.file_completion.set_signaled(route.file_id, false) {
                self.release_file_reference(route.file_id);
                return status;
            }
            let mut flags = nt_io_manager::StackFlags::empty();
            if fail_immediately {
                flags |=
                    nt_io_manager::StackFlags::from_bits_retain(nt_io_manager::SL_FAIL_IMMEDIATELY);
            }
            if exclusive {
                flags |=
                    nt_io_manager::StackFlags::from_bits_retain(nt_io_manager::SL_EXCLUSIVE_LOCK);
            }
            let (mut status, information, pending_irp_id) =
                match driver_launch::dispatch_hosted_file_lock_control_irp_result_exact(
                    route.file_id,
                    self.current_tid,
                    nt_io_manager::LockControlParameters {
                        minor: nt_io_manager::IRP_MN_LOCK,
                        byte_offset,
                        length,
                        key,
                    },
                    flags,
                ) {
                    Ok((status, information, irp, _)) => {
                        (status as u32, information, irp.map_or(0, |irp| irp.raw()))
                    }
                    Err(status) => (status, 0, 0),
                };
            if status == STATUS_PENDING && pending_irp_id == 0 {
                status = STATUS_INSUFFICIENT_RESOURCES;
            }
            if status == STATUS_PENDING {
                self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                    file_id: route.file_id,
                    irp_id: pending_irp_id,
                    major: major::IRP_MJ_LOCK_CONTROL,
                    control_code: 0,
                    operation: nt_io_manager::PendingFileIoOperation::Transfer,
                    delivery_state: 0,
                    pi: self.pi as u32,
                    tid: self.current_tid,
                    sync_lock_owner_tid: 0,
                    badge: self.current_badge,
                    consumer_abandoned: false,
                    user_apc_interrupt_requested: false,
                    output_va: 0,
                    output_len: 0,
                    output_offset: 0,
                    iosb_va: iosb,
                    apc_routine,
                    apc_context,
                    completion_port_suppressed,
                    signal_file: synchronous || event_obj_idx == u64::MAX,
                    publish_iocp: apc_routine == 0,
                    event_obj_idx,
                    reply_cap: 0,
                    reply_required: false,
                    native_call_transport: false,
                    reply_mrs: [0; 18],
                    resume_ip: 0,
                    resume_sp: 0,
                    resume_flags: 0,
                });
                self.pending_file_io_wait = synchronous;
            } else {
                self.complete_terminal_file_io(
                    route.file_id,
                    event_obj_idx,
                    self.current_tid,
                    apc_routine,
                    apc_context,
                    iosb,
                    status,
                    information,
                    true,
                    completion_port_suppressed,
                );
                self.release_file_reference(route.file_id);
            }
            status
        }
    }

    unsafe fn nt_unlock_file_service(&mut self, args: &[u64]) -> u32 {
        const STATUS_PENDING: u32 = 0x0000_0103;
        let handle = args[0];
        let iosb = args[1];
        let mut offset_bytes = [0u8; 8];
        let mut length_bytes = [0u8; 8];
        if iosb == 0
            || !self.probe_user_output(iosb, 16)
            || args[2] == 0
            || !self.xas_read(args[2], &mut offset_bytes)
            || args[3] == 0
            || !self.xas_read(args[3], &mut length_bytes)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let byte_offset = u64::from_le_bytes(offset_bytes);
        let length = u64::from_le_bytes(length_bytes);
        let key = nt_ulong_arg(args[4]);
        let pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_fs::STATUS_INVALID_HANDLE,
        };
        let local_route = match self.local_byte_lock_route_for(handle) {
            Ok(route) => route,
            Err(status) => return status,
        };
        if let Some(route) = local_route {
            let status = self
                .byte_range_locks
                .unlock_single(nt_fs::ByteRangeLockRequest::new(
                    route.file_id,
                    nt_fs::ByteRangeLockOwner::new(route.file_object, pid as u64, key),
                    byte_offset,
                    length,
                    true,
                ));
            self.write_current_iosb(iosb, status, 0);
            self.publish_local_byte_lock_completions();
            return status;
        }

        let route = match self.hosted_file_route_for(handle) {
            Some(route) => route,
            None => return nt_fs::STATUS_INVALID_HANDLE,
        };
        if !self.reserve_pending_file_io_owner()
            || REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0
            || !wait_reply_pool_has_free()
        {
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        let access = self.hosted_file_access_for(handle).unwrap();
        match self.prepare_hosted_file_io(route, handle, access) {
            Ok(true) => {}
            Ok(false) => return STATUS_PENDING,
            Err(status) => return status,
        }
        if let Err(status) = self.file_completion.set_signaled(route.file_id, false) {
            self.release_file_reference(route.file_id);
            return status;
        }
        let (mut status, information, pending_irp_id) =
            match driver_launch::dispatch_hosted_file_lock_control_irp_result_exact(
                route.file_id,
                self.current_tid,
                nt_io_manager::LockControlParameters {
                    minor: nt_io_manager::IRP_MN_UNLOCK_SINGLE,
                    byte_offset,
                    length,
                    key,
                },
                nt_io_manager::StackFlags::empty(),
            ) {
                Ok((status, information, irp, _)) => {
                    (status as u32, information, irp.map_or(0, |irp| irp.raw()))
                }
                Err(status) => (status, 0, 0),
            };
        if status == STATUS_PENDING && pending_irp_id == 0 {
            status = STATUS_INSUFFICIENT_RESOURCES;
        }
        if status == STATUS_PENDING {
            self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                file_id: route.file_id,
                irp_id: pending_irp_id,
                major: major::IRP_MJ_LOCK_CONTROL,
                control_code: 0,
                operation: nt_io_manager::PendingFileIoOperation::Transfer,
                delivery_state: 0,
                pi: self.pi as u32,
                tid: self.current_tid,
                sync_lock_owner_tid: 0,
                badge: self.current_badge,
                consumer_abandoned: false,
                user_apc_interrupt_requested: false,
                output_va: 0,
                output_len: 0,
                output_offset: 0,
                iosb_va: iosb,
                apc_routine: 0,
                apc_context: 0,
                completion_port_suppressed: true,
                signal_file: true,
                publish_iocp: false,
                event_obj_idx: u64::MAX,
                reply_cap: 0,
                reply_required: false,
                native_call_transport: false,
                reply_mrs: [0; 18],
                resume_ip: 0,
                resume_sp: 0,
                resume_flags: 0,
            });
            self.pending_file_io_wait = true;
        } else {
            self.write_current_iosb(iosb, status, information);
            let _ = self.signal_file_completion(route.file_id, status);
            self.release_file_reference(route.file_id);
        }
        status
    }
    /// ★ CROSS-VSPACE `NtCreateThread` — a genuine ADDITIONAL thread inside a FOREIGN process
    /// (`RtlCreateUserThread(ProcessHandle != NtCurrentProcess)`; `DbgUiIssueRemoteBreakin`'s
    /// break-in thread is the first real user). This is the POLICY half of `PspCreateThread`:
    ///
    /// 1. **Access check** — creating a thread in another process is a privileged capability
    ///    operation, so the `ProcessHandle` is re-resolved through `resolve_process_for_access`
    ///    demanding `PROCESS_CREATE_THREAD` (0x0002). A handle without it is `STATUS_ACCESS_DENIED`,
    ///    an unknown handle `STATUS_INVALID_HANDLE` — never an ambient side effect.
    /// 2. The target must be ALIVE with a published hosted VSpace, and not exiting.
    /// 3. The start context (`CONTEXT.Rip` = start routine, `.Rcx` = parameter) is read out of the
    ///    caller's `ThreadContext` argument — this is what makes the created thread the RIGHT
    ///    thread rather than "some thread somewhere".
    /// 4. A real ETHREAD is claimed from the **TARGET's** pool (the thread belongs to the target),
    ///    its TEB VA bound, and a TYPED `Thread(tid)` handle minted in the **CALLER's** table.
    /// 5. `*ThreadHandle` / `*ClientId {target pid, new tid}` out-params are queued.
    /// 6. The MECHANISM (the seL4 thread in the target's VSpace) is requested from the loop, which
    ///    owns the main fault endpoint the new thread is badged onto.
    pub(crate) unsafe fn create_remote_thread(&mut self, args: &[u64]) -> u32 {
        const PROCESS_CREATE_THREAD: u32 = 0x0002;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        macro_rules! reject {
            ($why:expr, $status:expr) => {{
                print_str(b"[remote-thread] reject ");
                print_str($why);
                print_str(b"\n");
                return $status;
            }};
        }
        let Some(caller_pid) = self.pm_pid_for_pi(self.pi) else {
            reject!(b"no-caller-pid", nt_process::STATUS_INVALID_HANDLE);
        };
        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[3], PROCESS_CREATE_THREAD) {
                Ok(resolved) => resolved,
                Err(status) => {
                    if status != 0xC000_0022 {
                        print_str(b"[remote-thread] reject resolve status=0x");
                        print_hex(status);
                        print_str(b"\n");
                    }
                    return status;
                }
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            reject!(
                b"target-terminating",
                nt_process::STATUS_PROCESS_IS_TERMINATING
            );
        }
        let Some(pml4) = self.hosted_process_vspace(target_pi) else {
            reject!(
                b"no-target-vspace",
                nt_process::STATUS_PROCESS_IS_TERMINATING
            );
        };
        let cid_ptr = args[NT_CREATE_THREAD_CLIENT_ID_ARG];
        let ctx_va = args[NT_CREATE_THREAD_CONTEXT_ARG];
        if ctx_va == 0 {
            reject!(b"null-thread-context", STATUS_INVALID_PARAMETER);
        }
        let start = nt_thread_start::Amd64ThreadContext::read(
            |address| unsafe { smss_stack_read(address) },
            ctx_va,
        );
        if start.rip == 0 {
            reject!(b"null-start-address", STATUS_INVALID_PARAMETER);
        }
        let initial_teb_va = args[NT_CREATE_THREAD_INITIAL_TEB_ARG];
        let initial_teb = (initial_teb_va != 0).then(|| {
            nt_thread_start::InitialTeb64::read(
                |address| unsafe { smss_stack_read(address) },
                initial_teb_va,
            )
        });
        let create_suspended = nt_boolean_arg(args[NT_CREATE_THREAD_CREATE_SUSPENDED_ARG]);
        // The bounded per-process thread windows are a shared resource with the ntdll thread-pool
        // workers — one window per extra thread of that process.
        let Some(slot) = self.first_free_hosted_tp_worker_slot(target_pi) else {
            reject!(b"no-free-thread-slot", STATUS_INSUFFICIENT_RESOURCES);
        };
        let Some((pool_slot, tid)) = self.claim_pool_thread(target_pi, start.rip, create_suspended)
        else {
            reject!(b"no-pool-ethread", STATUS_INSUFFICIENT_RESOURCES);
        };
        let thread = tid as nt_process::ThreadId;
        if !self.reserve_hosted_tp_worker_slot(target_pi, slot, tid) {
            let _ = self
                .pm
                .set_thread_state(thread, nt_process::ThreadState::Initialized);
            self.release_pool_usage_slot(target_pi, pool_slot);
            reject!(b"reserve-thread-slot", STATUS_INSUFFICIENT_RESOURCES);
        }
        let handle = match self.insert_process_handle(
            caller_pid,
            nt_process::HandleObject::Thread(thread),
            nt_ulong_arg(args[1]),
        ) {
            Ok(handle) => handle as u64,
            Err(status) => {
                self.release_unmapped_hosted_tp_worker_slot(target_pi, slot, tid);
                let _ = self
                    .pm
                    .set_thread_state(thread, nt_process::ThreadState::Initialized);
                self.release_pool_usage_slot(target_pi, pool_slot);
                reject!(b"handle-insert", status);
            }
        };
        if let Some(initial_teb) = initial_teb {
            let _ = self.remember_hosted_thread_user_stack(tid, initial_teb);
        }
        self.pm.set_thread_teb(thread, tp_worker_teb_va(slot));
        let _ = self
            .pm
            .set_thread_create_time(thread, nt_system_time_100ns() as i64);
        let _ = self.pm.report_existing_thread_create(thread);
        PM_REMOTE_THREADS_CREATED.fetch_add(1, Ordering::Relaxed);
        self.queue_write(args[0], handle);
        if cid_ptr != 0 {
            self.queue_write(cid_ptr, target_pid as u64);
            self.queue_write(cid_ptr + 8, tid);
        }
        self.remote_thread_request = Some(RemoteThreadRequest {
            target_pi,
            slot,
            pml4,
            start,
            cid_proc: target_pid as u64,
            cid_thread: tid,
            resume: !create_suspended,
        });
        print_str(b"[remote-thread] cross-vspace create caller_pi=");
        print_u64(self.pi as u64);
        print_str(b" target_pi=");
        print_u64(target_pi as u64);
        print_str(b" slot=");
        print_u64(slot as u64);
        print_str(b" tid=");
        print_u64(tid);
        print_str(b" entry=0x");
        print_hex((start.rip >> 32) as u32);
        print_hex(start.rip as u32);
        print_str(b" param=0x");
        print_hex(start.rcx as u32);
        print_str(b" suspended=");
        print_u64(create_suspended as u64);
        print_str(b"\n");
        0
    }

    fn create_hosted_worker_thread_from_start(
        &mut self,
        owner_pi: usize,
        caller_pid: nt_process::ProcessId,
        desired_access: u32,
        start: nt_thread_start::Amd64ThreadContext,
        create_suspended: bool,
        hide_from_debugger: bool,
    ) -> Result<(usize, u64, u64), u32> {
        if owner_pi >= MAX_PI || start.rip == 0 {
            return Err(nt_process::STATUS_INVALID_PARAMETER);
        }
        let worker_slot = self
            .first_free_hosted_tp_worker_slot(owner_pi)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let (pool_slot, tid) = self
            .claim_pool_thread(owner_pi, start.rip, create_suspended)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let thread = tid as nt_process::ThreadId;
        let handle = match self.insert_process_handle(
            caller_pid,
            nt_process::HandleObject::Thread(thread),
            desired_access,
        ) {
            Ok(handle) => handle as u64,
            Err(status) => {
                let _ = self
                    .pm
                    .set_thread_state(thread, nt_process::ThreadState::Initialized);
                self.release_pool_usage_slot(owner_pi, pool_slot);
                return Err(status);
            }
        };
        if !self.reserve_hosted_tp_worker_slot(owner_pi, worker_slot, tid) {
            self.abandon_created_hosted_thread_for(owner_pi, pool_slot, tid, caller_pid, handle);
            return Err(STATUS_INSUFFICIENT_RESOURCES);
        }
        if hide_from_debugger {
            if let Err(status) = self.pm.set_thread_hide_from_debugger(thread) {
                self.abandon_created_hosted_thread_for(
                    owner_pi, pool_slot, tid, caller_pid, handle,
                );
                return Err(status);
            }
        }
        self.pm
            .set_thread_teb(thread, tp_worker_teb_va(worker_slot));
        let _ = self
            .pm
            .set_thread_create_time(thread, nt_system_time_100ns() as i64);
        let _ = self.pm.report_existing_thread_create(thread);
        PM_GENERAL_THREADS_CREATED.fetch_add(1, Ordering::Relaxed);
        Ok((worker_slot, tid, handle))
    }

    unsafe fn nt_create_thread_ex_service(&mut self, args: &[u64]) -> u32 {
        const PROCESS_CREATE_THREAD: u32 = 0x0002;
        const THREAD_CREATE_FLAGS_CREATE_SUSPENDED: u32 = 0x0000_0001;
        const THREAD_CREATE_FLAGS_HIDE_FROM_DEBUGGER: u32 = 0x0000_0004;
        const SUPPORTED_THREAD_CREATE_FLAGS: u32 =
            THREAD_CREATE_FLAGS_CREATE_SUSPENDED | THREAD_CREATE_FLAGS_HIDE_FROM_DEBUGGER;

        let thread_handle_out = args[0];
        if thread_handle_out == 0 || !self.probe_user_output(thread_handle_out, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        let start = nt_thread_start::Amd64ThreadContext {
            rip: args[4],
            rsp: 0,
            rcx: args[5],
            rdx: 0,
        };
        if start.rip == 0 {
            self.queue_write(thread_handle_out, 0);
            return STATUS_INVALID_PARAMETER;
        }
        let create_flags = nt_ulong_arg(args[6]);
        if create_flags & !SUPPORTED_THREAD_CREATE_FLAGS != 0 {
            self.queue_write(thread_handle_out, 0);
            return STATUS_NOT_SUPPORTED;
        }
        // The hosted worker-window stack is fixed and owned by the kernel thread mechanism. Do not
        // accept caller stack geometry until NtCreateThreadEx can honor it exactly.
        if args[7] != 0 || args[8] != 0 || args[9] != 0 || args[10] != 0 {
            self.queue_write(thread_handle_out, 0);
            return STATUS_NOT_SUPPORTED;
        }

        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => {
                self.queue_write(thread_handle_out, 0);
                return nt_process::STATUS_INVALID_HANDLE;
            }
        };
        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[3], PROCESS_CREATE_THREAD) {
                Ok(resolved) => resolved,
                Err(status) => {
                    self.queue_write(thread_handle_out, 0);
                    return status;
                }
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            self.queue_write(thread_handle_out, 0);
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }
        if self.hosted_process_vspace(target_pi).is_none() {
            self.queue_write(thread_handle_out, 0);
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }

        let create_suspended = create_flags & THREAD_CREATE_FLAGS_CREATE_SUSPENDED != 0;
        let hide_from_debugger = create_flags & THREAD_CREATE_FLAGS_HIDE_FROM_DEBUGGER != 0;
        let (slot, tid, handle) = match self.create_hosted_worker_thread_from_start(
            target_pi,
            caller_pid,
            nt_ulong_arg(args[1]),
            start,
            create_suspended,
            hide_from_debugger,
        ) {
            Ok(created) => created,
            Err(status) => {
                self.queue_write(thread_handle_out, 0);
                return status;
            }
        };
        self.queue_write(thread_handle_out, handle);
        self.thread_spawn_request = Some(HostedThreadSpawnRequest::TpWorker {
            pi: target_pi,
            slot,
            start,
        });

        print_str(b"[thread-ex] create caller_pi=");
        print_u64(self.pi as u64);
        print_str(b" target_pi=");
        print_u64(target_pi as u64);
        print_str(b" slot=");
        print_u64(slot as u64);
        print_str(b" tid=");
        print_u64(tid);
        print_str(b" entry=0x");
        print_hex((start.rip >> 32) as u32);
        print_hex(start.rip as u32);
        print_str(b" param=0x");
        print_hex((start.rcx >> 32) as u32);
        print_hex(start.rcx as u32);
        print_str(b" suspended=");
        print_u64(create_suspended as u64);
        print_str(b" hide-debug=");
        print_u64(hide_from_debugger as u64);
        print_str(b" handle=0x");
        print_hex(handle as u32);
        print_str(b"\n");
        0
    }

    /// Claim the next free pre-created pool ETHREAD belonging to hosted process `pi` and bind the
    /// caller-supplied start routine (alloc-free field writes, reset-safe — the pool exists so
    /// runtime thread creation never allocates under the per-syscall bump heap). Returns
    /// `(pool slot, tid)`, releasing the slot again on any failure. `pi` is a PARAMETER, not
    /// `self.pi`: a cross-VSpace `NtCreateThread` creates a thread that belongs to the TARGET
    /// process, so it must come out of the TARGET's pool.
    pub(crate) fn claim_pool_thread(
        &mut self,
        pi: usize,
        entry: u64,
        create_suspended: bool,
    ) -> Option<(usize, u64)> {
        let mut skipped = 0u64;
        loop {
            let slot = self.claim_pool_usage_slot_excluding(pi, skipped)?;
            let Some(tid32) = self.pm_pool_tid_for_slot(pi, slot) else {
                self.release_pool_usage_slot(pi, slot);
                skipped |= 1u64 << slot;
                crate::PM_POOL_UNRECLAIMABLE_SKIPS.fetch_add(1, Ordering::Relaxed);
                continue;
            };
            let tid = tid32 as u64;
            let t = tid as nt_process::ThreadId;
            let prepared = if self
                .pm
                .thread(t)
                .is_some_and(|thread| thread.state == nt_process::ThreadState::Terminated)
            {
                self.pm
                    .reuse_reclaimed_thread(t, entry, create_suspended)
                    .is_ok()
            } else {
                self.pm.set_thread_start_address(t, entry)
                    && if create_suspended {
                        self.pm.suspend_thread(t).is_ok()
                    } else {
                        self.pm
                            .set_thread_state(t, nt_process::ThreadState::Running)
                            .is_ok()
                    }
            };
            if prepared {
                return Some((slot, tid));
            }
            self.release_pool_usage_slot(pi, slot);
            skipped |= 1u64 << slot;
            crate::PM_POOL_UNRECLAIMABLE_SKIPS.fetch_add(1, Ordering::Relaxed);
        }
    }

    /// General NtCreateThread: claim the next real pool ETHREAD for the caller (`self.pi`) — bind the
    /// caller-supplied start routine + parameter (all alloc-free field writes, reset-safe),
    /// and mint a TYPED `Thread(tid)` handle in the caller's EPROCESS handle table (dense value, so
    /// `NtQueryInformationThread` resolves the handle VALUE → the real ETHREAD). Returns
    /// `(slot, tid, handle)`
    /// or `None` if the caller has no free pool ETHREAD. The seL4 TCB is spawned separately by the loop.
    pub(crate) fn nt_create_thread_handle(
        &mut self,
        entry: u64,
        create_suspended: bool,
        desired_access: u32,
    ) -> Option<(usize, u64, u64)> {
        let pid = self.pm_pid_for_pi(self.pi)?;
        let (slot, tid) = match self.claim_pool_thread(self.pi, entry, create_suspended) {
            Some(claimed) => claimed,
            None => {
                // A refused runtime thread create surfaces to the caller only as
                // STATUS_INSUFFICIENT_RESOURCES (rpcrt4 prints `error=5aa` and drops the
                // connection), so NAME the reason: which pool, how full, and whether the pre-created
                // ETHREAD pool had a slot at all.
                if crate::PM_POOL_REFUSALS.fetch_add(1, Ordering::Relaxed) < 8 {
                    unsafe {
                        print_str(b"[thread-pool] REFUSED NtCreateThread pi=");
                        print_u64(self.pi as u64);
                        print_str(b" used-mask=0x");
                        print_hex(self.pool_used_mask(self.pi) as u32);
                        print_str(b" slots=");
                        print_u64(PM_RUNTIME_THREAD_SLOTS as u64);
                        print_str(b" skipped=");
                        print_u64(crate::PM_POOL_UNRECLAIMABLE_SKIPS.load(Ordering::Relaxed));
                        print_str(b" pool-tids:");
                        for index in 0..PM_RUNTIME_THREAD_SLOTS {
                            print_str(b" ");
                            print_u64(
                                self.pm_pool_tid_for_slot(self.pi, index)
                                    .map(u64::from)
                                    .unwrap_or(0),
                            );
                        }
                        print_str(b"\n");
                    }
                }
                return None;
            }
        };
        let t = tid as nt_process::ThreadId;
        let h = match self.insert_process_handle(
            pid,
            nt_process::HandleObject::Thread(t),
            desired_access,
        ) {
            Ok(handle) => handle,
            Err(_) => {
                if create_suspended {
                    let _ = self.pm.resume_thread(t);
                }
                let _ = self
                    .pm
                    .set_thread_state(t, nt_process::ThreadState::Initialized);
                self.release_pool_usage_slot(self.pi, slot);
                return None;
            }
        };
        let _ = self
            .pm
            .set_thread_create_time(t, nt_system_time_100ns() as i64);
        let _ = self.pm.report_existing_thread_create(t);
        PM_GENERAL_THREADS_CREATED.fetch_add(1, Ordering::Relaxed);
        Some((slot, tid, h as u64))
    }

    fn next_role_owned_local_thread_spec(&self) -> Option<RoleOwnedLocalThreadSpec> {
        let process_role = self.current_hosted_process_role()?;
        for spec in ROLE_OWNED_LOCAL_THREAD_SPECS {
            if spec.owner_role != process_role {
                continue;
            }
            if spec
                .creator_role
                .is_some_and(|role| !self.current_thread_has_role(role))
            {
                continue;
            }
            if spec
                .previous_role
                .is_some_and(|role| self.hosted_thread_tid_for_role(self.pi, role).is_none())
            {
                continue;
            }
            if self
                .hosted_thread_tid_for_role(self.pi, spec.role)
                .is_none()
            {
                return Some(spec);
            }
        }
        None
    }

    fn current_rpc_worker_source_spec(&self) -> Option<RpcWorkerSourceSpec> {
        let process_role = self.current_hosted_process_role()?;
        for spec in RPC_WORKER_SOURCE_SPECS {
            if spec.requires_lsa_worker_route && !crate::LSA_WORKER_ROUTE_ENABLED {
                continue;
            }
            if spec.owner_role != process_role {
                continue;
            }
            if !self.current_thread_has_role(spec.listener_role) {
                continue;
            }
            if self
                .hosted_thread_tid_for_role(self.pi, spec.listener_role)
                .is_some()
            {
                return Some(spec);
            }
        }
        None
    }

    unsafe fn create_role_owned_local_thread(
        &mut self,
        args: &[u64],
        spec: RoleOwnedLocalThreadSpec,
    ) -> u32 {
        if args.len() <= NT_CREATE_THREAD_CREATE_SUSPENDED_ARG || args[3] != u64::MAX {
            return STATUS_INVALID_PARAMETER;
        }
        let ctx_va = args[NT_CREATE_THREAD_CONTEXT_ARG];
        let start =
            nt_thread_start::Amd64ThreadContext::read(|address| smss_stack_read(address), ctx_va);
        let initial_teb_va = args[NT_CREATE_THREAD_INITIAL_TEB_ARG];
        if initial_teb_va == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let initial_teb =
            nt_thread_start::InitialTeb64::read(|address| smss_stack_read(address), initial_teb_va);
        let create_suspended = nt_boolean_arg(args[NT_CREATE_THREAD_CREATE_SUSPENDED_ARG]);
        let Some((slot, tid, handle)) =
            self.nt_create_thread_handle(start.rip, create_suspended, nt_ulong_arg(args[1]))
        else {
            return STATUS_INSUFFICIENT_RESOURCES;
        };
        if !self.reserve_created_hosted_thread_role(slot, tid, handle, spec.badge, spec.role) {
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        self.pm
            .set_thread_teb(tid as nt_process::ThreadId, spec.teb);
        let pid = self.current_pm_pid().unwrap_or(0);
        self.queue_write(args[0], handle);
        let cid_ptr = args[NT_CREATE_THREAD_CLIENT_ID_ARG];
        if cid_ptr != 0 {
            self.queue_write(cid_ptr, pid as u64);
            self.queue_write(cid_ptr + 8, tid);
        }
        self.thread_spawn_request = Some(HostedThreadSpawnRequest::Multiplexed {
            kind: spec.spawn_kind,
            start,
            initial_teb,
        });
        self.trace_role_owned_local_thread_create(args, spec, start, handle, tid);
        0
    }

    unsafe fn trace_role_owned_local_thread_create(
        &self,
        args: &[u64],
        spec: RoleOwnedLocalThreadSpec,
        start: nt_thread_start::Amd64ThreadContext,
        handle: u64,
        tid: u64,
    ) {
        if spec.owner_role != nt_exe_image::HostedProcessRole::LocalSecurityAuthority
            && spec.trace != RoleOwnedLocalThreadTrace::LsassThird
        {
            return;
        }
        let initial_teb = args[NT_CREATE_THREAD_INITIAL_TEB_ARG];
        let create_suspended = nt_boolean_arg(args[NT_CREATE_THREAD_CREATE_SUSPENDED_ARG]);
        let slot = match spec.spawn_kind {
            HostedMultiplexedThreadKind::LsassListener { slot } => slot,
            _ => usize::MAX,
        };
        print_str(b"[thread-life] create caller=lsass badge=8 process=0x");
        print_hex_u64(args[3]);
        print_str(b" slot=");
        print_u64(slot as u64);
        print_str(b" start=0x");
        print_hex_u64(start.rip);
        print_str(b" arg0=0x");
        print_hex_u64(start.rcx);
        print_str(b" arg1=0x");
        print_hex_u64(start.rdx);
        print_str(b" rsp=0x");
        print_hex_u64(start.rsp);
        print_str(b" teb=0x");
        print_hex_u64(spec.teb);
        print_str(b" initial_teb=0x");
        print_hex_u64(initial_teb);
        if initial_teb != 0 {
            print_str(b" stack_base=0x");
            print_hex_u64(smss_stack_read(initial_teb + 0x10));
            print_str(b" stack_limit=0x");
            print_hex_u64(smss_stack_read(initial_teb + 0x18));
            print_str(b" alloc_base=0x");
            print_hex_u64(smss_stack_read(initial_teb + 0x20));
        }
        print_str(b" handle=0x");
        print_hex(handle as u32);
        print_str(b" tid=");
        print_u64(tid);
        print_str(b" suspended=");
        print_u64(create_suspended as u64);
        print_str(b" status=0\n");
    }

    unsafe fn create_generic_local_tp_worker_thread(
        &mut self,
        args: &[u64],
        ntdll_pool_worker_only: bool,
    ) -> Option<u32> {
        if args.len() <= NT_CREATE_THREAD_CREATE_SUSPENDED_ARG
            || args[3] != u64::MAX
            || self.pi >= MAX_PI
        {
            return None;
        }
        let pid = self.pm_pid_for_pi(self.pi)?;
        let ctx_va = args[NT_CREATE_THREAD_CONTEXT_ARG];
        let start =
            nt_thread_start::Amd64ThreadContext::read(|address| smss_stack_read(address), ctx_va);
        let initial_teb_va = args[NT_CREATE_THREAD_INITIAL_TEB_ARG];
        let initial_teb = (initial_teb_va != 0).then(|| {
            nt_thread_start::InitialTeb64::read(|address| smss_stack_read(address), initial_teb_va)
        });
        let scheduler_rva = img_spawn::OUR_TP_WORKER_RVA.load(Ordering::Relaxed);
        let completion_rva = img_spawn::OUR_TP_COMPLETION_WORKER_RVA.load(Ordering::Relaxed);
        let scheduler_entry = NTDLL_BASE.wrapping_add(scheduler_rva);
        let completion_entry = NTDLL_BASE.wrapping_add(completion_rva);

        // Native ntdll starts directly at RtlpWorkerThread. Kernel32's installed hook starts at
        // BaseThreadStartup and carries RtlpWorkerThread in RCX. Prefer the historical low lanes
        // while they are free, but do not pin real NT thread creation to them: rpcrt4 and ntdll can
        // legitimately create more than one worker with the same entry point.
        let preferred_slot = if scheduler_rva != 0
            && (start.rip == scheduler_entry || start.rcx == scheduler_entry)
        {
            Some(0)
        } else if completion_rva != 0
            && (start.rip == completion_entry || start.rcx == completion_entry)
        {
            Some(1)
        } else {
            None
        };
        let create_suspended = nt_boolean_arg(args[NT_CREATE_THREAD_CREATE_SUSPENDED_ARG]);
        if self.pi == 6 {
            let n = EXPLORER_TP_CREATE_TRACE_N.fetch_add(1, Ordering::Relaxed);
            if n < 96 {
                print_str(b"[explorer-tp-create] ntdll_only=");
                print_u64(ntdll_pool_worker_only as u64);
                print_str(b" ctx=0x");
                print_hex_u64(ctx_va);
                print_str(b" rip=0x");
                print_hex_u64(start.rip);
                print_str(b" rcx=0x");
                print_hex_u64(start.rcx);
                print_str(b" rdx=0x");
                print_hex_u64(start.rdx);
                print_str(b" rsp=0x");
                print_hex_u64(start.rsp);
                print_str(b" initial_teb=0x");
                print_hex_u64(initial_teb_va);
                if let Some(initial_teb) = initial_teb {
                    print_str(b" stack=(");
                    print_hex_u64(initial_teb.stack_base);
                    print_str(b",");
                    print_hex_u64(initial_teb.stack_limit);
                    print_str(b",");
                    print_hex_u64(initial_teb.allocated_stack_base);
                    print_str(b")");
                }
                print_str(b" preferred=");
                match preferred_slot {
                    Some(slot) => print_u64(slot as u64),
                    None => print_str(b"-"),
                }
                print_str(b" suspended=");
                print_u64(create_suspended as u64);
                print_str(b"\n");
            }
        }
        if ntdll_pool_worker_only && preferred_slot.is_none() {
            return None;
        }
        let rpc_worker_source = if !ntdll_pool_worker_only && preferred_slot.is_none() {
            self.current_rpc_worker_source_spec()
        } else {
            None
        };
        if let Some(spec) = rpc_worker_source {
            if let Some(counter) = spec.request_counter {
                counter.fetch_add(1, Ordering::Relaxed);
            }
        }
        let preferred_slot_free = preferred_slot.and_then(|slot| {
            Self::tp_worker_slot_bit(slot)
                .filter(|bit| self.hosted_tp_worker_window_mask(self.pi) & *bit == 0)
                .map(|_| slot)
        });
        let tp_slot = preferred_slot_free.or_else(|| {
            let slot = self.first_free_hosted_tp_worker_slot(self.pi);
            if let Some(spec) = rpc_worker_source {
                if let Some(counter) = spec.slot_claim_counter {
                    counter.fetch_add(1, Ordering::Relaxed);
                }
                print_str(spec.claim_trace_prefix);
                print_str(if slot.is_some() {
                    b"claiming dynamic worker slot\n"
                } else {
                    b"no free dynamic worker slot\n"
                });
            }
            if preferred_slot.is_some() && slot.is_some() {
                let trace = TP_WORKER_PREFERRED_BUSY_TRACE_N.fetch_add(1, Ordering::Relaxed);
                if trace < 8 {
                    print_str(b"[tp-worker] preferred lane busy pi=");
                    print_u64(self.pi as u64);
                    print_str(b" preferred=");
                    print_u64(preferred_slot.unwrap_or(usize::MAX) as u64);
                    print_str(b" claimed=");
                    print_u64(slot.unwrap_or(usize::MAX) as u64);
                    print_str(b" windows-used=0x");
                    print_hex(self.hosted_tp_worker_window_mask(self.pi) as u32);
                    print_str(b"\n");
                }
            }
            slot
        });
        let Some(tp_slot) = tp_slot else {
            print_str(b"[tp-worker] no free local worker slot pi=");
            print_u64(self.pi as u64);
            print_str(b" pid=");
            print_u64(pid as u64);
            print_str(b" windows-used=0x");
            print_hex(self.hosted_tp_worker_window_mask(self.pi) as u32);
            print_str(b" pool-used=0x");
            print_hex(self.pool_used_mask(self.pi) as u32);
            print_str(b" slots=");
            print_u64(TP_WORKER_SLOT_COUNT as u64);
            if let Some(slot) = preferred_slot {
                print_str(b" preferred=");
                print_u64(slot as u64);
            }
            print_str(b" entry=0x");
            print_hex((start.rip >> 32) as u32);
            print_hex(start.rip as u32);
            print_str(b"\n");
            return Some(0xC000_009A);
        };
        let hosted_role = rpc_worker_source
            .map(|spec| spec.worker_kind.worker_role(tp_slot))
            .unwrap_or(HostedThreadRole::TpWorker { slot: tp_slot });

        let Some((pool_slot, tid, handle)) =
            self.nt_create_thread_handle(start.rip, create_suspended, nt_ulong_arg(args[1]))
        else {
            return Some(0xC000_009A);
        };
        if !self.reserve_hosted_worker_window_slot(self.pi, tp_slot, tid, hosted_role) {
            self.abandon_created_hosted_thread(pool_slot, tid, handle);
            return Some(0xC000_009A);
        }
        if let Some(initial_teb) = initial_teb {
            let _ = self.remember_hosted_thread_user_stack(tid, initial_teb);
        }
        self.pm
            .set_thread_teb(tid as nt_process::ThreadId, tp_worker_teb_va(tp_slot));
        self.queue_write(args[0], handle);
        let cid_ptr = args[NT_CREATE_THREAD_CLIENT_ID_ARG];
        if cid_ptr != 0 {
            self.queue_write(cid_ptr, pid as u64);
            self.queue_write(cid_ptr + 8, tid);
        }
        self.thread_spawn_request = Some(HostedThreadSpawnRequest::TpWorker {
            pi: self.pi,
            slot: tp_slot,
            start,
        });
        print_str(b"[tp-worker] claimed pi=");
        print_u64(self.pi as u64);
        print_str(b" badge=");
        print_u64(tp_worker_badge(self.pi, tp_slot));
        print_str(b" tid=");
        print_u64(tid);
        print_str(b" entry=0x");
        print_hex((start.rip >> 32) as u32);
        print_hex(start.rip as u32);
        print_str(b" suspended=");
        print_u64(create_suspended as u64);
        if let Some(kind) = hosted_role.rpc_worker_kind() {
            print_str(b" role=");
            print_str(kind.trace_role());
        }
        if tp_slot != 0 {
            print_str(b" slot=");
            print_u64(tp_slot as u64);
        }
        print_str(b"\n");
        Some(0)
    }

    /// Bind a hosted process's MAIN THREAD to its real image entry at the actual seL4 spawn — the
    /// "route NtCreateThread through pm at real spawn time" step (the thread object was pre-created
    /// at boot for the non-leaking heap solution; this alloc-free field write completes it).
    pub(crate) fn bind_main_thread_entry(&mut self, pi: usize, entry: u64) {
        if let Some(tid) = self.pm_main_tid_for_pi(pi) {
            if self.pm.set_thread_start_address(tid, entry) {
                let _ = self.pm.set_thread_teb(tid, SMSS_TEB_VA);
                let _ = self
                    .pm
                    .set_thread_create_time(tid, nt_system_time_100ns() as i64);
                PM_THREAD_BINDS.fetch_add(1, Ordering::Relaxed);
            }
        }
    }
    /// Apply native `NtOpenProcess` selector and access policy after the caller structures have
    /// been captured from its address space. Publication of the returned handle remains the
    /// caller's responsibility so copyout can be transactional.
    pub(crate) fn open_process_captured(
        &mut self,
        object_attributes: nt_ntdll_layout::ObjectAttributes,
        client_id: Option<nt_ntdll_layout::ClientId>,
        desired_access: u32,
    ) -> Result<(nt_process::ProcessId, nt_process::Handle), u32> {
        const STATUS_INVALID_PARAMETER_MIX: u32 = 0xC000_0030;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        let has_name = object_attributes.object_name != 0;
        if has_name && client_id.is_some() || !has_name && client_id.is_none() {
            return Err(STATUS_INVALID_PARAMETER_MIX);
        }
        if has_name {
            // EPROCESS objects are not yet registered in the object-manager namespace.
            return Err(STATUS_OBJECT_NAME_NOT_FOUND);
        }
        let client_id = client_id.unwrap();
        let client_id = nt_process::process_client_id_from_native(
            client_id.unique_process,
            client_id.unique_thread,
        )?;
        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        if self.pm.process(caller_pid).is_none() {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        }
        let target_pid = if client_id.unique_thread != 0 {
            let thread = self
                .pm
                .thread(client_id.unique_thread)
                .ok_or(nt_process::STATUS_INVALID_CID)?;
            if thread.process_id != client_id.unique_process {
                return Err(nt_process::STATUS_INVALID_CID);
            }
            thread.process_id
        } else {
            self.pm
                .process(client_id.unique_process)
                .ok_or(nt_process::STATUS_INVALID_PARAMETER)?;
            client_id.unique_process
        };
        let handle = self.insert_process_handle(
            caller_pid,
            nt_process::HandleObject::Process(target_pid),
            nt_process::map_process_access(desired_access),
        )?;
        Ok((caller_pid, handle))
    }

    unsafe fn capture_object_attributes(
        &self,
        address: u64,
    ) -> Option<nt_ntdll_layout::ObjectAttributes> {
        let mut value = core::mem::MaybeUninit::<nt_ntdll_layout::ObjectAttributes>::uninit();
        let bytes = core::slice::from_raw_parts_mut(
            value.as_mut_ptr().cast::<u8>(),
            core::mem::size_of::<nt_ntdll_layout::ObjectAttributes>(),
        );
        self.xas_read(address, bytes).then(|| value.assume_init())
    }

    unsafe fn capture_client_id(&self, address: u64) -> Option<nt_ntdll_layout::ClientId> {
        let mut value = core::mem::MaybeUninit::<nt_ntdll_layout::ClientId>::uninit();
        let bytes = core::slice::from_raw_parts_mut(
            value.as_mut_ptr().cast::<u8>(),
            core::mem::size_of::<nt_ntdll_layout::ClientId>(),
        );
        self.xas_read(address, bytes).then(|| value.assume_init())
    }

    unsafe fn nt_open_process(
        &mut self,
        process_handle: u64,
        desired_access: u32,
        object_attributes: u64,
        client_id: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        if !self.probe_user_output(process_handle, core::mem::size_of::<u64>()) {
            return STATUS_ACCESS_VIOLATION;
        }
        let client_id = if client_id == 0 {
            None
        } else {
            if client_id & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            let Some(client_id) = self.capture_client_id(client_id) else {
                return STATUS_ACCESS_VIOLATION;
            };
            Some(client_id)
        };
        if object_attributes & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let Some(object_attributes) = self.capture_object_attributes(object_attributes) else {
            return STATUS_ACCESS_VIOLATION;
        };
        let (owner, handle) =
            match self.open_process_captured(object_attributes, client_id, desired_access) {
                Ok(opened) => opened,
                Err(status) => return status,
            };
        if !self.xas_write_u64(process_handle, handle as u64) {
            let _ = self.pm.take_handle(owner, handle);
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    /// Apply native `NtOpenThread` selector and access policy after capturing the caller inputs.
    pub(crate) fn open_thread_captured(
        &mut self,
        object_attributes: nt_ntdll_layout::ObjectAttributes,
        client_id: Option<nt_ntdll_layout::ClientId>,
        desired_access: u32,
    ) -> Result<(nt_process::ProcessId, nt_process::Handle), u32> {
        const STATUS_INVALID_PARAMETER_MIX: u32 = 0xC000_0030;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        let has_name = object_attributes.object_name != 0;
        if has_name && client_id.is_some() || !has_name && client_id.is_none() {
            return Err(STATUS_INVALID_PARAMETER_MIX);
        }
        if has_name {
            // ETHREAD objects are not yet registered in the object-manager namespace.
            return Err(STATUS_OBJECT_NAME_NOT_FOUND);
        }
        let client_id = client_id.unwrap();
        let client_id = nt_process::thread_client_id_from_native(
            client_id.unique_process,
            client_id.unique_thread,
        )?;
        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        if self.pm.process(caller_pid).is_none() {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        }
        let missing_status = if client_id.unique_process == 0 {
            nt_process::STATUS_INVALID_PARAMETER
        } else {
            nt_process::STATUS_INVALID_CID
        };
        let thread = self
            .pm
            .thread(client_id.unique_thread)
            .ok_or(missing_status)?;
        if client_id.unique_process != 0 && thread.process_id != client_id.unique_process {
            return Err(nt_process::STATUS_INVALID_CID);
        }
        let handle = self.insert_process_handle(
            caller_pid,
            nt_process::HandleObject::Thread(client_id.unique_thread),
            nt_process::map_thread_access(desired_access),
        )?;
        Ok((caller_pid, handle))
    }

    unsafe fn nt_open_thread(
        &mut self,
        thread_handle: u64,
        desired_access: u32,
        object_attributes: u64,
        client_id: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        if !self.probe_user_output(thread_handle, core::mem::size_of::<u64>()) {
            return STATUS_ACCESS_VIOLATION;
        }
        let client_id = if client_id == 0 {
            None
        } else {
            if client_id & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            let Some(client_id) = self.capture_client_id(client_id) else {
                return STATUS_ACCESS_VIOLATION;
            };
            Some(client_id)
        };
        if object_attributes & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let Some(object_attributes) = self.capture_object_attributes(object_attributes) else {
            return STATUS_ACCESS_VIOLATION;
        };
        let (owner, handle) =
            match self.open_thread_captured(object_attributes, client_id, desired_access) {
                Ok(opened) => opened,
                Err(status) => return status,
            };
        if !self.xas_write_u64(thread_handle, handle as u64) {
            let _ = self.pm.take_handle(owner, handle);
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    pub(crate) fn thread_query_length(information_class: u32) -> Result<usize, u32> {
        match information_class {
            0 => Ok(0x30),
            1 => Ok(0x20),
            9 | 11 => Ok(8),
            12 | 14 | 16 | 18 | 20 => Ok(4),
            17 => Ok(1),
            _ => Err(nt_process::STATUS_INVALID_INFO_CLASS),
        }
    }

    pub(crate) fn thread_set_length(information_class: u32) -> Result<usize, u32> {
        match information_class {
            2 | 3 | 10 => Ok(4),
            4 | 13 => Ok(8),
            9 | 14 => Ok(8),
            17 => Ok(0),
            18 => Ok(4),
            38 => Ok(0x10),
            _ => Err(nt_process::STATUS_INVALID_INFO_CLASS),
        }
    }

    pub(crate) fn set_thread_information_captured(
        &mut self,
        handle: u64,
        information_class: u32,
        value: u64,
    ) -> u32 {
        if information_class == 18 && !self.current_token_has_privilege(nt_security::SE_DEBUG) {
            return 0xC000_0061;
        }
        const THREAD_SET_INFORMATION: u32 = 0x0020;
        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let tid = match self.pm.resolve_thread_handle(
            caller,
            self.current_tid as nt_process::ThreadId,
            handle,
            THREAD_SET_INFORMATION,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        let update = match information_class {
            2 => {
                let priority = value as u32 as i32;
                if priority >= nt_process::LOW_REALTIME_PRIORITY
                    && !self.current_token_has_privilege(nt_security::SE_INCREASE_BASE_PRIORITY)
                {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.pm.set_thread_priority(tid, priority)
            }
            3 => self.pm.set_thread_base_priority(tid, value as u32 as i32),
            4 => self.pm.set_thread_affinity_mask(tid, value),
            9 => self.pm.set_thread_win32_start_address(tid, value),
            13 => {
                let update = self.pm.set_thread_ideal_processor(tid, value);
                if update.is_ok() {
                    if let Some(teb) = self.pm.thread_teb(tid).filter(|teb| *teb != 0) {
                        let ideal = [value as u8];
                        if unsafe {
                            !self.xas_try_write_buf(
                                teb + nt_ntdll_layout::TEB_IDEAL_PROCESSOR_OFFSET,
                                &ideal,
                            )
                        } {
                            return STATUS_ACCESS_VIOLATION;
                        }
                    }
                }
                update
            }
            14 => self.pm.set_thread_disable_boost(tid, value != 0),
            17 => self.pm.set_thread_hide_from_debugger(tid),
            18 => self
                .pm
                .set_thread_break_on_termination(tid, value as u32 != 0),
            _ => return nt_process::STATUS_INVALID_INFO_CLASS,
        };
        update.map_or_else(|status| status, |()| 0)
    }

    fn resolve_thread_for_set(&self, handle: u64) -> Result<nt_process::ThreadId, u32> {
        const THREAD_SET_INFORMATION: u32 = 0x0020;
        let caller = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        self.pm.resolve_thread_handle(
            caller,
            self.current_tid as nt_process::ThreadId,
            handle,
            THREAD_SET_INFORMATION,
        )
    }

    unsafe fn nt_set_thread_name(
        &mut self,
        handle: u64,
        information: u64,
        information_length: u32,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        if information_length != 0x10 {
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if information & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let mut descriptor = [0u8; 0x10];
        if information == 0 || !self.xas_read(information, &mut descriptor) {
            return STATUS_ACCESS_VIOLATION;
        }
        let raw_byte_length = u16::from_le_bytes(descriptor[0..2].try_into().unwrap()) as usize;
        let byte_length = raw_byte_length & !1;
        let buffer = u64::from_le_bytes(descriptor[8..16].try_into().unwrap());

        let tid = match self.resolve_thread_for_set(handle) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        if buffer == 0 {
            return self
                .pm
                .set_thread_name(tid, &[])
                .map_or_else(|status| status, |()| 0);
        }
        if raw_byte_length != 0 && buffer & 1 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if !self.probe_user_input(buffer, raw_byte_length) {
            return STATUS_ACCESS_VIOLATION;
        }
        if byte_length == 0 {
            return self
                .pm
                .set_thread_name(tid, &[])
                .map_or_else(|status| status, |()| 0);
        }
        if byte_length > nt_process::THREAD_NAME_MAX_UNITS * 2 {
            return 0xC000_009A;
        }
        let mut bytes = [0u8; nt_process::THREAD_NAME_MAX_UNITS * 2];
        if !self.xas_read(buffer, &mut bytes[..byte_length]) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut name = [0u16; nt_process::THREAD_NAME_MAX_UNITS];
        for (index, chunk) in bytes[..byte_length].chunks_exact(2).enumerate() {
            name[index] = u16::from_le_bytes([chunk[0], chunk[1]]);
        }
        self.pm
            .set_thread_name(tid, &name[..byte_length / 2])
            .map_or_else(|status| status, |()| 0)
    }

    unsafe fn nt_set_thread_zero_tls_cell(
        &mut self,
        handle: u64,
        information: u64,
        information_length: u32,
    ) -> u32 {
        const THREAD_SET_INFORMATION: u32 = 0x0020;
        const TLS_MINIMUM_AVAILABLE: u32 = 64;
        const TLS_EXPANSION_SLOTS: u32 = 1024;
        const TEB_CAPTURE_LIMIT: usize = 1 + PM_RUNTIME_THREAD_SLOTS;

        if information_length != 4 {
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if information & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let mut encoded = [0u8; 4];
        if information == 0 || !self.xas_read(information, &mut encoded) {
            return STATUS_ACCESS_VIOLATION;
        }
        let tls_index = u32::from_le_bytes(encoded);

        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let current_tid = self.current_tid as nt_process::ThreadId;
        let tid =
            match self
                .pm
                .resolve_thread_handle(caller, current_tid, handle, THREAD_SET_INFORMATION)
            {
                Ok(tid) => tid,
                Err(status) => return status,
            };
        if tid != current_tid {
            return STATUS_INVALID_PARAMETER;
        }
        let process_id = match self.pm.thread(tid).map(|thread| thread.process_id) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };

        let mut tebs = [0u64; TEB_CAPTURE_LIMIT];
        let mut count = 0usize;
        let mut overflow = false;
        if let Err(status) = self.pm.for_each_process_thread_teb(process_id, |_, teb| {
            if count < tebs.len() {
                tebs[count] = teb;
                count += 1;
            } else {
                overflow = true;
            }
        }) {
            return status;
        }
        if overflow {
            return STATUS_INSUFFICIENT_RESOURCES;
        }

        for teb in tebs[..count].iter().copied() {
            if tls_index < TLS_MINIMUM_AVAILABLE {
                let slot = teb
                    + nt_ntdll_layout::TEB_TLS_SLOTS_OFFSET
                    + u64::from(tls_index) * core::mem::size_of::<u64>() as u64;
                if !self.xas_write_u64(slot, 0) {
                    return STATUS_ACCESS_VIOLATION;
                }
            } else if tls_index < TLS_MINIMUM_AVAILABLE + TLS_EXPANSION_SLOTS {
                let mut expansion = [0u8; 8];
                let expansion_slots = teb + nt_ntdll_layout::TEB_TLS_EXPANSION_SLOTS_OFFSET;
                if !self.xas_read(expansion_slots, &mut expansion) {
                    return STATUS_ACCESS_VIOLATION;
                }
                let expansion_slots = u64::from_le_bytes(expansion);
                if expansion_slots != 0 {
                    let slot = expansion_slots
                        + u64::from(tls_index - TLS_MINIMUM_AVAILABLE)
                            * core::mem::size_of::<u64>() as u64;
                    if !self.xas_write_u64(slot, 0) {
                        return STATUS_ACCESS_VIOLATION;
                    }
                }
            }
        }

        0
    }

    pub(crate) fn query_thread_information_captured(
        &self,
        handle: u64,
        information_class: u32,
    ) -> Result<([u8; 0x30], usize), u32> {
        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let current_tid = self.current_tid as nt_process::ThreadId;
        let mut output = [0u8; 0x30];
        let length = match information_class {
            0 => {
                let basic = self
                    .pm
                    .query_thread_basic(caller_pid, current_tid, handle)?;
                let teb = if basic.teb_base_address != 0 {
                    basic.teb_base_address
                } else if self.current_process_is_smss() {
                    SMSS_TEB_VA
                } else {
                    TEB_VA
                };
                output[0..4].copy_from_slice(&basic.exit_status.to_le_bytes());
                output[8..16].copy_from_slice(&teb.to_le_bytes());
                output[0x10..0x18]
                    .copy_from_slice(&(basic.client_id.unique_process as u64).to_le_bytes());
                output[0x18..0x20]
                    .copy_from_slice(&(basic.client_id.unique_thread as u64).to_le_bytes());
                output[0x20..0x28].copy_from_slice(&basic.affinity_mask.to_le_bytes());
                output[0x28..0x2C].copy_from_slice(&basic.priority.to_le_bytes());
                output[0x2C..0x30].copy_from_slice(&basic.base_priority.to_le_bytes());
                0x30
            }
            1 => {
                let times = self
                    .pm
                    .query_thread_times(caller_pid, current_tid, handle)?;
                for (index, value) in [
                    times.create_time,
                    times.exit_time,
                    times.kernel_time,
                    times.user_time,
                ]
                .iter()
                .enumerate()
                {
                    output[index * 8..index * 8 + 8].copy_from_slice(&value.to_le_bytes());
                }
                0x20
            }
            9 | 11 => {
                let start_address =
                    self.pm
                        .thread_start_address(caller_pid, current_tid, handle)?;
                let value = if information_class == 9 {
                    start_address
                } else {
                    0
                };
                output[..8].copy_from_slice(&value.to_le_bytes());
                8
            }
            12 | 14 | 18 | 20 => {
                let value =
                    self.pm
                        .query_thread_u32(caller_pid, current_tid, handle, information_class)?;
                output[..4].copy_from_slice(&value.to_le_bytes());
                4
            }
            16 => {
                const THREAD_QUERY_INFORMATION: u32 = 0x0040;
                let tid = self.pm.resolve_thread_handle(
                    caller_pid,
                    current_tid,
                    handle,
                    THREAD_QUERY_INFORMATION,
                )?;
                let pending =
                    unsafe { (&*core::ptr::addr_of!(PENDING_FILE_IO)).has_thread(tid as u64) };
                output[..4].copy_from_slice(&(pending as u32).to_le_bytes());
                4
            }
            17 => {
                let value =
                    self.pm
                        .query_thread_u32(caller_pid, current_tid, handle, information_class)?;
                output[0] = value as u8;
                1
            }
            _ => return Err(nt_process::STATUS_INVALID_INFO_CLASS),
        };
        Ok((output, length))
    }

    pub(crate) fn query_thread_name_captured(
        &self,
        handle: u64,
        name: &mut [u16; nt_process::THREAD_NAME_MAX_UNITS],
    ) -> Result<usize, u32> {
        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        self.pm.query_thread_name(
            caller_pid,
            self.current_tid as nt_process::ThreadId,
            handle,
            name,
        )
    }

    unsafe fn nt_query_thread_name(
        &self,
        handle: u64,
        information: u64,
        information_length: u32,
        return_length: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const STATUS_BUFFER_TOO_SMALL: u32 = 0xC000_0023;
        if information != 0 {
            if information & 7 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            if !self.probe_user_output(information, information_length as usize) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        if return_length != 0 && !self.probe_user_output(return_length, 4) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut name = [0u16; nt_process::THREAD_NAME_MAX_UNITS];
        let mut required = 0u32;
        let mut status = match self.query_thread_name_captured(handle, &mut name) {
            Ok(units) => {
                required = (0x10 + units * 2) as u32;
                if information_length < required {
                    STATUS_BUFFER_TOO_SMALL
                } else {
                    let mut output = [0u8; 0x10 + nt_process::THREAD_NAME_MAX_UNITS * 2];
                    if units != 0 {
                        let byte_length = (units * 2) as u16;
                        output[0..2].copy_from_slice(&byte_length.to_le_bytes());
                        output[2..4].copy_from_slice(&byte_length.to_le_bytes());
                        output[8..16]
                            .copy_from_slice(&information.wrapping_add(0x10).to_le_bytes());
                        for (index, unit) in name[..units].iter().enumerate() {
                            output[0x10 + index * 2..0x12 + index * 2]
                                .copy_from_slice(&unit.to_le_bytes());
                        }
                    }
                    if self.xas_try_write_buf(information, &output[..required as usize]) {
                        0
                    } else {
                        STATUS_ACCESS_VIOLATION
                    }
                }
            }
            Err(status) => status,
        };
        if return_length != 0 && !self.xas_write_u32(return_length, required) {
            status = STATUS_ACCESS_VIOLATION;
        }
        status
    }

    unsafe fn nt_query_information_thread(
        &self,
        handle: u64,
        information_class: u32,
        information: u64,
        information_length: u32,
        return_length: u64,
    ) -> u32 {
        if information_class == 38 {
            return self.nt_query_thread_name(
                handle,
                information,
                information_length,
                return_length,
            );
        }
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        let expected = match Self::thread_query_length(information_class) {
            Ok(length) => length,
            Err(status) => return status,
        };
        if information_length as usize != expected {
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if information != 0 {
            if information & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            let mut probe = [0u8; 0x30];
            if !self.xas_read(information, &mut probe[..expected]) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        if return_length != 0 && !self.probe_user_output(return_length, 4) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut status = match self.query_thread_information_captured(handle, information_class) {
            Ok((output, length)) => {
                if self.xas_try_write_buf(information, &output[..length]) {
                    if information_class == 0 {
                        WL_LISTENER_TEB_QUERIED.fetch_add(1, Ordering::Relaxed);
                    }
                    0
                } else {
                    STATUS_ACCESS_VIOLATION
                }
            }
            Err(status) => status,
        };
        if return_length != 0 && !self.xas_write_u32(return_length, expected as u32) {
            status = STATUS_ACCESS_VIOLATION;
        }
        status
    }

    fn process_query_length(information_class: u32, information_length: u32) -> Result<usize, u32> {
        let exact = |expected: usize| {
            if information_length as usize == expected {
                Ok(expected)
            } else {
                Err(nt_process::STATUS_INFO_LENGTH_MISMATCH)
            }
        };
        match information_class {
            0 => exact(0x30), // PROCESS_BASIC_INFORMATION
            1 => match information_length {
                // QUOTA_LIMITS / QUOTA_LIMITS_EX
                0x30 | 0x58 => Ok(information_length as usize),
                _ => Err(nt_process::STATUS_INFO_LENGTH_MISMATCH),
            },
            2 => exact(0x30), // IO_COUNTERS
            3 => match information_length {
                // VM_COUNTERS / VM_COUNTERS_EX
                0x58 | 0x60 => Ok(information_length as usize),
                _ => Err(nt_process::STATUS_INFO_LENGTH_MISMATCH),
            },
            4 => exact(0x20),  // KERNEL_USER_TIMES
            7 => exact(0x08),  // ProcessDebugPort
            12 => exact(0x04), // ProcessDefaultHardErrorMode
            18 => exact(0x02), // PROCESS_PRIORITY_CLASS
            20 => exact(0x04), // ProcessHandleCount
            23 => exact(0x24), // PROCESS_DEVICEMAP_INFORMATION
            24 => exact(0x04), // PROCESS_SESSION_INFORMATION
            26 => exact(0x08), // ProcessWow64Information
            28 => exact(0x04), // ProcessLUIDDeviceMapsEnabled
            29 => exact(0x04), // ProcessBreakOnTermination
            30 => exact(0x08), // ProcessDebugObjectHandle
            31 => exact(0x04), // ProcessDebugFlags
            33 => exact(0x04), // ProcessIoPriority
            34 => exact(0x04), // ProcessExecuteFlags
            36 => exact(0x04), // ProcessCookie
            37 => exact(0x40), // SECTION_IMAGE_INFORMATION
            38 => exact(0x08), // ProcessCycleTime
            39 => exact(0x04), // ProcessPagePriority
            _ => Err(nt_process::STATUS_INVALID_INFO_CLASS),
        }
    }

    fn process_virtual_footprint(&self, pid: nt_process::ProcessId) -> u64 {
        if self.pm_pid_for_pi(self.pi) == Some(pid) {
            if let Some(ctx) = self.loop_ctx {
                return ctx.img_end.saturating_sub(PE_LOAD_BASE).max(0x1000);
            }
        }
        let section = self
            .pm
            .process(pid)
            .and_then(|process| process.image_section)
            .and_then(|section| self.pm.image_section(section));
        section
            .map(|section| section.size_of_image() as u64)
            .unwrap_or(0x1000)
            .max(0x1000)
    }

    unsafe fn current_process_image_information(&self) -> Option<[u8; 0x40]> {
        let ctx = self.loop_ctx?;
        if ctx.pe.is_null() {
            return None;
        }
        let pe = &*ctx.pe;
        let metadata = image_metadata_from_pe(pe, PE_LOAD_BASE);
        let mut info = nt_dll_registry::image_info(
            PE_LOAD_BASE,
            metadata.entry_rva,
            metadata.image_size as u32,
            false,
        );
        info[0x20..0x24].copy_from_slice(&(metadata.subsystem as u32).to_le_bytes());
        info[0x24..0x26].copy_from_slice(&metadata.subsystem_minor.to_le_bytes());
        info[0x26..0x28].copy_from_slice(&metadata.subsystem_major.to_le_bytes());
        Some(info)
    }

    fn process_image_name_units(
        &self,
        pid: nt_process::ProcessId,
        win32_path: bool,
        out: &mut [u16],
    ) -> usize {
        let Some(process) = self.pm.process(pid) else {
            return 0;
        };
        let hosted = self
            .pi_for_pid(pid)
            .and_then(|pi| self.hosted_process_image(pi));
        let system32 = hosted
            .map(|image| image.image_root == nt_exe_image::HostedImageRoot::System32)
            .unwrap_or(true);
        let prefix = if win32_path {
            if system32 {
                b"C:\\ReactOS\\System32\\" as &[u8]
            } else {
                b"C:\\ReactOS\\"
            }
        } else if system32 {
            b"\\Device\\Harddisk0\\Partition1\\reactos\\system32\\" as &[u8]
        } else {
            b"\\Device\\Harddisk0\\Partition1\\reactos\\" as &[u8]
        };
        let mut n = 0usize;
        for &byte in prefix.iter().chain(process.image_file_name.as_bytes()) {
            if n == out.len() {
                break;
            }
            out[n] = byte as u16;
            n += 1;
        }
        n
    }

    unsafe fn nt_query_process_image_name(
        &self,
        handle: u64,
        information_class: u32,
        information: u64,
        information_length: u32,
        return_length: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const UNICODE_STRING_SIZE: usize = 0x10;
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let pid = match self.pm.resolve_process_handle(
            caller_pid,
            handle,
            nt_process::PROCESS_QUERY_INFORMATION,
        ) {
            Ok(pid) => pid,
            Err(status) => return status,
        };
        let mut units = [0u16; 300];
        let units_len = self.process_image_name_units(pid, information_class == 43, &mut units);
        let byte_len = (units_len * 2) as u16;
        let max_len = byte_len.saturating_add(2);
        let required = UNICODE_STRING_SIZE + max_len as usize;
        if return_length != 0 && !self.probe_user_output(return_length, 4) {
            return STATUS_ACCESS_VIOLATION;
        }
        if (information_length as usize) < required {
            if return_length != 0 {
                let _ = self.xas_write_u32(return_length, required as u32);
            }
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if information == 0 || information & 1 != 0 {
            return if information & 1 != 0 {
                STATUS_DATATYPE_MISALIGNMENT
            } else {
                STATUS_ACCESS_VIOLATION
            };
        }
        if !self.probe_user_output(information, required) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut output = [0u8; UNICODE_STRING_SIZE + 300 * 2 + 2];
        output[0..2].copy_from_slice(&byte_len.to_le_bytes());
        output[2..4].copy_from_slice(&max_len.to_le_bytes());
        output[8..16].copy_from_slice(&information.wrapping_add(0x10).to_le_bytes());
        for (index, unit) in units[..units_len].iter().enumerate() {
            let off = UNICODE_STRING_SIZE + index * 2;
            output[off..off + 2].copy_from_slice(&unit.to_le_bytes());
        }
        let mut status = if self.xas_try_write_buf(information, &output[..required]) {
            0
        } else {
            STATUS_ACCESS_VIOLATION
        };
        if return_length != 0 && !self.xas_write_u32(return_length, required as u32) {
            status = STATUS_ACCESS_VIOLATION;
        }
        status
    }

    unsafe fn query_process_information_captured(
        &mut self,
        handle: u64,
        information_class: u32,
        information_length: usize,
    ) -> Result<([u8; 0x60], usize, Option<nt_process::Handle>), u32> {
        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let mut output = [0u8; 0x60];
        let mut published_handle = None;
        fn put_u32(output: &mut [u8], off: usize, value: u32) {
            output[off..off + 4].copy_from_slice(&value.to_le_bytes());
        }
        fn put_i32(output: &mut [u8], off: usize, value: i32) {
            output[off..off + 4].copy_from_slice(&value.to_le_bytes());
        }
        fn put_u64(output: &mut [u8], off: usize, value: u64) {
            output[off..off + 8].copy_from_slice(&value.to_le_bytes());
        }
        fn put_i64(output: &mut [u8], off: usize, value: i64) {
            output[off..off + 8].copy_from_slice(&value.to_le_bytes());
        }

        let length = match information_class {
            0 => {
                let basic = self.pm.query_process_basic(caller_pid, handle)?;
                put_u32(&mut output, 0, basic.exit_status);
                put_u64(&mut output, 8, basic.peb_base_address);
                put_u64(&mut output, 0x10, basic.affinity_mask);
                put_i32(&mut output, 0x18, basic.base_priority);
                put_u64(&mut output, 0x20, basic.unique_process_id as u64);
                put_u64(
                    &mut output,
                    0x28,
                    basic.inherited_from_unique_process_id as u64,
                );
                0x30
            }
            1 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                put_u64(&mut output, 0x10, 204_800);
                put_u64(&mut output, 0x18, 1_413_120);
                put_u64(&mut output, 0x20, u64::MAX);
                put_u64(&mut output, 0x28, u64::MAX);
                if information_length == 0x58 {
                    put_u64(&mut output, 0x30, 0);
                    put_u64(&mut output, 0x38, 0);
                    put_u64(&mut output, 0x40, 0);
                    put_u64(&mut output, 0x48, 0);
                    put_u32(&mut output, 0x50, 0);
                    put_u32(&mut output, 0x54, 0);
                }
                information_length
            }
            2 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                0x30
            }
            3 => {
                let pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                let virtual_size = self.process_virtual_footprint(pid);
                let working_set = virtual_size.max(0x4000);
                put_u64(&mut output, 0x00, virtual_size);
                put_u64(&mut output, 0x08, virtual_size);
                put_u32(&mut output, 0x10, 0);
                put_u64(&mut output, 0x18, working_set);
                put_u64(&mut output, 0x20, working_set);
                put_u64(&mut output, 0x48, virtual_size);
                put_u64(&mut output, 0x50, virtual_size);
                if information_length == 0x60 {
                    put_u64(&mut output, 0x58, virtual_size);
                }
                information_length
            }
            4 => {
                let times = self.pm.query_process_times(caller_pid, handle)?;
                put_i64(&mut output, 0x00, times.create_time);
                put_i64(&mut output, 0x08, times.exit_time);
                put_i64(&mut output, 0x10, times.kernel_time);
                put_i64(&mut output, 0x18, times.user_time);
                0x20
            }
            7 => {
                let value = self.pm.query_process_debug_port(caller_pid, handle)?;
                put_u64(&mut output, 0, value);
                0x08
            }
            12 => {
                let pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                let mode = self
                    .pm
                    .process_default_hard_error_processing(pid)
                    .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
                put_u32(&mut output, 0, mode);
                0x04
            }
            18 => {
                let priority = self.pm.query_process_priority_class(caller_pid, handle)?;
                output[0] = self.pm.query_process_foreground(caller_pid, handle)? as u8;
                output[1] = priority;
                0x02
            }
            20 => {
                put_u32(
                    &mut output,
                    0,
                    self.pm.query_process_handle_count(caller_pid, handle)?,
                );
                0x04
            }
            23 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                let (drive_map, drive_type) = nt_fs::MountManager::new().process_device_map();
                put_u32(&mut output, 0, drive_map);
                output[4..0x24].copy_from_slice(&drive_type);
                0x24
            }
            24 => {
                let session_id = self.pm.query_process_session_id(caller_pid, handle)?;
                put_u32(&mut output, 0, session_id);
                0x04
            }
            26 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                put_u64(&mut output, 0, 0);
                0x08
            }
            28 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                put_u32(&mut output, 0, 0);
                0x04
            }
            29 => {
                let pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                let enabled = self
                    .pm
                    .process_break_on_termination(pid)
                    .ok_or(nt_process::STATUS_INVALID_HANDLE)? as u32;
                put_u32(&mut output, 0, enabled);
                0x04
            }
            30 => {
                let pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                let Some(object) = self.pm.process_debug_port(pid) else {
                    return Err(nt_process::dbgk::STATUS_PORT_NOT_SET);
                };
                let debug_handle = self.insert_process_handle(
                    caller_pid,
                    nt_process::HandleObject::DebugObject(object),
                    nt_process::dbgk::DEBUG_OBJECT_ALL_ACCESS,
                )?;
                published_handle = Some(debug_handle);
                put_u64(&mut output, 0, debug_handle as u64);
                0x08
            }
            31 => {
                put_u32(
                    &mut output,
                    0,
                    self.pm.query_process_debug_flags(caller_pid, handle)?,
                );
                0x04
            }
            33 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                put_u32(&mut output, 0, 2);
                0x04
            }
            34 => {
                if handle != u64::MAX {
                    return Err(nt_process::STATUS_INVALID_PARAMETER);
                }
                put_u32(&mut output, 0, 0);
                0x04
            }
            36 => {
                if handle != u64::MAX {
                    return Err(nt_process::STATUS_INVALID_PARAMETER);
                }
                let time = nt_system_time_100ns();
                let mut candidate = time as u32
                    ^ (time >> 32) as u32
                    ^ caller_pid
                    ^ self.current_tid as u32
                    ^ (self.pi as u32).wrapping_mul(0x9E37_79B9);
                if candidate == 0 {
                    candidate = 0xBB40_E64E;
                }
                let cookie = self
                    .pm
                    .get_or_initialize_process_cookie(caller_pid, candidate)
                    .ok_or(0xC000_009Au32)?;
                put_u32(&mut output, 0, cookie);
                0x04
            }
            37 => {
                if handle != u64::MAX {
                    return Err(nt_process::STATUS_INVALID_PARAMETER);
                }
                let Some(info) = self.current_process_image_information() else {
                    return Err(nt_process::STATUS_INVALID_HANDLE);
                };
                output[..0x40].copy_from_slice(&info);
                0x40
            }
            38 => {
                let times = self.pm.query_process_times(caller_pid, handle)?;
                put_u64(
                    &mut output,
                    0,
                    times.kernel_time.saturating_add(times.user_time) as u64,
                );
                0x08
            }
            39 => {
                let _pid = self.pm.resolve_process_handle(
                    caller_pid,
                    handle,
                    nt_process::PROCESS_QUERY_INFORMATION,
                )?;
                put_u32(&mut output, 0, 5);
                0x04
            }
            _ => return Err(nt_process::STATUS_INVALID_INFO_CLASS),
        };
        Ok((output, length, published_handle))
    }

    unsafe fn nt_query_information_process(
        &mut self,
        handle: u64,
        information_class: u32,
        information: u64,
        information_length: u32,
        return_length: u64,
    ) -> u32 {
        if information_class == 27 || information_class == 43 {
            return self.nt_query_process_image_name(
                handle,
                information_class,
                information,
                information_length,
                return_length,
            );
        }
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        let expected = match Self::process_query_length(information_class, information_length) {
            Ok(length) => length,
            Err(status) => return status,
        };
        if information == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        if information & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if !self.probe_user_output(information, expected) {
            return STATUS_ACCESS_VIOLATION;
        }
        if return_length != 0 && !self.probe_user_output(return_length, 4) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut status =
            match self.query_process_information_captured(handle, information_class, expected) {
                Ok((output, length, published_handle)) => {
                    if self.xas_try_write_buf(information, &output[..length]) {
                        0
                    } else {
                        if let Some(handle) = published_handle {
                            if let Some(caller_pid) = self.pm_pid_for_pi(self.pi) {
                                let _ = self.close_process_handle(caller_pid, handle as u64);
                            }
                        }
                        STATUS_ACCESS_VIOLATION
                    }
                }
                Err(status) => status,
            };
        if return_length != 0 && !self.xas_write_u32(return_length, expected as u32) {
            status = STATUS_ACCESS_VIOLATION;
        }
        status
    }
    /// Resolve a `NtTerminateProcess`/`NtOpenProcess`-style ProcessHandle to the target EPROCESS pid.
    /// `NtCurrentProcess()` (`-1`) → the caller (self-terminate). A real child ProcessHandle is now
    /// resolved via path 1b's value→object index: process handles are dense typed `Process(pid)`
    /// entries in the CALLER's EPROCESS handle table, so `lookup_handle(caller, handle)` returns the
    /// target pid. Returns `None` for an unknown/untyped handle; each syscall maps that to its native
    /// error/fallback behavior.
    pub(crate) fn resolve_process_handle(&self, handle: u64) -> Option<nt_process::ProcessId> {
        let caller = self.pm_pid_for_pi(self.pi)?;
        if handle == 0xFFFF_FFFF_FFFF_FFFF {
            return Some(caller); // NtCurrentProcess()
        }
        // Path 1b: dense process-local handle VALUE → typed Process(pid) object in the caller's table.
        match self.pm.lookup_handle(caller, handle as nt_process::Handle) {
            Some(nt_process::HandleObject::Process(pid)) => Some(pid),
            _ => None,
        }
    }

    fn csr_client_source_pid_for_handle(
        &self,
        handle: nt_process::Handle,
    ) -> Option<nt_process::ProcessId> {
        let client_pid = self.current_server_client_pid;
        if client_pid == 0 {
            return None;
        }
        self.pm
            .lookup_handle(client_pid, handle)
            .is_some()
            .then_some(client_pid)
    }

    fn is_process_security_handle(&self, caller: nt_process::ProcessId, handle: u64) -> bool {
        if handle == u64::MAX {
            return true;
        }
        handle <= u32::MAX as u64
            && matches!(
                self.pm.lookup_handle(caller, handle as nt_process::Handle),
                Some(nt_process::HandleObject::Process(_))
            )
    }

    fn is_thread_security_handle(&self, caller: nt_process::ProcessId, handle: u64) -> bool {
        if handle == u64::MAX - 1 {
            return true;
        }
        handle <= u32::MAX as u64
            && matches!(
                self.pm.lookup_handle(caller, handle as nt_process::Handle),
                Some(nt_process::HandleObject::Thread(_))
            )
    }

    fn pi_for_pid(&self, pid: nt_process::ProcessId) -> Option<usize> {
        self.process_mechanisms
            .pi_for_pid(pid)
            .or_else(|| self.temporary_pi_for_pid(pid))
    }

    pub(crate) fn resolve_process_for_access(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<(nt_process::ProcessId, usize), u32> {
        let caller = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let pid = self
            .pm
            .resolve_process_handle(caller, handle, required_access)?;
        let pi = self
            .pi_for_pid(pid)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        Ok((pid, pi))
    }

    fn resolve_hosted_thread_for_control(
        &self,
        handle: u64,
    ) -> Result<(nt_process::ThreadId, nt_user_host::ThreadMechanism), u32> {
        const THREAD_SUSPEND_RESUME: u32 = 0x0002;

        let caller_pid = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let tid = self.pm.resolve_thread_handle(
            caller_pid,
            self.current_tid as nt_process::ThreadId,
            handle,
            THREAD_SUSPEND_RESUME,
        )?;
        let mechanism = self
            .hosted_thread_mechanism_for_tid(tid as u64)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        Ok((tid, mechanism))
    }

    unsafe fn user_memory_read(&self, memory: SyscallUserMemory, va: u64, dst: &mut [u8]) -> bool {
        match memory {
            SyscallUserMemory::CurrentProcess => self.xas_read(va, dst),
        }
    }

    unsafe fn user_memory_write(&self, memory: SyscallUserMemory, va: u64, src: &[u8]) -> bool {
        match memory {
            SyscallUserMemory::CurrentProcess => self.xas_try_write_buf(va, src),
        }
    }

    unsafe fn user_memory_probe_output(
        &self,
        memory: SyscallUserMemory,
        va: u64,
        len: usize,
    ) -> bool {
        match memory {
            SyscallUserMemory::CurrentProcess => self.probe_user_output(va, len),
        }
    }

    pub(crate) unsafe fn nt_resume_thread_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;

        let thread_handle = args[0];
        let previous_count = args[1];
        if previous_count != 0 && previous_count & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if previous_count != 0 && !self.user_memory_probe_output(memory, previous_count, 4) {
            return STATUS_ACCESS_VIOLATION;
        }
        print_str(b"[thread-life] NtResumeThread pi=");
        print_u64(self.pi as u64);
        print_str(b" handle=0x");
        print_hex(thread_handle as u32);
        print_str(b" previous_ptr=0x");
        print_hex((previous_count >> 32) as u32);
        print_hex(previous_count as u32);
        print_str(b"\n");

        let (tid, mechanism) = match self.resolve_hosted_thread_for_control(thread_handle) {
            Ok((tid, mechanism)) => (tid as u64, mechanism),
            Err(status) => {
                print_str(b"[thread-life] resume failed: handle resolution status=0x");
                print_hex(status);
                print_str(b"\n");
                return status;
            }
        };
        let previous = match self.pm.resume_thread(tid as nt_process::ThreadId) {
            Ok(previous) => previous,
            Err(status) => return status,
        };
        if previous == 1 {
            let tcb = self.hosted_thread_tcb(tid).unwrap_or(0);
            if tcb <= 1 || tcb_resume(tcb) != 0 {
                let _ = self.pm.suspend_thread(tid as nt_process::ThreadId);
                return STATUS_UNSUCCESSFUL;
            }
        }
        print_str(b"[thread-life] resume tid=");
        print_u64(tid);
        print_str(b" pi=");
        print_u64(mechanism.pi as u64);
        print_str(b" previous=");
        print_u64(previous as u64);
        print_str(b"\n");
        if previous_count != 0
            && !self.user_memory_write(memory, previous_count, &previous.to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    pub(crate) unsafe fn nt_suspend_thread_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;

        let previous_count = args[1];
        if previous_count != 0 && previous_count & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if previous_count != 0 && !self.user_memory_probe_output(memory, previous_count, 4) {
            return STATUS_ACCESS_VIOLATION;
        }
        let (tid, mechanism) = match self.resolve_hosted_thread_for_control(args[0]) {
            Ok((tid, mechanism)) => (tid as u64, mechanism),
            Err(status) => return status,
        };
        let previous = match self.pm.suspend_thread(tid as nt_process::ThreadId) {
            Ok(previous) => previous,
            Err(status) => return status,
        };
        if previous == 0 {
            let tcb = self.hosted_thread_tcb(tid).unwrap_or(0);
            if tcb <= 1 || tcb_suspend_r(tcb) != 0 {
                let _ = self.pm.resume_thread(tid as nt_process::ThreadId);
                return STATUS_UNSUCCESSFUL;
            }
        }
        print_str(b"[thread-life] suspend tid=");
        print_u64(tid);
        print_str(b" pi=");
        print_u64(mechanism.pi as u64);
        print_str(b" previous=");
        print_u64(previous as u64);
        print_str(b"\n");
        if previous_count != 0
            && !self.user_memory_write(memory, previous_count, &previous.to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    fn query_object_type_name(
        &self,
        object: nt_process::HandleObject,
        namespace_kind: Option<u8>,
    ) -> &'static [u8] {
        match namespace_kind {
            Some(0) => b"Directory",
            Some(1) => b"SymbolicLink",
            Some(2) => b"Event",
            Some(3) => b"Semaphore",
            Some(4) => b"Mutant",
            Some(OBJ_KIND_TIMER) => b"Timer",
            Some(OBJ_KIND_IO_COMPLETION) => b"IoCompletion",
            _ => match object {
                nt_process::HandleObject::Process(_) => b"Process",
                nt_process::HandleObject::Thread(_) => b"Thread",
                nt_process::HandleObject::Section(_) => b"Section",
                nt_process::HandleObject::File(_)
                | nt_process::HandleObject::RoutedFile { .. }
                | nt_process::HandleObject::DiskFile { .. }
                | nt_process::HandleObject::Directory { .. }
                | nt_process::HandleObject::OverlayFile(_) => b"File",
                nt_process::HandleObject::IoCompletion(_) => b"IoCompletion",
                nt_process::HandleObject::RegistryKey(_) => b"Key",
                nt_process::HandleObject::Token(_) | nt_process::HandleObject::TokenObject(_) => {
                    b"Token"
                }
                nt_process::HandleObject::DebugObject(_) => b"DebugObject",
                nt_process::HandleObject::Job(_) => b"Job",
                nt_process::HandleObject::Opaque(tag)
                    if tag & EVENT_HANDLE_TAG_MASK == EVENT_HANDLE_TAG =>
                {
                    b"Event"
                }
                nt_process::HandleObject::Opaque(tag)
                    if tag & SEMAPHORE_HANDLE_TAG_MASK == SEMAPHORE_HANDLE_TAG =>
                {
                    b"Semaphore"
                }
                nt_process::HandleObject::Opaque(tag)
                    if tag & MUTANT_HANDLE_TAG_MASK == MUTANT_HANDLE_TAG =>
                {
                    b"Mutant"
                }
                nt_process::HandleObject::Opaque(tag)
                    if tag & TIMER_HANDLE_TAG_MASK == TIMER_HANDLE_TAG =>
                {
                    b"Timer"
                }
                nt_process::HandleObject::Opaque(tag)
                    if tag & OBJECT_NAMESPACE_HANDLE_TAG_MASK == DIRECTORY_OBJECT_HANDLE_TAG =>
                {
                    b"Directory"
                }
                nt_process::HandleObject::Opaque(tag)
                    if tag & OBJECT_NAMESPACE_HANDLE_TAG_MASK == SYMBOLIC_LINK_HANDLE_TAG =>
                {
                    b"SymbolicLink"
                }
                nt_process::HandleObject::Opaque(tag) if tag == KEYEDEVENT_HANDLE_TAG => {
                    b"KeyedEvent"
                }
                nt_process::HandleObject::Opaque(_) => b"Object",
            },
        }
    }

    fn query_object_namespace_index(
        &self,
        object: nt_process::HandleObject,
        direct_index: Option<usize>,
    ) -> Option<usize> {
        if let Some(index) = direct_index {
            return self
                .obj_ns
                .get(index)
                .filter(|entry| entry.is_live())
                .map(|_| index);
        }
        if let nt_process::HandleObject::IoCompletion(id) = object {
            return self.io_completion_namespace_index(id);
        }
        if let nt_process::HandleObject::Job(id) = object {
            return self.job_namespace_index(id);
        }
        let tag = match object {
            nt_process::HandleObject::Opaque(tag) => tag,
            _ => return None,
        };
        let (kind, index) = Self::opaque_object_namespace_index(tag)?;
        self.obj_ns
            .get(index)
            .filter(|entry| entry.is_live() && entry.kind == kind)
            .map(|_| index)
    }

    fn query_object_resolve(
        &self,
        handle: u64,
    ) -> Result<(nt_process::HandleObject, u32, Option<usize>), u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const PSEUDO_GRANTED_ACCESS: u32 = 0x001F_FFFF;
        let caller = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        if handle == u64::MAX {
            return Ok((
                nt_process::HandleObject::Process(caller),
                PSEUDO_GRANTED_ACCESS,
                None,
            ));
        }
        if handle == u64::MAX - 1 {
            let tid = self.current_tid as nt_process::ThreadId;
            self.pm.thread(tid).ok_or(STATUS_INVALID_HANDLE)?;
            return Ok((
                nt_process::HandleObject::Thread(tid),
                PSEUDO_GRANTED_ACCESS,
                None,
            ));
        }
        if handle >= OBJ_HANDLE_BASE {
            let index = (handle - OBJ_HANDLE_BASE) as usize;
            self.obj_ns
                .get(index)
                .filter(|entry| entry.is_live())
                .ok_or(STATUS_INVALID_HANDLE)?;
            return Ok((
                nt_process::HandleObject::Opaque(handle),
                PSEUDO_GRANTED_ACCESS,
                Some(index),
            ));
        }
        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        let handle32 = handle as nt_process::Handle;
        let object = self
            .pm
            .lookup_handle(caller, handle32)
            .ok_or(STATUS_INVALID_HANDLE)?;
        let access = self
            .pm
            .handle_access(caller, handle32)
            .ok_or(STATUS_INVALID_HANDLE)?;
        Ok((object, access, None))
    }

    fn query_object_handle_flags(&self, handle: u64) -> Result<nt_process::HandleFlags, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        if handle == u64::MAX || handle == u64::MAX - 1 || handle >= OBJ_HANDLE_BASE {
            self.query_object_resolve(handle)?;
            return Ok(nt_process::HandleFlags::default());
        }
        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        let caller = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        self.pm
            .handle_flags(caller, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    fn query_object_namespace_path(&self, index: usize, out: &mut [u8]) -> usize {
        let mut chain = [0usize; 16];
        let mut count = 0usize;
        let mut cur = Some(index);
        while let Some(i) = cur {
            let Some(entry) = self.obj_ns.get(i) else {
                break;
            };
            if count == chain.len() || !entry.is_live() {
                break;
            }
            chain[count] = i;
            count += 1;
            let parent = entry.parent;
            cur = if parent == OBJ_PARENT_ROOT {
                None
            } else {
                Some(parent)
            };
        }
        if out.is_empty() {
            return 0;
        }
        let mut n = 0usize;
        out[n] = b'\\';
        n += 1;
        for pos in (0..count).rev() {
            let entry = &self.obj_ns[chain[pos]];
            if entry.parent == OBJ_PARENT_ROOT {
                continue;
            }
            if n > 1 {
                if n == out.len() {
                    break;
                }
                out[n] = b'\\';
                n += 1;
            }
            for &b in entry.name() {
                if n == out.len() {
                    return n;
                }
                out[n] = b;
                n += 1;
            }
        }
        n
    }

    /// Reconstruct a canonical namespace path without truncation. File parsing uses this stricter
    /// form because a shortened Object Manager directory name must never select a different device
    /// or volume.
    fn object_namespace_path_exact(&self, index: usize, out: &mut [u8]) -> Option<usize> {
        const MAX_COMPONENTS: usize = NAMED_OBJECT_PATH_CAP / 2 + 1;
        let mut chain = [0usize; MAX_COMPONENTS];
        let mut count = 0usize;
        let mut current = index;
        loop {
            let entry = self.obj_ns.get(current)?;
            if !entry.is_live() || count == chain.len() {
                return None;
            }
            chain[count] = current;
            count += 1;
            if entry.parent == OBJ_PARENT_ROOT {
                break;
            }
            current = entry.parent;
        }
        if out.is_empty() {
            return None;
        }
        out[0] = b'\\';
        let mut length = 1usize;
        for position in (0..count).rev() {
            let entry = &self.obj_ns[chain[position]];
            if entry.parent == OBJ_PARENT_ROOT {
                continue;
            }
            let separator = usize::from(length > 1);
            let next = length
                .checked_add(separator)?
                .checked_add(entry.name().len())?;
            if next > out.len() {
                return None;
            }
            if separator != 0 {
                out[length] = b'\\';
                length += 1;
            }
            out[length..next].copy_from_slice(entry.name());
            length = next;
        }
        Some(length)
    }

    fn object_namespace_absolute_name_into(
        &self,
        root_index: usize,
        name: &[u8],
        output: &mut [u8],
    ) -> Option<usize> {
        if name.first() == Some(&b'\\') {
            if name.len() > output.len() {
                return None;
            }
            output[..name.len()].copy_from_slice(name);
            return Some(name.len());
        }
        let root_len = self.object_namespace_path_exact(root_index, output)?;
        let separator = usize::from(root_len > 1 && output[root_len - 1] != b'\\');
        let length = root_len.checked_add(separator)?.checked_add(name.len())?;
        if name.is_empty() || length > output.len() {
            return None;
        }
        if separator != 0 {
            output[root_len] = b'\\';
        }
        output[root_len + separator..length].copy_from_slice(name);
        Some(length)
    }

    fn write_ascii_utf16le(src: &[u8], dst: &mut [u8]) -> usize {
        let mut n = 0usize;
        for &b in src {
            if n + 1 >= dst.len() {
                break;
            }
            dst[n] = b;
            dst[n + 1] = 0;
            n += 2;
        }
        n
    }

    fn query_object_type_catalog() -> &'static [&'static [u8]] {
        &[
            b"Directory",
            b"SymbolicLink",
            b"Event",
            b"Semaphore",
            b"Mutant",
            b"Timer",
            b"Process",
            b"Thread",
            b"Section",
            b"File",
            b"IoCompletion",
            b"Key",
            b"Token",
            b"DebugObject",
            b"KeyedEvent",
            b"Object",
        ]
    }

    fn align_query_object_offset(value: usize) -> Option<usize> {
        value.checked_add(7).map(|v| v & !7)
    }

    fn query_object_type_record_size(type_name: &[u8]) -> Option<usize> {
        const OBJECT_TYPE_INFORMATION_SIZE: usize = 104;
        let bytes = type_name.len().checked_mul(2)?.checked_add(2)?;
        Self::align_query_object_offset(OBJECT_TYPE_INFORMATION_SIZE.checked_add(bytes)?)
    }

    fn query_object_all_types_size() -> Option<usize> {
        let mut size = Self::align_query_object_offset(4)?;
        for type_name in Self::query_object_type_catalog() {
            size = size.checked_add(Self::query_object_type_record_size(type_name)?)?;
        }
        Some(size)
    }

    unsafe fn write_query_object_return_length(
        &self,
        memory: SyscallUserMemory,
        return_length: u64,
        needed: u32,
    ) -> Result<(), u32> {
        if return_length == 0 {
            return Ok(());
        }
        if !self.user_memory_write(memory, return_length, &needed.to_le_bytes()) {
            return Err(0xC000_0005);
        }
        Ok(())
    }

    unsafe fn write_query_object_type_record(
        &self,
        memory: SyscallUserMemory,
        record_va: u64,
        type_name: &[u8],
        total_objects: u32,
        total_handles: u32,
    ) -> bool {
        const OBJECT_TYPE_INFORMATION_SIZE: usize = 104;
        let type_bytes = type_name.len() * 2;
        let Some(record_len) = Self::query_object_type_record_size(type_name) else {
            return false;
        };
        let mut output = [0u8; 160];
        if record_len > output.len() {
            return false;
        }
        let string_va = record_va + OBJECT_TYPE_INFORMATION_SIZE as u64;
        output[0..2].copy_from_slice(&(type_bytes as u16).to_le_bytes());
        output[2..4].copy_from_slice(&((type_bytes + 2) as u16).to_le_bytes());
        output[8..16].copy_from_slice(&string_va.to_le_bytes());
        output[16..20].copy_from_slice(&total_objects.to_le_bytes());
        output[20..24].copy_from_slice(&total_handles.to_le_bytes());
        output[84..88].copy_from_slice(&0x001F_FFFFu32.to_le_bytes());
        output[89] = 1; // MaintainHandleCount
        Self::write_ascii_utf16le(type_name, &mut output[OBJECT_TYPE_INFORMATION_SIZE..]);
        self.user_memory_write(memory, record_va, &output[..record_len])
    }

    unsafe fn write_query_object_all_types(
        &self,
        memory: SyscallUserMemory,
        information: u64,
    ) -> bool {
        let type_names = Self::query_object_type_catalog();
        let mut header = [0u8; 8];
        header[0..4].copy_from_slice(&(type_names.len() as u32).to_le_bytes());
        if !self.user_memory_write(memory, information, &header) {
            return false;
        }
        let mut offset = 8usize;
        for type_name in type_names {
            if !self.write_query_object_type_record(
                memory,
                information + offset as u64,
                type_name,
                0,
                0,
            ) {
                return false;
            }
            let Some(record_len) = Self::query_object_type_record_size(type_name) else {
                return false;
            };
            let Some(next) = offset.checked_add(record_len) else {
                return false;
            };
            offset = next;
        }
        true
    }

    pub(crate) unsafe fn nt_query_object_with_user_memory(
        &self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const STATUS_INVALID_INFO_CLASS: u32 = 0xC000_0003;
        const OBJECT_BASIC_INFORMATION_SIZE: usize = 56;
        const OBJECT_NAME_INFORMATION_SIZE: usize = 16;
        const OBJECT_TYPE_INFORMATION_SIZE: usize = 104;
        const OBJECT_HANDLE_FLAG_INFORMATION_SIZE: usize = 2;

        let handle = args.first().copied().unwrap_or(0);
        let class = nt_ulong_arg(args.get(1).copied().unwrap_or(u64::MAX));
        let information = args.get(2).copied().unwrap_or(0);
        let length = nt_ulong_arg(args.get(3).copied().unwrap_or(0)) as usize;
        let return_length = args.get(4).copied().unwrap_or(0);

        if return_length != 0 && !self.user_memory_probe_output(memory, return_length, 4) {
            return STATUS_ACCESS_VIOLATION;
        }
        if class == 3 {
            let Some(needed) = Self::query_object_all_types_size() else {
                return STATUS_INFO_LENGTH_MISMATCH;
            };
            if self
                .write_query_object_return_length(
                    memory,
                    return_length,
                    needed.min(u32::MAX as usize) as u32,
                )
                .is_err()
            {
                return STATUS_ACCESS_VIOLATION;
            }
            if length < needed || !self.user_memory_probe_output(memory, information, needed) {
                return STATUS_INFO_LENGTH_MISMATCH;
            }
            if self.write_query_object_all_types(memory, information) {
                return 0;
            }
            return STATUS_ACCESS_VIOLATION;
        }

        let (object, granted_access, namespace_index) = match self.query_object_resolve(handle) {
            Ok(target) => target,
            Err(status) => return status,
        };
        let namespace_kind =
            namespace_index.and_then(|index| self.obj_ns.get(index).map(|e| e.kind));
        let type_name = self.query_object_type_name(object, namespace_kind);

        match class {
            0 => {
                let mut name_ascii = [0u8; 256];
                let name_len = self
                    .query_object_namespace_index(object, namespace_index)
                    .map(|index| self.query_object_namespace_path(index, &mut name_ascii))
                    .unwrap_or(0);
                let type_info_len = (OBJECT_TYPE_INFORMATION_SIZE + type_name.len() * 2 + 2) as u32;
                let name_info_len = if name_len == 0 {
                    OBJECT_NAME_INFORMATION_SIZE as u32
                } else {
                    (OBJECT_NAME_INFORMATION_SIZE + name_len * 2 + 2) as u32
                };
                if self
                    .write_query_object_return_length(
                        memory,
                        return_length,
                        OBJECT_BASIC_INFORMATION_SIZE as u32,
                    )
                    .is_err()
                {
                    return STATUS_ACCESS_VIOLATION;
                }
                if length != OBJECT_BASIC_INFORMATION_SIZE
                    || !self.user_memory_probe_output(memory, information, length)
                {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut output = [0u8; OBJECT_BASIC_INFORMATION_SIZE];
                output[4..8].copy_from_slice(&granted_access.to_le_bytes());
                output[8..12].copy_from_slice(&1u32.to_le_bytes()); // HandleCount
                output[12..16].copy_from_slice(&1u32.to_le_bytes()); // PointerCount
                output[36..40].copy_from_slice(&name_info_len.to_le_bytes());
                output[40..44].copy_from_slice(&type_info_len.to_le_bytes());
                if self.user_memory_write(memory, information, &output) {
                    0
                } else {
                    STATUS_ACCESS_VIOLATION
                }
            }
            1 => {
                let mut name_ascii = [0u8; 256];
                let name_len = self
                    .query_object_namespace_index(object, namespace_index)
                    .map(|index| self.query_object_namespace_path(index, &mut name_ascii))
                    .unwrap_or(0);
                let name_bytes = name_len * 2;
                let needed = if name_len == 0 {
                    OBJECT_NAME_INFORMATION_SIZE
                } else {
                    OBJECT_NAME_INFORMATION_SIZE + name_bytes + 2
                };
                if self
                    .write_query_object_return_length(
                        memory,
                        return_length,
                        needed.min(u32::MAX as usize) as u32,
                    )
                    .is_err()
                {
                    return STATUS_ACCESS_VIOLATION;
                }
                if length < needed || !self.user_memory_probe_output(memory, information, needed) {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut output = [0u8; OBJECT_NAME_INFORMATION_SIZE + 256 * 2 + 2];
                if name_len != 0 {
                    output[0..2].copy_from_slice(&(name_bytes as u16).to_le_bytes());
                    output[2..4].copy_from_slice(&((name_bytes + 2) as u16).to_le_bytes());
                    output[8..16].copy_from_slice(&(information + 16).to_le_bytes());
                    Self::write_ascii_utf16le(
                        &name_ascii[..name_len],
                        &mut output[OBJECT_NAME_INFORMATION_SIZE..],
                    );
                }
                if self.user_memory_write(memory, information, &output[..needed]) {
                    0
                } else {
                    STATUS_ACCESS_VIOLATION
                }
            }
            2 => {
                let type_bytes = type_name.len() * 2;
                let needed = OBJECT_TYPE_INFORMATION_SIZE + type_bytes + 2;
                if self
                    .write_query_object_return_length(
                        memory,
                        return_length,
                        needed.min(u32::MAX as usize) as u32,
                    )
                    .is_err()
                {
                    return STATUS_ACCESS_VIOLATION;
                }
                if length < needed || !self.user_memory_probe_output(memory, information, needed) {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut output = [0u8; OBJECT_TYPE_INFORMATION_SIZE + 64];
                let string_va = information + OBJECT_TYPE_INFORMATION_SIZE as u64;
                output[0..2].copy_from_slice(&(type_bytes as u16).to_le_bytes());
                output[2..4].copy_from_slice(&((type_bytes + 2) as u16).to_le_bytes());
                output[8..16].copy_from_slice(&string_va.to_le_bytes());
                output[16..20].copy_from_slice(&1u32.to_le_bytes()); // TotalNumberOfObjects
                output[20..24].copy_from_slice(&1u32.to_le_bytes()); // TotalNumberOfHandles
                output[84..88].copy_from_slice(&0x001F_FFFFu32.to_le_bytes());
                output[89] = 1; // MaintainHandleCount
                Self::write_ascii_utf16le(type_name, &mut output[OBJECT_TYPE_INFORMATION_SIZE..]);
                if self.user_memory_write(memory, information, &output[..needed]) {
                    0
                } else {
                    STATUS_ACCESS_VIOLATION
                }
            }
            4 => {
                let flags = match self.query_object_handle_flags(handle) {
                    Ok(flags) => flags,
                    Err(status) => return status,
                };
                if self
                    .write_query_object_return_length(
                        memory,
                        return_length,
                        OBJECT_HANDLE_FLAG_INFORMATION_SIZE as u32,
                    )
                    .is_err()
                {
                    return STATUS_ACCESS_VIOLATION;
                }
                if length != OBJECT_HANDLE_FLAG_INFORMATION_SIZE
                    || !self.user_memory_probe_output(memory, information, length)
                {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let output = [flags.inherit as u8, flags.protect_from_close as u8];
                if self.user_memory_write(memory, information, &output) {
                    0
                } else {
                    STATUS_ACCESS_VIOLATION
                }
            }
            _ => {
                let _ = self.write_query_object_return_length(
                    memory,
                    return_length,
                    length.min(u32::MAX as usize) as u32,
                );
                STATUS_INVALID_INFO_CLASS
            }
        }
    }

    pub(crate) unsafe fn nt_set_information_object_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_INVALID_INFO_CLASS: u32 = 0xC000_0003;
        const OBJECT_HANDLE_FLAG_INFORMATION: u32 = 4;
        const OBJECT_SESSION_INFORMATION: u32 = 5;
        const OBJECT_HANDLE_FLAG_INFORMATION_SIZE: usize = 2;

        let handle = args.first().copied().unwrap_or(0);
        let class = nt_ulong_arg(args.get(1).copied().unwrap_or(u64::MAX));
        let information = args.get(2).copied().unwrap_or(0);
        let length = nt_ulong_arg(args.get(3).copied().unwrap_or(0)) as usize;

        match class {
            OBJECT_HANDLE_FLAG_INFORMATION => {
                if length != OBJECT_HANDLE_FLAG_INFORMATION_SIZE {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut encoded = [0u8; OBJECT_HANDLE_FLAG_INFORMATION_SIZE];
                if information == 0 || !self.user_memory_read(memory, information, &mut encoded) {
                    return STATUS_ACCESS_VIOLATION;
                }
                if handle == u64::MAX || handle == u64::MAX - 1 || handle >= OBJ_HANDLE_BASE {
                    return STATUS_INVALID_HANDLE;
                }
                if handle > u32::MAX as u64 {
                    return STATUS_INVALID_HANDLE;
                }
                let Some(caller) = self.pm_pid_for_pi(self.pi) else {
                    return STATUS_INVALID_HANDLE;
                };
                let flags = nt_process::HandleFlags {
                    inherit: encoded[0] != 0,
                    protect_from_close: encoded[1] != 0,
                };
                self.pm
                    .set_handle_flags(caller, handle as nt_process::Handle, flags)
                    .map_or_else(|status| status, |_| 0)
            }
            OBJECT_SESSION_INFORMATION => {
                match self.object_namespace_index_for_handle(handle, Some(OBJ_KIND_DIRECTORY), 0) {
                    Ok(_) => 0,
                    Err(_) => STATUS_INVALID_HANDLE,
                }
            }
            _ => STATUS_INVALID_INFO_CLASS,
        }
    }

    pub(crate) unsafe fn nt_allocate_virtual_memory_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const PROCESS_VM_OPERATION: u32 = 0x0008;
        const HIGHEST_VAD_ADDRESS: u64 = 0x0000_07ff_fffd_ffff;
        let ctx = self.loop_ctx.unwrap();
        let base_ptr = args[1];
        let size_ptr = args[3];
        let zero_bits = args[2];
        let allocation_type = nt_ulong_arg(args[4]);
        let protection = nt_ulong_arg(args[5]);
        if let Err(status) =
            nt_address_space::validate_allocate_parameters(zero_bits, allocation_type, protection)
        {
            return status;
        }
        if !self.user_memory_probe_output(memory, base_ptr, 8)
            || !self.user_memory_probe_output(memory, size_ptr, 8)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut word = [0u8; 8];
        if !self.user_memory_read(memory, base_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let base_in = u64::from_le_bytes(word);
        if !self.user_memory_read(memory, size_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let want = u64::from_le_bytes(word);
        if base_in > HIGHEST_VAD_ADDRESS {
            return nt_address_space::STATUS_INVALID_PARAMETER_2;
        }
        if HIGHEST_VAD_ADDRESS + 1 - base_in < want || want == 0 {
            return nt_address_space::STATUS_INVALID_PARAMETER_4;
        }
        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[0], PROCESS_VM_OPERATION) {
                Ok(target) => target,
                Err(status) => return status,
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }
        if allocation_type & nt_address_space::MEM_LARGE_PAGES != 0 {
            if !self.current_token_has_privilege(nt_security::SE_LOCK_MEMORY) {
                return STATUS_PRIVILEGE_NOT_HELD;
            }
            return STATUS_INVALID_PARAMETER;
        }
        if allocation_type & (nt_address_space::MEM_PHYSICAL | nt_address_space::MEM_WRITE_WATCH)
            != 0
        {
            return STATUS_INVALID_PARAMETER;
        }
        let copy_on_write = matches!(
            protection & 0xff,
            nt_address_space::PAGE_WRITECOPY | nt_address_space::PAGE_EXECUTE_WRITECOPY
        );
        let created_vad = base_in == 0 || allocation_type & nt_address_space::MEM_RESERVE != 0;
        if created_vad && copy_on_write {
            return nt_address_space::STATUS_INVALID_PAGE_PROTECTION;
        }
        let placement_limit = if base_in == 0 && zero_bits != 0 {
            let highest = u64::MAX >> zero_bits;
            if highest > HIGHEST_VAD_ADDRESS {
                return nt_address_space::STATUS_INVALID_PARAMETER_3;
            }
            PRIVATE_VM_LIMIT.min(highest + 1)
        } else {
            PRIVATE_VM_LIMIT
        };
        let procs = &mut *ctx.procs;
        let target = procs[target_pi];
        if target.pml4 == 0 || target.scratch_base == 0 {
            return nt_process::STATUS_INVALID_HANDLE;
        }
        let Some(vm_map) = process_vm_region_map_mut(target_pi) else {
            return nt_process::STATUS_INVALID_HANDLE;
        };
        // STATIC scratch, not stack — see the matching note in the free path.
        let before = &mut *core::ptr::addr_of_mut!(VM_MAP_BEFORE);
        let after = &mut *core::ptr::addr_of_mut!(VM_MAP_AFTER);
        *before = *vm_map;
        let plan = match allocate_private_vad_avoiding_fixed_authorities(
            before,
            after,
            target_pi,
            (base_in != 0).then_some(base_in),
            want,
            allocation_type,
            protection,
            placement_limit,
        ) {
            Ok(plan) => plan,
            Err(status) => return status,
        };
        crate::note_high_water(&crate::VM_REGION_HW, after.extent_count() as u64);
        if !created_vad && allocation_type != nt_address_space::MEM_RESET && copy_on_write {
            return nt_address_space::STATUS_INVALID_PAGE_PROTECTION;
        }

        // Commit the plan EXTENT-WISE, not page-wise.
        //
        // `extent_at` is a linear scan of the whole fixed-capacity extent array, so consulting it
        // once per page costs O(pages x capacity) for the WHOLE request — including the pages a
        // request does not touch at all. A large `MEM_RESERVE` commits nothing, yet the page-at-a-
        // time walk still paid two full scans per 4 KiB of reserved address space just to discover
        // there was nothing to do; smss's big reservations spent TENS OF SECONDS here each.
        //
        // Both maps are extent-based, so `old`/`new` are constant across any run that crosses no
        // extent boundary on either side. Advance a run at a time and do the per-page work only
        // inside runs that actually became committed (or changed protection). Behaviour per page is
        // identical — only the number of lookups changes.
        let region_end = plan.base + plan.size;
        let mut page = plan.base;
        let mut changed_end = plan.base;
        let mut map_status = 0u32;
        'commit: while page < region_end {
            let old = before.extent_at(page);
            let new = after.extent_at(page);
            // Longest run starting at `page` over which BOTH lookups keep their current answer.
            let mut run_end = region_end;
            match new {
                Some(extent) => run_end = run_end.min(extent.end()),
                None => {
                    if let Some(next) = after.next_extent_base_after(page) {
                        run_end = run_end.min(next);
                    }
                }
            }
            match old {
                Some(extent) => run_end = run_end.min(extent.end()),
                None => {
                    if let Some(next) = before.next_extent_base_after(page) {
                        run_end = run_end.min(next);
                    }
                }
            }
            // A run must always advance, or a boundary exactly at `page` would spin forever.
            let run_end = run_end.max(page + 0x1000).min(region_end);
            if new.is_some_and(|extent| extent.state == nt_address_space::VmExtentState::Committed)
            {
                if old
                    .is_none_or(|extent| extent.state != nt_address_space::VmExtentState::Committed)
                {
                    while page < run_end {
                        if let Err(status) = vm_map_private_page(
                            target_pi,
                            page,
                            new.unwrap().protection,
                            target.pml4,
                            target.scratch_base,
                        ) {
                            map_status = status;
                            break 'commit;
                        }
                        page += 0x1000;
                        changed_end = page;
                    }
                    continue;
                } else if old.unwrap().protection != new.unwrap().protection {
                    while page < run_end {
                        if let Err(status) = vm_reprotect_private_page(
                            target_pi,
                            page,
                            old.unwrap().protection,
                            new.unwrap().protection,
                            target.pml4,
                        ) {
                            map_status = status;
                            break 'commit;
                        }
                        page += 0x1000;
                        changed_end = page;
                    }
                    continue;
                }
            }
            // Nothing to do across this whole run (reserved, unchanged, or outside any extent).
            page = run_end;
            changed_end = page;
        }
        if map_status != 0 {
            page = plan.base;
            while page < changed_end {
                let old = before.extent_at(page);
                let new = after.extent_at(page);
                if old
                    .is_none_or(|extent| extent.state != nt_address_space::VmExtentState::Committed)
                    && new.is_some_and(|extent| {
                        extent.state == nt_address_space::VmExtentState::Committed
                    })
                {
                    vm_unmap_private_page(target_pi, page);
                } else if let (Some(old), Some(new)) = (old, new) {
                    if old.state == nt_address_space::VmExtentState::Committed
                        && new.state == nt_address_space::VmExtentState::Committed
                        && old.protection != new.protection
                    {
                        let _ = vm_reprotect_private_page(
                            target_pi,
                            page,
                            new.protection,
                            old.protection,
                            target.pml4,
                        );
                    }
                }
                page += 0x1000;
            }
            return map_status;
        }
        *vm_map = *after;
        let size_written = self.user_memory_write(memory, size_ptr, &plan.size.to_le_bytes());
        let base_written = self.user_memory_write(memory, base_ptr, &plan.base.to_le_bytes());
        if !created_vad && (!size_written || !base_written) {
            return STATUS_ACCESS_VIOLATION;
        }
        NTALLOC_SERVICED.fetch_add(1, Ordering::Relaxed);
        0
    }

    pub(crate) unsafe fn nt_protect_virtual_memory_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER_3: u32 = 0xC000_00F1;
        const PROCESS_VM_OPERATION: u32 = 0x0008;
        const HIGHEST_USER_ADDRESS: u64 = 0x0000_07ff_fffe_ffff;
        let base_ptr = args[1];
        let size_ptr = args[2];
        let new_protection = nt_ulong_arg(args[3]);
        let oldprot_ptr = args[4];
        if let Err(status) = nt_address_space::validate_protect_parameters(new_protection) {
            return status;
        }
        if !self.user_memory_probe_output(memory, base_ptr, 8)
            || !self.user_memory_probe_output(memory, size_ptr, 8)
            || oldprot_ptr == 0
            || !self.user_memory_probe_output(memory, oldprot_ptr, 4)
        {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut word = [0u8; 8];
        if !self.user_memory_read(memory, base_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let base = u64::from_le_bytes(word);
        if !self.user_memory_read(memory, size_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let size = u64::from_le_bytes(word);
        if base > HIGHEST_USER_ADDRESS {
            return nt_address_space::STATUS_INVALID_PARAMETER_2;
        }
        if HIGHEST_USER_ADDRESS - base < size || size == 0 {
            return STATUS_INVALID_PARAMETER_3;
        }

        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[0], PROCESS_VM_OPERATION) {
                Ok(target) => target,
                Err(status) => return status,
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }
        let Some(ctx) = self.loop_ctx else {
            return nt_process::STATUS_INVALID_HANDLE;
        };
        let procs = &mut *ctx.procs;
        let target = procs[target_pi];
        if target.pml4 == 0 || target.scratch_base == 0 {
            return nt_process::STATUS_INVALID_HANDLE;
        }
        if process_committed_mapping_basic_information(target_pi as u64, base).is_some() {
            let before_committed = &mut *core::ptr::addr_of_mut!(COMMITTED_MAP_BEFORE);
            let after_committed = &mut *core::ptr::addr_of_mut!(COMMITTED_MAP_AFTER);
            let Some(snapshot) = process_committed_mapping_snapshot(target_pi as u64) else {
                return nt_process::STATUS_INVALID_HANDLE;
            };
            *before_committed = snapshot;
            *after_committed = *before_committed;
            let plan = match after_committed.protect(base, size, new_protection) {
                Ok(plan) => plan,
                Err(status) => return status,
            };
            let mut page = plan.base;
            let mut changed_end = plan.base;
            let mut map_status = 0u32;
            while page < plan.base + plan.size {
                let old = before_committed.query_basic(page);
                let new = after_committed.query_basic(page);
                if let (Some(old), Some(new)) = (old, new) {
                    if old.protect != new.protect {
                        let old_page_protection = committed_mapping_effective_page_protection(old);
                        let new_page_protection = committed_mapping_effective_page_protection(new);
                        let result = if new.type_ == nt_address_space::MEM_IMAGE {
                            vm_reprotect_resident_image_page(
                                target_pi,
                                page,
                                old_page_protection,
                                new_page_protection,
                                target.pml4,
                                target.scratch_base,
                            )
                        } else if csrss_frame_get_exact(target_pi as u64, page).0 != 0 {
                            vm_reprotect_private_page(
                                target_pi,
                                page,
                                old_page_protection,
                                new_page_protection,
                                target.pml4,
                            )
                        } else {
                            Ok(())
                        };
                        if let Err(status) = result {
                            map_status = status;
                            break;
                        }
                    }
                }
                page += 0x1000;
                changed_end = page;
            }
            if map_status != 0 {
                page = plan.base;
                while page < changed_end {
                    let old = before_committed.query_basic(page);
                    let new = after_committed.query_basic(page);
                    if let (Some(old), Some(new)) = (old, new) {
                        if old.protect != new.protect {
                            let old_page_protection =
                                committed_mapping_effective_page_protection(old);
                            let new_page_protection =
                                committed_mapping_effective_page_protection(new);
                            if new.type_ == nt_address_space::MEM_IMAGE {
                                let _ = vm_reprotect_resident_image_page(
                                    target_pi,
                                    page,
                                    new_page_protection,
                                    old_page_protection,
                                    target.pml4,
                                    target.scratch_base,
                                );
                            } else if csrss_frame_get_exact(target_pi as u64, page).0 != 0 {
                                let _ = vm_reprotect_private_page(
                                    target_pi,
                                    page,
                                    new_page_protection,
                                    old_page_protection,
                                    target.pml4,
                                );
                            }
                        }
                    }
                    page += 0x1000;
                }
                return map_status;
            }
            if !process_committed_mapping_replace(target_pi as u64, *after_committed) {
                return nt_process::STATUS_INVALID_HANDLE;
            }
            loader_trace_record(
                self.pi,
                LoaderOp::ProtectVirtualMemory,
                0,
                None,
                plan.base,
                plan.size,
                b"",
            );
            let _ = self.user_memory_write(memory, oldprot_ptr, &plan.old_protection.to_le_bytes());
            let _ = self.user_memory_write(memory, base_ptr, &plan.base.to_le_bytes());
            let _ = self.user_memory_write(memory, size_ptr, &plan.size.to_le_bytes());
            return 0;
        }
        let Some(vm_map) = process_vm_region_map_mut(target_pi) else {
            return nt_process::STATUS_INVALID_HANDLE;
        };
        let before = &mut *core::ptr::addr_of_mut!(VM_MAP_BEFORE);
        let after = &mut *core::ptr::addr_of_mut!(VM_MAP_AFTER);
        *before = *vm_map;
        *after = *before;
        let plan = match after.protect(base, size, new_protection) {
            Ok(plan) => plan,
            Err(status) => return status,
        };
        crate::note_high_water(&crate::VM_REGION_HW, after.extent_count() as u64);
        crate::note_high_water(
            &crate::VM_PROTECTION_OVERRIDE_HW,
            after.protection_override_count() as u64,
        );
        let mut page = plan.base;
        let mut changed_end = plan.base;
        let mut map_status = 0u32;
        while page < plan.base + plan.size {
            let old_protection = before.protection_at(page);
            let new_protection = after.protection_at(page);
            if let (Some(old_protection), Some(new_protection)) = (old_protection, new_protection) {
                if old_protection != new_protection {
                    if let Err(status) = vm_reprotect_private_page(
                        target_pi,
                        page,
                        old_protection,
                        new_protection,
                        target.pml4,
                    ) {
                        map_status = status;
                        break;
                    }
                }
            }
            page += 0x1000;
            changed_end = page;
        }
        if map_status != 0 {
            page = plan.base;
            while page < changed_end {
                if let (Some(old_protection), Some(new_protection)) =
                    (before.protection_at(page), after.protection_at(page))
                {
                    if old_protection != new_protection {
                        let _ = vm_reprotect_private_page(
                            target_pi,
                            page,
                            new_protection,
                            old_protection,
                            target.pml4,
                        );
                    }
                }
                page += 0x1000;
            }
            return map_status;
        }
        *vm_map = *after;
        let registry_slot = self.loop_ctx.and_then(|ctx| {
            (&*ctx.reg)
                .dll_for_page(target_pi, plan.base)
                .map(|(slot, _)| slot)
        });
        loader_trace_record(
            self.pi,
            LoaderOp::ProtectVirtualMemory,
            0,
            registry_slot,
            plan.base,
            plan.size,
            b"",
        );
        let _ = self.user_memory_write(memory, oldprot_ptr, &plan.old_protection.to_le_bytes());
        let _ = self.user_memory_write(memory, base_ptr, &plan.base.to_le_bytes());
        let _ = self.user_memory_write(memory, size_ptr, &plan.size.to_le_bytes());
        0
    }

    unsafe fn ensure_residency_page(
        &mut self,
        target_pi: usize,
        plan: nt_address_space::VmResidencyPagePlan,
    ) -> Result<(), u32> {
        let ctx = self.loop_ctx.ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let procs = &mut *ctx.procs;
        let target = procs
            .get(target_pi)
            .copied()
            .filter(|target| target.pml4 != 0)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        match plan.source {
            nt_address_space::VmResidencySource::Private => {
                if plan.page == KUSER_VA && kuser_page_alias_get(target_pi) != 0 {
                    return Ok(());
                }
                if csrss_frame_get_exact(target_pi as u64, plan.page).0 == 0 {
                    vm_map_private_page(
                        target_pi,
                        plan.page,
                        plan.map_protection,
                        target.pml4,
                        target.scratch_base,
                    )?;
                }
                Ok(())
            }
            nt_address_space::VmResidencySource::Mapped => {
                match service_generic_section_fault(
                    &mut *ctx.generic_sections,
                    target_pi,
                    plan.page,
                    target.pml4,
                    target.scratch_base,
                    nt_address_space::FaultAccess::Lock,
                )? {
                    true => Ok(()),
                    false => Err(nt_address_space::STATUS_CONFLICTING_ADDRESSES),
                }
            }
            nt_address_space::VmResidencySource::Image => {
                let image = process_committed_image_allocation(target_pi as u64, plan.page)
                    .ok_or(nt_address_space::STATUS_NOT_COMMITTED)?;
                let base = image.allocation_base;
                let pe = if base == PE_LOAD_BASE {
                    (&*ctx.hosted_loaded_images)
                        .pe_by_pi(target_pi)
                        .ok_or(nt_address_space::STATUS_CONFLICTING_ADDRESSES)?
                } else if !ctx.ntdll_pe.is_null() && base == ctx.nt_base {
                    &*ctx.ntdll_pe
                } else {
                    let reg = &*ctx.reg;
                    let (index, _) = reg
                        .dll_for_page(target_pi, base)
                        .ok_or(nt_address_space::STATUS_CONFLICTING_ADDRESSES)?;
                    ctx.dll_pes()
                        .get(index)
                        .and_then(|slot| slot.as_ref())
                        .ok_or(nt_address_space::STATUS_CONFLICTING_ADDRESSES)?
                };
                let (filled_pages, faults) = if target_pi == self.pi {
                    (&mut *ctx.filled_pages, &mut *ctx.faults)
                } else {
                    (
                        &mut (&mut *ctx.pfilled)[target_pi],
                        &mut procs[target_pi].faults,
                    )
                };
                service_image_page_residency(
                    target_pi,
                    plan.page,
                    base,
                    pe,
                    target.pml4,
                    target.scratch_base,
                    hosted_active_image_mirror_for_pi(target_pi),
                    nt_address_space::FaultAccess::Lock,
                    false,
                    filled_pages,
                    faults,
                )
            }
        }
    }

    unsafe fn capture_virtual_memory_lock_request(
        &self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> Result<(usize, nt_address_space::VmResidencyRangePlan, u32, u64, u64), u32> {
        const PROCESS_VM_OPERATION: u32 = 0x0008;

        let map_type = nt_ulong_arg(args[3]);
        nt_address_space::VmPageLockTable::validate_map_type(map_type)?;
        let base_pointer = args[1];
        let size_pointer = args[2];
        if !self.user_memory_probe_output(memory, base_pointer, 8)
            || !self.user_memory_probe_output(memory, size_pointer, 8)
        {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut encoded = [0u8; 8];
        if !self.user_memory_read(memory, base_pointer, &mut encoded) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let address = u64::from_le_bytes(encoded);
        if !self.user_memory_read(memory, size_pointer, &mut encoded) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let size = u64::from_le_bytes(encoded);
        let range = nt_address_space::VmResidencyRangePlan::new(address, size, USER_ADDRESS_LIMIT)?;
        let (target_pid, target_pi) =
            self.resolve_process_for_access(args[0], PROCESS_VM_OPERATION)?;
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return Err(nt_process::STATUS_PROCESS_IS_TERMINATING);
        }
        if map_type & nt_address_space::MAP_SYSTEM != 0
            && !self.current_token_has_privilege(nt_security::SE_LOCK_MEMORY)
        {
            return Err(STATUS_PRIVILEGE_NOT_HELD);
        }
        Ok((target_pi, range, map_type, base_pointer, size_pointer))
    }

    pub(crate) unsafe fn nt_lock_virtual_memory_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        let (target_pi, range, map_type, base_pointer, size_pointer) =
            match self.capture_virtual_memory_lock_request(args, memory) {
                Ok(request) => request,
                Err(status) => return status,
            };

        let status = 'operation: {
            // Validate the complete mapping before causing any residency side effects. This is the
            // address-space-lock phase of MiLockVirtualMemory, expressed through the common mapping
            // classifier instead of separate private/image/section rules.
            for page in range.pages() {
                let information = match self.query_memory_basic_information(target_pi, page) {
                    Ok(information) => information,
                    Err(status) => break 'operation status,
                };
                if let Err(status) = nt_address_space::vm_residency_page_plan(page, information) {
                    break 'operation status;
                }
            }
            for page in range.pages() {
                let information = match self.query_memory_basic_information(target_pi, page) {
                    Ok(information) => information,
                    Err(status) => break 'operation status,
                };
                let plan = match nt_address_space::vm_residency_page_plan(page, information) {
                    Ok(plan) => plan,
                    Err(status) => break 'operation status,
                };
                if let Err(status) = self.ensure_residency_page(target_pi, plan) {
                    break 'operation status;
                }
            }
            match vm_page_lock_range(target_pi as u64, range, map_type) {
                Ok(status) => status,
                Err(status) => status,
            }
        };
        if !self.user_memory_write(memory, base_pointer, &range.base.to_le_bytes())
            || !self.user_memory_write(memory, size_pointer, &range.size.to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        status
    }

    pub(crate) unsafe fn nt_unlock_virtual_memory_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        let (target_pi, range, map_type, base_pointer, size_pointer) =
            match self.capture_virtual_memory_lock_request(args, memory) {
                Ok(request) => request,
                Err(status) => return status,
            };

        let status = 'operation: {
            // Lock exclusion guarantees residency until unlock. Still validate the whole range
            // first so stale or corrupted lock state cannot permit a partial mutation.
            for page in range.pages() {
                let information = match self.query_memory_basic_information(target_pi, page) {
                    Ok(information) => information,
                    Err(_) => break 'operation nt_address_space::STATUS_NOT_LOCKED,
                };
                if information.state != nt_address_space::MEM_COMMIT
                    || !matches!(
                        information.type_,
                        nt_address_space::MEM_PRIVATE
                            | nt_address_space::MEM_MAPPED
                            | nt_address_space::MEM_IMAGE
                    )
                    || !vm_page_is_resident(target_pi, page)
                {
                    break 'operation nt_address_space::STATUS_NOT_LOCKED;
                }
            }
            match vm_page_unlock_range(target_pi as u64, range, map_type) {
                Ok(()) => 0,
                Err(status) => status,
            }
        };
        if !self.user_memory_write(memory, base_pointer, &range.base.to_le_bytes())
            || !self.user_memory_write(memory, size_pointer, &range.size.to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        status
    }

    unsafe fn query_memory_basic_information(
        &self,
        target_pi: usize,
        address: u64,
    ) -> Result<nt_address_space::VmBasicInformation, u32> {
        let page = address & !0xfffu64;
        let Some(ctx) = self.loop_ctx else {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        };
        let procs = &*ctx.procs;
        if target_pi >= MAX_PI || procs[target_pi].pml4 == 0 {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        }

        if page == KUSER_VA && kuser_page_alias_get(target_pi) != 0 {
            return Ok(nt_address_space::VmBasicInformation {
                base_address: page,
                allocation_base: KUSER_VA,
                allocation_protect: nt_address_space::PAGE_READONLY,
                region_size: 0x1000,
                state: nt_address_space::MEM_COMMIT,
                protect: nt_address_space::PAGE_READONLY,
                type_: nt_address_space::MEM_PRIVATE,
            });
        }

        if let Some(info) = process_committed_mapping_basic_information(target_pi as u64, page) {
            return Ok(info);
        }

        let Some(vm_map) = process_vm_region_map(target_pi) else {
            return Err(nt_process::STATUS_INVALID_HANDLE);
        };
        if vm_map.extent_at(page).is_some() {
            return vm_map.query_basic(page, USER_ADDRESS_LIMIT);
        }

        if let Some(info) = registered_frame_basic_information(target_pi, page) {
            return Ok(info);
        }

        let mut next = USER_ADDRESS_LIMIT;
        if let Some(candidate) = vm_map.next_extent_base_after(page) {
            next = next.min(candidate);
        }
        if let Some(candidate) = process_committed_mapping_next_base_after(target_pi as u64, page) {
            next = next.min(candidate);
        }
        if let Some(candidate) = csrss_frame_next_page_after(target_pi as u64, page) {
            next = next.min(candidate);
        }
        if KUSER_VA > page && kuser_page_alias_get(target_pi) != 0 {
            next = next.min(KUSER_VA);
        }

        Ok(nt_address_space::VmBasicInformation {
            base_address: page,
            allocation_base: 0,
            allocation_protect: 0,
            region_size: next.saturating_sub(page),
            state: nt_address_space::MEM_FREE,
            protect: nt_address_space::PAGE_NOACCESS,
            type_: 0,
        })
    }

    pub(crate) unsafe fn nt_query_virtual_memory_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_INFO_CLASS: u32 = 0xC000_0003;
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const HIGHEST_USER_ADDRESS: u64 = 0x0000_07ff_fffe_ffff;
        let process_handle = args.first().copied().unwrap_or(0);
        let base = args.get(1).copied().unwrap_or(0);
        let info_class = nt_ulong_arg(args.get(2).copied().unwrap_or(u64::MAX));
        let buffer = args.get(3).copied().unwrap_or(0);
        let length = args.get(4).copied().unwrap_or(0);
        let return_length = args.get(5).copied().unwrap_or(0);

        if base > HIGHEST_USER_ADDRESS {
            return STATUS_INVALID_PARAMETER;
        }
        if info_class != 0 {
            return STATUS_INVALID_INFO_CLASS;
        }
        if length < nt_address_space::MEMORY_BASIC_INFORMATION_X64_SIZE as u64 {
            return STATUS_INFO_LENGTH_MISMATCH;
        }
        if buffer == 0
            || !self.user_memory_probe_output(
                memory,
                buffer,
                nt_address_space::MEMORY_BASIC_INFORMATION_X64_SIZE,
            )
            || return_length != 0
                && !self.user_memory_probe_output(
                    memory,
                    return_length,
                    core::mem::size_of::<u64>(),
                )
        {
            return STATUS_ACCESS_VIOLATION;
        }

        let (target_pid, target_pi) = match self
            .resolve_process_for_access(process_handle, nt_process::PROCESS_QUERY_INFORMATION)
        {
            Ok(target) => target,
            Err(status) => return status,
        };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }

        let info = match self.query_memory_basic_information(target_pi, base) {
            Ok(info) => info,
            Err(status) => return status,
        };
        if !self.user_memory_write(memory, buffer, &info.encode_x64()) {
            return STATUS_ACCESS_VIOLATION;
        }
        if return_length != 0 {
            let returned = nt_address_space::MEMORY_BASIC_INFORMATION_X64_SIZE as u64;
            if !self.user_memory_write(memory, return_length, &returned.to_le_bytes()) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        0
    }

    unsafe fn nt_copy_virtual_memory(&mut self, args: &[u64], read: bool) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_PARTIAL_COPY: u32 = 0x8000_000D;
        const PROCESS_VM_READ: u32 = 0x0010;
        const PROCESS_VM_WRITE: u32 = 0x0020;

        let remote = args[1];
        let local = args[2];
        let length = args[3];
        let count_ptr = args[4];
        let valid_range = |base: u64| {
            base.checked_add(length)
                .is_some_and(|end| end <= USER_ADDRESS_LIMIT)
        };
        if !valid_range(remote) || !valid_range(local) {
            return STATUS_ACCESS_VIOLATION;
        }
        if count_ptr != 0 {
            if !self.probe_user_output(count_ptr, 8) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        if length == 0 {
            if count_ptr != 0 {
                let _ = self.xas_write_u64(count_ptr, 0);
            }
            return 0;
        }

        let required_access = if read {
            PROCESS_VM_READ
        } else {
            PROCESS_VM_WRITE
        };
        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[0], required_access) {
                Ok(target) => target,
                Err(status) => {
                    if count_ptr != 0 {
                        let _ = self.xas_write_u64(count_ptr, 0);
                    }
                    return status;
                }
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            if count_ptr != 0 {
                let _ = self.xas_write_u64(count_ptr, 0);
            }
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }

        let ctx = match self.loop_ctx {
            Some(ctx) => ctx,
            None => {
                if count_ptr != 0 {
                    let _ = self.xas_write_u64(count_ptr, 0);
                }
                return STATUS_PARTIAL_COPY;
            }
        };
        let procs = &mut *ctx.procs;
        let target = procs[target_pi];
        if target.pml4 == 0 || target.scratch_base == 0 {
            if count_ptr != 0 {
                let _ = self.xas_write_u64(count_ptr, 0);
            }
            return nt_process::STATUS_INVALID_HANDLE;
        }
        let (target_filled, target_faults) = if target_pi == self.pi {
            (&*ctx.filled_pages, *ctx.faults as usize)
        } else {
            (&(*ctx.pfilled)[target_pi], procs[target_pi].faults as usize)
        };
        let target_vm = match process_vm_region_map(target_pi) {
            Some(map) => *map,
            None => {
                if count_ptr != 0 {
                    let _ = self.xas_write_u64(count_ptr, 0);
                }
                return nt_process::STATUS_INVALID_HANDLE;
            }
        };

        let mut transferred = 0u64;
        let mut buffer = [0u8; 256];
        while transferred < length {
            let remote_address = remote + transferred;
            let local_address = local + transferred;
            let remote_page = 0x1000 - (remote_address as usize & 0xfff);
            let local_page = 0x1000 - (local_address as usize & 0xfff);
            let chunk = (length - transferred)
                .min(buffer.len() as u64)
                .min(remote_page as u64)
                .min(local_page as u64) as usize;
            let private_extent = target_vm.extent_at(remote_address);
            let protection_allows = private_extent.is_none()
                || if read {
                    target_vm.permits_read(remote_address)
                } else {
                    target_vm.permits_write(remote_address)
                };
            let mut local_copied = false;
            let mut remote_copied = false;
            let copied = if !protection_allows {
                false
            } else if read {
                remote_copied = client_copyin_process_mapped(
                    target_pi as u64,
                    remote_address,
                    &mut buffer[..chunk],
                    target_filled,
                    target_faults,
                    target.scratch_base,
                    target_pi == self.pi,
                );
                local_copied =
                    remote_copied && self.xas_try_write_buf(local_address, &buffer[..chunk]);
                local_copied
            } else {
                local_copied = self.xas_read(local_address, &mut buffer[..chunk]);
                remote_copied = local_copied
                    && if target_pi == self.pi {
                        self.xas_try_write_buf(remote_address, &buffer[..chunk])
                    } else {
                        client_copyout_mapped(
                            target_pi as u64,
                            remote_address,
                            &buffer[..chunk],
                            target_filled,
                            target_faults,
                            target.scratch_base,
                        )
                    };
                remote_copied
            };
            if !copied {
                if self.current_process_is_winlogon() && target_pi != self.pi {
                    let (frame, _) =
                        csrss_frame_get_exact(target_pi as u64, remote_address & !0xfff);
                    print_str(b"[remote-vm] write failed target_pi=");
                    print_u64(target_pi as u64);
                    print_str(b" remote=0x");
                    print_hex((remote_address >> 32) as u32);
                    print_hex(remote_address as u32);
                    print_str(b" local=0x");
                    print_hex((local_address >> 32) as u32);
                    print_hex(local_address as u32);
                    print_str(b" chunk=0x");
                    print_hex(chunk as u32);
                    print_str(b" local_ok=");
                    print_u64(local_copied as u64);
                    print_str(b" remote_ok=");
                    print_u64(remote_copied as u64);
                    print_str(b" protection_ok=");
                    print_u64(protection_allows as u64);
                    print_str(b" frame=0x");
                    print_hex(frame as u32);
                    print_str(b" vad=");
                    print_u64(private_extent.is_some() as u64);
                    print_str(b"\n");
                }
                break;
            }
            transferred += chunk as u64;
        }
        if count_ptr != 0 {
            let _ = self.xas_write_u64(count_ptr, transferred);
        }
        if transferred == length {
            0
        } else {
            STATUS_PARTIAL_COPY
        }
    }

    unsafe fn nt_flush_virtual_memory(&mut self, args: &[u64]) -> u32 {
        const PROCESS_VM_OPERATION: u32 = 0x0008;
        const STATUS_INVALID_PARAMETER_2: u32 = 0xC000_00F0;
        let base_ptr = args.get(1).copied().unwrap_or(0);
        let size_ptr = args.get(2).copied().unwrap_or(0);
        let iosb = args.get(3).copied().unwrap_or(0);
        if base_ptr & 7 != 0 || size_ptr & 7 != 0 || iosb & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if !self.probe_user_output(base_ptr, 8)
            || !self.probe_user_output(size_ptr, 8)
            || !self.probe_user_output(iosb, 16)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut word = [0u8; 8];
        if !self.xas_read(base_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let base = u64::from_le_bytes(word);
        if !self.xas_read(size_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let size = u64::from_le_bytes(word);
        if base > HIGHEST_USER_ADDRESS
            || size > HIGHEST_USER_ADDRESS.saturating_add(1).saturating_sub(base)
        {
            return STATUS_INVALID_PARAMETER_2;
        }

        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[0], PROCESS_VM_OPERATION) {
                Ok(target) => target,
                Err(status) => return status,
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }
        let Some(ctx) = self.loop_ctx else {
            return STATUS_INVALID_HANDLE;
        };
        let generic_sections = &mut *ctx.generic_sections;
        let plan = match generic_sections.plan_flush(target_pi, base, size) {
            Ok(plan) => plan,
            Err(status) => return status,
        };
        let (status, information) = match service_generic_section_writeback_plan(
            generic_sections,
            plan,
            ctx.scratch_base,
        ) {
            Ok(written) => {
                if written != 0 {
                    self.writable_fs_dirty = true;
                }
                (0, plan.size)
            }
            Err(status) => (status, 0),
        };

        if !self.xas_try_write_buf(base_ptr, &plan.base.to_le_bytes())
            || !self.xas_try_write_buf(size_ptr, &plan.size.to_le_bytes())
            || !self.write_current_iosb(iosb, status, information)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        status
    }

    unsafe fn nt_free_virtual_memory(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER_3: u32 = 0xC000_00F1;
        const PROCESS_VM_OPERATION: u32 = 0x0008;
        const HIGHEST_USER_ADDRESS: u64 = 0x0000_07ff_fffe_ffff;

        let free_type = nt_ulong_arg(args[3]);
        if free_type != nt_address_space::MEM_RELEASE && free_type != nt_address_space::MEM_DECOMMIT
        {
            return nt_address_space::STATUS_INVALID_PARAMETER_4;
        }
        let base_ptr = args[1];
        let size_ptr = args[2];
        if !self.probe_user_output(base_ptr, 8) || !self.probe_user_output(size_ptr, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut word = [0u8; 8];
        if !self.xas_read(base_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let base = u64::from_le_bytes(word);
        if !self.xas_read(size_ptr, &mut word) {
            return STATUS_ACCESS_VIOLATION;
        }
        let size = u64::from_le_bytes(word);
        if base >= HIGHEST_USER_ADDRESS {
            return nt_address_space::STATUS_INVALID_PARAMETER_2;
        }
        if HIGHEST_USER_ADDRESS - base < size {
            return STATUS_INVALID_PARAMETER_3;
        }

        let (target_pid, target_pi) =
            match self.resolve_process_for_access(args[0], PROCESS_VM_OPERATION) {
                Ok(target) => target,
                Err(status) => return status,
            };
        if self.pm.process(target_pid).is_some_and(|process| {
            matches!(
                process.state,
                nt_process::ProcessState::Exiting | nt_process::ProcessState::Terminated
            )
        }) {
            return nt_process::STATUS_PROCESS_IS_TERMINATING;
        }
        let Some(vm_map) = process_vm_region_map_mut(target_pi) else {
            return nt_process::STATUS_INVALID_HANDLE;
        };
        // ★ The before/after snapshots live in STATIC scratch, never on the stack. The executive's
        // rootserver stack floats immediately after its loaded image and is only a few pages; a
        // whole `VmRegionMap` is kilobytes, so taking two copies per call overflowed straight into
        // the guard page the moment [`VM_REGION_CAPACITY`] was raised (measured: a `#PF err=6` in
        // the executive at `.bss_end + 0x898`, one page past the mapped image, during smss' spawn).
        // Single-threaded executive, and neither scratch outlives this call.
        let before = &mut *core::ptr::addr_of_mut!(VM_MAP_BEFORE);
        let after = &mut *core::ptr::addr_of_mut!(VM_MAP_AFTER);
        *before = *vm_map;
        *after = *before;
        let plan = match after.free(base, size, free_type) {
            Ok(plan) => plan,
            Err(status) => return status,
        };
        let _ = vm_page_lock_retire_range(target_pi as u64, plan.base, plan.size);
        let mut page = plan.base;
        while page < plan.base + plan.size {
            let old = before.extent_at(page);
            let new = after.extent_at(page);
            if old.is_some_and(|extent| extent.state == nt_address_space::VmExtentState::Committed)
                && new
                    .is_none_or(|extent| extent.state != nt_address_space::VmExtentState::Committed)
            {
                vm_unmap_private_page(target_pi, page);
            }
            page += 0x1000;
        }
        *vm_map = *after;
        let _ = self.xas_write_u64(size_ptr, plan.size);
        let _ = self.xas_write_u64(base_ptr, plan.base);
        0
    }

    fn token_id_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<nt_security::TokenId, u32> {
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        if handle > u32::MAX as u64 {
            return Err(STATUS_INVALID_HANDLE);
        }
        let caller = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let object = self
            .pm
            .lookup_handle(caller, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        let token = match object {
            nt_process::HandleObject::TokenObject(token) => token,
            nt_process::HandleObject::Token(pid) => self
                .pm
                .process_primary_token(pid)
                .ok_or(STATUS_INVALID_HANDLE)?,
            _ => return Err(STATUS_OBJECT_TYPE_MISMATCH),
        };
        let granted = self
            .pm
            .handle_access(caller, handle as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        if granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        self.token_store
            .get(token)
            .map(|_| token)
            .ok_or(STATUS_INVALID_HANDLE)
    }

    fn current_token_has_privilege(&self, name: &str) -> bool {
        self.pm
            .effective_token(self.current_tid as nt_process::ThreadId)
            .and_then(|token| self.token_store.get(token))
            .is_some_and(|token| token.has_privilege(name))
    }

    unsafe fn nt_set_system_time(&mut self, ctx: &NativeCallContext, args: &[u64]) -> u32 {
        let new_time = args[0];
        let previous_time = args[1];
        if ctx.previous_mode != nt_syscall::ProcessorMode::KernelMode
            && (new_time != 0 && new_time & 7 != 0 || previous_time != 0 && previous_time & 7 != 0)
        {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if new_time != 0 && !self.probe_user_input(new_time, 8)
            || previous_time != 0 && !self.probe_user_output(previous_time, 8)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        if ctx.previous_mode != nt_syscall::ProcessorMode::KernelMode
            && !self.current_token_has_privilege(nt_security::SE_SYSTEM_TIME)
        {
            return STATUS_PRIVILEGE_NOT_HELD;
        }

        let refreshed_time_zone = (new_time == 0).then(|| seed_time_zone(&self.mutable_hives));
        let refreshed_real_time_is_universal =
            (new_time == 0).then(|| seed_real_time_is_universal(&self.mutable_hives));
        let requested_system_time = if new_time == 0 {
            let persistent_time = match persistent_clock_read_100ns() {
                Ok(time) => time,
                Err(error) => return persistent_clock_error_status(error),
            };
            if refreshed_real_time_is_universal.unwrap() {
                persistent_time
            } else {
                let current = nt_system_time_100ns();
                let bias =
                    effective_time_zone(refreshed_time_zone.as_ref().unwrap(), current).bias_100ns;
                let Some(system_time) = adjusted_native_time(persistent_time, bias) else {
                    return STATUS_INVALID_PARAMETER;
                };
                system_time
            }
        } else {
            let mut encoded = [0u8; 8];
            if !self.xas_read(new_time, &mut encoded) {
                return STATUS_ACCESS_VIOLATION;
            }
            let captured = i64::from_le_bytes(encoded);
            if captured < 0
                || nt_time::validate_system_time(captured as u64)
                    == Err(nt_time::ClockError::InvalidSystemTime)
            {
                return STATUS_INVALID_PARAMETER;
            }
            captured as u64
        };

        if new_time != 0 {
            let persistent_time = if self.real_time_is_universal {
                requested_system_time
            } else {
                let bias = effective_time_zone(&self.time_zone_information, requested_system_time)
                    .bias_100ns;
                let Some(local_time) = adjusted_native_time(requested_system_time, -bias) else {
                    return STATUS_INVALID_PARAMETER;
                };
                local_time
            };
            if let Err(error) = persistent_clock_write_100ns(persistent_time) {
                return persistent_clock_error_status(error);
            }
        }

        let change = match nt_set_system_time_100ns(requested_system_time) {
            Ok(change) => change,
            Err(nt_time::ClockError::InvalidSystemTime) => return STATUS_INVALID_PARAMETER,
            Err(nt_time::ClockError::MonotonicRegression) => return STATUS_UNSUCCESSFUL,
        };
        if let Some(information) = refreshed_time_zone {
            self.time_zone_information = information;
            self.real_time_is_universal = refreshed_real_time_is_universal.unwrap();
        }
        // Latch this before the optional copyout: NT has already moved the clock if that later
        // write faults, so the service-loop tail must still publish and re-evaluate deadlines.
        self.system_time_change = Some(change);
        if previous_time != 0
            && !self.xas_try_write_buf(previous_time, &change.previous_100ns.to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        print_str(b"[system-time] generation=");
        print_u64(change.clock_generation);
        print_str(b" previous=");
        print_u64(change.previous_100ns);
        print_str(b" current=");
        print_u64(change.current_100ns);
        print_str(b" delta=");
        if change.delta_100ns < 0 {
            print_str(b"-");
            print_u64(change.delta_100ns.unsigned_abs().min(u64::MAX as u128) as u64);
        } else {
            print_u64((change.delta_100ns as u128).min(u64::MAX as u128) as u64);
        }
        print_str(b" source=");
        print_str(if new_time == 0 {
            b"persistent-refresh"
        } else {
            b"caller-writeback"
        });
        print_str(b"\n");
        0
    }

    fn pnp_query(
        query_kind: u16,
        selector: u32,
        instance: &str,
        auxiliary: &[u8],
    ) -> Result<nt_config_client::PnpQuerySnapshot, u32> {
        unsafe { config_manager_query_pnp(query_kind, selector, instance, auxiliary) }
            .map_err(|status| status as u32)
    }

    fn pnp_device_exists(instance: &str) -> Result<bool, u32> {
        match Self::pnp_query(
            nt_config_abi::pnp_query_kind::DEVICE_EXISTS,
            0,
            instance,
            &[],
        ) {
            Ok(_) => Ok(true),
            Err(STATUS_NO_SUCH_DEVICE) => Ok(false),
            Err(status) => Err(status),
        }
    }

    fn pnp_append_utf16_z(out: &mut alloc::vec::Vec<u8>, s: &str) {
        append_utf16le(out, s);
        out.extend_from_slice(&0u16.to_le_bytes());
    }

    fn pnp_encode_multi_sz_from_strings(strings: &[alloc::string::String]) -> alloc::vec::Vec<u8> {
        let mut out = alloc::vec::Vec::new();
        for s in strings {
            Self::pnp_append_utf16_z(&mut out, s);
        }
        out.extend_from_slice(&0u16.to_le_bytes());
        out
    }

    fn pnp_encode_device_install_event(instance: &str) -> alloc::vec::Vec<u8> {
        let total = PNP_EVENT_BLOCK_INSTALL_DEVICE_OFFSET
            .saturating_add(utf16le_byte_len(instance))
            .saturating_add(2);
        let mut out = alloc::vec![0u8; PNP_EVENT_BLOCK_INSTALL_DEVICE_OFFSET];
        out[..GUID_DEVICE_ENUMERATED_BYTES.len()].copy_from_slice(&GUID_DEVICE_ENUMERATED_BYTES);
        out[16..20].copy_from_slice(&PNP_EVENT_CATEGORY_DEVICE_INSTALL.to_le_bytes());
        out[36..40].copy_from_slice(&(total as u32).to_le_bytes());
        Self::pnp_append_utf16_z(&mut out, instance);
        out
    }

    fn pnp_event_wait_object(&mut self) -> Result<WaitObject, u32> {
        if self.pnp_notify_event == 0 {
            self.pnp_notify_event = self
                .obj_create_internal_dispatcher_event(true, false)
                .ok_or(STATUS_DEVICE_NOT_READY)?;
        }
        Ok(WaitObject::dispatcher(self.pnp_notify_event as usize))
    }

    unsafe fn pnp_read_u32(&self, va: u64) -> Result<u32, u32> {
        let mut bytes = [0u8; 4];
        if va == 0 || !self.xas_read(va, &mut bytes) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        Ok(u32::from_le_bytes(bytes))
    }

    unsafe fn pnp_read_u64(&self, va: u64) -> Result<u64, u32> {
        let mut bytes = [0u8; 8];
        if va == 0 || !self.xas_read(va, &mut bytes) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        Ok(u64::from_le_bytes(bytes))
    }

    unsafe fn pnp_read_device_instance(
        &self,
        control_buffer: u64,
    ) -> Result<alloc::string::String, u32> {
        let name16 = self.read_unicode_string16(control_buffer)?;
        let instance = utf16_units_to_string(&name16);
        if instance.is_empty() {
            Err(STATUS_INVALID_PARAMETER)
        } else {
            Ok(instance)
        }
    }

    unsafe fn nt_get_plug_play_event(&mut self, args: &[u64]) -> u32 {
        let reserved1 = args.first().copied().unwrap_or(0);
        let reserved2 = args.get(1).copied().unwrap_or(0);
        let buffer = args.get(2).copied().unwrap_or(0);
        let buffer_size = nt_ulong_arg(args.get(3).copied().unwrap_or(0)) as usize;
        if reserved1 != 0 || reserved2 != 0 {
            return STATUS_INVALID_PARAMETER;
        }
        if !self.current_token_has_privilege(nt_security::SE_TCB) {
            return STATUS_PRIVILEGE_NOT_HELD;
        }

        let instance = match Self::pnp_query(
            nt_config_abi::pnp_query_kind::ENUMERATE_DEVNODE,
            self.pnp_event_cursor.min(u32::MAX as usize) as u32,
            "",
            &[],
        ) {
            Ok(snapshot) if snapshot.strings.len() == 1 && snapshot.payload.is_empty() => {
                snapshot.strings.into_iter().next().unwrap()
            }
            Err(STATUS_NO_MORE_ENTRIES) => {
                let Ok(object) = self.pnp_event_wait_object() else {
                    return STATUS_DEVICE_NOT_READY;
                };
                self.wait_park_event = object.raw() as i64;
                self.wait_timeout = PendingWaitTimeout::none();
                return 0x102;
            }
            Err(status) => return status,
            _ => return STATUS_INVALID_PARAMETER,
        };

        let event = Self::pnp_encode_device_install_event(&instance);
        if buffer_size < event.len() {
            return STATUS_BUFFER_TOO_SMALL;
        }
        if !self.probe_user_output(buffer, event.len()) || !self.xas_try_write_buf(buffer, &event) {
            return STATUS_ACCESS_VIOLATION;
        }
        if self.pnp_notify_event != 0 {
            let _ = self.events.reset_existing(self.pnp_notify_event);
        }
        0
    }

    unsafe fn nt_plug_play_control(&mut self, args: &[u64]) -> u32 {
        let control_class = nt_ulong_arg(args.first().copied().unwrap_or(0));
        let buffer = args.get(1).copied().unwrap_or(0);
        let buffer_len = nt_ulong_arg(args.get(2).copied().unwrap_or(0)) as usize;
        if !self.current_token_has_privilege(nt_security::SE_TCB) {
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        if buffer_len != 0 && !self.probe_user_output(buffer, buffer_len) {
            return STATUS_ACCESS_VIOLATION;
        }

        match control_class {
            0 => self.pnp_control_known_device_action(
                buffer,
                buffer_len,
                PNP_CONTROL_ENUMERATE_DEVICE_LEN,
            ),
            3 | 4 | 20 => self.pnp_control_known_device_action(
                buffer,
                buffer_len,
                PNP_CONTROL_DEVICE_CONTROL_LEN,
            ),
            6 => self.pnp_control_query_remove(buffer, buffer_len),
            7 => self.pnp_control_user_response(buffer, buffer_len),
            9 => self.pnp_control_interface_device_list(buffer, buffer_len),
            10 => self.pnp_control_property(buffer, buffer_len),
            12 => self.pnp_control_related_device(buffer, buffer_len),
            14 => self.pnp_control_device_status(buffer, buffer_len),
            15 => self.pnp_control_device_depth(buffer, buffer_len),
            16 => self.pnp_control_device_relations(buffer, buffer_len),
            _ => STATUS_NOT_SUPPORTED,
        }
    }

    unsafe fn pnp_control_known_device_action(
        &self,
        buffer: u64,
        buffer_len: usize,
        required_len: usize,
    ) -> u32 {
        if buffer == 0 || buffer_len < required_len {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        match Self::pnp_device_exists(&instance) {
            Ok(true) => 0,
            Ok(false) => STATUS_NO_SUCH_DEVICE,
            Err(status) => status,
        }
    }

    unsafe fn pnp_control_query_remove(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_QUERY_REMOVE_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        match Self::pnp_device_exists(&instance) {
            Ok(true) => 0,
            Ok(false) => STATUS_NO_SUCH_DEVICE,
            Err(status) => status,
        }
    }

    unsafe fn pnp_control_user_response(&mut self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_USER_RESPONSE_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        self.pnp_event_cursor = self.pnp_event_cursor.saturating_add(1);
        if Self::pnp_query(
            nt_config_abi::pnp_query_kind::ENUMERATE_DEVNODE,
            self.pnp_event_cursor.min(u32::MAX as usize) as u32,
            "",
            &[],
        )
        .is_ok()
        {
            if self.pnp_notify_event != 0 {
                let _ = self.events.set_existing(self.pnp_notify_event);
                unsafe { wait_wake_dispatcher_set(self) };
            }
        }
        0
    }

    unsafe fn pnp_write_sized_output(
        &self,
        size_field: u64,
        output: u64,
        output_size: usize,
        data: &[u8],
    ) -> u32 {
        if !self.xas_write_u32(size_field, data.len().min(u32::MAX as usize) as u32) {
            return STATUS_ACCESS_VIOLATION;
        }
        if data.is_empty() {
            return 0;
        }
        if output == 0 || output_size < data.len() {
            return STATUS_BUFFER_TOO_SMALL;
        }
        if !self.probe_user_output(output, data.len()) || !self.xas_try_write_buf(output, data) {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    unsafe fn pnp_control_interface_device_list(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_INTERFACE_LIST_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let filter_guid = match self.pnp_read_u64(buffer + 16) {
            Ok(ptr) => ptr,
            Err(status) => return status,
        };
        let output = match self.pnp_read_u64(buffer + 32) {
            Ok(ptr) => ptr,
            Err(status) => return status,
        };
        let output_size = match self.pnp_read_u32(buffer + 40) {
            Ok(size) => size as usize,
            Err(status) => return status,
        };
        let mut guid = [0u8; 16];
        if filter_guid == 0 || !self.xas_read(filter_guid, &mut guid) {
            return STATUS_ACCESS_VIOLATION;
        }
        let links = match Self::pnp_query(
            nt_config_abi::pnp_query_kind::INTERFACE_LINKS,
            0,
            &instance,
            &guid,
        ) {
            Ok(snapshot) if snapshot.payload.is_empty() => snapshot.strings,
            Ok(_) => return STATUS_INVALID_PARAMETER,
            Err(status) => return status,
        };
        let mut list = alloc::vec::Vec::new();
        for link in links {
            Self::pnp_append_utf16_z(&mut list, &link);
        }
        list.extend_from_slice(&0u16.to_le_bytes());
        if !self.xas_write_u32(buffer + 40, list.len().min(u32::MAX as usize) as u32) {
            return STATUS_ACCESS_VIOLATION;
        }
        if output != 0 && output_size >= list.len() {
            if !self.probe_user_output(output, list.len()) || !self.xas_try_write_buf(output, &list)
            {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        0
    }

    unsafe fn pnp_control_property(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_PROPERTY_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let property = match self.pnp_read_u32(buffer + 16) {
            Ok(property) => property,
            Err(status) => return status,
        };
        let output = match self.pnp_read_u64(buffer + 24) {
            Ok(ptr) => ptr,
            Err(status) => return status,
        };
        let output_size = match self.pnp_read_u32(buffer + 32) {
            Ok(size) => size as usize,
            Err(status) => return status,
        };
        let data = match Self::pnp_query(
            nt_config_abi::pnp_query_kind::DYNAMIC_PROPERTY,
            property,
            &instance,
            &[],
        ) {
            Ok(snapshot) if snapshot.strings.is_empty() => snapshot.payload,
            Ok(_) => return STATUS_INVALID_PARAMETER,
            Err(STATUS_OBJECT_NAME_NOT_FOUND) => {
                let _ = self.xas_write_u32(buffer + 32, 0);
                return STATUS_OBJECT_NAME_NOT_FOUND;
            }
            Err(status) => return status,
        };
        self.pnp_write_sized_output(buffer + 32, output, output_size, &data)
    }

    unsafe fn pnp_control_related_device(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_RELATED_DEVICE_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let relation = match self.pnp_read_u32(buffer + 16) {
            Ok(relation) => relation,
            Err(status) => return status,
        };
        if !matches!(
            relation,
            nt_config_manager::pnp_relation::PARENT
                | nt_config_manager::pnp_relation::CHILD
                | nt_config_manager::pnp_relation::SIBLING
        ) {
            return STATUS_INVALID_PARAMETER;
        }
        let output = match self.pnp_read_u64(buffer + 24) {
            Ok(ptr) => ptr,
            Err(status) => return status,
        };
        let output_size = match self.pnp_read_u32(buffer + 32) {
            Ok(size) => size as usize,
            Err(status) => return status,
        };
        let related = match Self::pnp_query(
            nt_config_abi::pnp_query_kind::RELATED_DEVICE,
            relation,
            &instance,
            &[],
        ) {
            Ok(snapshot) if snapshot.strings.len() == 1 && snapshot.payload.is_empty() => {
                snapshot.strings.into_iter().next().unwrap()
            }
            Ok(_) => return STATUS_INVALID_PARAMETER,
            Err(status) => return status,
        };
        let mut data = alloc::vec::Vec::new();
        append_utf16le(&mut data, &related);
        self.pnp_write_sized_output(buffer + 32, output, output_size, &data)
    }

    fn pnp_status_slot(&self, instance: &str) -> Option<usize> {
        self.pnp_status.records.iter().position(|record| {
            record.occupied && record.instance_id.as_str().eq_ignore_ascii_case(instance)
        })
    }

    fn pnp_status_free_slot(&self) -> Option<usize> {
        self.pnp_status
            .records
            .iter()
            .position(|record| !record.occupied)
    }

    fn pnp_status_alloc_slot(&mut self) -> Option<usize> {
        if let Some(slot) = self.pnp_status_free_slot() {
            return Some(slot);
        }
        if self.pnp_status.records.len() == self.pnp_status.records.capacity() {
            let additional = self.pnp_status.records.capacity().max(16);
            if self.pnp_status.records.try_reserve(additional).is_err() {
                print_str(b"[pnp-status] failed to grow runtime status table\n");
                return None;
            }
            print_str(b"[pnp-status] grew runtime status table capacity=");
            print_u64(self.pnp_status.records.capacity() as u64);
            print_str(b"\n");
        }
        let slot = self.pnp_status.records.len();
        self.pnp_status
            .records
            .push(PnpRuntimeStatusRecord::empty());
        Some(slot)
    }

    fn pnp_runtime_status(&self, instance: &str) -> (u32, u32) {
        self.pnp_status_slot(instance)
            .map(|slot| {
                let record = self.pnp_status.records[slot];
                (record.status, record.problem)
            })
            .unwrap_or((0, 0))
    }

    fn pnp_store_runtime_status(&mut self, instance: &str, status: u32, problem: u32) -> u32 {
        if status == 0 && problem == 0 {
            if let Some(slot) = self.pnp_status_slot(instance) {
                self.pnp_status.records[slot] = PnpRuntimeStatusRecord::empty();
            }
            return 0;
        }
        let slot = match self.pnp_status_slot(instance) {
            Some(slot) => slot,
            None => {
                let Some(slot) = self.pnp_status_alloc_slot() else {
                    return STATUS_INSUFFICIENT_RESOURCES;
                };
                slot
            }
        };
        let mut record = PnpRuntimeStatusRecord::empty();
        if !record.instance_id.set_str(instance) {
            return STATUS_INVALID_PARAMETER;
        }
        record.status = status;
        record.problem = problem;
        record.occupied = true;
        self.pnp_status.records[slot] = record;
        0
    }

    fn pnp_clear_runtime_status(&mut self, instance: &str, status: u32, problem: u32) -> u32 {
        let (current_status, current_problem) = self.pnp_runtime_status(instance);
        let next_status = current_status & !status;
        let next_problem = if problem == 0 || problem == current_problem {
            0
        } else {
            current_problem
        };
        self.pnp_store_runtime_status(instance, next_status, next_problem)
    }

    unsafe fn pnp_control_device_status(&mut self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_STATUS_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let operation = match self.pnp_read_u32(buffer + 16) {
            Ok(operation) => operation,
            Err(status) => return status,
        };
        match Self::pnp_device_exists(&instance) {
            Ok(true) => {}
            Ok(false) => return STATUS_NO_SUCH_DEVICE,
            Err(status) => return status,
        }
        match operation {
            PNP_GET_DEVICE_STATUS => {
                let (status, problem) = self.pnp_runtime_status(&instance);
                if !self.xas_write_u32(buffer + 20, status)
                    || !self.xas_write_u32(buffer + 24, problem)
                {
                    return STATUS_ACCESS_VIOLATION;
                }
                0
            }
            PNP_SET_DEVICE_STATUS => {
                let status = match self.pnp_read_u32(buffer + 20) {
                    Ok(status) => status,
                    Err(status) => return status,
                };
                let problem = match self.pnp_read_u32(buffer + 24) {
                    Ok(problem) => problem,
                    Err(status) => return status,
                };
                self.pnp_store_runtime_status(&instance, status, problem)
            }
            PNP_CLEAR_DEVICE_STATUS => {
                let status = match self.pnp_read_u32(buffer + 20) {
                    Ok(status) => status,
                    Err(status) => return status,
                };
                let problem = match self.pnp_read_u32(buffer + 24) {
                    Ok(problem) => problem,
                    Err(status) => return status,
                };
                self.pnp_clear_runtime_status(&instance, status, problem)
            }
            _ => STATUS_INVALID_PARAMETER,
        }
    }

    unsafe fn pnp_control_device_depth(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_DEPTH_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let depth = match Self::pnp_query(
            nt_config_abi::pnp_query_kind::DEVICE_DEPTH,
            0,
            &instance,
            &[],
        ) {
            Ok(snapshot) if snapshot.strings.is_empty() && snapshot.payload.len() == 4 => {
                u32::from_le_bytes(snapshot.payload.try_into().unwrap())
            }
            Ok(_) => return STATUS_INVALID_PARAMETER,
            Err(status) => return status,
        };
        if !self.xas_write_u32(buffer + 16, depth) {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    unsafe fn pnp_control_device_relations(&self, buffer: u64, buffer_len: usize) -> u32 {
        if buffer == 0 || buffer_len < PNP_CONTROL_RELATIONS_LEN {
            return STATUS_INVALID_PARAMETER;
        }
        let instance = match self.pnp_read_device_instance(buffer) {
            Ok(instance) => instance,
            Err(status) => return status,
        };
        let relations = match self.pnp_read_u32(buffer + 16) {
            Ok(relations) => relations,
            Err(status) => return status,
        };
        let output_size = match self.pnp_read_u32(buffer + 20) {
            Ok(size) => size as usize,
            Err(status) => return status,
        };
        let output = match self.pnp_read_u64(buffer + 24) {
            Ok(ptr) => ptr,
            Err(status) => return status,
        };
        if relations > PNP_BUS_RELATIONS {
            return STATUS_INVALID_PARAMETER;
        }
        let data = if relations == PNP_BUS_RELATIONS {
            match Self::pnp_query(
                nt_config_abi::pnp_query_kind::BUS_RELATIONS,
                0,
                &instance,
                &[],
            ) {
                Ok(snapshot) if snapshot.payload.is_empty() => {
                    Self::pnp_encode_multi_sz_from_strings(&snapshot.strings)
                }
                Ok(_) => return STATUS_INVALID_PARAMETER,
                Err(status) => return status,
            }
        } else {
            match Self::pnp_device_exists(&instance) {
                Ok(true) => alloc::vec::Vec::new(),
                Ok(false) => return STATUS_NO_SUCH_DEVICE,
                Err(status) => return status,
            }
        };
        self.pnp_write_sized_output(buffer + 20, output, output_size, &data)
    }

    unsafe fn write_access_check_privilege_set(
        &self,
        privilege_set: u64,
        privilege_set_length: u64,
        captured_length: u32,
        privileges_used: &[&'static str],
    ) -> Result<(), u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_BUFFER_TOO_SMALL: u32 = 0xC000_0023;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        const PRIVILEGE_SET_MIN_SIZE: usize = 20; // sizeof(PRIVILEGE_SET), including ANYSIZE_ARRAY[1].
        const PRIVILEGE_SET_HEADER_SIZE: usize = 8;
        const LUID_AND_ATTRIBUTES_SIZE: usize = 12;
        const SE_PRIVILEGE_USED_FOR_ACCESS: u32 = 0x8000_0000;

        let mut luids = [nt_security::Luid::default(); 4];
        let mut count = 0usize;
        for name in privileges_used {
            let Some(luid) = nt_security::luid_for_privilege_name(name) else {
                continue;
            };
            let Some(slot) = luids.get_mut(count) else {
                return Err(STATUS_INSUFFICIENT_RESOURCES);
            };
            *slot = luid;
            count += 1;
        }
        let required = PRIVILEGE_SET_HEADER_SIZE
            .checked_add(
                count
                    .checked_mul(LUID_AND_ATTRIBUTES_SIZE)
                    .ok_or(STATUS_INSUFFICIENT_RESOURCES)?,
            )
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?
            .max(PRIVILEGE_SET_MIN_SIZE);
        if captured_length < required as u32 {
            if !self.xas_write_u32(privilege_set_length, required as u32) {
                return Err(STATUS_ACCESS_VIOLATION);
            }
            return Err(STATUS_BUFFER_TOO_SMALL);
        }

        let mut output = [0u8; 64];
        output[0..4].copy_from_slice(&(count as u32).to_le_bytes());
        for (index, luid) in luids[..count].iter().enumerate() {
            let offset = PRIVILEGE_SET_HEADER_SIZE + index * LUID_AND_ATTRIBUTES_SIZE;
            output[offset..offset + 4].copy_from_slice(&luid.low.to_le_bytes());
            output[offset + 4..offset + 8].copy_from_slice(&luid.high.to_le_bytes());
            output[offset + 8..offset + 12]
                .copy_from_slice(&SE_PRIVILEGE_USED_FOR_ACCESS.to_le_bytes());
        }
        if !self.xas_try_write_buf(privilege_set, &output[..required]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        Ok(())
    }

    /// `NtAccessCheck(SecurityDescriptor, ClientToken, DesiredAccess, GenericMapping, PrivilegeSet,
    /// PrivilegeSetLength, GrantedAccess, AccessStatus)` — `ntoskrnl/se/accesschk.c:NtAccessCheck`.
    unsafe fn nt_access_check(&mut self, ctx: &NativeCallContext, args: &[u64]) -> u32 {
        if args.len() < 8 {
            return STATUS_INVALID_PARAMETER;
        }
        self.nt_access_check_common(ctx, args, false, false)
    }

    unsafe fn nt_access_check_by_type(
        &mut self,
        ctx: &NativeCallContext,
        args: &[u64],
        use_result_list: bool,
    ) -> u32 {
        if args.len() < 11 {
            return STATUS_INVALID_PARAMETER;
        }
        self.nt_access_check_common(ctx, args, true, use_result_list)
    }

    unsafe fn nt_access_check_common(
        &mut self,
        ctx: &NativeCallContext,
        args: &[u64],
        by_type: bool,
        use_result_list: bool,
    ) -> u32 {
        const STATUS_GENERIC_NOT_MAPPED: u32 = 0xC000_00E6;
        const STATUS_NO_IMPERSONATION_TOKEN: u32 = 0xC000_005C;
        const TOKEN_QUERY: u32 = nt_security::TOKEN_QUERY;
        const GENERIC_MASK: u32 = nt_security::GENERIC_ALL
            | nt_security::GENERIC_EXECUTE
            | nt_security::GENERIC_READ
            | nt_security::GENERIC_WRITE;

        let (
            security_descriptor,
            principal_self,
            token_handle,
            desired_access,
            object_type_list,
            object_type_count,
            mapping_pointer,
            privilege_set,
            privilege_set_length,
            granted_access,
            access_status,
        ) = if by_type {
            (
                args[0],
                args[1],
                args[2],
                nt_ulong_arg(args[3]),
                args[4],
                nt_ulong_arg(args[5]),
                args[6],
                args[7],
                args[8],
                args[9],
                args[10],
            )
        } else {
            (
                args[0],
                0,
                args[1],
                nt_ulong_arg(args[2]),
                0,
                0,
                args[3],
                args[4],
                args[5],
                args[6],
                args[7],
            )
        };

        if mapping_pointer & 3 != 0
            || privilege_set_length & 3 != 0
            || granted_access & 3 != 0
            || access_status & 3 != 0
        {
            return STATUS_DATATYPE_MISALIGNMENT;
        }

        let mut mapping_bytes = [0u8; 16];
        if mapping_pointer == 0 || !self.xas_read(mapping_pointer, &mut mapping_bytes) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut privilege_set_length_bytes = [0u8; 4];
        if privilege_set_length == 0
            || !self.xas_read(privilege_set_length, &mut privilege_set_length_bytes)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let captured_privilege_set_length = u32::from_le_bytes(privilege_set_length_bytes);
        if captured_privilege_set_length != 0 {
            if privilege_set & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            if !self.probe_user_output(privilege_set, captured_privilege_set_length as usize) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        if use_result_list && object_type_count == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        if object_type_count > nt_security::MAX_CAPTURED_OBJECT_TYPES {
            return STATUS_INVALID_PARAMETER;
        }
        let result_count = if use_result_list {
            object_type_count as usize
        } else {
            1
        };
        let result_bytes = match result_count.checked_mul(4) {
            Some(bytes) => bytes,
            None => return STATUS_INVALID_PARAMETER,
        };
        if !self.probe_user_output(granted_access, result_bytes)
            || !self.probe_user_output(access_status, result_bytes)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        if desired_access & GENERIC_MASK != 0 {
            return STATUS_GENERIC_NOT_MAPPED;
        }

        let token_id = match self.token_id_for_handle(token_handle, TOKEN_QUERY) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let token = match self.token_store.get(token_id) {
            Some(token) => token,
            None => return STATUS_INVALID_HANDLE,
        };
        if token.token_type != nt_security::TokenType::Impersonation {
            return STATUS_NO_IMPERSONATION_TOKEN;
        }
        if token.impersonation_level < nt_security::SecurityImpersonationLevel::Identification {
            return nt_security::STATUS_BAD_IMPERSONATION_LEVEL;
        }

        let object_types = if by_type {
            let memory = ExecClientMemory { handler: &*self };
            match nt_security::capture_object_type_list(
                &memory,
                object_type_list,
                object_type_count,
            ) {
                Ok(list) => list,
                Err(status) => return status,
            }
        } else {
            alloc::vec::Vec::new()
        };

        let mapping = nt_security::GenericMapping {
            generic_read: u32::from_le_bytes(mapping_bytes[0..4].try_into().unwrap()),
            generic_write: u32::from_le_bytes(mapping_bytes[4..8].try_into().unwrap()),
            generic_execute: u32::from_le_bytes(mapping_bytes[8..12].try_into().unwrap()),
            generic_all: u32::from_le_bytes(mapping_bytes[12..16].try_into().unwrap()),
        };
        let sd = {
            let memory = ExecClientMemory { handler: &*self };
            nt_security::capture_security_descriptor(&memory, security_descriptor)
        };
        let sd = match sd {
            Ok(sd) => sd,
            Err(status) => return status,
        };
        if sd.owner.is_none() || sd.group.is_none() {
            return nt_security::STATUS_INVALID_SECURITY_DESCR;
        }
        let principal_self = if by_type && principal_self != 0 {
            let memory = ExecClientMemory { handler: &*self };
            match nt_security::capture_sid(&memory, principal_self) {
                Ok(sid) => Some(sid),
                Err(status) => return status,
            }
        } else {
            None
        };

        let mode = if ctx.previous_mode == nt_syscall::ProcessorMode::KernelMode {
            nt_security::ProcessorMode::KernelMode
        } else {
            nt_security::ProcessorMode::UserMode
        };
        let results = if by_type {
            match nt_security::access_check_by_type(
                &sd,
                token,
                principal_self.as_ref(),
                desired_access,
                &object_types,
                &mapping,
                mode,
                use_result_list,
            ) {
                Ok(results) => results,
                Err(status) => return status,
            }
        } else {
            let mut results = alloc::vec::Vec::with_capacity(1);
            results.push(nt_security::access_check(
                &sd,
                token,
                desired_access,
                &mapping,
                mode,
            ));
            results
        };
        let Some(first_result) = results.first() else {
            return STATUS_INVALID_PARAMETER;
        };
        if let Err(status) = self.write_access_check_privilege_set(
            privilege_set,
            privilege_set_length,
            captured_privilege_set_length,
            &first_result.privileges_used,
        ) {
            return status;
        }
        for (index, result) in results.iter().enumerate() {
            let offset = (index * 4) as u64;
            if !self.xas_write_u32(granted_access + offset, result.granted_access)
                || !self.xas_write_u32(access_status + offset, result.status)
            {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        0
    }

    /// `NtPrivilegeCheck(ClientToken, RequiredPrivileges, Result)` — capture the complete in/out
    /// privilege set, check enabled privileges on the referenced token, and return both the
    /// `SE_PRIVILEGE_USED_FOR_ACCESS` marks and the BOOLEAN decision.
    unsafe fn nt_privilege_check(&mut self, ctx: &NativeCallContext, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const TOKEN_QUERY: u32 = nt_security::TOKEN_QUERY;
        const HEADER_SIZE: usize = 8;
        const ENTRY_SIZE: usize = 12;
        const MAX_PRIVILEGES: usize = nt_security::MAX_CAPTURED_PRIVILEGES as usize;

        let required_set = args[1];
        let result_out = args[2];
        if required_set & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if required_set == 0
            || result_out == 0
            || !self.probe_user_output(required_set, HEADER_SIZE)
            || !self.probe_user_output(result_out, 1)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut header = [0u8; HEADER_SIZE];
        if !self.xas_read(required_set, &mut header) {
            return STATUS_ACCESS_VIOLATION;
        }
        let count = u32::from_le_bytes(header[0..4].try_into().unwrap()) as usize;
        let control = u32::from_le_bytes(header[4..8].try_into().unwrap());
        if count > MAX_PRIVILEGES {
            return STATUS_INVALID_PARAMETER;
        }
        let entries_size = match count.checked_mul(ENTRY_SIZE) {
            Some(size) => size,
            None => return STATUS_INVALID_PARAMETER,
        };
        let total_size = match HEADER_SIZE.checked_add(entries_size) {
            Some(size) => size,
            None => return STATUS_INVALID_PARAMETER,
        };
        if !self.probe_user_output(required_set, total_size) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut required = [nt_security::PrivilegeAdjustment::default(); MAX_PRIVILEGES];
        for (index, entry) in required[..count].iter_mut().enumerate() {
            let mut encoded = [0u8; ENTRY_SIZE];
            if !self.xas_read(
                required_set + HEADER_SIZE as u64 + index as u64 * ENTRY_SIZE as u64,
                &mut encoded,
            ) {
                return STATUS_ACCESS_VIOLATION;
            }
            entry.luid.low = u32::from_le_bytes(encoded[0..4].try_into().unwrap());
            entry.luid.high = i32::from_le_bytes(encoded[4..8].try_into().unwrap());
            entry.attributes = u32::from_le_bytes(encoded[8..12].try_into().unwrap());
        }

        let token_id = match self.token_id_for_handle(args[0], TOKEN_QUERY) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let token = match self.token_store.get(token_id) {
            Some(token) => token,
            None => return STATUS_INVALID_HANDLE,
        };
        if token.token_type == nt_security::TokenType::Impersonation
            && token.impersonation_level < nt_security::SecurityImpersonationLevel::Identification
        {
            return nt_security::STATUS_BAD_IMPERSONATION_LEVEL;
        }
        let mode = if ctx.previous_mode == nt_syscall::ProcessorMode::KernelMode {
            nt_security::ProcessorMode::KernelMode
        } else {
            nt_security::ProcessorMode::UserMode
        };
        let all_necessary = control & nt_security::se_exports::PRIVILEGE_SET_ALL_NECESSARY != 0;
        let passed =
            nt_security::check_token_privileges(token, &mut required[..count], all_necessary, mode);

        let mut output = [0u8; MAX_PRIVILEGES * ENTRY_SIZE];
        for (index, entry) in required[..count].iter().enumerate() {
            let offset = index * ENTRY_SIZE;
            output[offset..offset + 4].copy_from_slice(&entry.luid.low.to_le_bytes());
            output[offset + 4..offset + 8].copy_from_slice(&entry.luid.high.to_le_bytes());
            output[offset + 8..offset + 12].copy_from_slice(&entry.attributes.to_le_bytes());
        }
        if (entries_size != 0
            && !self.xas_try_write_buf(required_set + HEADER_SIZE as u64, &output[..entries_size]))
            || !self.xas_try_write_buf(result_out, &[u8::from(passed)])
        {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    /// `NtSetInformationProcess(ProcessAccessToken)`: capture the native two-HANDLE structure, but
    /// assign only its Token member. ReactOS fills Thread in advapi32 and the kernel deliberately
    /// ignores it (`ntoskrnl/ps/query.c`, ProcessAccessToken), so resolving that handle here would
    /// reject valid callers. TokenStore does not yet model token ancestry; require the real enabled
    /// assignment privilege for the independent interactive logon token used by CreateProcessAsUser.
    unsafe fn nt_set_process_access_token_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const PROCESS_SET_INFORMATION: u32 = 0x0200;
        const TOKEN_ASSIGN_PRIMARY: u32 = 0x0001;

        if nt_ulong_arg(args[3]) as usize != 16 {
            return STATUS_INFO_LENGTH_MISMATCH;
        }
        let mut captured = [0u8; 16];
        if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut captured) {
            return STATUS_ACCESS_VIOLATION;
        }
        let token_handle = u64::from_le_bytes(captured[..8].try_into().unwrap());
        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return STATUS_INVALID_HANDLE,
        };
        let target = match self
            .pm
            .resolve_process_handle(caller, args[0], PROCESS_SET_INFORMATION)
        {
            Ok(pid) => pid,
            Err(status) => return status,
        };
        let token = match self.token_id_for_handle(token_handle, TOKEN_ASSIGN_PRIMARY) {
            Ok(token) => token,
            Err(status) => return status,
        };
        if !self.current_token_has_privilege(nt_security::SE_ASSIGN_PRIMARY_TOKEN) {
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        if self
            .token_store
            .get(token)
            .is_none_or(|token| token.token_type != nt_security::TokenType::Primary)
        {
            return nt_security::STATUS_BAD_TOKEN_TYPE;
        }
        if self.token_store.retain(token).is_err() {
            return STATUS_INVALID_HANDLE;
        }
        let old = match self.pm.replace_process_primary_token(target, Some(token)) {
            Ok(old) => old,
            Err(status) => {
                let _ = self.token_store.release(token);
                return status;
            }
        };
        if let Some(old) = old {
            let _ = self.token_store.release(old);
        }
        if self.pi_for_pid(target) == Some(5) {
            USERINIT_PRIMARY_TOKEN_ASSIGNED.fetch_add(1, Ordering::Relaxed);
        }
        0
    }

    /// Apply `NtSetInformationProcess` through one kernel implementation while allowing private
    /// CSR workers to name stack-backed input buffers in their own address space.
    pub(crate) unsafe fn nt_set_information_process_with_user_memory(
        &mut self,
        args: &[u64],
        memory: SyscallUserMemory,
    ) -> u32 {
        let information_class = nt_ulong_arg(args[1]);
        let information_length = nt_ulong_arg(args[3]) as usize;
        if information_class == 9 {
            return self.nt_set_process_access_token_with_user_memory(args, memory);
        }
        const PROCESS_SET_INFORMATION: u32 = 0x0200;
        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return STATUS_INVALID_HANDLE,
        };
        let pid = match self
            .pm
            .resolve_process_handle(caller, args[0], PROCESS_SET_INFORMATION)
        {
            Ok(pid) => pid,
            Err(status) => return status,
        };

        match information_class {
            5 => {
                if information_length != 4 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                if args[2] & 3 != 0 {
                    return STATUS_DATATYPE_MISALIGNMENT;
                }
                let mut value = [0u8; 4];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                let raw = u32::from_le_bytes(value);
                let base_priority = (raw & !0x8000_0000) as i32;
                let current = self
                    .pm
                    .process(pid)
                    .map(|process| process.base_priority())
                    .unwrap_or(nt_process::DEFAULT_PROCESS_BASE_PRIORITY);
                if base_priority > current
                    && !self.current_token_has_privilege(nt_security::SE_INCREASE_BASE_PRIORITY)
                {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.pm
                    .set_process_base_priority(pid, base_priority)
                    .map_or_else(|status| status, |()| 0)
            }
            8 => {
                if information_length != 8 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                if args[2] & 7 != 0 {
                    return STATUS_DATATYPE_MISALIGNMENT;
                }
                let mut value = [0u8; 8];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                let port_handle = u64::from_le_bytes(value);
                let retained = match lpc_client() {
                    Some(client) => {
                        let metadata = match client.query_handle(port_handle) {
                            Ok(metadata) => metadata,
                            Err(status) => return status.raw() as u32,
                        };
                        if metadata.endpoint != nt_lpc_abi::handle_endpoint::LISTEN_PORT
                            && metadata.endpoint != nt_lpc_abi::handle_endpoint::CLIENT_COMM_PORT
                        {
                            return STATUS_OBJECT_TYPE_MISMATCH;
                        }
                        if metadata.endpoint == nt_lpc_abi::handle_endpoint::CLIENT_COMM_PORT
                            && metadata.state != nt_lpc_abi::connection_state::CONNECTED
                        {
                            return nt_status::NtStatus::PORT_DISCONNECTED.raw() as u32;
                        }
                        match client.retain_port_object(port_handle) {
                            Ok(retained) => retained,
                            Err(status) => return status.raw() as u32,
                        }
                    }
                    None => return STATUS_UNSUCCESSFUL,
                };
                let endpoint = nt_process::ExceptionPortEndpoint::new(retained)
                    .expect("the LPC broker never returns a null retained endpoint");
                match self
                    .pm
                    .install_process_exception_port_endpoint(pid, endpoint)
                {
                    Ok(()) => 0,
                    Err(status) => {
                        let release_status = lpc_client()
                            .ok_or(nt_status::NtStatus::UNSUCCESSFUL)
                            .and_then(|client| client.release_port_object(retained));
                        if let Err(release_status) = release_status {
                            print_str(
                                b"[lpc-invariant] exception-port rollback failed endpoint=0x",
                            );
                            print_hex_u64(retained);
                            print_str(b" status=0x");
                            print_hex(release_status.raw() as u32);
                            print_str(b"\n");
                        }
                        status
                    }
                }
            }
            12 => {
                if information_length != 4 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                if args[2] & 3 != 0 {
                    return STATUS_DATATYPE_MISALIGNMENT;
                }
                let mut value = [0u8; 4];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                self.pm
                    .set_process_default_hard_error_processing(pid, u32::from_le_bytes(value))
                    .map_or_else(|status| status, |()| 0)
            }
            18 => {
                if information_length != 2 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut value = [0u8; 2];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                let priority_class = value[1];
                if priority_class == nt_process::PROCESS_PRIORITY_CLASS_REALTIME
                    && !self.current_token_has_privilege(nt_security::SE_INCREASE_BASE_PRIORITY)
                {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                match self.pm.set_process_priority_class(pid, priority_class) {
                    Ok(()) => self
                        .pm
                        .set_process_foreground(pid, value[0] != 0)
                        .map_or_else(|status| status, |()| 0),
                    Err(status) => status,
                }
            }
            24 => {
                if information_length != 4 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                if args[2] & 3 != 0 {
                    return STATUS_DATATYPE_MISALIGNMENT;
                }
                let mut value = [0u8; 4];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.pm
                    .set_process_session_id(pid, u32::from_le_bytes(value))
                    .map_or_else(|status| status, |()| 0)
            }
            25 => {
                if information_length != 1 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut value = [0u8; 1];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                self.pm
                    .set_process_foreground(pid, value[0] != 0)
                    .map_or_else(|status| status, |()| 0)
            }
            29 => {
                if information_length != 4 {
                    return nt_process::STATUS_INFO_LENGTH_MISMATCH;
                }
                if args[2] & 3 != 0 {
                    return STATUS_DATATYPE_MISALIGNMENT;
                }
                let mut value = [0u8; 4];
                if args[2] == 0 || !self.user_memory_read(memory, args[2], &mut value) {
                    return STATUS_ACCESS_VIOLATION;
                }
                if !self.current_token_has_privilege(nt_security::SE_DEBUG) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.pm
                    .set_process_break_on_termination(pid, u32::from_le_bytes(value) != 0)
                    .map_or_else(|status| status, |()| 0)
            }
            _ => nt_process::STATUS_INVALID_INFO_CLASS,
        }
    }

    fn retain_external_handle_reference(
        &mut self,
        object: nt_process::HandleObject,
    ) -> Result<(), u32> {
        match object {
            nt_process::HandleObject::TokenObject(token) => self
                .token_store
                .retain(token)
                .map_err(|_| nt_process::STATUS_INVALID_HANDLE),
            nt_process::HandleObject::IoCompletion(id) => self.io_completion_ports.retain(id),
            nt_process::HandleObject::File(file_id)
            | nt_process::HandleObject::RoutedFile { file_id, .. } => {
                self.file_completion.retain_handle(file_id)
            }
            nt_process::HandleObject::Directory { object_id, .. } => {
                self.directory_opens.retain(object_id)
            }
            nt_process::HandleObject::DiskFile { object_id, .. } => {
                self.readonly_file_opens.retain(object_id)
            }
            nt_process::HandleObject::OverlayFile(file_id) => {
                self.writable_fs_dirty = true;
                unsafe { crate::writable_fs::retain(file_id) }
            }
            _ => Ok(()),
        }
    }

    /// Undo only a reference acquired by `retain_external_handle_reference`. Ps-owned Job/Debug
    /// references do not enter this path because they are acquired by handle-table publication.
    fn release_external_handle_reference(&mut self, object: nt_process::HandleObject) {
        match object {
            nt_process::HandleObject::TokenObject(token) => {
                let _ = self.token_store.release(token);
            }
            nt_process::HandleObject::IoCompletion(id) => {
                self.release_io_completion_reference(id);
            }
            nt_process::HandleObject::File(file_id)
            | nt_process::HandleObject::RoutedFile { file_id, .. } => {
                self.release_file_handle_reference(file_id);
            }
            nt_process::HandleObject::Directory { object_id, .. } => {
                let _ = self.directory_opens.release(object_id);
            }
            nt_process::HandleObject::DiskFile { object_id, .. } => {
                let _ = self.readonly_file_opens.release(object_id);
            }
            nt_process::HandleObject::OverlayFile(file_id) => {
                unsafe { crate::writable_fs::close(file_id) };
                self.writable_fs_dirty = true;
            }
            _ => {}
        }
    }

    fn release_handle_object(&mut self, object: nt_process::HandleObject) {
        match object {
            nt_process::HandleObject::TokenObject(token) => {
                let _ = self.token_store.release(token);
            }
            nt_process::HandleObject::IoCompletion(id) => {
                self.release_io_completion_reference(id);
            }
            nt_process::HandleObject::File(file_id) => {
                self.release_file_handle_reference(file_id);
            }
            nt_process::HandleObject::RoutedFile { file_id, .. } => {
                self.release_file_handle_reference(file_id);
            }
            nt_process::HandleObject::Directory { object_id, .. } => {
                if self.directory_opens.is_final_reference(object_id) == Ok(true) {
                    let completed = self
                        .readonly_directory_notifications
                        .cleanup_file_object(LOCAL_FAT_DIRECTORY_OBJECT_TAG | object_id as u64);
                    if completed != 0 {
                        crate::service_sec_image::FILE_IO_DELIVERY_RETRY_PENDING
                            .store(true, Ordering::Release);
                    }
                }
                let _ = self.directory_opens.release(object_id);
            }
            nt_process::HandleObject::DiskFile { object_id, .. } => {
                if self.readonly_file_opens.is_final_reference(object_id) == Ok(true) {
                    let status = self
                        .byte_range_locks
                        .cleanup_file_object_all(LOCAL_FAT_FILE_OBJECT_TAG | object_id as u64);
                    assert_eq!(status, nt_fs::STATUS_SUCCESS);
                    unsafe {
                        self.publish_local_byte_lock_completions();
                    }
                }
                let _ = self.readonly_file_opens.release(object_id);
            }
            nt_process::HandleObject::Section(section) => {
                if self
                    .pm
                    .handle_object_count(nt_process::HandleObject::Section(section))
                    == 0
                {
                    if let Some(loop_ctx) = self.loop_ctx {
                        unsafe {
                            let _ =
                                (&mut *loop_ctx.generic_sections).release_handle(section as usize);
                        }
                    }
                }
            }
            // The last handle on a writable-overlay file object: run the volume's cleanup/close
            // (which actions a pending delete) and free the FILE_OBJECT.
            nt_process::HandleObject::OverlayFile(file_id) => {
                if unsafe { crate::writable_fs::is_final_reference(file_id) } == Ok(true) {
                    let status = self.byte_range_locks.cleanup_file_object_all(
                        LOCAL_OVERLAY_FILE_OBJECT_TAG | (file_id & LOCAL_ID_PAYLOAD_MASK),
                    );
                    assert_eq!(status, nt_fs::STATUS_SUCCESS);
                    unsafe {
                        self.publish_local_byte_lock_completions();
                    }
                }
                unsafe { crate::writable_fs::close(file_id) };
                crate::service_sec_image::FILE_IO_DELIVERY_RETRY_PENDING
                    .store(true, Ordering::Release);
                self.writable_fs_dirty = true;
            }
            nt_process::HandleObject::Process(pid) => {
                let _ = self
                    .pm
                    .clear_deleted_process_debug_object_if_unreferenced(pid);
                let _ = self.try_delete_hosted_process_object(pid);
            }
            nt_process::HandleObject::Thread(tid) => {
                if let Some(pid) = self.pm.thread(tid).map(|thread| thread.process_id) {
                    let _ = self.try_delete_hosted_process_object(pid);
                }
            }
            // DbgkpCloseObject: the debugger's last handle went away — mark the object inactive,
            // detach every debuggee, and drop it.
            nt_process::HandleObject::DebugObject(object) => {
                if self.pm.release_debug_object_handle(object).unwrap_or(false) {
                    // ★ ESCAPE HATCH: the DEBUGGER IS GONE. Release every target still blocked on
                    // one of this object's events before the object (and its event list) is dropped
                    // — otherwise a debugger that dies mid-event would leave a reporter parked
                    // forever and the boot could never quiesce.
                    unsafe { self.dbgk_release_blocked_reporters(object, None) };
                    // `DbgkpMarkProcessPeb(Process, FALSE)` for every debuggee this object still
                    // holds — done BEFORE the detach, while the attachment is still resolvable.
                    unsafe { self.dbgk_clear_peb_marks_for_object(object) };
                    self.pm.destroy_debug_object(object);
                }
            }
            nt_process::HandleObject::Job(object) => {
                self.release_job_reference(object);
            }
            nt_process::HandleObject::Opaque(tag) => {
                self.release_opaque_namespace_reference(tag);
            }
            nt_process::HandleObject::RegistryKey(target) => {
                self.release_registry_key_target(target);
            }
            _ => {}
        }
    }

    pub(crate) fn close_process_handle_checked(
        &mut self,
        pid: nt_process::ProcessId,
        handle: u64,
    ) -> Result<bool, u32> {
        let Ok(handle) = nt_process::Handle::try_from(handle) else {
            return Ok(false);
        };
        match self.pm.take_handle_for_close(pid, handle) {
            Ok(object) => {
                self.release_handle_object(object);
                PM_HANDLES_CLOSED.fetch_add(1, Ordering::Relaxed);
                Ok(true)
            }
            Err(nt_process::STATUS_INVALID_HANDLE) => Ok(false),
            Err(status) => Err(status),
        }
    }

    pub(crate) fn close_process_handle(&mut self, pid: nt_process::ProcessId, handle: u64) -> bool {
        self.close_process_handle_checked(pid, handle)
            .unwrap_or(false)
    }

    fn release_process_handles(&mut self, pid: nt_process::ProcessId) {
        while let Some(object) = self.pm.take_any_handle(pid) {
            self.release_handle_object(object);
            PM_HANDLES_CLOSED.fetch_add(1, Ordering::Relaxed);
        }
        unsafe {
            crate::power_manager::remove_process_wakeup_latency(pid as u64);
        }
        let Some(endpoint) = self.pm.process_exception_port_endpoint(pid) else {
            return;
        };
        let Some(client) = (unsafe { lpc_client() }) else {
            print_str(b"[lpc-invariant] exception-port teardown has no broker endpoint=0x");
            print_hex_u64(endpoint.get());
            print_str(b"\n");
            return;
        };
        if let Err(status) = client.release_port_object(endpoint.get()) {
            print_str(b"[lpc-invariant] exception-port release failed endpoint=0x");
            print_hex_u64(endpoint.get());
            print_str(b" status=0x");
            print_hex(status.raw() as u32);
            print_str(b"\n");
            return;
        }
        let released = self
            .pm
            .take_process_exception_port_endpoint(pid)
            .expect("a process with a retained exception port remains live through teardown");
        assert_eq!(released, Some(endpoint));
    }

    /// Complete the Object Manager's EPROCESS delete procedure after hosted mechanism/VM teardown
    /// and the last process/thread handle or wait reference. Ps removes ETHREADs and job membership;
    /// the executive returns only the external Security Manager and LPC references from the deletion
    /// record, then frees the pi identity for a later genuine process.
    pub(crate) fn try_delete_hosted_process_object(&mut self, pid: nt_process::ProcessId) -> bool {
        let Some(pi) = self.process_mechanisms.pi_for_pid(pid) else {
            return false;
        };
        if self.process_vspaces.get(pi).copied().unwrap_or(1) != 0
            || !self.pm.process_object_delete_ready(pid)
        {
            return false;
        }

        let thread_count = self
            .pm
            .process(pid)
            .map(|process| process.threads.len())
            .unwrap_or(0);
        for index in 0..thread_count {
            let tid = self
                .pm
                .process(pid)
                .and_then(|process| process.threads.get(index).copied());
            let Some(tid) = tid else {
                return false;
            };
            if let Ok(Some(context)) = self.pm.replace_thread_impersonation(tid, None) {
                let _ = self.token_store.release(context.token);
            }
        }

        let Some(deletion) = self.pm.delete_process_object_if_unreferenced(pid) else {
            return false;
        };
        if let Some(token) = deletion.primary_token {
            let _ = self.token_store.release(token);
        }
        if let Some(endpoint) = deletion.exception_port {
            let client = unsafe { lpc_client() };
            match client {
                Some(client) => {
                    if let Err(status) = client.release_port_object(endpoint.get()) {
                        print_str(
                            b"[lpc-invariant] deleted process port release failed endpoint=0x",
                        );
                        print_hex_u64(endpoint.get());
                        print_str(b" status=0x");
                        print_hex(status.raw() as u32);
                        print_str(b"\n");
                    }
                }
                None => {
                    print_str(
                        b"[lpc-invariant] deleted process retained port without broker endpoint=0x",
                    );
                    print_hex_u64(endpoint.get());
                    print_str(b"\n");
                }
            }
        }
        let _ = self.thread_mechanisms.release_main(pi);
        for slot in 0..PM_RUNTIME_THREAD_SLOTS {
            let _ = self.thread_mechanisms.release_pool(pi, slot);
        }
        let released = self.process_mechanisms.release_pi(pi);
        debug_assert!(released.is_some_and(|mechanism| mechanism.pid == pid));
        self.pool_used[pi] = 0;
        self.drain_job_destructions();
        self.refresh_process_manager_gates();
        true
    }

    pub(crate) fn duplicate_process_handle_with_access(
        &mut self,
        source_pid: nt_process::ProcessId,
        source_handle: nt_process::Handle,
        target_pid: nt_process::ProcessId,
        desired_access: Option<u32>,
    ) -> Result<nt_process::Handle, u32> {
        let object = self
            .pm
            .lookup_handle(source_pid, source_handle)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let source_access = self
            .pm
            .handle_access(source_pid, source_handle)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let source_flags = self
            .pm
            .handle_flags(source_pid, source_handle)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let desired_access = desired_access.map(|access| match object {
            nt_process::HandleObject::TokenObject(_) | nt_process::HandleObject::Token(_) => {
                nt_security::map_token_access(access)
            }
            nt_process::HandleObject::Job(_) => nt_process::job::map_job_access(access),
            _ => access,
        });
        self.retain_external_handle_reference(object)?;
        let handle = match self.insert_process_handle(
            target_pid,
            object,
            desired_access.unwrap_or(source_access),
        ) {
            Ok(handle) => handle,
            Err(status) => {
                self.release_external_handle_reference(object);
                return Err(status);
            }
        };
        if let Err(status) = self.pm.set_handle_flags(target_pid, handle, source_flags) {
            if let Ok(object) = self.pm.take_handle(target_pid, handle) {
                self.release_handle_object(object);
            }
            return Err(status);
        }
        // ★ Record the logon token crossing into winlogon: `LsapLogonUser`'s closing
        // `NtDuplicateObject(NtCurrentProcess(), TokenHandle, ClientProcessHandle, &Reply.Token, …)`
        // (authpackage.c:1712). Only the token the `NtCreateToken` service minted counts.
        if let nt_process::HandleObject::TokenObject(token) = object {
            if token.raw() as u64 == SE_CREATE_TOKEN_ID.load(Ordering::Relaxed)
                && SE_CREATE_TOKEN_ID.load(Ordering::Relaxed) != 0
                && self.pi_for_pid(target_pid) == Some(2)
            {
                WINLOGON_LOGON_TOKEN_HANDLE.store(handle as u64, Ordering::Relaxed);
                WINLOGON_LOGON_TOKEN_DUPLICATES.fetch_add(1, Ordering::Relaxed);
            }
        }
        Ok(handle)
    }

    fn duplicate_process_handle_with_request_source(
        &mut self,
        source_pid: Option<nt_process::ProcessId>,
        source_handle: nt_process::Handle,
        target_pid: nt_process::ProcessId,
        desired_access: Option<u32>,
    ) -> Result<(nt_process::Handle, nt_process::ProcessId, bool), u32> {
        let mut invalid_status = STATUS_INVALID_HANDLE;
        if let Some(pid) = source_pid {
            match self.duplicate_process_handle_with_access(
                pid,
                source_handle,
                target_pid,
                desired_access,
            ) {
                Ok(handle) => return Ok((handle, pid, false)),
                Err(status) if status != STATUS_INVALID_HANDLE => return Err(status),
                Err(status) => invalid_status = status,
            }
        }

        let Some(client_pid) = self.csr_client_source_pid_for_handle(source_handle) else {
            return Err(invalid_status);
        };
        if Some(client_pid) == source_pid {
            return Err(invalid_status);
        }
        self.duplicate_process_handle_with_access(
            client_pid,
            source_handle,
            target_pid,
            desired_access,
        )
        .map(|handle| (handle, client_pid, true))
    }

    /// Transfer one existing token reference into a new caller-local handle. Every failure path
    /// releases that reference; success leaves the handle as its sole owner.
    unsafe fn insert_owned_token_handle(
        &mut self,
        caller_pid: nt_process::ProcessId,
        token: nt_security::TokenId,
        desired_access: u32,
        out: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        let handle = match self.insert_process_handle(
            caller_pid,
            nt_process::HandleObject::TokenObject(token),
            nt_security::map_token_access(desired_access),
        ) {
            Ok(handle) => handle,
            Err(_) => {
                let _ = self.token_store.release(token);
                return STATUS_INSUFFICIENT_RESOURCES;
            }
        };
        if !self.xas_write_u64(out, handle as u64) {
            if let Ok(object) = self.pm.take_handle(caller_pid, handle) {
                self.release_handle_object(object);
            }
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    pub(crate) unsafe fn nt_open_process_token(
        &mut self,
        process_handle: u64,
        desired_access: u32,
        out: u64,
    ) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_HANDLE: u32 = 0xC000_0008;
        if !self.probe_user_output(out, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        let target_pid = match self.resolve_process_handle(process_handle) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        if self.pi_for_pid(target_pid).is_none() {
            return STATUS_INVALID_HANDLE;
        }
        let token = match self.pm.process_primary_token(target_pid) {
            Some(token) => token,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return STATUS_INVALID_HANDLE,
        };
        if self.token_store.retain(token).is_err() {
            return STATUS_INVALID_HANDLE;
        }
        self.insert_owned_token_handle(caller_pid, token, desired_access, out)
    }

    unsafe fn nt_duplicate_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const TOKEN_DUPLICATE: u32 = 0x0002;

        let token_type = match nt_ulong_arg(args[4]) {
            1 => nt_security::TokenType::Primary,
            2 => nt_security::TokenType::Impersonation,
            _ => return STATUS_INVALID_PARAMETER,
        };
        let out = args[5];
        if !self.probe_user_output(out, 8) {
            return STATUS_ACCESS_VIOLATION;
        }

        let mut level = nt_security::SecurityImpersonationLevel::Anonymous;
        if args[2] != 0 {
            let mut oa = [0u8; 48];
            if !self.xas_read(args[2], &mut oa) {
                return STATUS_ACCESS_VIOLATION;
            }
            if u32::from_le_bytes(oa[0..4].try_into().unwrap()) != 48 {
                return STATUS_INVALID_PARAMETER;
            }
            let qos = u64::from_le_bytes(oa[40..48].try_into().unwrap());
            if qos != 0 {
                let mut captured = [0u8; 12];
                if !self.xas_read(qos, &mut captured) {
                    return STATUS_ACCESS_VIOLATION;
                }
                if u32::from_le_bytes(captured[0..4].try_into().unwrap()) != 12 {
                    return STATUS_INVALID_PARAMETER;
                }
                level = match nt_security::SecurityImpersonationLevel::try_from(u32::from_le_bytes(
                    captured[4..8].try_into().unwrap(),
                )) {
                    Ok(level) => level,
                    Err(status) => return status,
                };
            }
        }

        let source = match self.token_id_for_handle(args[0], TOKEN_DUPLICATE) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let desired_access_arg = nt_ulong_arg(args[1]);
        let desired_access = if desired_access_arg == 0 {
            match self
                .pm
                .handle_access(caller_pid, args[0] as nt_process::Handle)
            {
                Some(access) => access,
                None => return nt_process::STATUS_INVALID_HANDLE,
            }
        } else {
            desired_access_arg
        };
        let duplicate =
            match self
                .token_store
                .duplicate(source, token_type, level, nt_boolean_arg(args[3]))
            {
                Ok(token) => token,
                Err(status) => return status,
            };
        self.insert_owned_token_handle(caller_pid, duplicate, desired_access, out)
    }

    /// `NtCreateToken(TokenHandle, DesiredAccess, ObjectAttributes, TokenType, AuthenticationId,`
    /// `ExpirationTime, TokenUser, TokenGroups, TokenPrivileges, TokenOwner, TokenPrimaryGroup,`
    /// `TokenDefaultDacl, TokenSource)` — `ntoskrnl/se/tokenlif.c:1559`.
    ///
    /// The **widest** service the executive hosts by argument-*meaning*: thirteen arguments, all
    /// normalized by the dispatcher's generic marshaller (arity 13 from the shared
    /// `nt_syscall_abi` table) before this handler runs. The handler receives a flat `args[0..13]`
    /// — but it must NOT assume it: a short vector means the copy-in failed and the call fails
    /// closed.
    ///
    /// Six of the thirteen arguments point at **variable-length structures in the caller's address
    /// space**, several of which are themselves arrays of pointers to SIDs. That capture is the
    /// pure, host-tested `nt_security::create_token` walk; everything here is the kernel-side
    /// policy around it: probe the output handle, check the token type, enforce
    /// `SeCreateTokenPrivilege`, capture the QoS impersonation level out of `ObjectAttributes`, and
    /// insert the resulting token object + a handle to it in the caller's own handle table.
    unsafe fn nt_create_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_PRIVILEGE_NOT_HELD: u32 = 0xC000_0061;
        const STATUS_BAD_TOKEN_TYPE: u32 = 0xC000_00A8;

        SE_CREATE_TOKEN_CALLS.fetch_add(1, Ordering::Relaxed);
        SE_CREATE_TOKEN_ARGC.store(args.len() as u64, Ordering::Relaxed);
        // ★ WIDE-ARGUMENT GUARD. Args 5..13 are the nine stack slots; if the dispatcher could not
        // read them all it hands a short vector, and every structure pointer we need lives THERE.
        if args.len() < 13 {
            SE_CREATE_TOKEN_LAST_STATUS.store(STATUS_INVALID_PARAMETER as u64, Ordering::Relaxed);
            return STATUS_INVALID_PARAMETER;
        }
        SE_CREATE_TOKEN_STACK_ARGS.store(
            args[4..13].iter().filter(|value| **value != 0).count() as u64,
            Ordering::Relaxed,
        );

        let out = args[0];
        let desired_access = nt_ulong_arg(args[1]);
        let object_attributes = args[2];
        if !self.probe_user_output(out, 8) {
            SE_CREATE_TOKEN_LAST_STATUS.store(STATUS_ACCESS_VIOLATION as u64, Ordering::Relaxed);
            return STATUS_ACCESS_VIOLATION;
        }
        // ReactOS checks the token type BEFORE the privilege check, so a garbage type is reported
        // as STATUS_BAD_TOKEN_TYPE even to an unprivileged caller (tokenlif.c:1686).
        let token_type_arg = nt_ulong_arg(args[3]);
        if token_type_arg != 1 && token_type_arg != 2 {
            SE_CREATE_TOKEN_LAST_STATUS.store(STATUS_BAD_TOKEN_TYPE as u64, Ordering::Relaxed);
            return STATUS_BAD_TOKEN_TYPE;
        }
        // ★ `SeSinglePrivilegeCheck(SeCreateTokenPrivilege, PreviousMode)` (tokenlif.c:1695). The
        // caller's EFFECTIVE token (impersonation token if one is set, else the process primary
        // token) must hold the privilege ENABLED. lsass' LocalSystem token has it present-but-
        // disabled by default and enables it itself in `LsapRmInitializeServer` ->
        // `RtlAdjustPrivilege(SE_CREATE_TOKEN_PRIVILEGE, TRUE, FALSE, ...)` (lsasrv.c:314), which
        // runs through the real `NtAdjustPrivilegesToken` service.
        if !self.current_token_has_privilege(nt_security::SE_CREATE_TOKEN) {
            SE_CREATE_TOKEN_PRIV_DENIED.fetch_add(1, Ordering::Relaxed);
            SE_CREATE_TOKEN_LAST_STATUS.store(STATUS_PRIVILEGE_NOT_HELD as u64, Ordering::Relaxed);
            return STATUS_PRIVILEGE_NOT_HELD;
        }

        // `ObjectAttributes->SecurityQualityOfService->ImpersonationLevel`, captured exactly as
        // `nt_duplicate_token` does. An absent OA / QoS leaves the level Anonymous.
        let mut level = nt_security::SecurityImpersonationLevel::Anonymous;
        if object_attributes != 0 {
            let mut oa = [0u8; 48];
            if !self.xas_read(object_attributes, &mut oa) {
                SE_CREATE_TOKEN_LAST_STATUS
                    .store(STATUS_ACCESS_VIOLATION as u64, Ordering::Relaxed);
                return STATUS_ACCESS_VIOLATION;
            }
            if u32::from_le_bytes(oa[0..4].try_into().unwrap()) != 48 {
                SE_CREATE_TOKEN_LAST_STATUS
                    .store(STATUS_INVALID_PARAMETER as u64, Ordering::Relaxed);
                return STATUS_INVALID_PARAMETER;
            }
            let qos = u64::from_le_bytes(oa[40..48].try_into().unwrap());
            if qos != 0 {
                let mut captured = [0u8; 12];
                if !self.xas_read(qos, &mut captured) {
                    SE_CREATE_TOKEN_LAST_STATUS
                        .store(STATUS_ACCESS_VIOLATION as u64, Ordering::Relaxed);
                    return STATUS_ACCESS_VIOLATION;
                }
                level = match nt_security::SecurityImpersonationLevel::try_from(u32::from_le_bytes(
                    captured[4..8].try_into().unwrap(),
                )) {
                    Ok(level) => level,
                    Err(status) => {
                        SE_CREATE_TOKEN_LAST_STATUS.store(status as u64, Ordering::Relaxed);
                        return status;
                    }
                };
            }
        }

        let request = nt_security::CreateTokenArgs {
            token_type: token_type_arg,
            authentication_id: args[4],
            expiration_time: args[5],
            token_user: args[6],
            token_groups: args[7],
            token_privileges: args[8],
            token_owner: args[9],
            token_primary_group: args[10],
            token_default_dacl: args[11],
            token_source: args[12],
        };
        // The bounded cross-address-space capture. Scoped so the immutable borrow of `self` ends
        // before the token store is mutated.
        let captured = {
            let memory = ExecClientMemory { handler: &*self };
            nt_security::capture_token(&memory, &request, level)
        };
        let captured = match captured {
            Ok(captured) => captured,
            Err(status) => {
                SE_CREATE_TOKEN_CAPTURE_FAILS.fetch_add(1, Ordering::Relaxed);
                SE_CREATE_TOKEN_LAST_STATUS.store(status as u64, Ordering::Relaxed);
                return status;
            }
        };

        let Some(caller_pid) = self.pm_pid_for_pi(self.pi) else {
            SE_CREATE_TOKEN_LAST_STATUS
                .store(nt_process::STATUS_INVALID_HANDLE as u64, Ordering::Relaxed);
            return nt_process::STATUS_INVALID_HANDLE;
        };
        let user_rid = captured.token.user.sub_authorities.last().copied();
        let user_subauths = captured.token.user.sub_authorities.len() as u64;
        let group_count = captured.token.groups.len() as u64;
        // ★ Does the token lsasrv minted carry a LOGON SID (`SE_GROUP_LOGON_ID`)?
        // `winlogon!AllowAccessOnSession` scans `TOKEN_GROUPS` for exactly this and dereferences an
        // UNINITIALISED local when it finds nothing (measured: a read fault at `RtlLengthSid+0x5`,
        // `ntdll+0x1acc5`, with a garbage `LogonSid`). Counted so the claim is a measurement.
        let logon_sid_groups = captured
            .token
            .groups
            .iter()
            .filter(|group| group.is_logon_id())
            .count() as u64;
        SE_CREATE_TOKEN_LOGON_SIDS.store(logon_sid_groups, Ordering::Relaxed);
        let privilege_count = captured.token.privileges.len() as u64;
        let authentication_id = captured.token.authentication_id;
        let token_type = captured.token.token_type;
        let source_name = u64::from_le_bytes(captured.source.name);

        let token = self.token_store.insert_created(
            captured.token,
            captured.expiration_time,
            captured.source,
        );
        let status = self.insert_owned_token_handle(caller_pid, token, desired_access, out);
        SE_CREATE_TOKEN_LAST_STATUS.store(status as u64, Ordering::Relaxed);
        if status != 0 {
            // `insert_owned_token_handle` already released the token on every failure path.
            return status;
        }
        SE_CREATE_TOKEN_MINTED.fetch_add(1, Ordering::Relaxed);
        if SE_CREATE_TOKEN_PI.load(Ordering::Relaxed) == u64::MAX {
            // Read the shape back OUT OF THE STORE, not out of the captured value, so the recorded
            // evidence is what the token object actually holds.
            let stored = self.token_store.get(token);
            SE_CREATE_TOKEN_PI.store(self.pi as u64, Ordering::Relaxed);
            SE_CREATE_TOKEN_ID.store(token.raw() as u64, Ordering::Relaxed);
            SE_CREATE_TOKEN_USER_RID.store(user_rid.unwrap_or(u32::MAX) as u64, Ordering::Relaxed);
            SE_CREATE_TOKEN_USER_SUBAUTHS.store(user_subauths, Ordering::Relaxed);
            SE_CREATE_TOKEN_GROUPS.store(
                stored.map(|t| t.groups.len() as u64).unwrap_or(group_count),
                Ordering::Relaxed,
            );
            SE_CREATE_TOKEN_PRIVS.store(
                stored
                    .map(|t| t.privileges.len() as u64)
                    .unwrap_or(privilege_count),
                Ordering::Relaxed,
            );
            SE_CREATE_TOKEN_AUTH_LUID.store(
                (authentication_id.high as u32 as u64) << 32 | authentication_id.low as u64,
                Ordering::Relaxed,
            );
            SE_CREATE_TOKEN_TYPE.store(token_type as u64, Ordering::Relaxed);
            SE_CREATE_TOKEN_SOURCE_NAME.store(source_name, Ordering::Relaxed);
            let mut handle_out = [0u8; 8];
            if self.xas_read(out, &mut handle_out) {
                SE_CREATE_TOKEN_HANDLE.store(u64::from_le_bytes(handle_out), Ordering::Relaxed);
            }
            print_str(b"[se-token] NtCreateToken minted pi=");
            print_u64(self.pi as u64);
            print_str(b" id=");
            print_u64(token.raw() as u64);
            print_str(b" type=");
            print_u64(token_type as u64);
            print_str(b" user-rid=");
            print_u64(user_rid.unwrap_or(u32::MAX) as u64);
            print_str(b" subauths=");
            print_u64(user_subauths);
            print_str(b" groups=");
            print_u64(group_count);
            print_str(b" logon-sid-groups=");
            print_u64(logon_sid_groups);
            print_str(b" privs=");
            print_u64(privilege_count);
            print_str(b" authid=0x");
            print_hex(authentication_id.high as u32);
            print_hex(authentication_id.low);
            print_str(b" source=");
            print_str(&captured_source_bytes(source_name));
            print_str(b" stack-args=");
            print_u64(SE_CREATE_TOKEN_STACK_ARGS.load(Ordering::Relaxed));
            print_str(b"/9\n");
        }
        0
    }

    unsafe fn nt_open_thread_token(&mut self, args: &[u64], extended: bool) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_CANT_OPEN_ANONYMOUS: u32 = 0xC000_00A6;
        const STATUS_NO_TOKEN: u32 = 0xC000_007C;
        const THREAD_QUERY_INFORMATION: u32 = 0x0040;

        let out = args[if extended { 4 } else { 3 }];
        if !self.probe_user_output(out, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let tid = match self.pm.resolve_thread_handle(
            caller_pid,
            self.current_tid as nt_process::ThreadId,
            args[0],
            THREAD_QUERY_INFORMATION,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        let context = match self.pm.thread_impersonation(tid) {
            Some(context) => context,
            None => return STATUS_NO_TOKEN,
        };
        if context.level == nt_security::SecurityImpersonationLevel::Anonymous {
            return STATUS_CANT_OPEN_ANONYMOUS;
        }

        // OpenAsSelf affects the object access check identity. The current token model has no token
        // DACL yet, so both identities grant the requested mask without changing which token opens.
        let owned = if context.copy_on_open {
            match self.token_store.duplicate(
                context.token,
                nt_security::TokenType::Impersonation,
                context.level,
                context.effective_only,
            ) {
                Ok(token) => token,
                Err(status) => return status,
            }
        } else {
            if let Err(status) = self.token_store.retain(context.token) {
                return status;
            }
            context.token
        };
        self.insert_owned_token_handle(caller_pid, owned, nt_ulong_arg(args[1]), out)
    }

    /// Mirror authoritative ETHREAD impersonation state into the target thread's TEB. Like
    /// `PspWriteTebImpersonationInfo`, this is best-effort bookkeeping and never owns the state.
    unsafe fn write_thread_teb_impersonation_state(
        &self,
        tid: nt_process::ThreadId,
        active: bool,
    ) -> bool {
        let Some(thread) = self.pm.thread(tid) else {
            return false;
        };
        let pid = thread.process_id;
        let teb = if thread.teb_base != 0 {
            thread.teb_base
        } else if tid == self.current_tid as nt_process::ThreadId {
            if self.current_process_is_smss() {
                SMSS_TEB_VA
            } else {
                TEB_VA
            }
        } else {
            return true;
        };
        let Some(target_pi) = self.pi_for_pid(pid) else {
            return false;
        };
        let mut state = [0u8; 8];
        state[..4].copy_from_slice(&(if active { u32::MAX } else { 0 }).to_le_bytes());
        state[4] = u8::from(active);
        let address = teb + nt_ntdll_layout::TEB_IMPERSONATION_LOCALE_OFFSET;
        if target_pi == self.pi {
            return self.xas_try_write_buf(address, &state);
        }
        let (filled, faults, scratch_base) = match self.loop_ctx {
            Some(ctx) => {
                let procs = &*ctx.procs;
                let per_process = &*ctx.pfilled;
                (
                    &per_process[target_pi][..],
                    procs[target_pi].faults as usize,
                    procs[target_pi].scratch_base,
                )
            }
            None => (&[][..], 0, 0),
        };
        client_copyout_mapped(
            target_pi as u64,
            address,
            &state,
            filled,
            faults,
            scratch_base,
        )
    }

    /// Install a retained/owned impersonation context and release the replaced token reference.
    /// The ETHREAD context is authoritative; TEB fields are a best-effort user-mode mirror.
    unsafe fn install_thread_impersonation_context(
        &mut self,
        tid: nt_process::ThreadId,
        replacement: Option<nt_process::ImpersonationContext>,
    ) -> u32 {
        let old = match self.pm.replace_thread_impersonation(tid, replacement) {
            Ok(old) => old,
            Err(status) => {
                if let Some(context) = replacement {
                    let _ = self.token_store.release(context.token);
                }
                return status;
            }
        };
        let _ = self.write_thread_teb_impersonation_state(tid, replacement.is_some());
        if let Some(context) = old {
            let _ = self.token_store.release(context.token);
        }
        0
    }

    unsafe fn nt_impersonate_client_of_port(&mut self, args: &[u64]) -> u32 {
        const PORT_MESSAGE_HEADER_LEN: usize = nt_lpc_abi::PORT_MESSAGE_HEADER_LEN;

        let message = args[1];
        if message & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if message == 0 || !self.probe_user_input(message, PORT_MESSAGE_HEADER_LEN) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut header = [0u8; PORT_MESSAGE_HEADER_LEN];
        if !self.xas_read(message, &mut header) {
            return STATUS_ACCESS_VIOLATION;
        }
        let client_process = u64::from_le_bytes(header[8..16].try_into().unwrap());
        let client_thread = u64::from_le_bytes(header[16..24].try_into().unwrap());
        let message_id = u32::from_le_bytes(header[24..28].try_into().unwrap());

        let request = match lpc_client()
            .map(|client| client.query_request(args[0], client_process, client_thread, message_id))
        {
            Some(Ok(request)) => request,
            Some(Err(status)) => return status.raw() as u32,
            None => return STATUS_UNSUCCESSFUL,
        };
        let security = nt_port_core::ConnectionSecurity {
            impersonation_level: request.impersonation_level,
            dynamic_tracking: request.dynamic_tracking,
            effective_only: request.effective_only,
        };
        let Some(connection) = self.lpc_connections.iter().copied().find(|connection| {
            connection.connection_id == request.connection_id
                && connection.client_process == request.client_process
                && connection.client_thread == request.client_thread
                && connection.security == security
        }) else {
            return nt_status::NtStatus::REPLY_MESSAGE_MISMATCH.raw() as u32;
        };

        let (mut owned_token, effective_only, mut level) = if request.dynamic_tracking {
            let qos = match Self::lpc_security_qos(security) {
                Ok(qos) => qos,
                Err(status) => return status,
            };
            let (source_token, source_type, source_effective_only, source_level) =
                match self.lpc_effective_token_source(client_process, client_thread) {
                    Ok(source) => source,
                    Err(status) => return status,
                };
            let plan = match nt_security::plan_client_impersonation(
                source_type,
                source_level,
                source_effective_only,
                qos,
            ) {
                Ok(plan) if !plan.static_tracking => plan,
                Ok(_) => return STATUS_UNSUCCESSFUL,
                Err(status) => return status,
            };
            if let Err(status) = self.token_store.retain(source_token) {
                return status;
            }
            (source_token, plan.effective_only, plan.level)
        } else {
            let Some(context) = connection.static_security else {
                return nt_status::NtStatus::REPLY_MESSAGE_MISMATCH.raw() as u32;
            };
            if let Err(status) = self.token_store.retain(context.token) {
                return status;
            }
            (context.token, context.effective_only, context.level)
        };

        let server_pid = match self
            .pm
            .thread(self.current_tid as nt_process::ThreadId)
            .map(|thread| thread.process_id)
        {
            Some(pid) => pid,
            None => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        let server_primary = match self.pm.process_primary_token(server_pid) {
            Some(token) => token,
            None => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        let can_impersonate = match (
            self.token_store.get(server_primary),
            self.token_store.get(owned_token),
        ) {
            (Some(server), Some(client)) => {
                nt_security::token_can_impersonate(server, client, level)
            }
            _ => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        if !can_impersonate {
            let identified = match self.token_store.duplicate(
                owned_token,
                nt_security::TokenType::Impersonation,
                nt_security::SecurityImpersonationLevel::Identification,
                false,
            ) {
                Ok(token) => token,
                Err(status) => {
                    let _ = self.token_store.release(owned_token);
                    return status;
                }
            };
            let _ = self.token_store.release(owned_token);
            owned_token = identified;
            level = nt_security::SecurityImpersonationLevel::Identification;
        }

        self.install_thread_impersonation_context(
            self.current_tid as nt_process::ThreadId,
            Some(nt_process::ImpersonationContext {
                token: owned_token,
                copy_on_open: true,
                effective_only,
                level,
            }),
        )
    }

    unsafe fn nt_impersonate_thread(&mut self, args: &[u64]) -> u32 {
        const THREAD_IMPERSONATE: u32 = 0x0100;
        const THREAD_DIRECT_IMPERSONATION: u32 = 0x0200;
        const QOS_SIZE: usize = 12;

        let qos_pointer = args[2];
        if qos_pointer & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if qos_pointer == 0 || !self.probe_user_input(qos_pointer, QOS_SIZE) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut qos_bytes = [0u8; QOS_SIZE];
        if !self.xas_read(qos_pointer, &mut qos_bytes) {
            return STATUS_ACCESS_VIOLATION;
        }
        let qos = match nt_security::SecurityQualityOfService::from_native_bytes(&qos_bytes) {
            Ok(qos) => qos,
            Err(status) => return status,
        };

        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return STATUS_INVALID_HANDLE,
        };
        let current_tid = self.current_tid as nt_process::ThreadId;
        let target_tid = match self.pm.resolve_thread_handle(
            caller_pid,
            current_tid,
            args[0],
            THREAD_DIRECT_IMPERSONATION,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        let source_tid = match self.pm.resolve_thread_handle(
            caller_pid,
            current_tid,
            args[1],
            THREAD_IMPERSONATE,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        let (source_token, source_type, source_effective_only, source_level) =
            if let Some(context) = self.pm.thread_impersonation(source_tid) {
                (
                    context.token,
                    nt_security::TokenType::Impersonation,
                    context.effective_only,
                    context.level,
                )
            } else {
                let source_pid = match self.pm.thread(source_tid) {
                    Some(thread) => thread.process_id,
                    None => return STATUS_INVALID_HANDLE,
                };
                let token = match self.pm.process_primary_token(source_pid) {
                    Some(token) => token,
                    None => return STATUS_INVALID_HANDLE,
                };
                (
                    token,
                    nt_security::TokenType::Primary,
                    false,
                    nt_security::SecurityImpersonationLevel::Anonymous,
                )
            };
        let plan = match nt_security::plan_client_impersonation(
            source_type,
            source_level,
            source_effective_only,
            qos,
        ) {
            Ok(plan) => plan,
            Err(status) => return status,
        };

        let mut owned_token = if plan.static_tracking {
            match self.token_store.duplicate(
                source_token,
                nt_security::TokenType::Impersonation,
                plan.level,
                false,
            ) {
                Ok(token) => token,
                Err(status) => return status,
            }
        } else {
            if let Err(status) = self.token_store.retain(source_token) {
                return status;
            }
            source_token
        };

        let target_pid = match self.pm.thread(target_tid) {
            Some(thread) => thread.process_id,
            None => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        let target_primary = match self.pm.process_primary_token(target_pid) {
            Some(token) => token,
            None => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        let can_impersonate = match (
            self.token_store.get(target_primary),
            self.token_store.get(owned_token),
        ) {
            (Some(server), Some(client)) => {
                nt_security::token_can_impersonate(server, client, plan.level)
            }
            _ => {
                let _ = self.token_store.release(owned_token);
                return STATUS_INVALID_HANDLE;
            }
        };
        let mut level = plan.level;
        if !can_impersonate {
            let identified = match self.token_store.duplicate(
                owned_token,
                nt_security::TokenType::Impersonation,
                nt_security::SecurityImpersonationLevel::Identification,
                false,
            ) {
                Ok(token) => token,
                Err(status) => {
                    let _ = self.token_store.release(owned_token);
                    return status;
                }
            };
            let _ = self.token_store.release(owned_token);
            owned_token = identified;
            level = nt_security::SecurityImpersonationLevel::Identification;
        }

        self.install_thread_impersonation_context(
            target_tid,
            Some(nt_process::ImpersonationContext {
                token: owned_token,
                copy_on_open: true,
                effective_only: plan.effective_only,
                level,
            }),
        )
    }

    fn everyone_includes_anonymous(&self) -> Result<bool, u32> {
        const LSA_CONTROL_PATH: &str =
            "\\Registry\\Machine\\SYSTEM\\CurrentControlSet\\Control\\Lsa";
        const POLICY_VALUE: &str = "EveryoneIncludesAnonymous";

        let key = self
            .mutable_registry_key_by_path(LSA_CONTROL_PATH)
            .ok_or(STATUS_OBJECT_NAME_NOT_FOUND)?;
        let (value_type, data) = self
            .mutable_hives
            .query_value(key, POLICY_VALUE)
            .ok_or(STATUS_OBJECT_NAME_NOT_FOUND)?;
        if value_type != nt_hive_core::RegistryValueType::Dword || data.len() != 4 {
            return Err(STATUS_OBJECT_TYPE_MISMATCH);
        }
        Ok(u32::from_le_bytes([data[0], data[1], data[2], data[3]]) != 0)
    }

    unsafe fn nt_impersonate_anonymous_token(&mut self, thread_handle: u64) -> u32 {
        const THREAD_IMPERSONATE: u32 = 0x0100;

        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return STATUS_INVALID_HANDLE,
        };
        let target_tid = match self.pm.resolve_thread_handle(
            caller_pid,
            self.current_tid as nt_process::ThreadId,
            thread_handle,
            THREAD_IMPERSONATE,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };
        let include_everyone = match self.everyone_includes_anonymous() {
            Ok(include) => include,
            Err(status) => return status,
        };
        let caller_primary = match self.pm.process_primary_token(caller_pid) {
            Some(token) => token,
            None => return STATUS_UNSUCCESSFUL,
        };
        let token = match self.token_store.reference_anonymous_logon_token(
            self.anonymous_logon_tokens,
            include_everyone,
            caller_primary,
        ) {
            Ok(token) => token,
            Err(status) => return status,
        };

        self.install_thread_impersonation_context(
            target_tid,
            Some(nt_process::ImpersonationContext {
                token,
                copy_on_open: true,
                effective_only: false,
                level: nt_security::SecurityImpersonationLevel::Impersonation,
            }),
        )
    }

    unsafe fn nt_set_thread_impersonation_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const STATUS_BAD_TOKEN_TYPE: u32 = 0xC000_00A8;
        const THREAD_SET_THREAD_TOKEN: u32 = 0x0080;
        const TOKEN_IMPERSONATE: u32 = 0x0004;

        if nt_ulong_arg(args[3]) as usize != 8 {
            return STATUS_INFO_LENGTH_MISMATCH;
        }
        let mut captured = [0u8; 8];
        if args[2] == 0 || !self.xas_read(args[2], &mut captured) {
            return STATUS_ACCESS_VIOLATION;
        }
        let token_handle = u64::from_le_bytes(captured);
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let tid = match self.pm.resolve_thread_handle(
            caller_pid,
            self.current_tid as nt_process::ThreadId,
            args[0],
            THREAD_SET_THREAD_TOKEN,
        ) {
            Ok(tid) => tid,
            Err(status) => return status,
        };

        let replacement = if token_handle == 0 {
            None
        } else {
            let token = match self.token_id_for_handle(token_handle, TOKEN_IMPERSONATE) {
                Ok(token) => token,
                Err(status) => return status,
            };
            let (token_type, level) = match self.token_store.get(token) {
                Some(token) => (token.token_type, token.impersonation_level),
                None => return nt_process::STATUS_INVALID_HANDLE,
            };
            if token_type != nt_security::TokenType::Impersonation {
                return STATUS_BAD_TOKEN_TYPE;
            }
            if let Err(status) = self.token_store.retain(token) {
                return status;
            }
            Some(nt_process::ImpersonationContext {
                token,
                copy_on_open: false,
                effective_only: false,
                level,
            })
        };

        self.install_thread_impersonation_context(tid, replacement)
    }

    unsafe fn capture_token_groups_input(
        &self,
        address: u64,
    ) -> Result<alloc::vec::Vec<(nt_security::Sid, u32)>, u32> {
        const TOKEN_GROUPS_HEADER_SIZE: usize = 24;
        if address & 3 != 0 {
            return Err(STATUS_DATATYPE_MISALIGNMENT);
        }
        let mut header = [0u8; TOKEN_GROUPS_HEADER_SIZE];
        if address == 0 || !self.xas_read(address, &mut header) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let count = u32::from_le_bytes(header[..4].try_into().unwrap());
        let groups_address = address
            .checked_add(nt_security::TOKEN_GROUPS_ARRAY_OFFSET)
            .ok_or(STATUS_ACCESS_VIOLATION)?;
        nt_security::capture_sid_and_attributes_array(
            &ExecClientMemory { handler: self },
            groups_address,
            count,
        )
    }

    unsafe fn capture_token_privileges_input(
        &self,
        address: u64,
    ) -> Result<alloc::vec::Vec<(nt_security::Luid, u32)>, u32> {
        const TOKEN_PRIVILEGES_HEADER_SIZE: usize = 16;
        if address & 3 != 0 {
            return Err(STATUS_DATATYPE_MISALIGNMENT);
        }
        let mut header = [0u8; TOKEN_PRIVILEGES_HEADER_SIZE];
        if address == 0 || !self.xas_read(address, &mut header) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let count = u32::from_le_bytes(header[..4].try_into().unwrap());
        let privileges_address = address
            .checked_add(nt_security::TOKEN_PRIVILEGES_ARRAY_OFFSET)
            .ok_or(STATUS_ACCESS_VIOLATION)?;
        nt_security::capture_luid_and_attributes_array(
            &ExecClientMemory { handler: self },
            privileges_address,
            count,
        )
    }

    unsafe fn nt_filter_token(&mut self, args: &[u64]) -> u32 {
        const TOKEN_DUPLICATE: u32 = 0x0002;

        let flags = nt_ulong_arg(args[1]);
        if flags & !nt_security::TOKEN_FILTER_VALID_FLAGS != 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let sids_to_disable = if args[2] == 0 {
            alloc::vec::Vec::new()
        } else {
            match self.capture_token_groups_input(args[2]) {
                Ok(captured) => captured,
                Err(status) => return status,
            }
        };
        let privileges_to_delete = if args[3] == 0 {
            alloc::vec::Vec::new()
        } else {
            match self.capture_token_privileges_input(args[3]) {
                Ok(captured) => captured,
                Err(status) => return status,
            }
        };
        let restricted_sids = if args[4] == 0 {
            alloc::vec::Vec::new()
        } else {
            match self.capture_token_groups_input(args[4]) {
                Ok(captured) => captured,
                Err(status) => return status,
            }
        };

        let out = args[5];
        if out & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        if !self.probe_user_output(out, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        let source = match self.token_id_for_handle(args[0], TOKEN_DUPLICATE) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let caller_pid = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let granted_access = match self
            .pm
            .handle_access(caller_pid, args[0] as nt_process::Handle)
        {
            Some(access) => access,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let filtered = match self.token_store.filter(
            source,
            nt_security::TokenFilterRequest {
                flags,
                sids_to_disable: &sids_to_disable,
                privileges_to_delete: &privileges_to_delete,
                restricted_sids: &restricted_sids,
            },
        ) {
            Ok(token) => token,
            Err(status) => return status,
        };
        self.insert_owned_token_handle(caller_pid, filtered, granted_access, out)
    }

    unsafe fn nt_adjust_privileges_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_SUCCESS: u32 = 0;
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_BUFFER_TOO_SMALL: u32 = 0xC000_0023;
        const STATUS_NOT_ALL_ASSIGNED: u32 = 0x0000_0106;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        const TOKEN_QUERY: u32 = 0x0008;
        const TOKEN_ADJUST_PRIVILEGES: u32 = 0x0020;

        let disable_all = nt_boolean_arg(args[1]);
        let new_state = args[2];
        let buffer_length = nt_ulong_arg(args[3]) as usize;
        let previous_state = args[4];
        let return_length = args[5];
        if !disable_all && new_state == 0 {
            return STATUS_INVALID_PARAMETER;
        }

        let mut requested = alloc::vec::Vec::new();
        if !disable_all {
            let captured = match self.capture_token_privileges_input(new_state) {
                Ok(captured) => captured,
                Err(status) => return status,
            };
            if requested.try_reserve_exact(captured.len()).is_err() {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            for (luid, attributes) in captured {
                requested.push(nt_security::PrivilegeAdjustment { luid, attributes });
            }
        }

        if previous_state != 0
            && (return_length == 0
                || !self.probe_user_output(previous_state, buffer_length)
                || !self.probe_user_output(return_length, 4))
        {
            return STATUS_ACCESS_VIOLATION;
        }

        let required_access =
            TOKEN_ADJUST_PRIVILEGES | if previous_state != 0 { TOKEN_QUERY } else { 0 };
        let token_id = match self.token_id_for_handle(args[0], required_access) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let plan = match self.token_store.get(token_id) {
            Some(token) => token.plan_privilege_adjustment(disable_all, &requested),
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let required_length = 4 + plan.changed * 12;
        if previous_state != 0 {
            if !self.xas_write_u32(return_length, required_length as u32) {
                return STATUS_ACCESS_VIOLATION;
            }
            if buffer_length < required_length {
                return STATUS_BUFFER_TOO_SMALL;
            }
        }

        // The exact ReactOS SYSTEM token has 24 privileges, so this is sufficient even for
        // DisableAllPrivileges and remains allocation-free across the executive heap reset.
        let mut previous = [nt_security::PrivilegeAdjustment::default(); 24];
        let result = match self.token_store.adjust_privileges(
            token_id,
            disable_all,
            &requested,
            &mut previous[..plan.changed],
        ) {
            Ok(result) => result,
            Err(status) => return status,
        };
        if previous_state != 0 {
            let mut output = [0u8; 4 + 24 * 12];
            output[..4].copy_from_slice(&(result.changed as u32).to_le_bytes());
            for (index, privilege) in previous[..result.changed].iter().enumerate() {
                let offset = 4 + index * 12;
                output[offset..offset + 4].copy_from_slice(&privilege.luid.low.to_le_bytes());
                output[offset + 4..offset + 8].copy_from_slice(&privilege.luid.high.to_le_bytes());
                output[offset + 8..offset + 12]
                    .copy_from_slice(&privilege.attributes.to_le_bytes());
            }
            if !self.xas_try_write_buf(previous_state, &output[..required_length]) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        if !disable_all && result.matched < requested.len() {
            STATUS_NOT_ALL_ASSIGNED
        } else {
            STATUS_SUCCESS
        }
    }

    unsafe fn nt_adjust_groups_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_SUCCESS: u32 = 0;
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_BUFFER_TOO_SMALL: u32 = 0xC000_0023;
        const STATUS_NOT_ALL_ASSIGNED: u32 = 0x0000_0106;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        const TOKEN_QUERY: u32 = 0x0008;
        const TOKEN_ADJUST_GROUPS: u32 = 0x0040;

        let reset_to_default = nt_boolean_arg(args[1]);
        let new_state = args[2];
        let buffer_length = nt_ulong_arg(args[3]) as usize;
        let previous_state = args[4];
        let return_length = args[5];
        if !reset_to_default && new_state == 0 {
            return STATUS_INVALID_PARAMETER;
        }

        let mut requested = alloc::vec::Vec::new();
        if !reset_to_default {
            let captured = match self.capture_token_groups_input(new_state) {
                Ok(captured) => captured,
                Err(status) => return status,
            };
            if requested.try_reserve_exact(captured.len()).is_err() {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            requested.extend(
                captured
                    .into_iter()
                    .map(|(sid, attributes)| nt_security::GroupAdjustment { sid, attributes }),
            );
        }

        if previous_state != 0 {
            if previous_state & 3 != 0 || return_length & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            if return_length == 0
                || !self.probe_user_output(previous_state, buffer_length)
                || !self.probe_user_output(return_length, 4)
            {
                return STATUS_ACCESS_VIOLATION;
            }
        }

        let required_access =
            TOKEN_ADJUST_GROUPS | if previous_state != 0 { TOKEN_QUERY } else { 0 };
        let token_id = match self.token_id_for_handle(args[0], required_access) {
            Ok(token) => token,
            Err(status) => return status,
        };
        let plan = match self.token_store.get(token_id) {
            Some(token) => match token.plan_group_adjustment(reset_to_default, &requested) {
                Ok(plan) => plan,
                Err(status) => return status,
            },
            None => return nt_process::STATUS_INVALID_HANDLE,
        };

        let mut previous_output = alloc::vec::Vec::new();
        if previous_state != 0 {
            let sized = match nt_security::encode_token_group_entries(
                &plan.previous,
                previous_state,
                &mut [],
            ) {
                Ok(sized) => sized,
                Err(_) => return STATUS_INVALID_PARAMETER,
            };
            if sized.required_length > u32::MAX as usize {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            if !self.xas_write_u32(return_length, sized.required_length as u32) {
                return STATUS_ACCESS_VIOLATION;
            }
            if buffer_length < sized.required_length {
                return STATUS_BUFFER_TOO_SMALL;
            }
            if previous_output
                .try_reserve_exact(sized.required_length)
                .is_err()
            {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            previous_output.resize(sized.required_length, 0);
            match nt_security::encode_token_group_entries(
                &plan.previous,
                previous_state,
                &mut previous_output,
            ) {
                Ok(encoded) if encoded.written => {}
                Ok(_) | Err(_) => return STATUS_INVALID_PARAMETER,
            }
        }

        let result = match self
            .token_store
            .adjust_groups(token_id, reset_to_default, &requested)
        {
            Ok(result) => result,
            Err(status) => return status,
        };
        if previous_state != 0
            && !self.xas_try_write_buf(previous_state, previous_output.as_slice())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        if !reset_to_default && result.matched < requested.len() {
            STATUS_NOT_ALL_ASSIGNED
        } else {
            STATUS_SUCCESS
        }
    }

    unsafe fn nt_set_information_token(&mut self, args: &[u64]) -> u32 {
        const STATUS_INFO_LENGTH_MISMATCH: u32 = 0xC000_0004;
        const AUDIT_POLICY_ENTRY_SIZE: usize = 8;
        use nt_security::TokenSetInformationClass::*;

        let information_class = nt_ulong_arg(args[1]);
        let information = args[2];
        let information_length = nt_ulong_arg(args[3]) as usize;
        let plan =
            match nt_security::plan_token_information_set(information_class, information_length) {
                Ok(plan) => plan,
                Err(status) => return status,
            };
        if information & 3 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }

        let mut captured = [0u8; 8];
        if !self.xas_read(information, &mut captured[..plan.fixed_length]) {
            return STATUS_ACCESS_VIOLATION;
        }
        let token_id = match self.token_id_for_handle(args[0], plan.required_access) {
            Ok(token) => token,
            Err(status) => return status,
        };

        match plan.class {
            Owner => {
                let owner = match nt_security::capture_sid(
                    &ExecClientMemory { handler: self },
                    u64::from_le_bytes(captured),
                ) {
                    Ok(owner) => owner,
                    Err(status) => return status,
                };
                self.token_store
                    .set_owner(token_id, owner)
                    .err()
                    .unwrap_or(0)
            }
            PrimaryGroup => {
                let primary_group = match nt_security::capture_sid(
                    &ExecClientMemory { handler: self },
                    u64::from_le_bytes(captured),
                ) {
                    Ok(primary_group) => primary_group,
                    Err(status) => return status,
                };
                self.token_store
                    .set_primary_group(token_id, primary_group)
                    .err()
                    .unwrap_or(0)
            }
            DefaultDacl => {
                let acl_pointer = u64::from_le_bytes(captured);
                let default_dacl = if acl_pointer == 0 {
                    None
                } else {
                    match nt_security::capture_acl(&ExecClientMemory { handler: self }, acl_pointer)
                    {
                        Ok(acl) => Some(acl),
                        Err(status) => return status,
                    }
                };
                self.token_store
                    .set_default_dacl(token_id, default_dacl)
                    .err()
                    .unwrap_or(0)
            }
            SessionId => {
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.token_store
                    .set_session_id(
                        token_id,
                        u32::from_le_bytes(captured[..4].try_into().unwrap()),
                    )
                    .err()
                    .unwrap_or(0)
            }
            SessionReference => {
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.token_store
                    .set_session_referenced(
                        token_id,
                        u32::from_le_bytes(captured[..4].try_into().unwrap()) != 0,
                    )
                    .err()
                    .unwrap_or(0)
            }
            AuditPolicy => {
                let count = u32::from_le_bytes(captured[..4].try_into().unwrap()) as usize;
                if count > nt_security::TOKEN_AUDIT_CATEGORY_COUNT {
                    return STATUS_INVALID_PARAMETER;
                }
                let required_length = match count
                    .checked_mul(AUDIT_POLICY_ENTRY_SIZE)
                    .and_then(|entries| entries.checked_add(4))
                {
                    Some(length) => length,
                    None => return STATUS_INVALID_PARAMETER,
                };
                if information_length < required_length {
                    return STATUS_INFO_LENGTH_MISMATCH;
                }
                let mut entries = [(0u32, 0u8); nt_security::TOKEN_AUDIT_CATEGORY_COUNT];
                for (index, entry) in entries[..count].iter_mut().enumerate() {
                    let mut bytes = [0u8; AUDIT_POLICY_ENTRY_SIZE];
                    let Some(entry_address) = information.checked_add(4).and_then(|address| {
                        address.checked_add((index * AUDIT_POLICY_ENTRY_SIZE) as u64)
                    }) else {
                        return STATUS_ACCESS_VIOLATION;
                    };
                    if !self.xas_read(entry_address, &mut bytes) {
                        return STATUS_ACCESS_VIOLATION;
                    }
                    *entry = (u32::from_le_bytes(bytes[..4].try_into().unwrap()), bytes[4]);
                }
                let audit_policy =
                    match nt_security::TokenAuditPolicy::from_entries(&entries[..count]) {
                        Ok(policy) => policy,
                        Err(status) => return status,
                    };
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.token_store
                    .set_audit_policy(token_id, audit_policy)
                    .err()
                    .unwrap_or(0)
            }
            Origin => {
                if !self.current_token_has_privilege(nt_security::SE_TCB) {
                    return STATUS_PRIVILEGE_NOT_HELD;
                }
                self.token_store
                    .set_origin(
                        token_id,
                        nt_security::Luid {
                            low: u32::from_le_bytes(captured[..4].try_into().unwrap()),
                            high: i32::from_le_bytes(captured[4..8].try_into().unwrap()),
                        },
                    )
                    .map(|_| 0)
                    .unwrap_or_else(|status| status)
            }
        }
    }

    /// Queue an 8-byte out-param write for the loop to perform after dispatch (group B2). Silently
    /// drops if the fixed queue is full (bounded per-syscall — no handler queues more than 6).
    pub(crate) fn queue_write(&mut self, ptr: u64, val: u64) {
        if self.out_writes_n < self.out_writes.len() {
            self.out_writes[self.out_writes_n] = (ptr, val);
            self.out_writes_n += 1;
        }
    }

    fn write_nt_open_file_handle_out(&mut self, ptr: u64, val: u64) {
        if ptr == 0 {
            return;
        }
        if self.pi >= 2 {
            self.queue_write(ptr, val);
        } else {
            unsafe {
                smss_stack_write(ptr, val);
            }
        }
    }

    pub(crate) fn close_current_handle(&mut self, handle: u64) {
        if let Some(pid) = self.pm_pid_for_pi(self.pi) {
            let _ = self.close_process_handle(pid, handle);
        }
    }
    /// Read a UNICODE_STRING's UTF-16 buffer from the faulting process for an LPC syscall, handling
    /// a buffer that lives OUTSIDE the stack/heap/image mirrors — e.g. csrss's `NtConnectPort`
    /// PortName `L"\\SmApiPort"` is a static string in csrsrv's `.rdata` (~0x8000_xxxx). The
    /// UNICODE_STRING struct itself is a stack local (mirror-readable); its Buffer is read via the
    /// per-fault scratch alias of the already-demand-faulted `.rdata` page (`scratch_for`). Empty on
    /// failure (→ the caller's connect misses by name, a clean error, not a crash).
    /// Read an OBJECT_ATTRIBUTES.ObjectName (OA+0x10 → PUNICODE_STRING) with the SAME .rdata-capable
    /// fallback as `read_lpc_name`. The free `smss_read_objattr_name` is mirror-only, so csrss's
    /// `NtCreatePort(\Windows\ApiPort)` (name in csrsrv .rdata) registered under an EMPTY name → the
    /// broker couldn't match winlogon's connect. Use this so the port registers under its real name.
    pub(crate) unsafe fn read_objattr_name(&self, oa_va: u64) -> alloc::vec::Vec<u16> {
        let mut p = [0u8; 8];
        if !self.xas_read(oa_va + 0x10, &mut p) {
            return alloc::vec::Vec::new();
        }
        let objname = u64::from_le_bytes(p);
        if objname == 0 {
            return alloc::vec::Vec::new();
        }
        self.read_lpc_name(objname)
    }
    pub(crate) unsafe fn read_lpc_name(&self, ustr_va: u64) -> alloc::vec::Vec<u16> {
        if ustr_va == 0 {
            return alloc::vec::Vec::new();
        }
        let mut lm = [0u8; 2];
        let mut bp = [0u8; 8];
        if !self.xas_read(ustr_va, &mut lm) || !self.xas_read(ustr_va + 8, &mut bp) {
            return alloc::vec::Vec::new();
        }
        let buffer_va = u64::from_le_bytes(bp);
        let n = ((u16::from_le_bytes(lm) as usize) / 2).min(1024);
        let mut out = alloc::vec::Vec::with_capacity(n);
        for i in 0..n {
            let va = buffer_va + (i as u64) * 2;
            let mut w = [0u8; 2];
            if self.xas_read(va, &mut w) {
                out.push(u16::from_le_bytes(w));
                continue;
            }
            // Not in a mirror → try the scratch alias of an already-faulted page (csrsrv .rdata).
            if let Some(ctx) = self.loop_ctx.as_ref() {
                let fp = &*ctx.filled_pages;
                let nf = *ctx.faults as usize;
                if let Some(m) = scratch_for(va, fp, nf, ctx.scratch_base) {
                    let p = m as *const u8;
                    w[0] = *p;
                    w[1] = *p.add(1);
                    out.push(u16::from_le_bytes(w));
                    continue;
                }
            }
            break;
        }
        out
    }
    /// Read `dst.len()` bytes from the current process's VA `va`, resolving a page OUTSIDE the
    /// stack/heap/image mirrors by reading the STATIC content straight from the backing PE image
    /// (main image / ntdll / a registered DLL). Hosted GUI/service registry strings are often
    /// `RTL_CONSTANT_STRING` literals in DLL `.rdata` pages the process never dereferences (the
    /// executive is the first reader), so the page is not demand-faulted and not in any mirror or
    /// frame table — but its bytes are exactly the (relocation-free) `.rdata` file content, which we
    /// read via the loaded PE. Handles a read that spans a page boundary.
    pub(crate) unsafe fn xas_read(&self, va: u64, dst: &mut [u8]) -> bool {
        if va.checked_add(dst.len() as u64).is_none() {
            return false;
        }
        if let Some(ctx) = self
            .loop_ctx
            .as_ref()
            .filter(|_| self.current_hosted_thread_user_stack_contains(va, dst.len()))
        {
            return client_copyin_mapped(
                self.pi as u64,
                va,
                dst,
                &*ctx.filled_pages,
                *ctx.faults as usize,
                ctx.scratch_base,
            );
        }
        if smss_copyin(va, dst) {
            return true;
        }
        let ctx = match self.loop_ctx.as_ref() {
            Some(c) => c,
            None => return false,
        };
        let filled_pages = &*ctx.filled_pages;
        let faults = *ctx.faults as usize;
        if client_copyin_mapped(
            self.pi as u64,
            va,
            dst,
            filled_pages,
            faults,
            ctx.scratch_base,
        ) {
            return true;
        }
        let reg = &*ctx.reg;
        let dll_pes = ctx.dll_pes();
        let mut done = 0usize;
        while done < dst.len() {
            let cur = va + done as u64;
            let (pe, byte_rva): (&nt_pe_loader::PeFile, u32) =
                if cur >= PE_LOAD_BASE && cur < ctx.img_end {
                    (&*ctx.pe, (cur - PE_LOAD_BASE) as u32)
                } else if !ctx.ntdll_pe.is_null() && cur >= ctx.nt_base && cur < ctx.nt_end {
                    (&*ctx.ntdll_pe, (cur - ctx.nt_base) as u32)
                } else if let Some((i, rva)) = reg.dll_for_page(self.pi, cur) {
                    match dll_pes[i].as_ref() {
                        Some(pe) => (pe, rva),
                        None => return false,
                    }
                } else {
                    return false;
                };
            let off = (cur & 0xFFF) as usize;
            let n = (0x1000 - off).min(dst.len() - done);
            for j in 0..n {
                match pe_byte_at_rva(pe, byte_rva + j as u32) {
                    Some(b) => dst[done + j] = b,
                    None => return false,
                }
            }
            done += n;
        }
        true
    }

    fn read_user_i64(&self, va: u64) -> Result<i64, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        if va == 0 {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut bytes = [0u8; 8];
        if !unsafe { self.xas_read(va, &mut bytes) } {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        Ok(i64::from_le_bytes(bytes))
    }

    fn wait_timeout_interval(&self, timeout_ptr: u64) -> Result<Option<i64>, u32> {
        if timeout_ptr == 0 {
            return Ok(None);
        }
        if timeout_ptr & 7 != 0 {
            return Err(STATUS_DATATYPE_MISALIGNMENT);
        }
        Ok(Some(self.read_user_i64(timeout_ptr)?))
    }

    unsafe fn current_image_protection_for_page(&self, ctx: ExecLoopCtx, page: u64) -> Option<u32> {
        if page >= PE_LOAD_BASE && page < ctx.img_end {
            return Some(image_page_protection(&*ctx.pe, PE_LOAD_BASE, page));
        }
        if !ctx.ntdll_pe.is_null() && page >= ctx.nt_base && page < ctx.nt_end {
            return Some(image_page_protection(&*ctx.ntdll_pe, ctx.nt_base, page));
        }
        let reg = &*ctx.reg;
        let dll_pes = ctx.dll_pes();
        let (index, rva) = reg.dll_for_page(self.pi, page)?;
        let pe = dll_pes.get(index).and_then(|slot| slot.as_ref())?;
        Some(image_rva_protection(pe, rva))
    }

    unsafe fn clear_current_scratch_page(&self, ctx: ExecLoopCtx, page: u64) {
        let filled_pages = &mut *ctx.filled_pages;
        let faults = (*ctx.faults as usize).min(filled_pages.len());
        for filled_page in filled_pages.iter_mut().take(faults) {
            if *filled_page == page {
                *filled_page = 0;
            }
        }
    }

    unsafe fn promote_current_image_cow_for_write(&self, va: u64, len: usize) -> bool {
        if len == 0 {
            return true;
        }
        let Some(ctx) = self.loop_ctx else {
            return true;
        };
        let Some(last) = va.checked_add(len as u64 - 1) else {
            return false;
        };
        let mut page = va & !0xfff;
        let last_page = last & !0xfff;
        loop {
            if let Some(protection) = self.current_image_protection_for_page(ctx, page) {
                let write_plan = nt_address_space::image_view_fault_plan(protection, true);
                if write_plan.copy_on_write {
                    if vm_promote_image_cow_for_kernel_write(
                        self.pi,
                        page,
                        protection,
                        ctx.pml4,
                        ctx.scratch_base,
                    )
                    .is_err()
                    {
                        return false;
                    }
                    self.clear_current_scratch_page(ctx, page);
                }
            }
            if page == last_page {
                return true;
            }
            let Some(next) = page.checked_add(0x1000) else {
                return false;
            };
            page = next;
        }
    }

    /// Cross-AS 8-byte out-param write to the current process's VA `va` — handles a target that lives
    /// in a DLL `.data` global (e.g. advapi32's `DefaultHandleTable[]`, where MapDefaultKey stores the
    /// predefined-root handle) that the stack/heap/image mirror can't reach. Delegates to
    /// [`client_copyout_or_fill_mapped`] (mirror → backed page alias → demand-fill from the DLL PE).
    /// No-op if there is no loop context. Used for hosted-process NtOpenKey handle copyout.
    pub(crate) unsafe fn xas_write_u64(&self, va: u64, val: u64) -> bool {
        if let Some(ctx) = self.loop_ctx {
            if !self.promote_current_image_cow_for_write(va, 8) {
                return false;
            }
            let filled_pages = &mut *ctx.filled_pages;
            let faults = &mut *ctx.faults;
            let reg = &*ctx.reg;
            let dll_pes = ctx.dll_pes();
            client_copyout_or_fill_mapped(
                self.pi as u64,
                va,
                &val.to_le_bytes(),
                filled_pages,
                faults,
                ctx.scratch_base,
                reg,
                dll_pes,
                ctx.pml4,
            )
        } else {
            smss_copyout(va, &val.to_le_bytes())
        }
    }

    /// Publish the two user-visible outputs of a successful `NtCreateProcess[Ex]`: the process
    /// handle and the child PEB pointer returned through the creator TEB's ArbitraryUserPointer.
    pub(crate) unsafe fn publish_created_process(
        &self,
        process_handle_out: u64,
        process_handle: u64,
        child_peb: u64,
    ) -> bool {
        let Some(teb) = self
            .pm
            .thread_teb(self.current_tid as nt_process::ThreadId)
            .filter(|teb| *teb != 0)
        else {
            return false;
        };
        let Some(peb_out) = teb.checked_add(nt_ntdll_layout::TEB_ARBITRARY_USER_POINTER_OFFSET)
        else {
            return false;
        };
        self.xas_write_u64(peb_out, child_peb)
            && self.xas_write_u64(process_handle_out, process_handle)
    }

    /// Cross-address-space DWORD copyout without imposing 8-byte alignment on the user pointer.
    pub(crate) unsafe fn xas_write_u32(&self, va: u64, val: u32) -> bool {
        if let Some(ctx) = self.loop_ctx {
            if !self.promote_current_image_cow_for_write(va, 4) {
                return false;
            }
            let filled_pages = &mut *ctx.filled_pages;
            let faults = &mut *ctx.faults;
            let reg = &*ctx.reg;
            let dll_pes = ctx.dll_pes();
            client_copyout_or_fill_mapped(
                self.pi as u64,
                va,
                &val.to_le_bytes(),
                filled_pages,
                faults,
                ctx.scratch_base,
                reg,
                dll_pes,
                ctx.pml4,
            )
        } else {
            smss_copyout(va, &val.to_le_bytes())
        }
    }

    /// Probe a small writable event output before changing dispatcher state.
    pub(crate) unsafe fn probe_event_output(&self, va: u64, len: usize) -> bool {
        len <= 8 && self.probe_user_output(va, len)
    }

    /// Probe an arbitrary readable user range, including image and DLL `.rdata` that has not faulted
    /// into the process yet.
    pub(crate) unsafe fn probe_user_input(&self, va: u64, len: usize) -> bool {
        if len == 0 {
            return true;
        }
        if va == 0 || va.checked_add(len as u64).is_none() {
            return false;
        }
        let mut address = va;
        let mut remaining = len;
        let mut bytes = [0u8; 8];
        while remaining != 0 {
            let chunk = remaining.min(bytes.len());
            if !self.xas_read(address, &mut bytes[..chunk]) {
                return false;
            }
            address += chunk as u64;
            remaining -= chunk;
        }
        true
    }

    /// Probe an arbitrary user output range without changing its contents.
    pub(crate) unsafe fn probe_user_output(&self, va: u64, len: usize) -> bool {
        if len == 0 {
            return true;
        }
        if va == 0 || va.checked_add(len as u64).is_none() {
            return false;
        }
        let Some(ctx) = self.loop_ctx else {
            let mut address = va;
            let mut remaining = len;
            let mut bytes = [0u8; 8];
            while remaining != 0 {
                let chunk = remaining.min(bytes.len());
                if !self.xas_read(address, &mut bytes[..chunk]) {
                    return false;
                }
                address += chunk as u64;
                remaining -= chunk;
            }
            return true;
        };
        let end = va + len as u64;
        if self.current_hosted_thread_user_stack_contains(va, len) {
            return client_range_has_backing(self.pi as u64, va, len);
        }
        let stack_base = ACTIVE_STACK_BASE.load(Ordering::Relaxed);
        let stack_end = stack_base + ACTIVE_STACK_SIZE.load(Ordering::Relaxed);
        if va >= stack_base && end <= stack_end
            || va >= SMSS_ALLOC_VA && end <= SMSS_ALLOC_VA + SMSS_HEAP_MIRROR_WINDOW
        {
            return true;
        }
        // ★ A hosted thread's stack GROWS BELOW its declared window. `ACTIVE_STACK_BASE/SIZE` are
        // the pages the spawn pre-mapped; a deeper frame simply faults and the service loop
        // demand-maps it, so a legitimate buffer can sit below `stack_base` and still be fully
        // backed. kernel32's `FindFirstFileExW` is exactly that case — it puts a 16 KiB
        // `DECLSPEC_ALIGN(4) BYTE DirectoryInfo[FIND_DATA_SIZE]` scratch buffer plus its
        // IO_STATUS_BLOCK on the caller's stack (`kernel32/client/file/find.c:694`), which for
        // winlogon lands ~12 KiB below the 16 KiB declared window. The window test alone called
        // that unreachable, so `NtQueryDirectoryFile` returned STATUS_ACCESS_VIOLATION and
        // `CopyDirectory` reported `GetLastError() == 998` (ERROR_NOACCESS).
        //
        // This clause is a strictly MONOTONE widening: it runs only where the code already
        // returned false, and it does not assume anything — it asks whether every page of the
        // range REALLY has backing in the caller's VSpace, the same `client_range_has_backing`
        // test the winlogon listener stack above already uses. Unmapped memory is still refused.
        const STACK_GROWTH_WINDOW: u64 = 0x10_0000; // 1 MiB, the PE's committed stack reserve
        if end <= stack_end && va >= stack_base.saturating_sub(STACK_GROWTH_WINDOW) {
            return client_range_has_backing(self.pi as u64, va, len);
        }

        unsafe fn committed_mapped_output_range_backed(pi: u64, va: u64, len: usize) -> bool {
            let Some(chunks) = nt_address_space::page_chunks(va, len) else {
                return false;
            };
            for chunk in chunks {
                let Some(info) = process_committed_mapping_basic_information(pi, chunk.page_base)
                else {
                    return false;
                };
                if info.type_ != nt_address_space::MEM_MAPPED
                    || nt_address_space::mapped_view_fault_access_status(
                        info.protect,
                        nt_address_space::FaultAccess::Write,
                    )
                    .is_err()
                    || csrss_frame_get_exact(pi, chunk.page_base).0 == 0
                {
                    return false;
                }
            }
            true
        }

        if committed_mapped_output_range_backed(self.pi as u64, va, len) {
            return true;
        }

        fn writable_image_range(pe: &nt_pe_loader::PeFile, base: u64, va: u64, len: usize) -> bool {
            let rva = match va.checked_sub(base) {
                Some(rva) => rva,
                None => return false,
            };
            let end = match rva.checked_add(len as u64) {
                Some(end) => end,
                None => return false,
            };
            pe.sections().iter().any(|section| {
                let start = section.virtual_address as u64;
                let section_end = start + section.virtual_size.max(section.size_of_raw_data) as u64;
                rva >= start && end <= section_end && section.is_writable()
            })
        }

        unsafe fn scratch_pages_available(
            ctx: ExecLoopCtx,
            pi: u64,
            va: u64,
            len: usize,
            may_fill: bool,
        ) -> bool {
            let filled_pages = unsafe { &*ctx.filled_pages };
            let faults = unsafe { *ctx.faults } as usize;
            let mut missing = 0usize;
            let mut page = va & !0xFFF;
            let last = (va + len as u64 - 1) & !0xFFF;
            loop {
                let has_alias = unsafe { csrss_frame_alias_get(pi, page) } != 0;
                if !has_alias
                    && unsafe { scratch_for(page, filled_pages, faults, ctx.scratch_base) }
                        .is_none()
                {
                    if !may_fill {
                        return false;
                    }
                    missing += 1;
                }
                if page == last {
                    break;
                }
                page += 0x1000;
            }
            missing == 0
                || faults
                    .checked_add(missing)
                    .is_some_and(|needed| needed <= filled_pages.len())
        }

        if va >= PE_LOAD_BASE && end <= ctx.img_end {
            return writable_image_range(&*ctx.pe, PE_LOAD_BASE, va, len);
        }
        if !ctx.ntdll_pe.is_null() && va >= ctx.nt_base && end <= ctx.nt_end {
            return writable_image_range(&*ctx.ntdll_pe, ctx.nt_base, va, len)
                && scratch_pages_available(ctx, self.pi as u64, va, len, false);
        }
        let reg = &*ctx.reg;
        if let Some((index, _)) = reg.dll_for_page(self.pi, va) {
            if let Some(pe) = ctx.dll_pes()[index].as_ref() {
                return writable_image_range(pe, reg.base(index), va, len)
                    && scratch_pages_available(ctx, self.pi as u64, va, len, true);
            }
        }
        false
    }

    /// Cross-AS byte-buffer write to the current process's VA `va` — mirror first, else 8-byte chunks
    /// via [`xas_write_u64`] (each demand-fills a not-yet-faulted DLL/heap page as needed). The last
    /// partial word is read-modify-written so trailing bytes past `src` in that word are preserved.
    /// Used for hosted-process registry info-structure copyout (KEY_*_INFORMATION into a heap buffer).
    pub(crate) unsafe fn xas_write_buf(&self, va: u64, src: &[u8]) {
        let _ = self.xas_try_write_buf(va, src);
    }

    unsafe fn write_current_user_buf(&self, va: u64, src: &[u8], use_xas_write: bool) -> bool {
        if src.is_empty() {
            return true;
        }
        if use_xas_write {
            self.xas_try_write_buf(va, src)
        } else {
            smss_copyout(va, src)
        }
    }

    unsafe fn write_current_user_buf_at(
        &self,
        base: u64,
        offset: usize,
        src: &[u8],
        use_xas_write: bool,
    ) -> bool {
        let Some(dst) = base.checked_add(offset as u64) else {
            return false;
        };
        self.write_current_user_buf(dst, src, use_xas_write)
    }

    unsafe fn write_current_user_buf_chunked_at(
        &self,
        base: u64,
        offset: usize,
        src: &[u8],
        use_xas_write: bool,
    ) -> bool {
        const CHUNK: usize = 64 * 1024;
        let mut done = 0usize;
        while done < src.len() {
            let n = (src.len() - done).min(CHUNK);
            let Some(dst_offset) = offset.checked_add(done) else {
                return false;
            };
            if !self.write_current_user_buf_at(
                base,
                dst_offset,
                &src[done..done + n],
                use_xas_write,
            ) {
                return false;
            }
            done += n;
        }
        true
    }

    unsafe fn write_current_user_buf_bounded_at(
        &self,
        base: u64,
        offset: usize,
        src: &[u8],
        bound: usize,
        use_xas_write: bool,
    ) -> bool {
        if offset >= bound {
            return true;
        }
        let n = src.len().min(bound - offset);
        self.write_current_user_buf_at(base, offset, &src[..n], use_xas_write)
    }

    unsafe fn write_current_user_buf_chunked_bounded_at(
        &self,
        base: u64,
        offset: usize,
        src: &[u8],
        bound: usize,
        use_xas_write: bool,
    ) -> bool {
        if offset >= bound {
            return true;
        }
        let n = src.len().min(bound - offset);
        self.write_current_user_buf_chunked_at(base, offset, &src[..n], use_xas_write)
    }

    unsafe fn write_current_user_zeroes_at(
        &self,
        base: u64,
        offset: usize,
        len: usize,
        use_xas_write: bool,
    ) -> bool {
        let zeroes = [0u8; 64];
        let mut done = 0usize;
        while done < len {
            let n = (len - done).min(zeroes.len());
            let Some(dst_offset) = offset.checked_add(done) else {
                return false;
            };
            if !self.write_current_user_buf_at(base, dst_offset, &zeroes[..n], use_xas_write) {
                return false;
            }
            done += n;
        }
        true
    }

    unsafe fn write_current_user_zeroes_bounded_at(
        &self,
        base: u64,
        offset: usize,
        len: usize,
        bound: usize,
        use_xas_write: bool,
    ) -> bool {
        if offset >= bound {
            return true;
        }
        self.write_current_user_zeroes_at(base, offset, len.min(bound - offset), use_xas_write)
    }

    unsafe fn write_current_user_utf16le_at(
        &self,
        base: u64,
        offset: usize,
        s: &str,
        use_xas_write: bool,
    ) -> bool {
        let mut scratch = [0u8; 128];
        let mut pending = 0usize;
        let mut written = 0usize;
        for unit in s.encode_utf16() {
            if pending + 2 > scratch.len() {
                let Some(dst_offset) = offset.checked_add(written) else {
                    return false;
                };
                if !self.write_current_user_buf_at(
                    base,
                    dst_offset,
                    &scratch[..pending],
                    use_xas_write,
                ) {
                    return false;
                }
                written += pending;
                pending = 0;
            }
            scratch[pending..pending + 2].copy_from_slice(&unit.to_le_bytes());
            pending += 2;
        }
        if pending != 0 {
            let Some(dst_offset) = offset.checked_add(written) else {
                return false;
            };
            if !self.write_current_user_buf_at(base, dst_offset, &scratch[..pending], use_xas_write)
            {
                return false;
            }
        }
        true
    }

    unsafe fn write_current_user_utf16le_bounded_at(
        &self,
        base: u64,
        offset: usize,
        s: &str,
        bound: usize,
        use_xas_write: bool,
    ) -> bool {
        if offset >= bound {
            return true;
        }
        let mut remaining = bound - offset;
        let mut scratch = [0u8; 128];
        let mut pending = 0usize;
        let mut written = 0usize;
        for unit in s.encode_utf16() {
            if remaining == 0 {
                break;
            }
            let bytes = unit.to_le_bytes();
            let n = remaining.min(2);
            if pending + n > scratch.len() {
                let Some(dst_offset) = offset.checked_add(written) else {
                    return false;
                };
                if !self.write_current_user_buf_at(
                    base,
                    dst_offset,
                    &scratch[..pending],
                    use_xas_write,
                ) {
                    return false;
                }
                written += pending;
                pending = 0;
            }
            scratch[pending..pending + n].copy_from_slice(&bytes[..n]);
            pending += n;
            remaining -= n;
        }
        if pending != 0 {
            let Some(dst_offset) = offset.checked_add(written) else {
                return false;
            };
            if !self.write_current_user_buf_at(base, dst_offset, &scratch[..pending], use_xas_write)
            {
                return false;
            }
        }
        true
    }

    unsafe fn write_key_value_info_to_user(
        &self,
        va: u64,
        class: u64,
        name: &str,
        ty: u32,
        data: &[u8],
        use_xas_write: bool,
    ) -> bool {
        let Ok(layout) = key_value_info_layout(class, name, data.len()) else {
            return false;
        };
        if layout.name_len > u32::MAX as usize || layout.data_len > u32::MAX as usize {
            return false;
        }
        match class {
            0 => {
                let mut header = [0u8; 0x0c];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, layout.name_len as u32);
                self.write_current_user_buf_at(va, 0, &header, use_xas_write)
                    && self.write_current_user_utf16le_at(va, 0x0c, name, use_xas_write)
            }
            2 => {
                let Some(data_offset) = layout.data_offset else {
                    return false;
                };
                let mut header = [0u8; 0x0c];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, layout.data_len as u32);
                self.write_current_user_buf_at(va, 0, &header, use_xas_write)
                    && self.write_current_user_buf_chunked_at(va, data_offset, data, use_xas_write)
            }
            4 => {
                let Some(data_offset) = layout.data_offset else {
                    return false;
                };
                let mut header = [0u8; 0x08];
                put_u32_le(&mut header, 0x00, ty);
                put_u32_le(&mut header, 0x04, layout.data_len as u32);
                self.write_current_user_buf_at(va, 0, &header, use_xas_write)
                    && self.write_current_user_buf_chunked_at(va, data_offset, data, use_xas_write)
            }
            1 | 3 => {
                let data_offset = layout.data_offset.unwrap_or(u32::MAX as usize);
                if data_offset > u32::MAX as usize {
                    return false;
                }
                let mut header = [0u8; 0x14];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, data_offset as u32);
                put_u32_le(&mut header, 0x0c, layout.data_len as u32);
                put_u32_le(&mut header, 0x10, layout.name_len as u32);
                let name_end = 0x14usize + layout.name_len;
                let wrote_prefix = self.write_current_user_buf_at(va, 0, &header, use_xas_write)
                    && self.write_current_user_utf16le_at(va, 0x14, name, use_xas_write);
                if !wrote_prefix {
                    return false;
                }
                if let Some(data_offset) = layout.data_offset {
                    self.write_current_user_zeroes_at(
                        va,
                        name_end,
                        data_offset.saturating_sub(name_end),
                        use_xas_write,
                    ) && self.write_current_user_buf_chunked_at(
                        va,
                        data_offset,
                        data,
                        use_xas_write,
                    )
                } else {
                    true
                }
            }
            _ => false,
        }
    }

    unsafe fn write_key_value_info_prefix_to_user(
        &self,
        va: u64,
        class: u64,
        name: &str,
        ty: u32,
        data: &[u8],
        limit: usize,
        use_xas_write: bool,
    ) -> bool {
        if limit == 0 {
            return true;
        }
        let Ok(layout) = key_value_info_layout(class, name, data.len()) else {
            return false;
        };
        if layout.name_len > u32::MAX as usize || layout.data_len > u32::MAX as usize {
            return false;
        }
        match class {
            0 => {
                let mut header = [0u8; 0x0c];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, layout.name_len as u32);
                self.write_current_user_buf_bounded_at(va, 0, &header, limit, use_xas_write)
                    && self.write_current_user_utf16le_bounded_at(
                        va,
                        0x0c,
                        name,
                        limit,
                        use_xas_write,
                    )
            }
            2 => {
                let Some(data_offset) = layout.data_offset else {
                    return false;
                };
                let mut header = [0u8; 0x0c];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, layout.data_len as u32);
                self.write_current_user_buf_bounded_at(va, 0, &header, limit, use_xas_write)
                    && self.write_current_user_buf_chunked_bounded_at(
                        va,
                        data_offset,
                        data,
                        limit,
                        use_xas_write,
                    )
            }
            4 => {
                let Some(data_offset) = layout.data_offset else {
                    return false;
                };
                let mut header = [0u8; 0x08];
                put_u32_le(&mut header, 0x00, ty);
                put_u32_le(&mut header, 0x04, layout.data_len as u32);
                self.write_current_user_buf_bounded_at(va, 0, &header, limit, use_xas_write)
                    && self.write_current_user_buf_chunked_bounded_at(
                        va,
                        data_offset,
                        data,
                        limit,
                        use_xas_write,
                    )
            }
            1 | 3 => {
                let data_offset = layout.data_offset.unwrap_or(u32::MAX as usize);
                if data_offset > u32::MAX as usize {
                    return false;
                }
                let mut header = [0u8; 0x14];
                put_u32_le(&mut header, 0x00, 0);
                put_u32_le(&mut header, 0x04, ty);
                put_u32_le(&mut header, 0x08, data_offset as u32);
                put_u32_le(&mut header, 0x0c, layout.data_len as u32);
                put_u32_le(&mut header, 0x10, layout.name_len as u32);
                let name_end = 0x14usize + layout.name_len;
                let wrote_prefix =
                    self.write_current_user_buf_bounded_at(va, 0, &header, limit, use_xas_write)
                        && self.write_current_user_utf16le_bounded_at(
                            va,
                            0x14,
                            name,
                            limit,
                            use_xas_write,
                        );
                if !wrote_prefix {
                    return false;
                }
                if let Some(data_offset) = layout.data_offset {
                    self.write_current_user_zeroes_bounded_at(
                        va,
                        name_end,
                        data_offset.saturating_sub(name_end),
                        limit,
                        use_xas_write,
                    ) && self.write_current_user_buf_chunked_bounded_at(
                        va,
                        data_offset,
                        data,
                        limit,
                        use_xas_write,
                    )
                } else {
                    true
                }
            }
            _ => false,
        }
    }

    unsafe fn query_value_key_copyout_status(
        &self,
        info_class: u64,
        output_va: u64,
        output_length: usize,
        result_length_va: u64,
        name: &str,
        ty: u32,
        data: &[u8],
        use_xas_write: bool,
    ) -> u32 {
        let layout = match key_value_info_layout(info_class, name, data.len()) {
            Ok(layout) => layout,
            Err(status) => return status,
        };
        let Ok(result_length) = u32::try_from(layout.total_len) else {
            return STATUS_INSUFFICIENT_RESOURCES;
        };
        let result_length = result_length.to_le_bytes();
        let result_length_written = if use_xas_write {
            self.xas_try_write_buf(result_length_va, &result_length)
        } else {
            smss_copyout(result_length_va, &result_length)
        };
        if !result_length_written {
            return STATUS_ACCESS_VIOLATION;
        }
        if output_length < layout.minimum_len {
            return STATUS_BUFFER_TOO_SMALL;
        }
        if layout.total_len > output_length {
            if !self.write_key_value_info_prefix_to_user(
                output_va,
                info_class,
                name,
                ty,
                data,
                output_length,
                use_xas_write,
            ) {
                return STATUS_ACCESS_VIOLATION;
            }
            return STATUS_BUFFER_OVERFLOW;
        }
        if !self.write_key_value_info_to_user(output_va, info_class, name, ty, data, use_xas_write)
        {
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    fn registry_value_copy_provenance_for_copyout(
        &self,
        info_class: u64,
        output_va: u64,
        name: &str,
        ty: u32,
        data_len: usize,
        source: Option<ResolvedHiveValue>,
    ) -> RegistryValueCopyProvenance {
        let Some(source) = source else {
            return RegistryValueCopyProvenance::default();
        };
        let Ok(layout) = key_value_info_layout(info_class, name, data_len) else {
            return RegistryValueCopyProvenance::default();
        };
        let Some(data_offset) = layout.data_offset else {
            return RegistryValueCopyProvenance::default();
        };
        if layout.data_len == 0 || data_len > u32::MAX as usize {
            return RegistryValueCopyProvenance::default();
        }
        let Some(data_va) = output_va.checked_add(data_offset as u64) else {
            return RegistryValueCopyProvenance::default();
        };
        RegistryValueCopyProvenance::new(
            source,
            self.pi as u64,
            self.current_tid,
            data_va,
            data_len,
            ty,
        )
    }

    fn registry_value_copy_source_for_user_data(
        &self,
        data_ptr: u64,
        data_size: usize,
        ty: u32,
    ) -> Option<ResolvedHiveValue> {
        self.registry_value_copy_provenance.source_for_user_data(
            self.pi as u64,
            self.current_tid,
            data_ptr,
            data_size,
            ty,
        )
    }

    pub(crate) unsafe fn xas_try_write_buf(&self, va: u64, src: &[u8]) -> bool {
        if let Some(ctx) = self
            .loop_ctx
            .as_ref()
            .filter(|_| self.current_hosted_thread_user_stack_contains(va, src.len()))
        {
            return client_copyout_mapped(
                self.pi as u64,
                va,
                src,
                &*ctx.filled_pages,
                *ctx.faults as usize,
                ctx.scratch_base,
            );
        }
        if let Some(ctx) = self.loop_ctx {
            if !self.promote_current_image_cow_for_write(va, src.len()) {
                return false;
            }
            if client_copyout_or_fill_mapped(
                self.pi as u64,
                va,
                src,
                &mut *ctx.filled_pages,
                &mut *ctx.faults,
                ctx.scratch_base,
                &*ctx.reg,
                ctx.dll_pes(),
                ctx.pml4,
            ) {
                return true;
            }
        }
        if smss_copyout(va, src) {
            return true;
        }
        let mut i = 0usize;
        while i < src.len() {
            let n = (src.len() - i).min(8);
            let mut w = [0u8; 8];
            if n < 8 && !self.xas_read(va + i as u64, &mut w) {
                return false;
            }
            w[..n].copy_from_slice(&src[i..i + n]);
            if !self.xas_write_u64(va + i as u64, u64::from_le_bytes(w)) {
                return false;
            }
            i += 8;
        }
        true
    }
    /// Capture an NtAddAtom/NtFindAtom explicit-length UTF-16 name from the current process. Small
    /// pointer values preserve MAKEINTATOM semantics and are returned directly without a read.
    pub(crate) unsafe fn copyin_atom_name(
        &self,
        name_va: u64,
        byte_len: u32,
        name: &mut [u16; nt_kernel_exec::rtl_atom::NAME_CAP],
    ) -> Result<Option<u16>, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        let byte_len = byte_len as usize;
        if byte_len > nt_kernel_exec::rtl_atom::NAME_CAP * 2 || byte_len & 1 != 0 {
            return Err(nt_kernel_exec::rtl_atom::status::INVALID_PARAMETER);
        }
        if name_va <= 0xFFFF {
            return Ok(Some(name_va as u16));
        }
        let units = byte_len / 2;
        let mut bytes = [0u8; nt_kernel_exec::rtl_atom::NAME_CAP * 2];
        if !self.xas_read(name_va, &mut bytes[..byte_len]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        for i in 0..units {
            name[i] = u16::from_le_bytes([bytes[i * 2], bytes[i * 2 + 1]]);
        }
        Ok(None)
    }

    /// Probe a small user output range using the current process's cross-address-space reader.
    pub(crate) unsafe fn probe_atom_output(&self, va: u64, len: usize) -> bool {
        if len == 0 {
            return true;
        }
        if va == 0 || len > 8 {
            return false;
        }
        let mut probe = [0u8; 8];
        self.xas_read(va, &mut probe[..len])
    }
    /// Cross-AS UNICODE_STRING read (x64 {u16 Length, u16 Max, u32 pad, u64 Buffer}) via [`xas_read`],
    /// so a Buffer in a not-yet-faulted DLL `.rdata` page resolves from the backing PE. Used for
    /// hosted-process registry name strings (key names + value names).
    pub(crate) unsafe fn read_ustr_pe(&self, ustr_va: u64) -> alloc::vec::Vec<u16> {
        if ustr_va == 0 {
            return alloc::vec::Vec::new();
        }
        let mut lm = [0u8; 2];
        let mut bp = [0u8; 8];
        if !self.xas_read(ustr_va, &mut lm) || !self.xas_read(ustr_va + 8, &mut bp) {
            return alloc::vec::Vec::new();
        }
        let byte_len = u16::from_le_bytes(lm) as usize;
        let buffer_va = u64::from_le_bytes(bp);
        let n = (byte_len / 2).min(1024);
        let mut out = alloc::vec::Vec::with_capacity(n);
        for i in 0..n {
            let mut w = [0u8; 2];
            if !self.xas_read(buffer_va + (i as u64) * 2, &mut w) {
                break;
            }
            out.push(u16::from_le_bytes(w));
        }
        out
    }

    unsafe fn read_directory_pattern(
        &self,
        ustr_va: u64,
        output: &mut [u16; nt_fs::MAX_DIRECTORY_NAME],
    ) -> Result<usize, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        if ustr_va == 0 {
            return Ok(0);
        }
        let mut header = [0u8; 16];
        if !self.xas_read(ustr_va, &mut header) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let byte_len = u16::from_le_bytes([header[0], header[1]]) as usize;
        let maximum_len = u16::from_le_bytes([header[2], header[3]]) as usize;
        let buffer = u64::from_le_bytes(header[8..16].try_into().unwrap());
        if byte_len & 1 != 0 || byte_len > maximum_len || byte_len / 2 > output.len() {
            return Err(STATUS_INVALID_PARAMETER);
        }
        if byte_len == 0 {
            return Ok(0);
        }
        if buffer == 0 {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut bytes = [0u8; nt_fs::MAX_DIRECTORY_NAME * 2];
        if !self.xas_read(buffer, &mut bytes[..byte_len]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        for index in 0..byte_len / 2 {
            output[index] = u16::from_le_bytes([bytes[index * 2], bytes[index * 2 + 1]]);
        }
        Ok(byte_len / 2)
    }
    /// Cross-AS OBJECT_ATTRIBUTES.ObjectName read (OA+0x10 → PUNICODE_STRING) via [`read_ustr_pe`],
    /// so a name Buffer in a not-yet-faulted DLL `.rdata` page resolves from the PE. Used for hosted
    /// process registry key opens (see `read_objattr_name`, whose scratch-alias fallback only reaches
    /// already-faulted pages).
    pub(crate) unsafe fn read_objattr_name_pe(&self, oa_va: u64) -> alloc::vec::Vec<u16> {
        let mut p = [0u8; 8];
        if !self.xas_read(oa_va + 0x10, &mut p) {
            return alloc::vec::Vec::new();
        }
        let objname = u64::from_le_bytes(p);
        if objname == 0 {
            return alloc::vec::Vec::new();
        }
        self.read_ustr_pe(objname)
    }

    /// Capture the caller-owned part of an I/O Manager file open. The fixed representation may be
    /// borrowed while resolving the device and constructing a canonical FILE_OBJECT/IRP, but no
    /// pointer into caller memory or this capture may be retained by a pending request.
    unsafe fn capture_file_object_attributes(
        &self,
        oa_va: u64,
    ) -> Result<CapturedFileObjectAttributes, u32> {
        if oa_va == 0 {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let mut oa = [0u8; 0x30];
        if !self.xas_read(oa_va, &mut oa) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let length = u32::from_le_bytes(oa[0..4].try_into().unwrap());
        let attributes = u32::from_le_bytes(oa[24..28].try_into().unwrap());
        if length != oa.len() as u32 || attributes & !0x0000_07f2 != 0 {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let root = u64::from_le_bytes(oa[8..16].try_into().unwrap());
        let object_name = u64::from_le_bytes(oa[16..24].try_into().unwrap());
        if object_name == 0 {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }

        let mut ustr = [0u8; 16];
        if !self.xas_read(object_name, &mut ustr) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let length = u16::from_le_bytes(ustr[0..2].try_into().unwrap()) as usize;
        let maximum = u16::from_le_bytes(ustr[2..4].try_into().unwrap()) as usize;
        let buffer = u64::from_le_bytes(ustr[8..16].try_into().unwrap());
        if length == 0
            || length & 1 != 0
            || length > maximum
            || length > FILE_OBJECT_NAME_CAP * 2
            || buffer == 0
        {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        let mut bytes = [0u8; FILE_OBJECT_NAME_CAP * 2];
        if !self.xas_read(buffer, &mut bytes[..length]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let name_len = length / 2;
        let mut name = [0u16; FILE_OBJECT_NAME_CAP];
        for (index, word) in bytes[..length].chunks_exact(2).enumerate() {
            name[index] = u16::from_le_bytes([word[0], word[1]]);
        }
        Ok(CapturedFileObjectAttributes {
            root,
            attributes,
            name_len,
            name,
        })
    }

    /// Resolve the I/O parse root through the caller's canonical process handle table. A null root
    /// requires an absolute Object Manager name. A File root deliberately accepts either spelling;
    /// the owning filesystem parse routine decides whether a leading separator is valid.
    fn resolve_file_parse_root(
        &self,
        captured: &CapturedFileObjectAttributes,
    ) -> Result<FileParseRoot, u32> {
        self.resolve_file_parse_root_for(captured.root, captured.name())
    }

    fn resolve_file_parse_root_for(&self, root: u64, name: &[u16]) -> Result<FileParseRoot, u32> {
        if root == 0 {
            return if name.first() == Some(&(b'\\' as u16)) {
                Ok(FileParseRoot::Absolute)
            } else {
                Err(STATUS_OBJECT_PATH_SYNTAX_BAD)
            };
        }
        if root >= OBJ_HANDLE_BASE {
            let index = self.object_namespace_index_for_handle(
                root,
                Some(OBJ_KIND_DIRECTORY),
                DIRECTORY_TRAVERSE_ACCESS,
            )?;
            return Ok(FileParseRoot::ObjectDirectory { index });
        }
        let pid = self.pm_pid_for_pi(self.pi).ok_or(STATUS_INVALID_HANDLE)?;
        let object = self
            .pm
            .lookup_handle(pid, root as nt_process::Handle)
            .ok_or(STATUS_INVALID_HANDLE)?;
        match object {
            nt_process::HandleObject::Opaque(_) => {
                let index = self.object_namespace_index_for_handle(
                    root,
                    Some(OBJ_KIND_DIRECTORY),
                    DIRECTORY_TRAVERSE_ACCESS,
                )?;
                Ok(FileParseRoot::ObjectDirectory { index })
            }
            nt_process::HandleObject::Directory {
                first_cluster,
                object_id,
            } => {
                let open = self.directory_opens.get(object_id)?;
                if open.first_cluster != first_cluster {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(FileParseRoot::FatDirectory {
                    first_cluster,
                    object_id,
                })
            }
            nt_process::HandleObject::OverlayFile(file_id) => {
                // SAFETY: the executive service loop serializes every writable-volume access.
                if unsafe { crate::writable_fs::standard_information(file_id) }.is_none() {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(FileParseRoot::OverlayFile(file_id))
            }
            nt_process::HandleObject::RoutedFile { file_id, device_id } => {
                let Some((live_device_id, _)) = driver_launch::hosted_file_route(file_id) else {
                    return Err(STATUS_INVALID_HANDLE);
                };
                if live_device_id != device_id {
                    return Err(STATUS_INVALID_HANDLE);
                }
                Ok(FileParseRoot::HostedFile { file_id, device_id })
            }
            nt_process::HandleObject::File(file_id) => {
                let Some((device_id, _)) = driver_launch::hosted_file_route(file_id) else {
                    return Err(STATUS_INVALID_HANDLE);
                };
                Ok(FileParseRoot::HostedFile { file_id, device_id })
            }
            nt_process::HandleObject::DiskFile { .. } => Ok(FileParseRoot::NonDirectoryFile),
            _ => Err(STATUS_INVALID_HANDLE),
        }
    }

    fn normalize_object_directory_file_name<'a>(
        &self,
        root: FileParseRoot,
        name: &'a [u16],
        namespace_path: &mut [u8],
        absolute_name: &'a mut [u16],
    ) -> Result<(FileParseRoot, &'a [u16]), u32> {
        let FileParseRoot::ObjectDirectory { index } = root else {
            return Ok((root, name));
        };
        let path_len = self
            .object_namespace_path_exact(index, namespace_path)
            .ok_or(STATUS_OBJECT_NAME_INVALID)?;
        let name_len = nt_types::join_object_directory_name_into(
            &namespace_path[..path_len],
            name,
            absolute_name,
        )
        .ok_or(STATUS_OBJECT_NAME_INVALID)?;
        Ok((FileParseRoot::Absolute, &absolute_name[..name_len]))
    }

    fn capture_relative_file_path(
        name: &[u16],
        folded: &mut [u8],
        relative: &mut [u8],
    ) -> Result<usize, u32> {
        nt_fs::nt_file_relative_path_into(name, folded, relative).ok_or(STATUS_OBJECT_NAME_INVALID)
    }

    fn join_volume_relative_path(
        parent: &[u8],
        child: &[u8],
        output: &mut [u8],
    ) -> Result<usize, u32> {
        let separator = usize::from(!parent.is_empty());
        let length = parent
            .len()
            .checked_add(separator)
            .and_then(|length| length.checked_add(child.len()))
            .filter(|length| *length <= output.len())
            .ok_or(STATUS_OBJECT_NAME_INVALID)?;
        output[..parent.len()].copy_from_slice(parent);
        if separator != 0 {
            output[parent.len()] = b'\\';
        }
        output[parent.len() + separator..length].copy_from_slice(child);
        Ok(length)
    }

    fn decode_set_file_name_units(file_name: &[u8], output: &mut [u16]) -> Result<usize, u32> {
        if file_name.is_empty() || file_name.len() & 1 != 0 || file_name.len() / 2 > output.len() {
            return Err(nt_fs::STATUS_OBJECT_NAME_INVALID);
        }
        for (index, word) in file_name.chunks_exact(2).enumerate() {
            output[index] = u16::from_le_bytes([word[0], word[1]]);
        }
        Ok(file_name.len() / 2)
    }

    fn encode_ascii_path_utf16le(path: &[u8], output: &mut [u8]) -> Result<usize, u32> {
        let length = path
            .len()
            .checked_mul(2)
            .filter(|length| *length <= output.len())
            .ok_or(nt_fs::STATUS_OBJECT_NAME_INVALID)?;
        for (index, &byte) in path.iter().enumerate() {
            if !byte.is_ascii() {
                return Err(nt_fs::STATUS_OBJECT_NAME_INVALID);
            }
            output[index * 2..index * 2 + 2].copy_from_slice(&(byte as u16).to_le_bytes());
        }
        Ok(length)
    }

    unsafe fn resolve_local_set_file_name_target(
        &self,
        root_directory: u64,
        file_name: &[u8],
        output: &mut [u8],
    ) -> Result<(nt_fs::FileRenameRoot, usize), u32> {
        let mut name_units = [0u16; FILE_OBJECT_NAME_CAP];
        let name_len = Self::decode_set_file_name_units(file_name, &mut name_units)?;
        let name = &name_units[..name_len];
        if root_directory == 0 && name.first() != Some(&(b'\\' as u16)) {
            if output.len() < file_name.len() {
                return Err(nt_fs::STATUS_OBJECT_NAME_INVALID);
            }
            output[..file_name.len()].copy_from_slice(file_name);
            return Ok((nt_fs::FileRenameRoot::SourceParent, file_name.len()));
        }

        let root = self.resolve_file_parse_root_for(root_directory, name)?;
        let mut namespace_path = [0u8; NAMED_OBJECT_PATH_CAP];
        let mut absolute_name = [0u16; FILE_OBJECT_NAME_CAP];
        let (root, name) = self.normalize_object_directory_file_name(
            root,
            name,
            &mut namespace_path,
            &mut absolute_name,
        )?;
        match root {
            FileParseRoot::OverlayFile(root_file_id) => {
                let Some(standard) = crate::writable_fs::standard_information(root_file_id) else {
                    return Err(nt_fs::STATUS_INVALID_HANDLE);
                };
                if !standard.is_directory {
                    return Err(nt_fs::STATUS_NOT_A_DIRECTORY);
                }
                if output.len() < file_name.len() {
                    return Err(nt_fs::STATUS_OBJECT_NAME_INVALID);
                }
                output[..file_name.len()].copy_from_slice(file_name);
                Ok((
                    nt_fs::FileRenameRoot::Directory(root_file_id),
                    file_name.len(),
                ))
            }
            FileParseRoot::FatDirectory {
                first_cluster,
                object_id,
            } => {
                let mut folded = [0u8; FILE_OBJECT_NAME_CAP];
                let mut relative = [0u8; FILE_OBJECT_NAME_CAP];
                let child_len = Self::capture_relative_file_path(name, &mut folded, &mut relative)?;
                let mut parent = [0u8; nt_fs::DIRECTORY_OPEN_PATH_CAP];
                let parent_len = {
                    let open = self.directory_opens.get(object_id)?;
                    if open.first_cluster != first_cluster
                        || open.volume_relative_path().len() > parent.len()
                    {
                        return Err(nt_fs::STATUS_INVALID_HANDLE);
                    }
                    let length = open.volume_relative_path().len();
                    parent[..length].copy_from_slice(open.volume_relative_path());
                    length
                };
                let mut target = [0u8; FILE_VOLUME_RELATIVE_CAP];
                let target_len = Self::join_volume_relative_path(
                    &parent[..parent_len],
                    &relative[..child_len],
                    &mut target,
                )?;
                let encoded = Self::encode_ascii_path_utf16le(&target[..target_len], output)?;
                Ok((nt_fs::FileRenameRoot::VolumeRoot, encoded))
            }
            FileParseRoot::Absolute => {
                let mut folded = [0u8; FILE_OBJECT_NAME_CAP];
                let mut relative = [0u8; FILE_VOLUME_RELATIVE_CAP];
                let length = crate::writable_fs::volume_path_into(name, &mut folded, &mut relative)
                    .ok_or(nt_fs::STATUS_NOT_SAME_DEVICE)?;
                let encoded = Self::encode_ascii_path_utf16le(&relative[..length], output)?;
                Ok((nt_fs::FileRenameRoot::VolumeRoot, encoded))
            }
            FileParseRoot::HostedFile { .. } => Err(nt_fs::STATUS_NOT_SAME_DEVICE),
            FileParseRoot::NonDirectoryFile => Err(nt_fs::STATUS_NOT_A_DIRECTORY),
            FileParseRoot::ObjectDirectory { .. } => Err(nt_fs::STATUS_INVALID_HANDLE),
        }
    }

    fn resolve_hosted_set_file_name_target(
        &self,
        source: HostedFileRoute,
        root_directory: u64,
        file_name: &[u8],
        open_name: &mut [u16],
    ) -> Result<HostedSetFileNameTarget, u32> {
        let mut name_units = [0u16; FILE_OBJECT_NAME_CAP];
        let name_len = Self::decode_set_file_name_units(file_name, &mut name_units)?;
        let name = &name_units[..name_len];
        if root_directory == 0 && name.first() != Some(&(b'\\' as u16)) {
            return Ok(HostedSetFileNameTarget::SourceParent);
        }
        let root = self.resolve_file_parse_root_for(root_directory, name)?;
        let mut namespace_path = [0u8; NAMED_OBJECT_PATH_CAP];
        let mut absolute_name = [0u16; FILE_OBJECT_NAME_CAP];
        let (root, name) = self.normalize_object_directory_file_name(
            root,
            name,
            &mut namespace_path,
            &mut absolute_name,
        )?;
        match root {
            FileParseRoot::HostedFile { file_id, device_id } => {
                if name.first() == Some(&(b'\\' as u16)) {
                    return Err(nt_fs::STATUS_INVALID_PARAMETER);
                }
                if device_id != source.device_id {
                    return Err(nt_fs::STATUS_NOT_SAME_DEVICE);
                }
                Ok(HostedSetFileNameTarget::Canonical(file_id))
            }
            FileParseRoot::OverlayFile(_) | FileParseRoot::FatDirectory { .. } => {
                Err(nt_fs::STATUS_NOT_SAME_DEVICE)
            }
            FileParseRoot::NonDirectoryFile => Err(nt_fs::STATUS_NOT_A_DIRECTORY),
            FileParseRoot::Absolute => {
                let mut canonical = [0u16; FILE_OBJECT_NAME_CAP];
                let canonical_len =
                    unsafe { crate::object_manager_reparse_file_path(name, &mut canonical) }
                        .map_err(|status| status.raw() as u32)?;
                driver_launch::hosted_file_device_relative_name(
                    source.file_id,
                    &canonical[..canonical_len],
                    open_name,
                )
                .map(HostedSetFileNameTarget::OpenParent)
            }
            FileParseRoot::ObjectDirectory { .. } => Err(nt_fs::STATUS_INVALID_HANDLE),
        }
    }

    unsafe fn query_local_file_relative(
        &self,
        root: FileParseRoot,
        name: &[u16],
    ) -> Result<nt_fs::FileMetadata, u32> {
        let mut folded = [0u8; FILE_OBJECT_NAME_CAP];
        let mut relative = [0u8; FILE_OBJECT_NAME_CAP];
        let relative_len = Self::capture_relative_file_path(name, &mut folded, &mut relative)?;
        let relative = &relative[..relative_len];
        match root {
            FileParseRoot::OverlayFile(root_file_id) => unsafe {
                crate::writable_fs::query_metadata_relative_to_directory(root_file_id, relative)
            },
            FileParseRoot::FatDirectory {
                first_cluster,
                object_id,
            } => {
                let open = self.directory_opens.get(object_id)?;
                if open.first_cluster != first_cluster {
                    return Err(STATUS_INVALID_HANDLE);
                }
                let Some(entry) = exec_fs().and_then(|fs| {
                    crate::fs_loader::fat_open_path_metadata_from(&fs, first_cluster, relative)
                }) else {
                    return Err(nt_fs::STATUS_OBJECT_NAME_NOT_FOUND);
                };
                Ok(entry.metadata)
            }
            FileParseRoot::NonDirectoryFile => Err(nt_fs::STATUS_NOT_A_DIRECTORY),
            FileParseRoot::HostedFile { .. } => Err(STATUS_NOT_SUPPORTED),
            FileParseRoot::Absolute | FileParseRoot::ObjectDirectory { .. } => {
                Err(STATUS_INVALID_HANDLE)
            }
        }
    }

    unsafe fn write_file_basic_information(&self, output: u64, info: nt_fs::FileMetadata) -> bool {
        let mut basic = [0u8; 40];
        if nt_fs::encode_query_information(
            nt_fs::FILE_BASIC_INFORMATION,
            info.query_metadata(),
            &mut basic,
        )
        .is_err()
        {
            return false;
        }
        self.xas_try_write_buf(output, &basic)
    }

    unsafe fn write_file_network_open_information(
        &self,
        output: u64,
        info: nt_fs::FileMetadata,
    ) -> bool {
        let mut network = [0u8; 56];
        if nt_fs::encode_query_information(
            nt_fs::FILE_NETWORK_OPEN_INFORMATION,
            info.query_metadata(),
            &mut network,
        )
        .is_err()
        {
            return false;
        }
        self.xas_try_write_buf(output, &network)
    }

    /// Capture and validate the byte-oriented subset of named Object Manager attributes supported
    /// by the compact namespace. Caller memory never escapes this fixed stack representation.
    unsafe fn capture_named_object_attributes(
        &self,
        oa_va: u64,
    ) -> Result<CapturedNamedObjectAttributes, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INVALID_PARAMETER: u32 = 0xC000_000D;
        const STATUS_OBJECT_NAME_INVALID: u32 = 0xC000_0033;

        if oa_va == 0 {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let mut oa = [0u8; 0x30];
        if !self.xas_read(oa_va, &mut oa) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        if u32::from_le_bytes(oa[0..4].try_into().unwrap()) < 0x30 {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let root = u64::from_le_bytes(oa[8..16].try_into().unwrap());
        let object_name = u64::from_le_bytes(oa[16..24].try_into().unwrap());
        let attributes = u32::from_le_bytes(oa[24..28].try_into().unwrap());
        if object_name == 0 {
            return Ok(CapturedNamedObjectAttributes {
                root,
                attributes,
                path_len: None,
                path: [0; NAMED_OBJECT_PATH_CAP],
            });
        }

        let mut ustr = [0u8; 16];
        if !self.xas_read(object_name, &mut ustr) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let length = u16::from_le_bytes(ustr[0..2].try_into().unwrap()) as usize;
        let maximum = u16::from_le_bytes(ustr[2..4].try_into().unwrap()) as usize;
        let buffer = u64::from_le_bytes(ustr[8..16].try_into().unwrap());
        if length == 0
            || length & 1 != 0
            || length > maximum
            || length > NAMED_OBJECT_PATH_CAP * 2
            || buffer == 0
        {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        let mut bytes = [0u8; NAMED_OBJECT_PATH_CAP * 2];
        if !self.xas_read(buffer, &mut bytes[..length]) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let path_len = length / 2;
        let mut path = [0u8; NAMED_OBJECT_PATH_CAP];
        for (index, word) in bytes[..length].chunks_exact(2).enumerate() {
            let unit = u16::from_le_bytes([word[0], word[1]]);
            if unit > 0x7f {
                return Err(STATUS_OBJECT_NAME_INVALID);
            }
            path[index] = (unit as u8).to_ascii_lowercase();
        }
        let mut components = path[..path_len].split(|&byte| byte == b'\\');
        if path.first() == Some(&b'\\') {
            components.next();
        }
        if components.any(|component| component.is_empty() || component.len() > OBJ_NAME_CAP) {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        Ok(CapturedNamedObjectAttributes {
            root,
            attributes,
            path_len: Some(path_len),
            path,
        })
    }

    unsafe fn read_unicode_string16(&self, ustr_va: u64) -> Result<alloc::vec::Vec<u16>, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_OBJECT_NAME_INVALID: u32 = 0xC000_0033;
        if ustr_va == 0 {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let mut ustr = [0u8; 16];
        if !self.xas_read(ustr_va, &mut ustr) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let length = u16::from_le_bytes(ustr[0..2].try_into().unwrap()) as usize;
        let maximum = u16::from_le_bytes(ustr[2..4].try_into().unwrap()) as usize;
        let buffer = u64::from_le_bytes(ustr[8..16].try_into().unwrap());
        if length & 1 != 0 || length > maximum || length > 2048 || (length != 0 && buffer == 0) {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        let mut bytes = alloc::vec![0u8; length];
        if length != 0 && !self.xas_read(buffer, &mut bytes) {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        Ok(bytes
            .chunks_exact(2)
            .map(|word| u16::from_le_bytes([word[0], word[1]]))
            .collect())
    }

    fn event_root_index(&self, root: u64) -> Result<usize, u32> {
        match root {
            0 => Ok(0),
            _ => self.object_namespace_index_for_handle(
                root,
                Some(OBJ_KIND_DIRECTORY),
                DIRECTORY_TRAVERSE_ACCESS,
            ),
        }
    }

    /// Apply native OBJECT_ATTRIBUTES path rules: a null RootDirectory requires an absolute name,
    /// while a directory handle requires a relative name.
    fn event_root_and_path<'a>(&self, root: u64, path: &'a [u8]) -> Result<(usize, &'a [u8]), u32> {
        const STATUS_OBJECT_NAME_INVALID: u32 = 0xC000_0033;
        if root == 0 {
            if path.first() != Some(&b'\\') {
                return Err(STATUS_OBJECT_NAME_INVALID);
            }
            return Ok((0, path));
        }
        if path.first() == Some(&b'\\') {
            return Err(STATUS_OBJECT_NAME_INVALID);
        }
        Ok((self.event_root_index(root)?, path))
    }

    fn rollback_new_event(&mut self, index: usize) {
        if index + 1 == self.obj_ns.len() {
            self.obj_ns.pop();
            self.events.remove_existing(index as u64);
        }
    }

    fn rollback_new_timer(&mut self, index: usize) {
        if index + 1 == self.obj_ns.len() {
            self.obj_ns.pop();
            self.events.remove_existing(index as u64);
            self.user_timer_remove(index as u64);
        }
    }

    fn rollback_new_semaphore(&mut self, index: usize) {
        if index + 1 == self.obj_ns.len() {
            self.obj_ns.pop();
            self.semaphores.remove(index as u64);
        }
    }

    fn rollback_new_mutant(&mut self, index: usize) {
        if index + 1 == self.obj_ns.len() {
            self.obj_ns.pop();
            self.mutants.remove(index as u64);
        }
    }

    fn rollback_new_namespace_object(&mut self, index: usize) {
        if index + 1 == self.obj_ns.len() {
            self.obj_ns.pop();
        }
    }

    fn obj_delete_name_check(&mut self, index: usize) {
        let Some(entry) = self.obj_ns.get(index) else {
            return;
        };
        if !entry.is_live()
            || entry.permanent
            || entry.wait_references != 0
            || entry.parent == OBJ_PARENT_ROOT
        {
            return;
        }
        let kind = entry.kind;
        let mirrored_symbolic_link = kind == OBJ_KIND_SYMBOLIC_LINK && entry.payload != 0;
        let mut mirrored_path = [0u8; NAMED_OBJECT_PATH_CAP];
        if mirrored_symbolic_link && entry.parent != OBJ_PARENT_ANONYMOUS {
            let Some(length) = self.object_namespace_path_exact(index, &mut mirrored_path) else {
                return;
            };
            let Ok(path) = core::str::from_utf8(&mirrored_path[..length]) else {
                return;
            };
            if unsafe { crate::object_manager_delete_symbolic_link_path(path) }.is_err() {
                return;
            }
        }
        match kind {
            OBJ_KIND_DIRECTORY | OBJ_KIND_SYMBOLIC_LINK | OBJ_KIND_LPC_PORT => {}
            OBJ_KIND_EVENT => {
                self.events.remove_existing(index as u64);
            }
            OBJ_KIND_TIMER => {
                self.events.remove_existing(index as u64);
                self.user_timer_remove(index as u64);
            }
            OBJ_KIND_SEMAPHORE => {
                self.semaphores.remove(index as u64);
            }
            OBJ_KIND_MUTANT => {
                self.mutants.remove(index as u64);
            }
            _ => return,
        }
        self.obj_ns[index].unlink();
    }

    fn release_opaque_namespace_reference(&mut self, tag: u64) {
        let Some((kind, index)) = Self::opaque_object_namespace_index(tag) else {
            return;
        };
        let Some(entry) = self.obj_ns.get(index) else {
            return;
        };
        if !entry.is_live() || entry.kind != kind {
            return;
        }
        if self
            .pm
            .handle_object_count(nt_process::HandleObject::Opaque(tag))
            == 0
        {
            self.obj_delete_name_check(index);
        }
    }

    fn job_id_for_handle(
        &self,
        handle: u64,
        required_access: u32,
    ) -> Result<nt_process::job::JobId, u32> {
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        let caller = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        let handle = u32::try_from(handle).map_err(|_| nt_process::STATUS_INVALID_HANDLE)?;
        let id = match self.pm.lookup_handle(caller, handle) {
            Some(nt_process::HandleObject::Job(id)) if self.pm.job_exists(id) => id,
            _ => return Err(nt_process::STATUS_INVALID_HANDLE),
        };
        let granted = self
            .pm
            .handle_access(caller, handle)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        if required_access != 0 && granted & required_access != required_access {
            return Err(STATUS_ACCESS_DENIED);
        }
        Ok(id)
    }

    fn job_namespace_index(&self, id: nt_process::job::JobId) -> Option<usize> {
        self.obj_ns.iter().position(|entry| {
            entry.is_live() && entry.kind == OBJ_KIND_JOB && entry.payload == id as u64
        })
    }

    fn unlink_job_namespace(&mut self, id: nt_process::job::JobId) {
        if let Some(index) = self.job_namespace_index(id) {
            if !self.obj_ns[index].permanent {
                self.obj_ns[index].unlink();
            }
        }
    }

    fn mint_job_handle(
        &mut self,
        id: nt_process::job::JobId,
        desired_access: u32,
    ) -> Result<u64, u32> {
        let owner = self
            .pm_pid_for_pi(self.pi)
            .ok_or(nt_process::STATUS_INVALID_HANDLE)?;
        self.insert_process_handle(
            owner,
            nt_process::HandleObject::Job(id),
            nt_process::job::map_job_access(desired_access),
        )
        .map(u64::from)
    }

    fn drain_job_notifications(&mut self) {
        while let Some(notification) = self.pm.take_job_notification() {
            let _ = self.post_io_completion_packet(
                notification.association.port_id,
                nt_io_completion::CompletionPacket {
                    key_context: notification.association.completion_key,
                    apc_context: notification.process_id as u64,
                    status: 0,
                    information: notification.message as u64,
                },
            );
        }
    }

    fn drain_job_destructions(&mut self) {
        while let Some(destruction) = self.pm.take_job_destruction() {
            if let Some(association) = destruction.released_completion_port {
                let _ = self.io_completion_ports.release(association.port_id);
            }
            self.unlink_job_namespace(destruction.id);
        }
    }

    fn terminate_job_process(
        &mut self,
        pid: nt_process::ProcessId,
        exit_status: u32,
    ) -> Result<(), u32> {
        if self.pm.is_process_signaled(pid) {
            return Ok(());
        }
        if let Some(code) = self.pm.critical_process_termination_code(pid) {
            self.post_action = ExecPostAction::CriticalTermination {
                code,
                object: pid as u64,
            };
            return Ok(());
        }
        self.pm.mark_job_process_forced_termination(pid)?;
        self.pm
            .terminate_process_at(pid, exit_status, nt_system_time_100ns() as i64)?;
        self.release_process_handles(pid);
        if let Some(process_index) = self.pi_for_pid(pid) {
            let Some(bit) = 1u32.checked_shl(process_index as u32) else {
                return Err(nt_process::STATUS_INSUFFICIENT_RESOURCES);
            };
            self.pending_job_termination_mask |= bit;
        }
        self.drain_job_notifications();
        Ok(())
    }

    fn terminate_job_members(
        &mut self,
        id: nt_process::job::JobId,
        exit_status: u32,
    ) -> Result<(), u32> {
        let mut pids = [0u32; MAX_PI];
        let count = self.pm.job_active_process_ids(id, &mut pids)?;
        for &pid in &pids[..count] {
            self.terminate_job_process(pid, exit_status)?;
        }
        Ok(())
    }

    fn release_job_reference(&mut self, id: nt_process::job::JobId) {
        let Ok(action) = self.pm.release_job_handle(id) else {
            return;
        };
        if action.kill_active_processes {
            let _ = self.terminate_job_members(id, 0);
        }
        self.drain_job_destructions();
    }

    unsafe fn nt_create_job_object(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        const STATUS_OBJECT_NAME_EXISTS: u32 = 0x4000_0000;
        const STATUS_OBJECT_NAME_COLLISION: u32 = 0xC000_0035;
        const STATUS_OBJECT_PATH_NOT_FOUND: u32 = 0xC000_003A;
        const OBJ_OPENIF: u32 = 0x0000_0080;

        let output = args[0];
        if output == 0 || !self.probe_user_output(output, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        if output & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let desired_access = nt_ulong_arg(args[1]);
        let captured = if args[2] == 0 {
            None
        } else {
            match self.capture_named_object_attributes(args[2]) {
                Ok(captured) => Some(captured),
                Err(status) => return status,
            }
        };

        let mut namespace = None;
        let mut permanent = false;
        if let Some(captured) = captured.as_ref() {
            permanent = captured.attributes & OBJ_PERMANENT != 0;
            if let Some(path) = captured.path() {
                let (root, path) = match self.event_root_and_path(captured.root, path) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                if let Some(index) = self.obj_resolve(path, root) {
                    if self.obj_ns[index].kind != OBJ_KIND_JOB {
                        return STATUS_OBJECT_TYPE_MISMATCH;
                    }
                    if captured.attributes & OBJ_OPENIF == 0 {
                        return STATUS_OBJECT_NAME_COLLISION;
                    }
                    let id = self.obj_ns[index].payload as nt_process::job::JobId;
                    if !self.pm.job_exists(id) {
                        return nt_process::STATUS_INVALID_HANDLE;
                    }
                    let handle = match self.mint_job_handle(id, desired_access) {
                        Ok(handle) => handle,
                        Err(status) => return status,
                    };
                    if !self.xas_write_u64(output, handle) {
                        self.close_current_handle(handle);
                        return STATUS_ACCESS_VIOLATION;
                    }
                    return STATUS_OBJECT_NAME_EXISTS;
                }
                namespace = Some((root, path));
            }
        }

        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let session_id = match self.pm.process(caller) {
            Some(process) => process.session_id,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let id = match self.pm.create_job(session_id) {
            Ok(id) => id,
            Err(status) => return status,
        };
        let namespace_index = if let Some((root, path)) = namespace {
            let Some(index) = self.obj_create(path, root, OBJ_KIND_JOB, &[], permanent) else {
                self.pm.discard_unreferenced_job(id);
                self.drain_job_destructions();
                return STATUS_OBJECT_PATH_NOT_FOUND;
            };
            self.obj_ns[index].payload = id as u64;
            if permanent {
                if let Err(status) = self.pm.retain_job_wait_reference(id) {
                    self.obj_ns[index].unlink();
                    self.pm.discard_unreferenced_job(id);
                    self.drain_job_destructions();
                    return status;
                }
            }
            Some(index)
        } else {
            None
        };
        let handle = match self.mint_job_handle(id, desired_access) {
            Ok(handle) => handle,
            Err(status) => {
                if permanent {
                    let _ = self.pm.release_job_wait_reference(id);
                }
                if let Some(index) = namespace_index {
                    self.obj_ns[index].unlink();
                }
                self.pm.discard_unreferenced_job(id);
                self.drain_job_destructions();
                return status;
            }
        };
        if !self.xas_write_u64(output, handle) {
            self.close_current_handle(handle);
            if let Some(index) = namespace_index {
                if self.obj_ns[index].is_live() && !self.obj_ns[index].permanent {
                    self.obj_ns[index].unlink();
                }
            }
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    unsafe fn nt_open_job_object(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const STATUS_OBJECT_NAME_NOT_FOUND: u32 = 0xC000_0034;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;

        let output = args[0];
        if output == 0 || !self.probe_user_output(output, 8) {
            return STATUS_ACCESS_VIOLATION;
        }
        if output & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let captured = match self.capture_named_object_attributes(args[2]) {
            Ok(captured) => captured,
            Err(status) => return status,
        };
        let Some(path) = captured.path() else {
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        let (root, path) = match self.event_root_and_path(captured.root, path) {
            Ok(value) => value,
            Err(status) => return status,
        };
        let Some(index) = self.obj_resolve(path, root) else {
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        if self.obj_ns[index].kind != OBJ_KIND_JOB {
            return STATUS_OBJECT_TYPE_MISMATCH;
        }
        let id = self.obj_ns[index].payload as nt_process::job::JobId;
        if !self.pm.job_exists(id) {
            return nt_process::STATUS_INVALID_HANDLE;
        }
        let handle = match self.mint_job_handle(id, nt_ulong_arg(args[1])) {
            Ok(handle) => handle,
            Err(status) => return status,
        };
        if !self.xas_write_u64(output, handle) {
            self.close_current_handle(handle);
            return STATUS_ACCESS_VIOLATION;
        }
        0
    }

    fn nt_is_process_in_job(&self, args: &[u64]) -> u32 {
        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let pid = match self.pm.resolve_process_handle(
            caller,
            args[0],
            nt_process::PROCESS_QUERY_INFORMATION,
        ) {
            Ok(pid) => pid,
            Err(status) => return status,
        };
        let job = if args[1] == 0 {
            None
        } else {
            match self.job_id_for_handle(args[1], nt_process::job::JOB_OBJECT_QUERY) {
                Ok(id) => Some(id),
                Err(status) => return status,
            }
        };
        self.pm
            .is_process_in_job(pid, job)
            .unwrap_or_else(|status| status)
    }

    fn nt_assign_process_to_job_object(&mut self, args: &[u64]) -> u32 {
        let id = match self.job_id_for_handle(args[0], nt_process::job::JOB_OBJECT_ASSIGN_PROCESS) {
            Ok(id) => id,
            Err(status) => return status,
        };
        let caller = match self.pm_pid_for_pi(self.pi) {
            Some(pid) => pid,
            None => return nt_process::STATUS_INVALID_HANDLE,
        };
        let pid = match self.pm.resolve_process_handle(
            caller,
            args[1],
            nt_process::PROCESS_SET_QUOTA | nt_process::PROCESS_TERMINATE,
        ) {
            Ok(pid) => pid,
            Err(status) => return status,
        };
        if self.pm.job_security_limits(id).unwrap_or(0) != 0 {
            return STATUS_NOT_SUPPORTED;
        }
        let status = match self.pm.assign_process_to_job(id, pid) {
            Ok(status) => status,
            Err(status) => return status,
        };
        self.drain_job_notifications();
        if status == nt_process::job::STATUS_QUOTA_EXCEEDED {
            if let Err(error) = self.terminate_job_process(pid, 0x0000_0008) {
                return error;
            }
        }
        status
    }

    unsafe fn nt_create_job_set(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        let count = nt_ulong_arg(args[0]) as usize;
        if nt_ulong_arg(args[2]) != 0 || count <= 1 {
            return nt_process::STATUS_INVALID_PARAMETER;
        }
        let Some(length) = count.checked_mul(nt_process::job_abi::JOB_SET_ARRAY_ENTRY_SIZE) else {
            return nt_process::STATUS_INVALID_PARAMETER;
        };
        if args[1] == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        if args[1] & 7 != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let mut bytes = alloc::vec::Vec::new();
        if bytes.try_reserve_exact(length).is_err() {
            return nt_process::STATUS_INSUFFICIENT_RESOURCES;
        }
        bytes.resize(length, 0);
        if !self.xas_read(args[1], &mut bytes) {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut members = alloc::vec::Vec::new();
        if members.try_reserve_exact(count).is_err() {
            return nt_process::STATUS_INSUFFICIENT_RESOURCES;
        }
        for entry in bytes.chunks_exact(nt_process::job_abi::JOB_SET_ARRAY_ENTRY_SIZE) {
            let handle = u64::from_le_bytes(entry[0..8].try_into().unwrap());
            let level = u32::from_le_bytes(entry[8..12].try_into().unwrap());
            let flags = u32::from_le_bytes(entry[12..16].try_into().unwrap());
            if flags != 0 {
                return nt_process::STATUS_INVALID_PARAMETER;
            }
            let id = match self.job_id_for_handle(handle, nt_process::job::JOB_OBJECT_QUERY) {
                Ok(id) => id,
                Err(status) => return status,
            };
            members.push((id, level));
        }
        self.pm
            .create_job_set(&members)
            .map_or_else(|status| status, |()| 0)
    }

    unsafe fn nt_query_information_job_object(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;

        let class = match nt_process::job_abi::JobInformationClass::from_u32(nt_ulong_arg(args[1]))
        {
            Some(class) => class,
            None => return nt_process::STATUS_INVALID_INFO_CLASS,
        };
        let length = nt_ulong_arg(args[3]) as usize;
        let minimum = class.minimum_length();
        if if class.variable_length() {
            length < minimum
        } else {
            length != minimum
        } {
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if args[2] == 0 || args[2] & (class.alignment() as u64 - 1) != 0 {
            return if args[2] == 0 {
                STATUS_ACCESS_VIOLATION
            } else {
                STATUS_DATATYPE_MISALIGNMENT
            };
        }
        if !self.probe_user_output(args[2], length) {
            return STATUS_ACCESS_VIOLATION;
        }
        if args[4] != 0 {
            if args[4] & 3 != 0 {
                return STATUS_DATATYPE_MISALIGNMENT;
            }
            if !self.probe_user_output(args[4], 4) {
                return STATUS_ACCESS_VIOLATION;
            }
        }
        let id = if args[0] == 0 {
            let caller = match self.pm_pid_for_pi(self.pi) {
                Some(pid) => pid,
                None => return nt_process::STATUS_INVALID_HANDLE,
            };
            match self.pm.process_job(caller) {
                Some(id) => id,
                None => return STATUS_ACCESS_DENIED,
            }
        } else {
            match self.job_id_for_handle(args[0], nt_process::job::JOB_OBJECT_QUERY) {
                Ok(id) => id,
                Err(status) => return status,
            }
        };

        let mut fixed = [0u8; nt_process::job_abi::BASIC_PROCESS_ID_LIST_HEADER_SIZE + MAX_PI * 8];
        let (status, actual, output): (u32, usize, &[u8]) = match class {
            nt_process::job_abi::JobInformationClass::BasicAccounting => {
                let accounting = match self.pm.job_accounting(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                let actual =
                    nt_process::job_abi::encode_accounting(accounting, &mut fixed).unwrap();
                (0, actual, &fixed[..actual])
            }
            nt_process::job_abi::JobInformationClass::BasicAndIoAccounting => {
                let accounting = match self.pm.job_accounting(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                let actual =
                    nt_process::job_abi::encode_basic_and_io_accounting(accounting, &mut fixed)
                        .unwrap();
                (0, actual, &fixed[..actual])
            }
            nt_process::job_abi::JobInformationClass::BasicLimit => {
                let limits = match self.pm.job_basic_limits(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                let actual = nt_process::job_abi::encode_basic_limits(limits, &mut fixed).unwrap();
                (0, actual, &fixed[..actual])
            }
            nt_process::job_abi::JobInformationClass::ExtendedLimit => {
                let limits = match self.pm.job_extended_limits(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                let actual =
                    nt_process::job_abi::encode_extended_limits(limits, &mut fixed).unwrap();
                (0, actual, &fixed[..actual])
            }
            nt_process::job_abi::JobInformationClass::BasicUiRestrictions => {
                let value = match self.pm.job_ui_restrictions(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                fixed[..4].copy_from_slice(&value.to_le_bytes());
                (0, 4, &fixed[..4])
            }
            nt_process::job_abi::JobInformationClass::SecurityLimit => {
                let value = match self.pm.job_security_limits(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                fixed[..40].fill(0);
                fixed[..4].copy_from_slice(&value.to_le_bytes());
                (0, 40, &fixed[..40])
            }
            nt_process::job_abi::JobInformationClass::EndOfJobTime => {
                let value = match self.pm.job_end_of_job_time_action(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                fixed[..4].copy_from_slice(&value.to_le_bytes());
                (0, 4, &fixed[..4])
            }
            nt_process::job_abi::JobInformationClass::JobSet => {
                let value = match self.pm.job_member_level(id) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                fixed[..4].copy_from_slice(&value.to_le_bytes());
                (0, 4, &fixed[..4])
            }
            nt_process::job_abi::JobInformationClass::AssociateCompletionPort => {
                return nt_process::STATUS_INVALID_INFO_CLASS;
            }
            nt_process::job_abi::JobInformationClass::BasicProcessIdList => {
                let mut pids = [0u32; MAX_PI];
                let (assigned, count) = match self.pm.job_process_ids(id, &mut pids) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                let available = length.min(fixed.len());
                match nt_process::job_abi::encode_process_ids(
                    assigned,
                    &pids[..count],
                    &mut fixed[..available],
                ) {
                    Ok(actual) => (0, actual, &fixed[..actual]),
                    Err(status) => {
                        let actual = nt_process::job_abi::BASIC_PROCESS_ID_LIST_HEADER_SIZE
                            + ((available
                                - nt_process::job_abi::BASIC_PROCESS_ID_LIST_HEADER_SIZE)
                                / 8)
                            .min(count)
                                * 8;
                        (status, actual, &fixed[..actual])
                    }
                }
            }
        };
        if !self.xas_try_write_buf(args[2], output) {
            return STATUS_ACCESS_VIOLATION;
        }
        if status == 0
            && args[4] != 0
            && !self.xas_try_write_buf(args[4], &(actual as u32).to_le_bytes())
        {
            return STATUS_ACCESS_VIOLATION;
        }
        status
    }

    unsafe fn nt_set_information_job_object(&mut self, args: &[u64]) -> u32 {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_DATATYPE_MISALIGNMENT: u32 = 0x8000_0002;
        const SUPPORTED_LIMIT_FLAGS: u32 = nt_process::job::JOB_OBJECT_LIMIT_ACTIVE_PROCESS
            | nt_process::job::JOB_OBJECT_LIMIT_AFFINITY
            | nt_process::job::JOB_OBJECT_LIMIT_PRIORITY_CLASS
            | nt_process::job::JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;

        let class = match nt_process::job_abi::JobInformationClass::from_u32(nt_ulong_arg(args[1]))
        {
            Some(class) => class,
            None => return nt_process::STATUS_INVALID_INFO_CLASS,
        };
        let required_access = if class == nt_process::job_abi::JobInformationClass::SecurityLimit {
            nt_process::job::JOB_OBJECT_SET_SECURITY_ATTRIBUTES
        } else {
            nt_process::job::JOB_OBJECT_SET_ATTRIBUTES
        };
        let id = match self.job_id_for_handle(args[0], required_access) {
            Ok(id) => id,
            Err(status) => return status,
        };
        let length = nt_ulong_arg(args[3]) as usize;
        if length != class.minimum_length() {
            return nt_process::STATUS_INFO_LENGTH_MISMATCH;
        }
        if args[2] == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        if args[2] & (class.alignment() as u64 - 1) != 0 {
            return STATUS_DATATYPE_MISALIGNMENT;
        }
        let mut input = [0u8; nt_process::job_abi::EXTENDED_LIMIT_SIZE];
        if !self.xas_read(args[2], &mut input[..length]) {
            return STATUS_ACCESS_VIOLATION;
        }
        match class {
            nt_process::job_abi::JobInformationClass::BasicLimit => {
                let limits = nt_process::job_abi::decode_basic_limits(&input[..length]).unwrap();
                if limits.limit_flags & !SUPPORTED_LIMIT_FLAGS != 0 {
                    return STATUS_NOT_SUPPORTED;
                }
                self.pm
                    .set_job_basic_limits(id, limits)
                    .map_or_else(|status| status, |()| 0)
            }
            nt_process::job_abi::JobInformationClass::ExtendedLimit => {
                let limits = nt_process::job_abi::decode_extended_limits(&input[..length]).unwrap();
                if limits.basic.limit_flags & !SUPPORTED_LIMIT_FLAGS != 0 {
                    return STATUS_NOT_SUPPORTED;
                }
                self.pm
                    .set_job_extended_limits(id, limits)
                    .map_or_else(|status| status, |()| 0)
            }
            nt_process::job_abi::JobInformationClass::BasicUiRestrictions => {
                let value = u32::from_le_bytes(input[..4].try_into().unwrap());
                if value != 0 {
                    return STATUS_NOT_SUPPORTED;
                }
                self.pm
                    .set_job_ui_restrictions(id, value)
                    .map_or_else(|status| status, |()| 0)
            }
            nt_process::job_abi::JobInformationClass::SecurityLimit => {
                let value = u32::from_le_bytes(input[..4].try_into().unwrap());
                if value != 0 {
                    return STATUS_NOT_SUPPORTED;
                }
                self.pm
                    .set_job_security_limits(id, value)
                    .map_or_else(|status| status, |()| 0)
            }
            nt_process::job_abi::JobInformationClass::EndOfJobTime => {
                let value = u32::from_le_bytes(input[..4].try_into().unwrap());
                self.pm
                    .set_job_end_of_job_time_action(id, value)
                    .map_or_else(|status| status, |()| 0)
            }
            nt_process::job_abi::JobInformationClass::AssociateCompletionPort => {
                let completion_key = u64::from_le_bytes(input[..8].try_into().unwrap());
                let port_handle = u64::from_le_bytes(input[8..16].try_into().unwrap());
                let port_id = match self.io_completion_id_for(port_handle, 0x0002) {
                    Ok(id) => id,
                    Err(status) => return status,
                };
                if let Err(status) = self.io_completion_ports.retain(port_id) {
                    return status;
                }
                let association = nt_process::job::CompletionPortAssociation {
                    port_id,
                    completion_key,
                };
                if let Err(status) = self.pm.associate_job_completion_port(id, association) {
                    let _ = self.io_completion_ports.release(port_id);
                    return status;
                }
                let mut pids = [0u32; MAX_PI];
                let (_, count) = match self.pm.job_process_ids(id, &mut pids) {
                    Ok(value) => value,
                    Err(status) => return status,
                };
                for &pid in &pids[..count] {
                    let status = self.post_io_completion_packet(
                        port_id,
                        nt_io_completion::CompletionPacket {
                            key_context: completion_key,
                            apc_context: pid as u64,
                            status: 0,
                            information: nt_process::job::JOB_OBJECT_MSG_NEW_PROCESS as u64,
                        },
                    );
                    if status != 0 {
                        return status;
                    }
                }
                0
            }
            _ => nt_process::STATUS_INVALID_INFO_CLASS,
        }
    }

    fn nt_terminate_job_object(&mut self, args: &[u64]) -> u32 {
        let id = match self.job_id_for_handle(args[0], nt_process::job::JOB_OBJECT_TERMINATE) {
            Ok(id) => id,
            Err(status) => return status,
        };
        self.terminate_job_members(id, args[1] as u32)
            .map_or_else(|status| status, |()| 0)
    }

    fn nt_make_temporary_object(&mut self, handle: u64) -> u32 {
        const STATUS_ACCESS_DENIED: u32 = 0xC000_0022;
        const STATUS_OBJECT_TYPE_MISMATCH: u32 = 0xC000_0024;
        let (object, granted_access, direct_index) = match self.query_object_resolve(handle) {
            Ok(resolved) => resolved,
            Err(status) => return status,
        };
        if handle < OBJ_HANDLE_BASE && granted_access & DELETE_ACCESS != DELETE_ACCESS {
            return STATUS_ACCESS_DENIED;
        }
        let Some(index) = self.query_object_namespace_index(object, direct_index) else {
            return STATUS_OBJECT_TYPE_MISMATCH;
        };
        let (was_permanent, kind, payload) = match self.obj_ns.get_mut(index) {
            Some(entry) if entry.is_live() => {
                let state = (entry.permanent, entry.kind, entry.payload);
                entry.permanent = false;
                state
            }
            _ => return 0xC000_0008,
        };
        if was_permanent && kind == OBJ_KIND_IO_COMPLETION {
            self.release_io_completion_reference(payload as u32);
            return 0;
        }
        if was_permanent && kind == OBJ_KIND_JOB {
            let _ = self
                .pm
                .release_job_wait_reference(payload as nt_process::job::JobId);
            self.drain_job_destructions();
            return 0;
        }
        // For ordinary objects, removing OBJ_PERMANENT drops only the namespace's permanent
        // reference. The existing handle still owns the body; normal last-handle close deletes it.
        0
    }

    fn nt_make_permanent_object(&mut self, ctx: &NativeCallContext, handle: u64) -> u32 {
        if ctx.previous_mode != nt_syscall::ProcessorMode::KernelMode
            && !self.current_token_has_privilege(nt_security::SE_CREATE_PERMANENT)
        {
            return STATUS_PRIVILEGE_NOT_HELD;
        }
        let (object, _, direct_index) = match self.query_object_resolve(handle) {
            Ok(resolved) => resolved,
            Err(status) => return status,
        };
        let Some(index) = self.query_object_namespace_index(object, direct_index) else {
            return STATUS_OBJECT_TYPE_MISMATCH;
        };
        let (was_permanent, kind, payload) = match self.obj_ns.get(index) {
            Some(entry) if entry.is_live() => (entry.permanent, entry.kind, entry.payload),
            _ => return STATUS_INVALID_HANDLE,
        };
        if was_permanent {
            return 0;
        }
        if kind == OBJ_KIND_IO_COMPLETION {
            if let Err(status) = self.io_completion_ports.retain(payload as u32) {
                return status;
            }
        }
        if kind == OBJ_KIND_JOB {
            if let Err(status) = self
                .pm
                .retain_job_wait_reference(payload as nt_process::job::JobId)
            {
                return status;
            }
        }
        self.obj_ns[index].permanent = true;
        0
    }
    /// Normalize a caller's pipe path (`\Device\NamedPipe\ntsvcs`, `\??\pipe\ntsvcs`, `\??\PIPE\ntsvcs`,
    /// or a relative `ntsvcs`) to npfs's leaf form `\ntsvcs` (UTF-16, leading backslash). npfs's
    /// NpFsdCreate strips the device prefix; the leaf is what the VCB prefix tree keys on.
    pub(crate) fn pipe_leaf16_into(name16: &[u16], out: &mut [u16]) -> Option<usize> {
        // Find the last occurrence of "namedpipe\" or "pipe\" and take everything after it.
        let after = |needle: &[u8]| -> Option<usize> {
            if name16.len() < needle.len() {
                return None;
            }
            (0..=name16.len() - needle.len())
                .rev()
                .find(|&i| {
                    name16[i..i + needle.len()]
                        .iter()
                        .zip(needle)
                        .all(|(&unit, &byte)| {
                            unit <= 0x7f && (unit as u8).eq_ignore_ascii_case(&byte)
                        })
                })
                .map(|i| i + needle.len())
        };
        let start = after(b"namedpipe\\")
            .or_else(|| after(b"pipe\\"))
            .unwrap_or(0);
        let leaf = &name16[start..];
        // Ensure a single leading backslash (the leaf npfs expects, e.g. "\ntsvcs").
        let prefix_len = usize::from(leaf.first().copied() != Some(b'\\' as u16));
        let out_len = leaf.len().checked_add(prefix_len)?;
        if out_len > out.len() {
            return None;
        }
        let mut index = 0;
        if leaf.first().copied() != Some(b'\\' as u16) {
            out[index] = b'\\' as u16;
            index += 1;
        }
        out[index..index + leaf.len()].copy_from_slice(leaf);
        Some(out_len)
    }

    pub(crate) fn is_named_pipe_root_path(name16: &[u16]) -> bool {
        let mut end = name16.len();
        while end > 1 && name16[end - 1] == b'\\' as u16 {
            end -= 1;
        }
        let path = &name16[..end];
        [
            b"\\??\\pipe" as &[u8],
            b"\\dosdevices\\pipe",
            b"\\device\\namedpipe",
        ]
        .iter()
        .any(|candidate| {
            path.len() == candidate.len()
                && path
                    .iter()
                    .zip(*candidate)
                    .all(|(&unit, &byte)| unit <= 0x7f && (unit as u8).eq_ignore_ascii_case(&byte))
        })
    }

    /// Allocate one canonical File, reserve every publication surface, and route CREATE through the
    /// dynamically registered NPFS device. A pending result transfers its exact File/IRP and caller
    /// outputs into the common pending File-I/O owner; CREATE syscalls always wait for terminal
    /// completion regardless of the new File's synchronous flag.
    pub(crate) unsafe fn npfs_create_file(
        &mut self,
        major: u8,
        name16: &[u16],
        related_file_id: Option<u64>,
        provider_context: u64,
        desired_access: u32,
        share_access: u32,
        create_disposition: u32,
        file_attributes: u32,
        create_options: u32,
        ea: &[u8],
        file_handle_va: u64,
        iosb_va: u64,
    ) -> Result<HostedCreateDispatch, u32> {
        const STATUS_ACCESS_VIOLATION: u32 = 0xC000_0005;
        const STATUS_INSUFFICIENT_RESOURCES: u32 = 0xC000_009A;
        if !driver_launch::npfs_ready() {
            return Err(STATUS_DEVICE_NOT_READY);
        }
        let io_mode = file_io_mode_from_create(desired_access, create_options)?;
        if file_handle_va == 0
            || iosb_va == 0
            || !self.probe_user_output(file_handle_va, 8)
            || !self.probe_user_output(iosb_va, 16)
        {
            return Err(STATUS_ACCESS_VIOLATION);
        }
        let device_id = driver_launch::device_id_by_name("\\Device\\NamedPipe")
            .ok_or(STATUS_DEVICE_NOT_READY)?;
        if related_file_id.is_some_and(|file_id| {
            driver_launch::hosted_file_route(file_id)
                .is_none_or(|(parent_device_id, _)| parent_device_id != device_id)
        }) {
            return Err(STATUS_INVALID_HANDLE);
        }
        let server = major == major::IRP_MJ_CREATE_NAMED_PIPE;
        if !matches!(
            major,
            major::IRP_MJ_CREATE | major::IRP_MJ_CREATE_NAMED_PIPE
        ) || !self.reserve_pending_file_io_owner()
            || REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0
            || !wait_reply_pool_has_free()
            || (provider_context != 0 && !crate::reserve_pipe_create_metadata(server))
        {
            return Err(STATUS_INSUFFICIENT_RESOURCES);
        }
        let reservation = self.reserve_current_process_handle_slot()?;
        let allocated_file = match related_file_id {
            Some(related_file_id) => driver_launch::allocate_hosted_relative_file(
                related_file_id,
                desired_access,
                share_access,
                create_options,
                name16,
            ),
            None => driver_launch::allocate_hosted_file(
                device_id,
                desired_access,
                share_access,
                create_options,
                name16,
            ),
        };
        let canonical_file_id = match allocated_file {
            Ok(file_id) => file_id,
            Err(status) => {
                let _ = self.pm.cancel_reserved_handle(reservation);
                return Err(status);
            }
        };
        if let Err(status) = self.file_completion.reserve_file_handle_publication(
            canonical_file_id,
            device_id,
            io_mode,
        ) {
            let _ = self.pm.cancel_reserved_handle(reservation);
            let _ = driver_launch::abandon_unpublished_hosted_file(canonical_file_id);
            return Err(status);
        }
        let name_bytes_len = name16
            .len()
            .checked_mul(2)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let input_len = name_bytes_len
            .checked_add(ea.len())
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
        let mut in_bytes = alloc::vec::Vec::new();
        in_bytes
            .try_reserve_exact(input_len)
            .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
        for &w in name16 {
            in_bytes.extend_from_slice(&w.to_le_bytes());
        }
        in_bytes.extend_from_slice(ea);
        let mut out = [0u8; 64];
        let dispatch = driver_launch::dispatch_hosted_file_create_irp_result_exact(
            canonical_file_id,
            major,
            self.current_tid,
            nt_io_manager::CreateParameters {
                desired_access: nt_types::AccessMask::from_bits_retain(desired_access),
                share_access: nt_io_manager::ShareAccess::from_bits_retain(share_access),
                create_options: nt_io_manager::CreateOptions::from_bits_retain(create_options),
                create_disposition,
                file_attributes,
                ea_length: u32::try_from(ea.len()).map_err(|_| STATUS_INVALID_BUFFER_SIZE)?,
                related_file: related_file_id.map(nt_io_manager::FileId),
            },
            &in_bytes,
            &mut out,
        );
        let (status, information, pending_irp_id, file_context) = match dispatch {
            Ok(result) => result,
            Err(status) => {
                let _ = self.pm.cancel_reserved_handle(reservation);
                let _ = self
                    .file_completion
                    .cancel_reserved_file_handle(canonical_file_id);
                let _ = driver_launch::abandon_unpublished_hosted_file(canonical_file_id);
                return Err(status);
            }
        };
        NPFS_ROUTED_IRPS.fetch_add(1, Ordering::Relaxed);
        if let Some(irp_id) = pending_irp_id {
            self.pending_file_io_transfer = Some(nt_io_manager::PendingFileIo {
                file_id: canonical_file_id,
                irp_id: irp_id.raw(),
                major,
                control_code: 0,
                operation: nt_io_manager::PendingFileIoOperation::Create(
                    nt_io_manager::PendingFileCreate {
                        handle_va: file_handle_va,
                        desired_access,
                        provider_context,
                        reservation_pid: reservation.process_id,
                        reserved_handle: reservation.handle,
                        reservation_generation: reservation.generation,
                        status: STATUS_PENDING,
                        information: 0,
                        handle_value: 0,
                    },
                ),
                delivery_state: 0,
                pi: self.pi as u32,
                tid: self.current_tid,
                sync_lock_owner_tid: 0,
                badge: self.current_badge,
                consumer_abandoned: false,
                user_apc_interrupt_requested: false,
                output_va: 0,
                output_len: 0,
                output_offset: 0,
                iosb_va,
                apc_routine: 0,
                apc_context: 0,
                completion_port_suppressed: true,
                signal_file: false,
                publish_iocp: false,
                event_obj_idx: u64::MAX,
                reply_cap: 0,
                reply_required: false,
                native_call_transport: false,
                reply_mrs: [0; 18],
                resume_ip: 0,
                resume_sp: 0,
                resume_flags: 0,
            });
            self.pending_file_io_wait = true;
            return Ok(HostedCreateDispatch::Pending);
        }
        if status < 0 {
            let _ = self.pm.cancel_reserved_handle(reservation);
            let _ = self
                .file_completion
                .cancel_reserved_file_handle(canonical_file_id);
            let _ = driver_launch::abandon_unpublished_hosted_file(canonical_file_id);
            return Ok(HostedCreateDispatch::Completed {
                status: status as u32,
                information,
                file_id: 0,
                fs_context: 0,
                reservation: None,
            });
        }
        let fs_context = file_context
            .or_else(|| driver_launch::hosted_file_route(canonical_file_id).map(|(_, ctx)| ctx))
            .unwrap_or(0);
        Ok(HostedCreateDispatch::Completed {
            status: status as u32,
            information,
            file_id: canonical_file_id,
            fs_context,
            reservation: Some(reservation),
        })
    }

    pub(crate) unsafe fn publish_npfs_create(
        &mut self,
        major: u8,
        file_id: u64,
        fs_context: u64,
        reservation: nt_process::HandleReservation,
        desired_access: u32,
        provider_context: u64,
        status: u32,
        information: u64,
    ) -> Result<HostedCreatePublication, u32> {
        let named_pipe_device = driver_launch::device_id_by_name("\\Device\\NamedPipe")
            .ok_or(STATUS_DEVICE_NOT_READY)?;
        let (device_id, live_context) = driver_launch::hosted_file_route(file_id)
            .ok_or(nt_fs::STATUS_INVALID_DEVICE_REQUEST)?;
        let fs_context = if fs_context != 0 {
            if live_context != 0 && live_context != fs_context {
                return Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST);
            }
            fs_context
        } else {
            live_context
        };
        if device_id != named_pipe_device || fs_context == 0 {
            return Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST);
        }

        // A zero provider context denotes the NPFS root/control File. The RootDcb FILE_OBJECT is a
        // canonical routed File, but it has no endpoint-name metadata to publish in the executive.
        if major == major::IRP_MJ_CREATE && provider_context == 0 {
            let handle = self.bind_reserved_file_handle(file_id, reservation, desired_access)?;
            return Ok(HostedCreatePublication {
                status,
                information,
                handle,
                wake_server_fid: 0,
            });
        }
        if provider_context == 0 {
            return Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST);
        }

        let mut wake_server_fid = 0;
        let mut preconnected_recorded = false;
        let provider_result = match major {
            major::IRP_MJ_CREATE_NAMED_PIPE => {
                crate::pipe_fid_name_remember(fs_context, provider_context)
            }
            major::IRP_MJ_CREATE => {
                let server_fid = nt_io_manager::pipe_server_file_id_for_endpoint(fs_context)
                    .ok_or(nt_fs::STATUS_INVALID_DEVICE_REQUEST)?;
                wake_server_fid = server_fid;
                crate::pipe_fid_name_remember(fs_context, provider_context).and_then(|()| {
                    if self.pending_pipe_listen_for_server(server_fid) {
                        Ok(())
                    } else {
                        preconnected_recorded =
                            crate::pipe_server_preconnected_remember(server_fid)?;
                        Ok(())
                    }
                })
            }
            _ => Err(nt_fs::STATUS_INVALID_DEVICE_REQUEST),
        };
        if let Err(provider_status) = provider_result {
            crate::pipe_fid_name_forget(fs_context);
            if major != major::IRP_MJ_CREATE_NAMED_PIPE
                && wake_server_fid != 0
                && preconnected_recorded
            {
                crate::pipe_server_preconnected_forget(wake_server_fid);
            }
            return Err(provider_status);
        }

        let handle = match self.bind_reserved_file_handle(file_id, reservation, desired_access) {
            Ok(handle) => handle,
            Err(handle_status) => {
                crate::pipe_fid_name_forget(fs_context);
                if major != major::IRP_MJ_CREATE_NAMED_PIPE
                    && wake_server_fid != 0
                    && preconnected_recorded
                {
                    crate::pipe_server_preconnected_forget(wake_server_fid);
                }
                return Err(handle_status);
            }
        };
        Ok(HostedCreatePublication {
            status,
            information,
            handle,
            wake_server_fid,
        })
    }

    pub(crate) unsafe fn finish_npfs_create_dispatch(
        &mut self,
        dispatch: HostedCreateDispatch,
        major: u8,
        desired_access: u32,
        provider_context: u64,
    ) -> Option<HostedCreatePublication> {
        let HostedCreateDispatch::Completed {
            status,
            information,
            file_id,
            fs_context,
            reservation,
        } = dispatch
        else {
            return None;
        };
        if (status as i32) < 0 {
            return Some(HostedCreatePublication {
                status,
                information,
                handle: 0,
                wake_server_fid: 0,
            });
        }
        let Some(reservation) = reservation else {
            return Some(HostedCreatePublication {
                status: nt_fs::STATUS_INVALID_DEVICE_REQUEST,
                information: 0,
                handle: 0,
                wake_server_fid: 0,
            });
        };
        match self.publish_npfs_create(
            major,
            file_id,
            fs_context,
            reservation,
            desired_access,
            provider_context,
            status,
            information,
        ) {
            Ok(publication) => match self.publish_bound_file_handle(reservation) {
                Ok(handle) => {
                    debug_assert_eq!(handle, publication.handle);
                    Some(publication)
                }
                Err(status) => {
                    self.release_hosted_create_reservation(file_id, reservation);
                    Some(HostedCreatePublication {
                        status,
                        information: 0,
                        handle: 0,
                        wake_server_fid: 0,
                    })
                }
            },
            Err(status) => {
                self.release_hosted_create_reservation(file_id, reservation);
                Some(HostedCreatePublication {
                    status,
                    information: 0,
                    handle: 0,
                    wake_server_fid: 0,
                })
            }
        }
    }

    pub(crate) fn pending_create_reservation(
        create: nt_io_manager::PendingFileCreate,
    ) -> nt_process::HandleReservation {
        nt_process::HandleReservation {
            process_id: create.reservation_pid,
            handle: create.reserved_handle,
            generation: create.reservation_generation,
        }
    }

    fn release_hosted_create_reservation(
        &mut self,
        file_id: u64,
        reservation: nt_process::HandleReservation,
    ) {
        if let Ok(object) = self.pm.cancel_bound_handle(reservation) {
            self.release_handle_object(object);
            return;
        }
        let _ = self.pm.cancel_reserved_handle(reservation);
        let _ = self.file_completion.cancel_reserved_file_handle(file_id);
        let _ = driver_launch::abandon_unpublished_hosted_file(file_id);
    }

    pub(crate) fn release_unpublished_hosted_create(
        &mut self,
        pending: nt_io_manager::PendingFileIo,
    ) {
        let nt_io_manager::PendingFileIoOperation::Create(create) = pending.operation else {
            return;
        };
        if pending.delivery_state & nt_io_manager::IO_DELIVERY_HANDLE_PUBLISHED != 0 {
            return;
        }
        self.release_hosted_create_reservation(
            pending.file_id,
            Self::pending_create_reservation(create),
        );
    }

    pub(crate) fn cancel_hosted_create_publication(
        &mut self,
        file_id: u64,
        reservation: nt_process::HandleReservation,
    ) {
        let _ = self.pm.cancel_reserved_handle(reservation);
        let _ = self.file_completion.cancel_reserved_file_handle(file_id);
    }

    /// Route an endpoint IRP through the device that owned the handle's FILE_OBJECT.
    pub(crate) unsafe fn dispatch_hosted_file_irp_for(
        &mut self,
        route: HostedFileRoute,
        major: u64,
        fsctl: u64,
        input: &[u8],
        output: &mut [u8],
    ) -> Result<(i32, u64, u64), u32> {
        let (status, information, pending_irp_id, _) =
            driver_launch::dispatch_hosted_file_irp_result_exact(
                route.file_id,
                major,
                fsctl,
                self.current_tid,
                input,
                output,
            )?;
        if driver_launch::device_id_by_name("\\Device\\NamedPipe") == Some(route.device_id) {
            NPFS_ROUTED_IRPS.fetch_add(1, Ordering::Relaxed);
        }
        Ok((
            status,
            information,
            pending_irp_id.map(|irp_id| irp_id.raw()).unwrap_or(0),
        ))
    }

