                        let mut tb: alloc::vec::Vec<u8> = alloc::vec::Vec::new();
                        for c in t.encode_utf16() {
                            tb.extend_from_slice(&c.to_le_bytes());
                        }
                        tb.extend_from_slice(&0u16.to_le_bytes());
                        self.xas_write_buf(type_buf_va, &tb);
                        str_off += type_bytes + 2;
