                    print_u64(self.pi as u64);
                    print_str(b" badge=");
                    print_u64(self.current_badge);
                    print_str(b" tid=");
                    print_u64(self.current_tid);
                    print_str(b" candidate=");
                    print_u64(has_candidate as u64);
                    print_str(b"\n");
