                        trace_io_completion(
                            self.pi,
                            b"remove-error",
                            args[0],
                            Some(object_id),
                            status,
                            self.io_completion_ports.depth(object_id).ok(),
                            timeout_interval.unwrap_or(0),
                            args[1],
                            args[2],
                            args[3],
                        );
